#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct FrameHeader {
    time_t Timestamp;
    unsigned int SequenceNumber;
    void *Packet; // Pointer to dynamically allocated Packet structure
} FrameHeader;

// Function to create a Packet structure with Payload of variable length
typedef struct Packet {
    char *Payload;
    size_t PayloadLength;
} Packet;

int initFrameArray(FrameHeader**, unsigned int arraySize, unsigned int maxPacketSize) {
    FrameHeader *array = NULL;
    unsigned int i;

    // Allocate memory for the array and individual FrameHeader structures
    array = (FrameHeader*)malloc(arraySize * sizeof(FrameHeader));
    if (!array) {
        fprintf(stderr, "Error: Memory allocation for FrameHeader array failed.\n");
        return -1;
    }

    // Initialize each element in the array with zeroed memory
    memset(array, 0, arraySize * sizeof(FrameHeader));

    // Allocate and initialize Packet structures for each FrameHeader
    for (i = 0; i < arraySize; ++i) {
        Packet *packet = (Packet*)malloc(sizeof(Packet));
        if (!packet) {
            fprintf(stderr, "Error: Memory allocation for Packet failed.\n");
            // Free the allocated FrameHeader array if an error occurs within the loop
            for (unsigned int j = 0; j <= i; ++j)
                free(array[j].Packet);
            free(array);
            return -1;
        }

        packet->PayloadLength = rand() % maxPacketSize + 1;
        packet->Payload = (char*)malloc(packet->PayloadLength);
        if (!packet->Payload) {
            fprintf(stderr, "Error: Memory allocation for Packet Payload failed.\n");
            free(packet);
            // Free the FrameHeader and its associated Packet if an error occurs within the inner loop
            array[i].Packet = NULL;
            continue;
        }

        // Populate the FrameHeader structure with a valid Timestamp, SequenceNumber, and Packet pointer
        array[i].Timestamp = time(NULL);
        array[i].SequenceNumber = i + 1;
        array[i].Packet = packet;
    }

    return 0; // No errors occurred during initialization
}
