int allocate_and_init(size_t *long_offsets, size_t *keys, struct Record **records, const size_t capacity, const size_t offset_range, const size_t key_range, const char* filename) {
    size_t i;
    FILE *file = fopen(filename, "r");
    if (!file) return 1; // error handling for file open failure

    *long_offsets = malloc(capacity * sizeof(*long_offsets));
