        perror("Failed to allocate memory for long offsets");
        fclose(file);
        return 2; // error handling for memory allocation failure
    }

    *keys = malloc(capacity * sizeof(*keys));
    if (*keys == NULL) {
        perror("Failed to allocate memory for keys");
        free(*long_offsets);
        fclose(file);
        return 3; // error handling for memory allocation failure
    }

    *records = malloc(capacity * sizeof(**records));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        free(*long_offsets);
        free(*keys);
        fclose(file);
        return 4; // error handling for memory allocation failure
    }

    assert(capacity > 0);

    srand((unsigned)time(NULL));

    for (i = 0; i < capacity; ++i) {
        if (fscanf(file, "%zu %d", &(*long_offsets)[i], &(*keys)[i]) != 2) break; // handle cases where the file does not contain valid data
    }

    if (ferror(file)) { // error handling for file read failure
        perror("Error reading from file");
        free(*long_offsets);
        free(*keys);
        free(*records);
        fclose(file);
        return 5;
    }

    if (i < capacity) {
        free(*long_offsets);
        free(*keys);
        free(*records);
