#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <getopt.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <syslog.h>

static const char *LOG_FILE = NULL;

void log_message(int priority, const char *format, ...) {
    va_list args;

    if (LOG_FILE == NULL) {
        vsyslog(priority, format, args);
    } else {
        va_list args2;
        FILE *log_file = fopen(LOG_FILE, "a");

        if (!log_file) {
            vsyslog(LOG_EMERG, "Failed to open log file: %s", strerror(errno));
            return;
        }

        va_start(args2, format);
        vfprintf(log_file, format, args2);
        va_end(args2);
        fclose(log_file);
    }
}

struct file_stats {
    size_t num_lines;
    size_t total_length;
    size_t max_line_length;
};

static void process_file(const char *path, struct file_stats *stats) {
    int fd = open(path, O_RDONLY);
    struct stat st;
    char buffer[4096];
    size_t bytes_read;
    size_t line_length;
    bool is_line = false;

    if (fd == -1) {
        log_message(LOG_ERR, "Failed to open file %s: %s", path, strerror(errno));
        return;
    }

    fstat(fd, &st);
    stats->num_lines = 0;
    stats->total_length = 0;
    stats->max_line_length = 0;

    while ((bytes_read = read(fd, buffer, sizeof(buffer))) > 0) {
        for (size_t i = 0; i < bytes_read; ++i) {
            if (buffer[i] == '\n') {
                is_line = false;
                stats->num_lines++;

                line_length = i > 0 ? i : 1;
                if (line_length > stats->max_line_length) {
                    stats->max_line_length = line_length;
                }

                stats->total_length += line_length;
            } else if (!is_line && buffer[i] == '\r') {
                // Ignore carriage returns on Windows systems
                continue;
            } else {
                is_line = true;

                line_length = i > 0 ? i : 1;
                if (line_length > stats->max_line_length) {
                    stats->max_line_length = line_length;
                }

                stats->total_length += line_length;
            }
        }
    }

    close(fd);
}

int main(int argc, char **argv) {
    const char *input_file = NULL;
    const char *output_file = "stdout";
    bool manpage = false;
    int log_level = LOG_INFO;
    FILE *log_file = NULL;

    static struct option long_options[] = {
        {"manpage", no_argument, 0, 'h'},
        {"help", no_argument, 0, 'h'},
        {"output-file", required_argument, 0, 'o'},
        {"log-level", required_argument, 0, 'l'},
        {0}
    };

    int option_index;
    while (1) {
        int c = getopt_long(argc, argv, "hlo:", long_options, &option_index);
        if (c == -1) break;

        switch (c) {
            case 'h':
                manpage = true;
                goto end_main;
            case 'o':
                output_file = optarg;
                break;
            case 'l':
                log_level = strtol(optarg, NULL, 10);
                if (log_level < LOG_EMERG || log_level > LOG_DEBUG) {
                    log_message(LOG_ERR, "Invalid log level: %d", log_level);
                    return EXIT_FAILURE;
                }
                openlog("linecounter", LOG_PID | log_level, LOG_DAEMON);
                log_file = stdout;
                break;
            default:
                break;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Usage: %s [options] [files...]\n\n", argv[0]);
        manpage = true;
        goto end_main;
    }

    input_file = argv[optind++];

    if (manpage) {
        printf("Line counter version 1.0\n\n");
        printf("Usage: %s [options] [files...]\n\n", argv[0]);
        printf("Options:\n");
        printf("  -h, --help                   Display this help message and exit\n");
        printf("  -l, --log-level=LEVEL         Set the log level (valid levels: EMERG, ALERT, CRIT, ERR, WARN, NOTICE, INFO, DEBUG)\n");
        printf("  -o, --output-file=FILE        Output to a file instead of stdout\n");
        exit(EXIT_SUCCESS);
    }

end_main:
    if (log_file && log_level > LOG_INFO) {
        closelog();
    }

    if (output_file != "stdout") {
        log_file = fopen(output_file, "w");
        if (!log_file) {
            perror("Failed to open output file");
            return EXIT_FAILURE;
        }
    }

    struct file_stats stats;
    process_file(input_file, &stats);

    fprintf(log_file, "File: %s\n", input_file);
    fprintf(log_file, "Number of lines: %zu\n", stats.num_lines);
    fprintf(log_file, "Total length: %zu\n", stats.total_length);
    fprintf(log_file, "Average line length: %.2f\n", (double)stats.total_length / stats.num_lines);
    fprintf(log_file, "Maximum line length: %zu\n", stats.max_line_length);

    if (output_file != "stdout") {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}
