```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <pthread.h>
#include <errno.h>
#include <evlog.h> // or syslog.h for libevlog replacement

#define MAX_THREADS 10
#define BUF_SIZE 256

u_char ip_buffer[BUF_SIZE];
int ip_buffer_len;

struct hostname {
    char name[BUF_SIZE];
    u_char *ip;
    int len;
};

typedef struct hostname Hostname;

Hostname** hostnames;
pthread_t** threads;
pthread_mutex_t queue_lock;
int num_threads = 0, queued = 0;

void* resolve(void* arg) {
    int idx = ((Hostname*)arg - hostnames);
    Hostname* h = &hostnames[idx];

    struct addrinfo hints, *res, *p;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    int err = getaddrinfo(h->name, NULL, &hints, &res);
    if (err) {
        evlog(LOG_ERR, "getaddrinfo: %s", gai_strerror(err));
        h->ip = NULL;
        h->len = 0;
        return NULL;
    }

    h->ip = malloc(res->ai_addrlen);
    memcpy(h->ip, res->ai_addr, res->ai_addrlen);
    h->len = res->ai_addrlen;

    freeaddrinfo(res);
    return NULL;
}

void enqueue(char* hostname) {
    pthread_mutex_lock(&queue_lock);
    if (queued < MAX_THREADS && num_threads < MAX_THREADS) {
        Hostname* h = malloc(sizeof(Hostname));
        strcpy(h->name, hostname);
        h->ip = NULL;
        h->len = 0;

        hostnames[queued] = h;
        threads[num_threads] = (pthread_t*)calloc(1, sizeof(pthread_t));
        pthread_create(threads[num_threads], NULL, resolve, hostnames[queued]);
        num_threads++;
        queued++;
    }
    pthread_mutex_unlock(&queue_lock);
}

int dns_resolve(char* hostname) {
    enqueue(hostname);

    while (num_threads > 0 || queued > 0) {
        pthread_t idle;
        pthread_t* next = NULL;
        int i;

        for (i = 0; i < num_threads && i < MAX_THREADS; i++) {
            if (pthread_equal(threads[i], (pthread_t*)NULL)) {
                next = threads + i;
                break;
            }
        }

        if (next) {
            pthread_join(*next, NULL);
            free(hostnames[*next - hostnames]);
            memmove(threads + (*next - threads), threads + (*next), sizeof(pthread_t)*(num_threads - *next));
            num_threads--;
        } else {
            pthread_mutex_lock(&queue_lock);
            for (i = 0; i < queued && i < MAX_THREADS; i++) {
                if (!hostnames[i]->ip) {
                    pthread_create(threads + num_threads, NULL, resolve, hostnames + i);
                    num_threads++;
                }
            }
            pthread_mutex_unlock(&queue_lock);
        }
    }

    if (ip_buffer_len > 0) {
        return ip_buffer_len;
    }
    return -1;
}
```

