#include <stdio.h>
#include <stdlib.h>

int validate_input(int num) {
    if (num < -1000 || num > 1000) {
        fprintf(stderr, "Invalid input: number out of range [-1000, 1000].\n");
        return 0;
    }
    return 1;
}

int* read_integers(int *count) {
    int num;
    int *arr = NULL;
    *count = 0;

    while (*count < 1000 && scanf("%d", &num)) {
        if (!validate_input(num)) continue;

        arr = realloc(arr, sizeof(int) * (*count + 1));
        if (!arr) {
            fprintf(stderr, "Memory allocation error.\n");
            free(arr);
            return NULL;
        }
        arr[*count] = num;
        (*count)++;
    }

    if (ferror(stdin)) {
        fprintf(stderr, "Error reading input.\n");
        free(arr);
        return NULL;
    }

    return arr;
}

void print_largest(int *arr, int count) {
    int i, largest = arr[0];

    for (i = 1; i < count; ++i)
        if (arr[i] > largest)
            largest = arr[i];

    printf("The largest integer is: %d\n", largest);
}

int main() {
    int *arr, count;

    arr = read_integers(&count);
    if (!arr) return 1;

    print_largest(arr, count);
    free(arr);

    return 0;
}
