#include <stdarg.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <unistd.h>
#define LOG_BUF_SIZE 1024
#define MAX_VERBOSITY 4

static char log_buffer[LOG_BUF_SIZE];
static size_t log_pos = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static int verbosity_level = MAX_VERBOSITY;
static int severity_mask = 0x0F; // (INFO, DEBUG, WARN, ERROR)
static char *log_file_path = "/path/to/logs.log";
static clock_t start_time = 0;
static struct timespec time_stamp;

void log_message(const char *fmt, ...) {
    if (!start_time)
        start_time = clock();

    if (verbosity_level <= severity_mask) {
        va_list args;
        va_start(args, fmt);
        snprintf(log_buffer + log_pos, LOG_BUF_SIZE - log_pos, "%.6lf: [%s] ",
                 (double)(clock() - start_time) / CLOCKS_PER_SEC, get_thread_name());

        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);
        time_stamp = current_time;

        vsnprintf(log_buffer + log_pos + strlen(log_buffer), LOG_BUF_SIZE - log_pos - strlen(log_buffer), fmt, args);
        log_pos += strlen(log_buffer) + va_arg_count(args) + 1; // +1 for '\0'
        if (log_pos >= LOG_BUF_SIZE) {
            pthread_mutex_lock(&log_mutex);
            fwrite(log_buffer, 1, log_pos, stderr);
            log_pos = 0;
            pthread_mutex_unlock(&log_mutex);
        }
    }

    va_end(args);
}

char *get_thread_name() {
    static char thread_name[32];
#if __linux__ || __APPLE__ || __FreeBSD__
    pthread_t tid = pthread_self();
    int len = snprintf(thread_name, sizeof(thread_name), "pthread-%lu", (unsigned long)tid);
    if (len > sizeof(thread_name)) {
        thread_name[sizeof(thread_name)-1] = '\0';
    }
#else // Assume Windows with PPL
    Concurrency::thread::current_id()->get_name(thread_name, sizeof(thread_name));
#endif
    return thread_name;
}
```

