#include <jansson/jansson.h>
#include <openssl/evp.h>

typedef struct {
    const EVP_CIPHER *cipher;
    int cipher_mode; // ECB, EDE, EDE3, CFB
} CryptoConfig;

bool validate_oauth2_token(const char *json_str) {
    json_t *root = json_loads(json_str, 0, NULL);
    if (!root) return false;

    if (!json_object_get_field(root, "access_token") ||
        !json_object_get_field(root, "expires_in") ||
        !json_is_integer(json_object_get_field(root, "expires_in")) ||
        json_object_get_field(root, "expires_in")->u.i < 0 ||
        !json_object_get_field(root, "token_type") ||
        !(strcmp(json_string_value(json_object_get_field(root, "token_type")), "Bearer")) ||
        (!json_object_get_field(root, "refresh_token"))) {
        json_decref(root);
        return false;
    }

    json_decref(root);
    return true;
}

CryptoConfig *setup_cipher(int cipher_mode) {
    static const EVP_CIPHER *des_ecb = EVP_des_ecb();
    static const EVP_CIPHER *des_ede = EVP_des_ede3_cbc();
    static const EVP_CIPHER *des_ede3 = EVP_des_ede3_cfb1();
    static const EVP_CIPHER *des_cfb = EVP_cfb128_bf_cbc();

    CryptoConfig *config = malloc(sizeof(CryptoConfig));
    switch (cipher_mode) {
        case 0: // ECB
            config->cipher = des_ecb;
            break;
        case 1: // EDE
            config->cipher = des_ede;
            break;
        case 2: // EDE3
            config->cipher = des_ede3;
            break;
        case 3: // CFB
            config->cipher = des_cfb;
            break;
        default:
            free(config);
            return NULL;
    }
    config->cipher_mode = cipher_mode;
    return config;
}
