import org.json.*;
import okhttp3.*;
import java.io.*;
import java.util.*;

public class PokemonInfo {
    public static JSONObject getPokemonDetails(Pokemon pokemon) throws IOException {
        OkHttpClient client = new OkHttpClient();
        Request request = new Request.Builder()
                .url("https://pokeapi.co/api/v2/pokemon/" + pokemon.getId())
                .build();

        try (Response response = client.newCall(request).execute()) {
            if (!response.isSuccessful()) throw new IOException("Unexpected code " + response);

            JSONObject pokemonJson = new JSONObject(response.body().string());
            JSONArray moves = pokemonJson.getJSONArray("moves");
            List<String> moveNames = new ArrayList<>();
            for (int i = 0; i < moves.length(); ++i) {
                moveNames.add(moves.getJSONObject(i).getString("move"));
            }

            JSONArray evolutionChain = pokemonJson.getJSONObject("evolution_chain").getJSONArray("url");
            if (!evolutionChain.isEmpty()) {
                Request evolutionRequest = new Request.Builder()
                        .url(evolutionChain.getString(0))
                        .build();
                try (Response evolutionResponse = client.newCall(evolutionRequest).execute()) {
                    if (!evolutionResponse.isSuccessful()) throw new IOException("Unexpected code " + evolutionResponse);

                    JSONObject evolutionJson = new JSONObject(evolutionResponse.body().string());
                    int id = evolutionJson.getJSONArray("chain").getJSONObject(0).getInt("id");
                    if (id > 1) {
                        JSONArray evolutionChainArray = evolutionJson.getJSONArray("chain");
                        for (int i = 1; i < evolutionChainArray.length(); ++i) {
                            id = evolutionChainArray.getJSONObject(i).getInt("id");
                            if (id > 1) {
                                Request speciesRequest = new Request.Builder()
                                        .url("https://pokeapi.co/api/v2/evolution-chain/" + id + "/")
                                        .build();
                                try (Response speciesResponse = client.newCall(speciesRequest).execute()) {
                                    if (!speciesResponse.isSuccessful()) continue;

                                    JSONObject speciesJson = new JSONObject(speciesResponse.body().string());
                                    String speciesName = speciesJson.getString("name");
                                    pokemon.setSpecies(speciesName);
                                }
                            }
                        }
                    }
                }
            }

            Map<String, List<String>> weaknesses = new HashMap<>();
            switch (pokemon.getType()) {
                case "fire":
                    weaknesses.put("weaknesses", Arrays.asList("water", "ground"));
                    break;
                case "water":
                    weaknesses.put("weaknesses", Arrays.asList("electric", "grass"));
                    break;
                case "electric":
                    weaknesses.put("weaknesses", Arrays.asList("water"));
                    break;
                case "grass":
                    weaknesses.put("weaknesses", Arrays.asList("fire", "ice", "poison", "flying", "psychic"));
                    break;
                case "ice":
                    weaknesses.put("weaknesses", Arrays.asList("grass", "ground", "water", "fighting", "rock", "steel", "fire"));
                    break;
                // Add other types here

                default:
