['```c
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <sys/mman.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

void* aes_crypt(const char *file_path, int mode) {
    AES_KEY key;
    AES_CTX ctx;
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, sizeof(iv));
    AES_init(&key, (const unsigned char*)"mysecretkey", 128);

    int fd = open(file_path, O_RDONLY);
    struct stat file_stat;
    fstat(fd, &file_stat);
    size_t map_size = AES_BLOCK_SIZE + (file_stat.st_size > (1ULL << 30) ? (file_stat.st_size >> 30) * getpagesize() : 0);
    void *map = mmap(NULL, map_size, PROT_READ, MAP_PRIVATE | MAP_POPULATE, fd, 0);
    close(fd);

    unsigned char *data = (unsigned char*)map;
    size_t offset = 0;
    while (offset < file_stat.st_size) {
        size_t read_len = offset + AES_BLOCK_SIZE > file_stat.st_size ? (file_stat.st_size - offset) : AES_BLOCK_SIZE;
        size_t process_len = read(fd, data + offset, read_len);
        if (process_len <= 0) {
            perror("Error reading file");
            munmap(map, map_size);
            return NULL;
        }
        offset += process_len;

        AES_ctx_init(&ctx, &key, iv);
        if (mode == ENCRYPT) {
            AES_encrypt((unsigned char*)(data + offset), (unsigned char*)(data + offset), &ctx);
        } else if (mode == DECRYPT) {
            AES_decrypt((unsigned char*)(data + offset), (unsigned char*)(data + offset), &ctx);
        }
    }

    AES_free_ctx(&ctx);
    munmap(map, map_size);

    void *cipher = malloc(sizeof(AES_KEY));
    memcpy(cipher, &key, sizeof(AES_KEY));
    return cipher;
}
