['```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    pthread_t thread_id;
    void (*function)(void*);
    void *arg;
} worker_t;

struct threadpool {
    size_t num_threads;
    queue_t *queue;
    pthread_mutex_t queue_lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
    int shutdown;
};

void threadpool_init(struct threadpool *tp, size_t num_threads) {
    tp->num_threads = num_threads;
    tp->queue = queue_create();
    pthread_mutex_init(&tp->queue_lock, NULL);
    pthread_cond_init(&tp->not_empty, NULL);
    pthread_cond_init(&tp->not_full, NULL);
    tp->shutdown = 0;
}

void *worker(void *arg) {
    struct threadpool *tp = arg;

    for (;;) {
        worker_t task;

        pthread_mutex_lock(&tp->queue_lock);
        while (!tp->shutdown && queue_empty(tp->queue)) {
            pthread_cond_wait(&tp->not_empty, &tp->queue_lock);
        }

        if (tp->shutdown) {
            pthread_mutex_unlock(&tp->queue_lock);
            break;
        }

        task = queue_dequeue(tp->queue);
        pthread_mutex_unlock(&tp->queue_lock);

        task.function(task.arg);
    }

    return NULL;
}

void enqueue(struct threadpool *tp, void (*function)(void*), void *arg) {
    worker_t task = { .function = function, .arg = arg };

    pthread_mutex_lock(&tp->queue_lock);
    while (tp->num_threads == queue_size(tp->queue)) {
        pthread_cond_wait(&tp->not_full, &tp->queue_lock);
    }

    queue_enqueue(tp->queue, task);
    pthread_cond_signal(&tp->not_empty);
    pthread_mutex_unlock(&tp->queue_lock);
}

void threadpool_shutdown(struct threadpool *tp) {
    tp->shutdown = 1;

    pthread_mutex_lock(&tp->queue_lock);
    pthread_cond_broadcast(&tp->not_empty);
    pthread_mutex_unlock(&tp->queue_lock);
}

void threadpool_destroy(struct threadpool *tp) {
    threadpool_shutdown(tp);

    pthread_mutex_destroy(&tp->queue_lock);
    pthread_cond_destroy(&tp->not_empty);
    pthread_cond_destroy(&tp->not_full);
    queue_destroy(tp->queue);
}
```']

