class SandeshClient {
public:
    void init(const std::string& configFile) {
        bp::ptree pt;
        try {
            boost::filesystem::ifstream ifs(configFile);
            bp::read_xml(ifs, pt);
            for (auto& e : pt.get_child("endpoints")) {
                auto endpoint = std::make_shared<Endpoint>(e.get<std::string>("uri"),
                                                           e.get<std::map<std::string, std::string>>("headers"),
                                                           e.get<std::string>("bodyContent"),
                                                           e.get<size_t>("timeout"));
                endpoints_.insert(endpoint);
            }
        } catch (const bp::ptree_error& ex) {
            std::cerr << "Error parsing configuration file: " << ex.what() << std::endl;
            exit(EXIT_FAILURE);
        }
    }

    void run() {
        for (auto& endpoint : endpoints_) {
            auto startTime = std::chrono::system_clock::now();
            HttpRequest req(endpoint->uri(), endpoint->headers_, endpoint->bodyContent_, endpoint->timeout_);

            try {
                http_.post(req);
                ++requestStats_.sent;
                if (req.status() == asio::error::success)
                    ++requestStats_.successful;
            } catch (const std::exception& ex) {
                ++requestStats_.failed;
                std::cerr << "Error executing request: " << ex.what() << std::endl;
            }

            auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now() - startTime).count();
            std::cout << std::put_time(std::gmtime(&duration), "%T")
                      << " | Endpoint: " << endpoint->uri_
                      << ", Status: " << (req.status() == asio::error::success ? "Success" : "Error")
                      << std::endl;
        }
    }

private:
