#include <atomic>
#include <iostream>
#include <fstream>
#include <sstream>
#include <mutex>
#include <thread>
#include <vector>

namespace LoggingSystem {
    enum class LogLevel { DEBUG, INFO, WARNING, ERROR, CRITICAL };
    struct Destination {
        std::ostream* stream;
        bool is_open;

        explicit Destination(std::ostream& o) : stream(&o), is_open(true) {}

        void close() {
            if (is_open) {
                is_open = false;
                stream->flush();
                stream->close();
            }
        }
    };

    class Logger {
    public:
        static std::atomic<LogLevel> log_level;
        static Destination* default_destination;
        static std::vector<Destination*> destinations;
        static std::mutex mtx;

        Logger() {}
        ~Logger() {
            for (auto& dest : destinations) {
                dest->close();
            }
        }

        static void add_destination(Destination* dest) {
            std::unique_lock<std::mutex> lock(mtx);
            destinations.push_back(dest);
        }

        static void log(LogLevel level, const std::string& msg) {
            if (level < log_level) return;

            std::ostringstream oss;
            oss << "[";
            switch (level) {
                case LogLevel::DEBUG: oss << "DEBUG] "; break;
                case LogLevel::INFO: oss << "INFO] "; break;
                case LogLevel::WARNING: oss << "WARNING] "; break;
                case LogLevel::ERROR: oss << "ERROR] "; break;
                case LogLevel::CRITICAL: oss << "CRITICAL] "; break;
            }
            oss << msg << "\n";

            std::unique_lock<std::mutex> lock(mtx);
            for (auto& dest : destinations) {
                if (dest->is_open) {
                    (*dest->stream) << oss.str();
                }
            }
        }
    };

    std::atomic<LogLevel> Logger::log_level = LogLevel::INFO;
    Destination* Logger::default_destination = new Destination(std::cout);
    Logger::destinations = { default_destination };
    Logger::mtx = std::mutex();
} // namespace LoggingSystem
```

This code defines a `Logger` class in the `LoggingSystem` namespace, which implements the required features. The log level and default destination are defined as static member variables, and additional destinations can be added at runtime using the `add_destination()` function. The destructor ensures that all attached destinations are properly closed when the logger is destroyed.

To handle high-throughput messages efficiently, a mutex lock is used to ensure thread safety, but note that this implementation may not scale for extremely high message rates in multithreaded environments. You may want to consider using an asynchronous approach or other optimization techniques for heavy loads.']

['```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Text;

public static SqlDataReader ExecuteDynamicQuery(string connectionString, string baseCommand, IDictionary<string, string> conditions, List<object> parameters)
{
    using (SqlConnection sqlConnection = new SqlConnection(connectionString))
    {
        SqlCommand command = new SqlCommand();
        command.Connection = sqlConnection;
        command.CommandType = System.Data.CommandType.Text;

        // Build SQL query
        StringBuilder builder = new StringBuilder();
        builder.Append(baseCommand);

        int parameterIndex = 0;
        foreach (KeyValuePair<string, string> condition in conditions)
        {
            if (parameterIndex < parameters.Count)
            {
                builder.Append(" AND ");
                builder.Append(condition.Key);
                builder.Append(" = @param");
                builder.Append(parameterIndex + 1);
                command.Parameters.AddWithValue($"@param{parameterIndex + 1}", parameters[parameterIndex]);
                parameterIndex++;
            }
            else
            {
                builder.Append(" AND ");
                builder.Append(condition.Key);
                builder.Append(" = @param");
                command.Parameters.AddWithValue($"@param{parameterIndex}", DBNull.Value);
            }
        }

        // Execute the SQL query and return the result set
        sqlConnection.Open();
        SqlDataReader reader = command.ExecuteReader();

        return reader;
    }
}
