```javascript
const express = require('express');
const router = express.Router();
const mongoose = require('mongoose');
const authMiddleware = require('./auth-middleware');

// Resource Model
const ResourceSchema = new mongoose.Schema({
  // resource fields here
});
const Resource = mongoose.model('Resource', ResourceSchema);

router.use(authMiddleware);

router.patch('/bulkUpdate', async (req, res) => {
    const ids = req.body.ids;
    const updates = req.body.updates;

    if (!Array.isArray(ids) || !ids.every(id => mongoose.Types.ObjectId.isValid(id))) {
        return res.status(400).json({ error: 'Invalid resource ids.' });
    }

    const updatedResources = [];
    const failedResources = [];

    for (let id of ids) {
        try {
            const resource = await Resource.findByIdAndUpdate(id, updates, { new: true });
            if (resource) {
                updatedResources.push(resource);
            }
        } catch (err) {
            failedResources.push(id);
        }
    }

    res.json({
        successfulUpdates: updatedResources.length,
        failedUpdates: failedResources.length,
        updatedResources,
        failedResources
    });
});

module.exports = router;
```

In this example, we create an Express route for handling bulk updates to resources (REST API /bulkUpdate). The function accepts a list of resource ids and a set of updates to apply. We validate that the ids are valid ObjectIds using Mongoose's `mongoose.Types.ObjectId.isValid()`.

In this example, we use simple validation of the id array being non-empty and containing only valid ObjectIds. In a real-world application, you would want to implement more robust authorization checks before allowing bulk updates.

For the actual update operation, we iterate over the ids, trying to find each resource by its id using `Resource.findByIdAndUpdate()`. If the update is successful, the updated resource object is pushed into an array of successfully updated resources. Otherwise, the failed id is pushed into an array of failed ids.

At last, the function returns a JSON object summarizing the number of successful and failed updates along with the lists of updated and failed resources."]

