        _httpClient = httpClient;
    }

    public async Task<string> UpdateElementAsync(string sessionToken, string sectionId, string elementId, string updatedContent)
    {
        if (string.IsNullOrEmpty(sessionToken))
            throw new ArgumentNullException(nameof(sessionToken));

        if (string.IsNullOrEmpty(sectionId))
            throw new ArgumentNullException(nameof(sectionId));

        if (string.IsNullOrEmpty(elementId))
            throw new ArgumentNullException(nameof(elementId));

        if (string.IsNullOrEmpty(updatedContent))
            throw new ArgumentNullException(nameof(updatedContent));

        var requestUri = "api/updateElement";

        var validationResponse = await _httpClient.GetAsync($"{requestUri}/validateSession?token={sessionToken}");
        if (!validationResponse.IsSuccessStatusCode)
            throw new InvalidOperationException("Invalid or expired session token.");

        var permissionsResponse = await _httpClient.GetAsync($"{requestUri}/checkPermissions?sectionId={sectionId}&elementId={elementId}");
        if (!permissionsResponse.IsSuccessStatusCode)
            throw new UnauthorizedAccessException("User does not have permissions to update this element.");

        var data = new
        {
            SectionId = sectionId,
            ElementId = elementId,
            Content = updatedContent
        };

        var jsonData = JsonConvert.SerializeObject(data);
        var content = new StringContent(jsonData, Encoding.UTF8, "application/json");

        var response = await _httpClient.PutAsync(requestUri, content);
        if (response.IsSuccessStatusCode)
        {
            AuditLogger.LogUpdateActivity(sectionId, elementId, sessionToken);
            return "Page should be refreshed.";
        }
        else
        {
            throw new Exception($"Failed to update element: Status Code: {response.StatusCode}");
        }
    }
}
