async function runTests({ moduleName, testLabel, testFunction }) {
  try {
    const module = await import(moduleName);

    // Initialize testing framework environment
    const { testRunner } = await import('test-runner');
    testRunner.configure({ customAssert });

    // Reset mocking library after each test execution
    jest.resetAllMocks();

    let successfulTests = 0;
    let failedTests = 0;

    console.log(`Starting tests for module: ${moduleName}`);

    const runTest = async (testName) => {
      try {
        console.log(`Running test: ${testLabel} - ${testName}`);
        await testFunction();
        successfulTests++;
        console.log(`Test passed: ${testLabel} - ${testName}`);
      } catch (error) {
        failedTests++;
        console.error(`Test failed: ${testLabel} - ${testName}\nError: ${error.message}`);
      }
    };

    // Extract tests from the module
    const testCases = Object.values(module[testLabel]);

    for (const testCase of testCases) {
      await runTest(testCase.name);
    }

    return { totalTests: testCases.length, successfulTests, failedTests };
  } catch (error) {
    console.error(`Error while loading module: ${moduleName}\nError: ${error.message}`);
    throw error;
  }
}
