const renderWidgets = (widgetArray, sidebar) => {
  const widgetIds = new Set();

  widgetArray.forEach(widget => {
    const widgetId = `widget-${widgetIds.add(widget.id).value}`;
    const widgetDiv = document.createElement('div');
    widgetDiv.id = widgetId;
    widgetDiv.className = 'widget';
    widgetDiv.innerHTML = widget.content;

    sidebar.appendChild(widgetDiv);
  });

  // Implement an observation mechanism to detect updates in the widget array
  const observer = new MutationObserver((mutationsList, observer) => {
    for (let mutation of mutationsList) {
      if (mutation.type === 'added') {
        const addedWidget = mutation.addedNodes[0];
        renderWidget(addedWidget);
      }
    }
  });

  // Observe the widgetArray and call the renderWidget function for any new additions
  observer.observe(widgetArray, { childList: true });

  const renderWidget = (widget) => {
    if (widget instanceof HTMLElement && widget.tagName === 'DIV' && /widget-/.test(widget.id)) {
      widget.innerHTML = widget.innerHTML || widget.innerText;
    }
  };
};
