[" Here's a basic implementation of the described requirements using ES6 modules, Promises, and Map data structure. This solution supports asynchronous loading, error handling, dependency management, and order constraints. However, some aspects like concurrency control, resource constraints, scalability, modularity, and performance optimization would require additional optimizations and libraries to fully address the requirements.

```javascript
class ScriptLoader {
  constructor() {
    this.scripts = new Map();
  }

  addScript(id, src, dependencies) {
    const scriptPromise = fetch(src)
      .then(response => response.text())
      .then(scriptText => {
        // Process JSON metadata within the script if necessary
        this.scripts.set(id, { id, text: scriptText });

        return Promise.all(dependencies.map(this.addScript.bind(this)));
      })
      .then(() => this);

    return scriptPromise;
  }

  loadAndExecute(...ids) {
    return ids.reduce((promiseChain, id) => promiseChain.then(() => {
      const script = this.scripts.get(id);
      if (script) {
        // Execute the loaded script
        new Function(...script.text.match(/[^\n]*\n/g), ...script.text.match(/=([\s\S]+)?\n/g)).apply(null, arguments);
      } else {
        console.error(`Script ${id} failed to load or execute`);
      }
    }), this.addScript(...ids));
  }
}
```

Usage:

```javascript
const loader = new ScriptLoader();
loader.addScript('script1', 'path/to/script1.js', ['dependency1'])
       .then(() => loader.addScript('script2', 'path/to/script2.js', ['dependency2']))
       .then(() => loader.loadAndExecute('script1', 'script2'));
```

