["```typescript
import jwt from 'jsonwebtoken';
import cookieSession from 'cookie-session';

// Generate a new token with given payload and secret key
function generateToken(payload, secret) {
  return jwt.sign(payload, secret);
}

// Verify the token and check if it has expired
function verifyToken(token, secret) {
  try {
    return jwt.verify(token, secret);
  } catch (err) {
    return false;
  }
}

// Middleware function to handle sessions
function sessionMiddleware(req, res, next) {
  // Check for a valid session token and update session metadata as needed
  const session = req.cookies['sessionID'];

  if (!session) {
    // Generate a new token, set secure cookie and call next()
    const newSession = generateToken({ role: 'user' }, process.env.JWT_SECRET);
    res.cookie('sessionID', newSession, {
      httpOnly: true,
      secure: req.secure || req.get('x-forwarded-proto') === 'https',
      sameSite: 'none',
      maxAge: 86400000 // 1 day in milliseconds
    });
    req.session = newSession;
    next();
  } else {
    const isValid = verifyToken(session, process.env.JWT_SECRET);

    if (!isValid) {
      // Invalidate the current session and generate a new one
      res.clearCookie('sessionID');
      const newSession = generateToken({ role: 'user' }, process.env.JWT_SECRET);
      res.cookie('sessionID', newSession, {
        httpOnly: true,
        secure: req.secure || req.get('x-forwarded-proto') === 'https',
        sameSite: 'none',
        maxAge: 86400000 // 1 day in milliseconds
      });
      req.session = newSession;
    }

    req.sessionData = jwt.decode(session); // Update the session metadata based on decoded token data
    next();
  }
}
