['```php
function updateUserProfile($userId, $email, $phoneNumber, $subscriptionStatus) {
    try {
        // Connect to database
        $db = new PDO('mysql:host=localhost;dbname=my_database', 'username', 'password');

        // Prepare SQL statement for validation and update
        $stmt = $db->prepare("SELECT id, email, phone_number, subscription_status FROM users WHERE id = :userId");
        $stmt->bindParam(':userId', $userId);
        $stmt->execute();

        if ($stmt->rowCount() == 0) {
            throw new Exception("User does not exist.");
        }

        // Fetch user data for validation
        $user = $stmt->fetch(PDO::FETCH_ASSOC);

        // Validate email format
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new Exception("Invalid email format.");
        }

        // Check for existing email (except for the user's own email)
        $stmt = $db->prepare("SELECT id FROM users WHERE email = :email AND id != :userId");
        $stmt->bindParam(':email', $email);
        $stmt->execute();

        if ($stmt->rowCount() > 0) {
            throw new Exception("Email already exists.");
        }

        // Validate phone number format
        if (!preg_match("/^(\+\d{1,3}\s?)?((\(\d{3}\)|\d{3})[-.\s]?)(\d{3}[-.\s]?\d{4})$/", $phoneNumber)) {
            throw new Exception("Invalid phone number format.");
        }

        // Update user profile
        $stmt = $db->prepare("UPDATE users SET email = :email, phone_number = :phoneNumber, subscription_status = :subscriptionStatus WHERE id = :userId");
        $stmt->execute([
            ':email' => $email,
            ':phoneNumber' => $phoneNumber,
            ':subscriptionStatus' => $subscriptionStatus,
            ':userId' => $userId
        ]);

        // Log the changes
        logChanges($userId, 'Email', $user['email'], $email);
        logChanges($userId, 'Phone Number', $user['phone_number'], $phoneNumber);
        logChanges($userId, 'Subscription Status', $user['subscription_status'], $subscriptionStatus);

        // Return success message
        return "User profile updated successfully.";
    } catch (Exception $e) {
        // Log the exception
        logException($e->getMessage());

        // Return error message
        return $e->getMessage();
    }
}

function logChanges($userId, $field, $oldValue, $newValue) {
    try {
        // Connect to database
        $db = new PDO('mysql:host=localhost;dbname=my_database', 'username', 'password');

        // Prepare SQL statement for logging
        $stmt = $db->prepare("INSERT INTO log_changes (user_id, field, old_value, new_value) VALUES (:userId, :field, :oldValue, :newValue)");
        $stmt->execute([
            ':userId' => $userId,
            ':field' => $field,
            ':oldValue' => $oldValue,
            ':newValue' => $newValue
        ]);
    } catch (Exception $e) {
        // Handle exception here if needed
    }
}

function logException($message) {
    try {
        // Connect to database
        $db = new PDO('mysql:host=localhost;dbname=my_database', 'username', 'password');

        // Prepare SQL statement for logging exceptions
        $stmt = $db->prepare("INSERT INTO log_exceptions (message) VALUES (:message)");
        $stmt->execute([
            ':message' => $message
        ]);
    } catch (Exception $e) {
        // Handle exception here if needed
    }
}
```']

