#include <iostream>
#include <fstream>
#include <chrono>
#include <map>
#include <vector>
#include <random>
#include <ctime>

std::mt19937 rng(time(0)); // Initialize random number generator with current time seed

struct Attack {
    int id;
    int cooldown;
    int remaining_cooldown;
};

std::map<int, double> probabilities = {{1, 0.3}, {2, 0.25}, {3, 0.2}, {4, 0.15}, {5, 0.1}};
std::vector<Attack> attacks;
std::ofstream combat_log("combat_log.txt", std::ios::app);

void initializeAttacks() {
    for (auto const& [id, prob] : probabilities) {
        Attack a = {id, 0, 0};
        attacks.push_back(a);
    }
}

void updateCooldowns() {
    for (Attack& a : attacks) {
        if (a.remaining_cooldown > 0)
            --a.remaining_cooldown;
    }
}

void logAttack(int id, int cooldown) {
    combat_log << "Attack " << id << " used with a cooldown of " << cooldown << "\n";
}

void chooseAttack() {
    std::uniform_int_distribution<int> dist(1, attacks.size());
    int selected = dist(rng);
    Attack& attack = attacks[selected - 1];

    if (attack.remaining_cooldown > 0) {
        chooseAttack(); // Try again if current attack is still on cooldown
        return;
    }

    attack.id = selected;
    attack.remaining_cooldown = attack.cooldown;
    logAttack(attack.id, attack.cooldown);
}

void manageCombat() {
    updateCooldowns();
    chooseAttack();
}

int main() {
    initializeAttacks();

    while (true) { // Game loop
        manageCombat();
        std::this_thread::sleep_for(std::chrono::milliseconds(1000)); // Sleep for 1 second before next iteration
    }
}
