    it('should handle large datasets efficiently', async () => {
        const bigNums = Array.from({ length: 1e6 }, (_, i) => i + 1);
        const sumCallback = (acc, num) => acc + num;
        const result = await asyncReduce(bigNums, sumCallback, 0);
        assert.strictEqual(result, (1e6 * (1e6 + 1)) / 2); // Expected output: 500,000,030,000
    });

    it('should handle transient errors and retry the operation', async () => {
        const nums = [1, function () { throw new Error('transient') }, 3];
        const sumCallback = (acc, num) => acc + num;
        const result = await asyncReduce(nums, sumCallback, 0);
        assert.strictEqual(result, 4); // The second number is replaced by its value during retry
    });

    it('should handle a temporary data source failure and resume operation when available', async () => {
        const numsUrl = 'https://invalid-api.com/numbers';
        const sumCallback = (acc, num) => acc + num;
        const result = await asyncReduce(numsUrl, sumCallback, 0);
        assert.strictEqual(result, 0); // The operation should complete without errors when the data source is available again
    });

    it('should reject when a permanent error occurs', async () => {
        const nums = [1, function () { throw new Error('not transient') }, 3];
        assert.rejects(asyncReduce(nums, sumCallback, 0), /Failed to process array due to permanent error/);
    });
});
