#define MAX_VALUES 100

void log_error(const char *message) {
    fprintf(stderr, "[ERROR] : %s\n", message);
}

bool is_number(char *str) {
    int i;
    for (i = 0; str[i] != '\0'; ++i) {
        if (!isdigit(str[i])) return false;
    }
    return true;
}

int main(int argc, char **argv) {
    FILE *file;
    int *line_values = NULL;
    size_t num_values = 0;
    double average;

    if (argc != 2) {
        log_error("Usage: ./average <filename>");
        return -1;
    }

    file = fopen(argv[1], "r");
    if (!file) {
        log_error("Error opening file");
        return -1;
    }

    while (fscanf(file, "%d", &line_values[num_values]) == 1) {
        ++num_values;
        if (num_values >= MAX_VALUES) {
            log_error("Line contains too many values. Increase the limit in 'MAX_VALUES' macro.");
            return -1;
        }
    }

    if (feof(file)) {
        rewind(file);

        for (size_t i = 0; i < num_values; ++i) {
            printf("%d", line_values[i]);
            if (i < num_values - 3) printf(", ");
            else {
                average = ((double)(line_values[i - 3] + line_values[i - 2] + line_values[i - 1]) / 3);
                printf("%.2f", average);
                if (i != num_values - 1) printf(", ");
            }
        }
    } else {
        log_error("Error reading file");
        return -1;
    }

    fclose(file);
    free(line_values);

    return 0;
}
