typedef struct {
    int bits_per_sample;
    int sample_per_pixel;
    int extra_samples;
    EVP_CIPHER_CTX *cipher;
} ParseTIFFAndEncryptResult;

ParseTIFFAndEncryptResult parseTIFFAndEncrypt(const char *filename, const char *algorithm) {
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        printf("Error: Could not open file.\n");
        ParseTIFFAndEncryptResult result = {0};
        result.cipher = NULL;
        return result;
    }

    uint16_t sample_format;
    int samples_per_pixel = tifd_getfield(tif, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel);
    if (samples_per_pixel <= 0) {
        printf("Error: Invalid number of sample per pixel.\n");
        TiffClose(tif);
        ParseTIFFAndEncryptResult result = {0};
        result.cipher = NULL;
        return result;
    }

    int bits_per_sample = tifd_getfield(tif, TIFFTAG_SAMPLEFORMAT, &sample_format);
    if (bits_per_sample <= 0) {
        printf("Error: Invalid number of bits per sample.\n");
        TiffClose(tif);
        ParseTIFFAndEncryptResult result = {0};
        result.cipher = NULL;
        return result;
    }

    switch (bits_per_sample) {
        case 1:
        case 2:
        case 4:
        case 8:
        case 16:
            break;
        default:
            printf("Error: Unsupported number of bits per sample.\n");
            TiffClose(tif);
            ParseTIFFAndEncryptResult result = {0};
            result.cipher = NULL;
            return result;
    }

    int extra_samples = tifd_getfield(tif, TIFFTAG_EXTRASAMPLES, &extra_samples);
    if (extra_samples > 0) {
        uint16_t photometric_interpretaion[TIFF_MAX_EXTRASAMPLES];
        uint32_t sample_name[TIFF_MAX_EXTRASAMPLES];
        for (int i = 0; i < extra_samples; ++i) {
            if (!tifd_getfield(tif, TIFFTAG_EXTRASAMPLEFORMAT + i, &photometric_interpretaion[i]) ||
                !tifd_getfield(tif, TIFFTAG_EXTRASAMPLENAME + i, &sample_name[i])) {
                printf("Error: Could not get extra sample information.\n");
                TiffClose(tif);
                ParseTIFFAndEncryptResult result = {0};
                result.cipher = NULL;
                return result;
            }
        }
    }

    EVP_CIPHER_CTX *cipher;
    const EVP_CIPHER *cipher_algo = EVP_get_cipherbyname(algorithm);
    if (!cipher_algo) {
        printf("Error: Unsupported encryption algorithm.\n");
        TiffClose(tif);
        ParseTIFFAndEncryptResult result = {0};
        result.cipher = NULL;
        return result;
    }

    if (1 != EVP_CIPHER_init(&cipher, cipher_algo)) {
        printf("Error: Failed to initialize cipher.\n");
        TiffClose(tif);
        ParseTIFFAndEncryptResult result = {0};
        result.cipher = NULL;
        return result;
    }

    ParseTIFFAndEncryptResult result = {};
    result.bits_per_sample = bits_per_sample;
    result.sample_per_pixel = samples_per_pixel;
    result.extra_samples = extra_samples > 0 ? extra_samples : 0;
    result.cipher = cipher;
    TiffClose(tif);

    return result;
}
