#include <openssl/crypto.h>
#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <openssl/rand.h>
#include <string.h>
#include <stddef.h>
#include <stdio.h>

static const size_t AES_KEY_SIZE = 32;
static const size_t IV_SIZE = 16;
static const size_t MIN_PASSWORD_LENGTH = 8;
static const size_t MAX_PASSWORD_LENGTH = 64;

typedef struct AESContext {
    AES_KEY key;
    unsigned char iv[IV_SIZE];
    EVP_CIPHER_CTX *ctx;
} AESContext;

AESContext* aes_context_new(const unsigned char *password, size_t password_length) {
    if (password_length < MIN_PASSWORD_LENGTH || password_length > MAX_PASSWORD_LENGTH) {
        fprintf(stderr, "Error: Password length must be between %zu and %zu\n", MIN_PASSWORD_LENGTH, MAX_PASSWORD_LENGTH);
        return NULL;
    }

    AESContext *ctx = OPENSSL_malloc(sizeof(AESContext));
    if (!ctx) {
        fprintf(stderr, "Error: Allocation failed\n");
        return NULL;
    }

    EVP_MD_CTX md_ctx;
    EVP_MD_CTX_init(&md_ctx);

    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    if (!cipher) {
        fprintf(stderr, "Error: Could not find AES-256-CBC cipher\n");
        OPENSSL_free(ctx);
        return NULL;
    }

    int key_ok = 0;
    unsigned char pbe_key[AES_KEY_SIZE];
    if (PKCS5_PBKDF2_HMAC((EVP_CIPHER *)cipher, pbe_key, AES_KEY_SIZE, password, password_length, NULL, 1, &key_ok, &md_ctx)) {
        EVP_MD_CTX_cleanup(&md_ctx);
        fprintf(stderr, "Error: PKCS5_PBKDF2_HMAC failed\n");
        OPENSSL_free(ctx);
        return NULL;
    }
    EVP_MD_CTX_cleanup(&md_ctx);

    if (key_ok) {
        memcpy(ctx->key.d, pbe_key, AES_KEY_SIZE);
        RAND_bytes(ctx->iv, IV_SIZE);

        ctx->ctx = EVP_CIPHER_CTX_new();
        if (!ctx->ctx) {
            fprintf(stderr, "Error: Could not allocate EVP_CIPHER_CTX\n");
            OPENSSL_free(ctx);
            return NULL;
        }

        int init_ok = 0;
        if (1 != EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, ctx->key.d, ctx->iv)) {
            fprintf(stderr, "Error: EVP_EncryptInit_ex failed\n");
            EVP_CIPHER_CTX_free(ctx->ctx);
            OPENSSL_free(ctx);
            return NULL;
        }
        init_ok = 1;

        if (1 != EVP_EncryptFinal_ex(ctx->ctx, NULL, &init_ok)) {
            fprintf(stderr, "Error: EVP_EncryptFinal_ex failed\n");
            EVP_CIPHER_CTX_free(ctx->ctx);
            OPENSSL_free(ctx);
            return NULL;
        }
        if (!init_ok) {
            fprintf(stderr, "Error: Initialization failed\n");
            EVP_CIPHER_CTX_free(ctx->ctx);
            OPENSSL_free(ctx);
            return NULL;
        }
    } else {
        fprintf(stderr, "Error: PBKDF2 key derivation failed\n");
        OPENSSL_free(ctx);
        return NULL;
    }

    return ctx;
}

void aes_context_free(AESContext *ctx) {
    if (!ctx) return;

    EVP_CIPHER_CTX_free(ctx->ctx);
    OPENSSL_clear_free(ctx, sizeof(AESContext));
}
```

With this implementation, you can create an AES-256-CBC cipher context using the given password and clean it up when no longer needed. The function will validate the password length and use PBKDF2 with SHA-256 for key derivation.']

