int convert_png_to_tiff(char *input_path, char *output_path, char *filter) {
    MAGIC_FILE magic_file;
    mag_open(&magic_file);

    DIR *dir = opendir(input_path);
    if (!dir) {
        perror("opendir");
        return 1;
    }

    struct dirent *entry;
    int file_count = 0;
    char output_file[1024];

    while ((entry = readdir(dir)) != NULL) {
        if (magic_file.last_errno == 0 && magic_file.mime_o & MAGIC_PNG) {
            strcpy(output_file, output_path);
            sprintf(&output_file[strlen(output_path)], "/%s", entry->d_name);

            if (access(output_file, F_OK)) {
                FILE *tiff_file = tifffile_create(output_file);
                if (!tiff_file) {
                    perror("tifffile_create");
                    return 1;
                }

                char png_path[strlen(input_path) + strlen(entry->d_name)];
                strcpy(png_path, input_path);
                sprintf(&png_path[strlen(input_path)], "/%s", entry->d_name);

                if (png_read_image(png_path, NULL, NULL, NULL)) {
                    fprintf(stderr, "Error reading PNG file: %s\n", png_errptr(png_get_errorPtr()));
                    return 1;
                }

                tifffile_write_image(tiff_file, NULL);
                fclose(tiff_file);

                file_count++;
            }
        }
    }
    closedir(dir);

    if (file_count == 0) return 1;
    return 0;
}
