using System;
using System.Data;
using System.IO;
using CsvHelper;
using CsvHelper.Configuration;

public class CustomCsvReader
{
    public IDataReader ReadCsv(string filePath, params string[] columnNames)
    {
        var config = new CsvConfiguration(CultureInfo.InvariantCulture);
        using (var reader = new StreamReader(filePath))
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException("The specified file does not exist.", filePath);

            using (var csv = new CsvReader(reader, config))
            {
                if (!csv.ReadHeader())
                    throw new Exception("Failed to read header from the provided CSV file.");

                var matchingColumnCount = columnNames.Intersect(csv.FieldHeaders).Count();
                if (matchingColumnCount != columnNames.Length)
                    throw new ArgumentException("Provided column names do not match the available columns in the CSV file.");

                var data = new DataTable();
                csv.Configuration.HasHeaderRecord = true;
                csv.Configuration.RegisterClassMap<CustomClassMap>(config);
                data.Load(csv);

                return data.CreateDataReader();
            }
        }
    }
}

public class CustomClassMap : ClassMap<MyCustomObject>
{
    public CustomClassMap()
    {
        Map(x => x.Column1).Name("Column1");
        Map(x => x.Column2).Name("Column2");
        // Add more column mappings as needed...
    }
}

public class MyCustomObject
{
    public string Column1 { get; set; }
    public string Column2 { get; set; }
    // Add other properties for your specific columns...
}
