    public class MD5StreamProcessor
    {
        private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);
        private readonly List<byte[]> _chunks = new List<byte[]>();
        private byte[] _hashedChunk;

        public async Task ProcessAsync(IAsyncEnumerable<char> input)
        {
            await foreach (var chunk in SplitStreamIntoChunks(input))
            {
                await _semaphore.WaitAsync();
                try
                {
                    ProcessChunk(chunk);
                }
                finally
                {
                    _semaphore.Release();
                }
            }

            if (_hashedChunk != null)
            {
                // Here you can integrate the hashed chunk into your logging service or any other process.
            }
        }

        private void ProcessChunk(byte[] chunk)
        {
            using (var md5 = MD5.Create())
            {
                _hashedChunk = md5.ComputeHash(chunk);
            }

            _chunks.Add(_hashedChunk);
            _hashedChunk = null;
        }

        private IEnumerable<IEnumerable<char>> SplitStreamIntoChunks(IAsyncEnumerable<char> input)
        {
            const int chunkSize = 8192; // Adjust this value based on your requirements.

            using var md5 = MD5.Create();
            byte[] buffer = new byte[chunkSize];
            var bufferAsCharArray = Encoding.UTF8.GetChars(buffer);

            while (await input.MoveNext())
            {
                int index = 0;

                foreach (var character in bufferAsCharArray)
                {
                    if (index >= chunkSize)
                        yield return bufferAsCharArray.Take(index);

                    buffer[index++] = (byte)character;

                    if (index >= chunkSize)
                        yield return bufferAsCharArray.Take(index);
                }
            }
        }
    }
}
