using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptor
{
    private readonly HashAlgorithmName _paddingScheme;
    private readonly int _batchSize;

    public AesCbcDecryptor(HashAlgorithmName paddingScheme = null, int batchSize = 1000)
    {
        _paddingScheme = paddingScheme ?? HashAlgorithmName.PKCS7;
        _batchSize = Math.Max(_batchSize, 1);
        _batchSize = Math.Min(_batchSize, 10000);
    }

    public byte[] Decrypt(byte[] cipherText, byte[] key, byte[] iv)
    {
        if (cipherText == null || key == null || iv == null)
            throw new ArgumentNullException();

        var encoder = new AesCryptoServiceProvider();
        encoder.Key = key;
        encoder.IV = iv;

        var paddingAlgorithm = CreatePaddingTransform(_paddingScheme);
        ICryptoTransform decryptor = encoder.CreateDecryptor(encoder.Key, encoder.IV);
        var decryptorWithPadding = CryptoHelper.CreateCombinedTransform(decryptor, paddingAlgorithm);

        using (var ms = new MemoryStream(cipherText))
        {
            var output = new MemoryStream();

            byte[] buffer = new byte[_batchSize];
            int bytesRead;

            do
            {
                bytesRead = ms.Read(buffer, 0, buffer.Length);
                decryptorWithPadding.TransformBlock(buffer, 0, bytesRead, output.ToArray(), 0);
                output.Position = 0;

                // Check IV integrity only for the first batch
                if (ms.Position == 0 && output.GetBuffer().Length >= 16)
                {
                    var decryptedIV = output.GetBuffer().Take(16).ToArray();
                    if (!Enumerable.SequenceEqual(decryptedIV, iv))
                        throw new InvalidDataException("Invalid IV");
                }
            } while (bytesRead > 0);

            return output.ToArray();
        }
    }

    private ICryptoTransform CreatePaddingTransform(HashAlgorithmName paddingScheme)
    {
        switch (paddingScheme)
        {
            case HashAlgorithmName.PKCS7:
                return new PKCS7PaddingTransform();
            case HashAlgorithmName.PKCS5:
                return new PKCS5PaddingTransform();
            default:
                throw new ArgumentException("Unsupported padding scheme");
        }
    }
}

public class PKCS7PaddingTransform : PaddingTransform
{
    protected override int ProcessFinalBlock(byte[] input, int inputOffset, int length)
    {
        if (length > 0)
        {
            int blockSize = AlgorithmName.BlockSizeValue;
            int padding = blockSize - ((input[inputOffset] & 0xff) % blockSize);
            Array.Resize(ref input, input.Length + padding);
            for (int i = input.Length - padding; i < input.Length; i++)
                input[i] = (byte)padding;
        }
        return length;
    }
}

public class PKCS5PaddingTransform : PaddingTransform
{
    protected override int ProcessFinalBlock(byte[] input, int inputOffset, int length)
    {
        if (length > 0)
        {
            int blockSize = AlgorithmName.BlockSizeValue;
            int padding = blockSize - ((input[inputOffset] & 0xff) % blockSize);
            if (padding > padding)
                padding = blockSize;
            Array.Resize(ref input, input.Length + padding);
            for (int i = input.Length - padding; i < input.Length; i++)
                input[i] = (byte)padding;
        }
        return length;
    }
}
