    public static dynamic LoadData<T>(string filePath) where T : new()
    {
        var options = new JsonSerializerOptions
        {
            Converters =
            {
                new JsonConverter<Type>()
                {
                    Write = (writer, type) => writer.WriteString(type.AssemblyQualifiedName),
                    Read = (reader, _) =>
                    {
                        var typeName = reader.GetString();
                        var assembly = typeof(Deserializer).GetTypeInfo().Assembly;
                        var type = assembly.GetTypes().FirstOrDefault(t => t.AssemblyQualifiedName == typeName);
                        return Activator.CreateInstance(type);
                    }
                },
            }
        };

        if (!File.Exists(filePath)) throw new FileNotFoundException("Data file does not exist", filePath);

        using var stream = new FileStream(filePath, FileMode.Open);
        var jsonDocument = JsonDocument.FromUtf8Stream(stream);

        if (jsonDocument.RootElement.GetPropertyName() != "data") throw new Exception("Invalid data file format");

        dynamic result = new List<dynamic>();
        foreach (var element in jsonDocument.RootElement.GetProperty("data").EnumerateArray())
        {
            result.Add(JsonSerializer.Deserialize<object>(element.GetRawText(), options));
        }

        return result;
    }
}
