using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Bluebird;
using Logger = Serilog.ILogger; // Assuming you're using Serilog for logging

public class FileUploaderRandom
{
    private readonly Logger _logger;
    private readonly SemaphoreSlim _semaphore;
    private float _min, _max;
    private List<Tuple<float, float>> _ranges = new List<Tuple<float, float>>();

    public FileUploaderRandom(Logger logger)
    {
        _logger = logger;
        _semaphore = new SemaphoreSlim(1);
        SetRange(0f, 100f);
    }

    public void SetRange(float min, float max)
    {
        ValidateRange(min, max);

        lock (_ranges)
        {
            _ranges.RemoveAll(x => ContainsRange(x.Item1, x.Item2, min, max));
            _min = min;
            _max = max;
            _ranges.Add(new Tuple<float, float>(_min, _max));
        }
    }

    private bool ContainsRange(float checkMin, float checkMax, float existingMin, float existingMax)
    {
        return ((existingMin <= checkMin && existingMax >= checkMax) || (existingMin < checkMin && checkMax < existingMax));
    }

    private void ValidateRange(float min, float max)
    {
        if (min > max)
            throw new ArgumentOutOfRangeException(nameof(max), "The maximum value must be greater than the minimum value.");
    }

    public T GetRandom<T>(Func<Random, T> randomGenerator)
    {
        Random random = new Random((int)(_min + (_max - _min) * RandomSource.NextDouble()));
        return randomGenerator(random);
    }

    private int RandomInt() => (int)GetRandom(x => x.Next(_min, _max + 1));
    private float RandomFloat() => GetRandom(x => x.NextSingle(_min, _max + 1));

    public string ToString()
    {
        return $"Min: {_min}, Max: {_max}";
    }

    public async Task<string> UploadFile(string url)
    {
        await _semaphore.WaitAsync();
        try
        {
            var uploadedUrl = await FileUploader.UploadAsync(url);
            _logger.Information("File has been successfully uploaded.");
            return uploadedUrl;
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "An error occurred during file upload.");
            throw;
        }
        finally
        {
            _semaphore.Release();
        }
    }
}
