const { exec } = require('child_process');
const path = require('path');
const urlParse = require('url').parse;

function executeShellCommand(command, callback) {
  const sanitizedCommand = sanitizeInput(command);

  exec(sanitizedCommand, (error, stdout, stderr) => {
    if (error) {
      console.log(`exec error: ${error}`);
      return callback({ error: 'Error executing command' });
    }

    console.log(`stdout: ${stdout}`);
    console.log(`stderr: ${stderr}`);

    if (!callback) {
      // If no callback is provided, just log the results and don't return anything
      return;
    }

    callback({ stdout, stderr });
  });
}

function sanitizeInput(input) {
  const parsedUrl = urlParse(input);
  if (!parsedUrl.protocol || !parsedUrl.pathname) {
    throw new Error('Invalid command input');
  }

  return path.normalize(`/bin/${parsedUrl.pathname}`);
}
```

