    void* Packet;
} FrameHeader;

struct FramePool {
    FrameHeader* frames;
    size_t capacity;
    size_t size;
};

struct FramePool* createFramePool(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;
    struct FramePool* pool = malloc(sizeof(struct FramePool));
    if (!pool) return NULL;
    pool->frames = calloc(initial_capacity, sizeof(FrameHeader));
    if (!pool->frames) {
        free(pool);
        return NULL;
    }
    pool->capacity = initial_capacity;
    pool->size = 0;
    return pool;
}

void destroyFramePool(struct FramePool* pool) {
    if (pool) {
        for (size_t i = 0; i < pool->size; ++i) {
            free((FrameHeader*)pool->frames[i].Packet);
        }
        free(pool->frames);
        free(pool);
    }
}

void* createPacket(size_t payload_length) {
    if (payload_length == 0) return NULL;
    void* packet = malloc(payload_length + sizeof(size_t)); // size_t for payload length
    if (!packet) return NULL;
    ((size_t*)packet)[0] = payload_length;
    return packet;
}

