#include <sys/mman.h> // For posix_memalign

typedef struct Node {
    void *offsets;
    void *keys;
    void *records;
    size_t num_records;
    struct Node *next;
} Node;

typedef struct Record {
    int value;
} Record;

Node* create_list(size_t offset_count, size_t key_count, size_t record_count, size_t record_size) {
    if (!offset_count || !key_count || !record_count || record_size < sizeof(Record)) {
        perror("Invalid input");
        return NULL;
    }

    Node *head = malloc(sizeof(Node));
    if (!head) {
        perror("Failed to allocate memory for head node");
        return NULL;
    }

    if (posix_memalign(head->offsets, 64, offset_count * sizeof(long))) { // 64 bytes alignment for performance reasons
        perror("Failed to align memory for offsets");
        free(head);
        return NULL;
    }

    if (posix_memalign(head->keys, 64, key_count * sizeof(int))) {
        perror("Failed to align memory for keys");
        free(head->offsets);
        free(head);
        return NULL;
    }

    if (posix_memalign(head->records, 64, record_count * record_size)) {
        perror("Failed to align memory for records");
        free(head->keys);
        free(head->offsets);
        free(head);
        return NULL;
    }

    head->num_records = record_count;
    head->next = NULL;

    // Initialize records with random values
    Record *record_ptr = head->records;
    for (size_t i = 0; i < record_count; ++i) {
        *(int*)(record_ptr + i) = rand() % INT_MAX;
    }

    return head;
}

void free_list(Node *head) {
    if (!head) {
        return;
    }

    Node *current = head, *next;
    while (current) {
        next = current->next;
        free(current->offsets);
        free(current->keys);
        free(current->records);
        free(current);
        current = next;
    }
}

