typedef struct {
    AES_KEY cipher;
    char *filename;
} SecureFileContext;

SecureFileContext* securelyInitializeAndRenameFile(const char *password, const char *original_filename) {
    size_t password_len = strlen(password);

    if (password_len < 8 || password_len > 64) {
        fprintf(stderr, "Error: Password length must be between 8 and 64 characters.\n");
        return NULL;
    }

    uint8_t key[AES_BLOCK_SIZE];
    uint8_t salt[SHA256_DIGEST_LENGTH] = {0};
    const EVP_CIPHER_CTX *cipher = EVP_aes_256_cbc();
    EVP_CIPHER_CTX *ctx = EVP_CTX_new();

    if (!pbkdf2(EVP_sha256(), password, password_len, salt, NULL, 100000, AES_BLOCK_SIZE, key)) {
        fprintf(stderr, "Error: Failed to derive encryption key using PBKDF2.\n");
        EVP_CTX_free(ctx);
        return NULL;
    }

    if (AES_set_encrypt_key(key, AES_BLOCK_SIZE, &ctx->encrypt) <= 0 ||
        AES_get_ivlen(ctx->cipher) != 16) {
        fprintf(stderr, "Error: Invalid key or IV length.\n");
        EVP_CTX_free(ctx);
        return NULL;
    }

    SecureFileContext *context = malloc(sizeof(SecureFileContext));
    if (!context) {
        fprintf(stderr, "Error: Failed to allocate memory for the context.\n");
        EVP_CTX_free(ctx);
        return NULL;
    }

    context->filename = rename_file(original_filename);
    if (!context->filename) {
        free(context);
        EVP_CTX_free(ctx);
        return NULL;
    }

    context->cipher = *ctx;
    return context;
}

char* rename_file(const char *original_filename) {
    // Derive the number of digits and file type from the original filename.
    size_t len = strlen(original_filename);
    int file_type = 0;
    int digit_count = 0;
    for (size_t i = 0; i < len; ++i) {
        if (isdigit(original_filename[i])) {
            ++digit_count;
        } else if (isalpha(original_filename[i]) && !file_type) {
            file_type = original_filename[i];
        }
    }

    char num_str[digit_count + 1] = {0};
    char new_filename[256] = {0};
    int index = 0;
    for (size_t i = 0; i < len; ++i) {
        if (isdigit(original_filename[i])) {
            num_str[index++] = original_filename[i];
        } else if (!file_type) {
            new_filename[index++] = original_filename[i];
        }
    }
    sprintf(&new_filename[index], ".enc%s", num_str);
    strcat(&new_filename[index + strlen(num_str)], file_type ? &file_type : "");

    return new_filename;
}
```

