#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int id;
    double value;
    int metadata;
} DataPoint;

struct Whitelist {
    size_t size;
    int *ids;
};

typedef struct ProcessData {
    pthread_mutex_t mutex;
    double moving_average;
    double window_sum;
    size_t window_count;
    size_t processed_data;
    double max_moving_average;
    int max_id;
    struct Whitelist whitelist;
    time_t last_discard_time;
} ProcessData;

void init_whitelist(struct Whitelist *wl, size_t size, ...) {
    va_list args;
    wl->size = size;
    wl->ids = malloc(wl->size * sizeof(int));

    va_start(args, size);
    for (size_t i = 0; i < size; ++i) {
        wl->ids[i] = va_arg(args, int);
    }
    va_end(args);
}

ProcessData init_process_data() {
    ProcessData pd;
    pd.moving_average = 0.0;
    pd.window_sum = 0.0;
    pd.window_count = 0;
    pd.processed_data = 0;
    pd.max_moving_average = -1.0 / 0.0;
    pd.max_id = -1;

    pthread_mutex_init(&pd.mutex, NULL);

    return pd;
}

int is_valid(const ProcessData *pd, const DataPoint *dp) {
    if (dp->timestamp < pd->last_discard_time)
        return 0;

    if (dp->value < pd->whitelist.ids[0] || dp->value > pd->whitelist.ids[pd->whitelist.size - 1])
        return 0;

    for (size_t i = 0; i < pd->whitelist.size; ++i) {
        if (dp->id == pd->whitelist.ids[i])
            return 0;
    }
    return 1;
}

void update_process_data(ProcessData *pd, const DataPoint *dp) {
    pthread_mutex_lock(&pd->mutex);
    if (is_valid(pd, dp)) {
        double delta = dp->timestamp - pd->last_discard_time;
        if (delta > 60.0) {
            pd->last_discard_time += 60.0;
        }

        if (dp->timestamp > pd->last_discard_time + 30.0) {
            pd->window_sum -= pd->moving_average * pd->window_count;
            pd->window_count = 0;
        }

        pd->window_sum += dp->value;
        ++pd->window_count;
        ++pd->processed_data;

        if (dp->value > pd->max_moving_average) {
            pd->max_moving_average = dp->value;
            pd->max_id = dp->id;
        }
    }
    pthread_mutex_unlock(&pd->mutex);
}

double process(ProcessData *pd, const DataPoint *dp) {
    update_process_data(pd, dp);

    if (pd->window_count >= 30.0 / 60.0) {
        double moving_average = pd->window_sum / pd->window_count;
        pd->moving_average = moving_average;
        pd->window_sum -= pd->moving_average * pd->window_count;
        pd->window_count = 0;
    }

    return pd->max_moving_average;
}
