typedef struct OctreeNode {
    struct OctreeNode* children[8];
    bool isLeaf;
    int minID, maxID;
    double sum, count;
    time_t oldest;
} OctreeNode;

OctreeNode* root = NULL;
int capacity, featureSize, numLeaves, windowSize, whitelistSize;
double* whitelistIDs;
double minValue, maxValue;
time_t sessionStart;
int processedCount, maxMA;
pthread_mutex_t mutex;

void initOctree(int featureSize, int numLeaves) {
    root = malloc(sizeof(OctreeNode));
    memset(root, 0, sizeof(OctreeNode));
    root->isLeaf = true;
    this->capacity = (1 << numLeaves);
    buildOctree(root, featureSize, 0);
}

void buildOctree(OctreeNode* node, int depth, int index) {
    if (depth == depth - 1) {
        node->isLeaf = true;
        return;
    }

    for (int i = 0; i < 8; ++i) {
        node->children[i] = malloc(sizeof(OctreeNode));
        memset(node->children[i], 0, sizeof(OctreeNode));
        buildOctree(node->children[i], depth - 1, (index << 3) | i);
    }
}

void insertDataPoint(DataPoint dp) {
    pthread_mutex_lock(&mutex);
    time_t now = time(NULL);

    if ((now - dp.timestamp) > 60) goto discard;

    OctreeNode* node = root;
    int featureIndex = (dp.value / featureSize) % capacity;

    while (featureIndex >= capacity) featureIndex -= capacity;

    for (int i = 0; i < depth(node, featureIndex); ++i) {
        node = node->children[bitIndex(i)];
    }

    if (node->isLeaf && !inWhitelist(dp.id)) goto discard;

    updateNode(node, dp);

discard:
    pthread_mutex_unlock(&mutex);
}

int depth(OctreeNode* node, int featureIndex) {
    for (int i = 0; i < 8; ++i) {
        if (!node->children[i]) return -1;
        if (bitIndex(featureIndex) == i) return 1;
        if (depth(node->children[i], featureIndex) >= 0) return 1 + depth(node->children[i], featureIndex);
    }
    return -1;
}

int bitIndex(int index) {
    return index >> 3;
}

double movingAverage() {
    pthread_mutex_lock(&mutex);
    double sum = 0;
    OctreeNode* node = root;
    for (int i = 0; i < depth(node, windowSize % capacity); ++i) {
        node = node->children[bitIndex(i)];
        sum += node->sum / node->count;
    }
    pthread_mutex_unlock(&mutex);
    return sum;
}

int* findMaxMA() {
    pthread_mutex_lock(&mutex);
    int maxID = -1, maxCount = 0;
    OctreeNode* node = root;
    for (int i = 0; i < depth(node, windowSize % capacity); ++i) {
        node = node->children[bitIndex(i)];
        if (node->sum > maxCount * node->count) {
            maxID = node->id;
            maxCount = node->count;
        }
    }
    pthread_mutex_unlock(&mutex);
    return &maxID;
}

bool inWhitelist(int id) {
    for (int i = 0; i < whitelistSize; ++i) {
        if (id == whitelistIDs[i]) return true;
    }
    return false;
}

void updateNode(OctreeNode* node, DataPoint dp) {
    pthread_mutex_lock(&mutex);

    if (!node->isLeaf && dp.value < minValue || dp.value > maxValue) goto skip;

    if (dp.timestamp > node->oldest) node->oldest = dp.timestamp;
    node->sum += dp.value;
    ++(node->count);

skip:
    if (node->isLeaf) return;

    int featureIndex = (dp.value / featureSize) % capacity;
    for (int i = 0; i < 8; ++i) {
        if (!node->children[i]) continue;
        if (bitIndex(featureIndex) == i) updateNode(node->children[i], dp);
    }

    pthread_mutex_unlock(&mutex);
}

