    private $customAlgo = null;
    private $checksums = [];
    private $logger;

    public function __construct($config = []) {
        if (isset($config['charset'])) {
            $this->defaultCharset = $config['charset'];
        }

        if (isset($config['hashAlgorithm'])) {
            $this->hashAlgorithm = $config['hashAlgorithm'];
        }

        if (isset($config['saltEnabled'])) {
            $this->saltEnabled = (bool) $config['saltEnabled'];
        }

        if (isset($config['customAlgo'])) {
            $this->customAlgo = $config['customAlgo'];
        }

        if (isset($config['checksums'])) {
            $this->checksums = $config['checksums'];
        }

        $this->logger = new MyLogger(); // Replace 'MyLogger' with your desired logging class or method.
    }

    public function generateRandomString($length, $charset = null) {
        if ($charset === null) {
            $charset = $this->defaultCharset;
        }

        $chars = $this->charsets[$charset];
        $randomString = '';

        for ($i = 0; $i < $length; $i++) {
            $randomString .= $chars[rand(0, strlen($chars) - 1)];
        }

        if ($this->checksums && array_key_exists($randomString, $this->checksums)) {
            throw new Exception("Generated string has an invalid checksum.");
        }

        return $randomString;
    }

    public function generateHash($password) {
        if ($this->customAlgo) {
            return call_user_func($this->customAlgo, $password);
        }

        return hash($this->hashAlgorithm . ($this->saltEnabled ? 'salt' : ''), $password);
    }

    public function validateIntegrity($string, $checksum) {
        if (!isset($this->checksums[$string])) {
            $this->checksums[$string] = sha1($string);
        }

        return hash_equals($this->checksums[$string], $checksum);
    }

    public function enableSalt() {
        $this->saltEnabled = true;
    }

    public function setCustomAlgo($callback) {
        $this->customAlgo = $callback;
    }
}
