#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

// Custom types and constants
typedef enum { HEADER, TYPE_ID, LENGTH, DATA } EntryType;
typedef struct ResourceBundle* ResourceBundlePtr;
struct ResourceBundle {
    size_t num_items;
    void** items;
    size_t header_size;
};

typedef struct CryptoConfig {
    const char* character_set;
    const char* hash_algorithm;
} CryptoConfig;

// Custom functions and components
ResourceBundlePtr load_resource_bundle(const char* filepath, CryptoConfig config);
size_t generate_random_string(size_t length, const char* character_set);
char* hashed_password(const char* password, const char* algorithm);
void integrate_metadata_source(CryptoConfig* config, const char* url);
void configure_cryptography(CryptoConfig* config, bool speed_priority);

// Thread-safe logging function
void log_message(const char* message);

ResourceBundlePtr load_resource_bundle(const char* filepath, CryptoConfig config) {
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open resource file");
        return NULL;
    }

    struct stat file_stat;
    fstat(fd, &file_stat);

    ResourceBundlePtr bundle = mmap(NULL, file_stat.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (bundle == MAP_FAILED) {
        perror("Failed to map resource file");
        close(fd);
        return NULL;
    }

    size_t header_size = *((size_t*)bundle);
    if (header_size != sizeof(size_t)) {
        fprintf(stderr, "Invalid resource bundle header size\n");
        munmap(bundle, file_stat.st_size);
        close(fd);
        return NULL;
    }

    ResourceBundlePtr result = malloc(sizeof(struct ResourceBundle));
    if (!result) {
        fprintf(stderr, "Out of memory allocating resource bundle\n");
        munmap(bundle, file_stat.st_size);
        close(fd);
        return NULL;
    }

    result->header_size = header_size;
    result->num_items = 0;
    result->items = NULL;

    char* current_position = (char*)bundle + header_size;
    while ((current_position - bundle) < file_stat.st_size) {
        size_t entry_type = *((const size_t*)current_position);
        if (entry_type >= HEADER || entry_type > DATA) {
            fprintf(stderr, "Malformed resource bundle entry\n");
            free(result);
            munmap(bundle, file_stat.st_size);
            close(fd);
            return NULL;
        }

        size_t* data = NULL;
        void** item = NULL;
        switch (entry_type) {
            case HEADER:
                break;
            case TYPE_ID:
                data = malloc(sizeof(size_t));
                if (!data) {
                    fprintf(stderr, "Out of memory allocating data for type ID\n");
                    free(result);
                    munmap(bundle, file_stat.st_size);
                    close(fd);
                    return NULL;
                }
                memcpy(data, current_position + sizeof(size_t), sizeof(size_t));
                break;
            case LENGTH:
                if (!data) {
                    fprintf(stderr, "Missing data for length entry\n");
                    free(data);
                    free(result);
                    munmap(bundle, file_stat.st_size);
                    close(fd);
                    return NULL;
                }
                item = malloc((*data + sizeof(size_t)) * 2);
                if (!item) {
                    fprintf(stderr, "Out of memory allocating item for length entry\n");
                    free(data);
                    free(result);
                    munmap(bundle, file_stat.st_size);
                    close(fd);
                    return NULL;
                }
                size_t* length_ptr = (size_t*)item;
                memcpy(length_ptr, current_position + sizeof(size_t), sizeof(size_t));
                char* data_ptr = (char*)length_ptr + *length_ptr + sizeof(size_t);
                item += *length_ptr + sizeof(size_t);
                break;
            case DATA:
                if (!item) {
                    fprintf(stderr, "Missing data for data entry\n");
                    free(data);
                    free(result);
                    munmap(bundle, file_stat.st_size);
                    close(fd);
                    return NULL;
                }
                memcpy(item, current_position + sizeof(size_t), *((const size_t*)current_position));
                break;
        }

        if (entry_type == LENGTH || entry_type == DATA) {
            result->num_items++;
            void** old_items = result->items;
            result->items = realloc(result->items, result->num_items * sizeof(void*));
            if (!result->items) {
                fprintf(stderr, "Out of memory allocating items array\n");
                free(data);
                free(item);
                free(result);
                munmap(bundle, file_stat.st_size);
                close(fd);
                return NULL;
            }
            memcpy(result->items + result->num_items - 1, item, sizeof(void*));

            if (data && entry_type == TYPE_ID) {
                size_t id = generate_random_string(*data, config.character_set);
                void** old_ids = result->items;
                result->items = realloc(result->items, (result->num_items + 1) * sizeof(void*));
                if (!result->items) {
                    fprintf(stderr, "Out of memory allocating items array\n");
                    free(data);
                    free(item);
                    free(result);
                    munmap(bundle, file_stat.st_size);
                    close(fd);
                    return NULL;
                }
                result->items[result->num_items] = &id;
            }
        }

        current_position += *((const size_t*)current_position) + sizeof(size_t);
    }

    close(fd);
    munmap(bundle, file_stat.st_size);

    void** old_items = result->items;
    result->items = realloc(result->items, result->num_items * sizeof(void*));
    if (!result->items) {
        fprintf(stderr, "Out of memory allocating items array\n");
        free(old_items);
        free(result);
        return NULL;
    }
    memcpy(result->items, old_items, result->num_items * sizeof(void*));

    configure_cryptography(&config, false); // Default to security over speed

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    result->mutex = &mutex;

    return result;
}
