class SecurityUtil {
    private $charSet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_";
    private $hashAlgorithm = 'sha256';
    private $salt;
    private $customHashAlgorithm;
    private $checksum;
    private static $instance;

    private function __construct() {}

    public static function getInstance(): SecurityUtil {
        if (null === self::$instance) {
            self::$instance = new SecurityUtil();
        }
        return self::$instance;
    }

    public function setCharSet(string $charSet): void {
        $this->charSet = $charSet;
    }

    public function setHashAlgorithm(string $hashAlgorithm): void {
        $this->hashAlgorithm = $hashAlgorithm;
    }

    public function setSalt(string $salt): void {
        $this->salt = $salt;
    }

    public function setCustomHashAlgorithm(callable $customHashAlgorithm): void {
        $this->customHashAlgorithm = $customHashAlgorithm;
    }

    public function setChecksum(string $checksum): void {
        $this->checksum = $checksum;
    }

    public function generateRandomString(int $length): string {
        $randomString = '';
        $charSetLength = strlen($this->charSet);
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $this->charSet[rand(0, $charSetLength - 1)];
        }
        return $this->validateChecksum($randomString) ? $randomString : false;
    }

    public function hashPassword(string $password): string {
        if ($this->customHashAlgorithm) {
            return call_user_func($this->customHashAlgorithm, $password);
        }
        return password_hash($this->salt . $password, $this->hashAlgorithm);
    }

    public function validatePassword(string $password, string $hashedPassword): bool {
        if ($this->customHashAlgorithm) {
            return call_user_func($this->customHashAlgorithm, $password) === $hashedPassword;
        }
        return password_verify($this->salt . $password, $hashedPassword);
    }

    private function validateChecksum(string $randomString): bool {
        return hash($this->checksum, $randomString) === $randomString;
    }
}
