// Custom structure for resource bundle and its items
struct Item {
    int type;
    size_t length;
    u_char* data;
};

struct Bundle {
    size_t num_items;
    struct Item* items;
};

// Function to read from the file and populate the bundle
int load_bundle(const char *filepath, struct Bundle **bundle) {
    FILE *fp = fopen(filepath, "rb");
    if (!fp) return 0;

    // Read header (size_t header_len is the size of the fixed header)
    size_t header_len = sizeof(int); // type identifier
    fread(&header_len, sizeof(size_t), 1, fp);
    if (feof(fp)) goto cleanup;

    // Check for truncated file or invalid format
    if (fgetc(fp) != EOF || fgetc(fp) != EOF) goto cleanup;

    struct Bundle *bundle_ptr = malloc(sizeof(struct Bundle));
    if (!bundle_ptr) goto cleanup;

    bundle_ptr->items = 0;
    bundle_ptr->num_items = 0;

    size_t item_size = header_len + sizeof(size_t); // length and data
    while (!feof(fp)) {
        struct Item *item = malloc(item_size);
        if (!item) goto cleanup;

        fread(item, item_size, 1, fp);

        // Handle malformed entries
        if (fgetc(fp) != EOF || fgetc(fp) != EOF) goto cleanup;

        bundle_ptr->items = realloc(bundle_ptr->items, (++bundle_ptr->num_items) * item_size);
        memcpy(&bundle_ptr->items[(bundle_ptr->num_items) - 1], item, item_size);
    }

    *bundle = bundle_ptr;
    return bundle_ptr->num_items;

cleanup:
    fclose(fp);
    free(bundle_ptr);
    return 0;
}

// Function to resolve DNS for a given hostname and return IP address
void* dns_resolve(const char *hostname, void *arg) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only for simplicity
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) return NULL;

    u_char *ip = malloc(sizeof(u_char) * INET_ADDRSTRLEN);
    inet_ntop(AF_INET, &((struct sockaddr_in *)res->ai_addr)->sin_addr, ip, sizeof(ip));
    free(res);
    return ip;
}

// Function to generate a secure random string of a specified length from a given character set
void gen_random_string(size_t len, u_char *str, const char *chars) {
    for (size_t i = 0; i < len; ++i)
        str[i] = chars[(unsigned int)(RAND_bytes(&opentls_rand_state, sizeof(str[0])) * strlen(chars))];
}

