    try {
        j = jsoncons::json::load(ifs);
    } catch (const jsoncons::JsonSyntaxError& e) {
        throw std::runtime_error("Invalid JSON format in the configuration file");
    }

    // Validate and process the configuration
    const auto& configs = j["configurations"];
    if (configs.size() == 0) {
        throw std::runtime_error("No configurations found in the configuration file");
    }
    for (auto& conf : configs) {
        // Parse and validate each configuration entry
        Config c;
        try {
            c.serverAddress = conf["serverAddress"].get<std::string>();
            c.timeout = conf["timeout"].get<int>();
            c.maxRetries = conf["maxRetries"].get<int>();
        } catch (const jsoncons::JsonPathError& e) {
            throw std::runtime_error("Missing or invalid field in a configuration entry");
        }

        // Add the server type to the supported list and initialize the connection
        supportedServerTypes.insert(c.serverAddress);
        addConnection(c);
    }

    return supportedServerTypes.size();
}

