typedef struct Buffer {
    void* DataPointer;
    size_t Length;
    uint32_t UsageFlags;
} Buffer;

struct BufferPool {
    Buffer* Buffers;
    size_t Capacity;
    size_t UsedCount;
    size_t TotalAllocatedSize;
};

enum BufferError {
    BUFFER_ERROR_SUCCESS = 0,
    BUFFER_ERROR_MEMORY_ALLOCATION_FAILURE,
    BUFFER_ERROR_INVALID_BUFFER
};

static void buffer_validate(const Buffer* buffer) {
    if (!buffer || !buffer->DataPointer || buffer->Length == 0) {
        // Invalid buffer
    }
}

static Buffer* buffer_find_unused(struct BufferPool* pool) {
    for (size_t i = 0; i < pool->Capacity; ++i) {
        if (!pool->Buffers[i].DataPointer || !(pool->Buffers[i].UsageFlags)) {
            return &pool->Buffers[i];
        }
    }
    return nullptr;
}

static void* buffer_realloc(void* ptr, size_t newSize) {
    if (ptr == nullptr) {
        return malloc(newSize);
    }
    void* result = realloc(ptr, newSize);
    if (!result) {
        free(ptr);
        return nullptr;
    }
    return result;
}

static Buffer* buffer_create(size_t length) {
    Buffer* buffer = (Buffer*)malloc(sizeof(Buffer));
    if (!buffer) {
        return nullptr;
    }
    buffer->DataPointer = malloc(length);
    if (!buffer->DataPointer) {
        free(buffer);
        return nullptr;
    }
    buffer->Length = length;
    buffer->UsageFlags = 0;
    return buffer;
}

static void buffer_free(Buffer* buffer) {
    if (buffer->DataPointer) {
        free(buffer->DataPointer);
        free(buffer);
    }
}

static int allocateAndConfigureBufferPool(struct BufferPool** pool, size_t initialCapacity, size_t bufferSize) {
    *pool = (struct BufferPool*)malloc(sizeof(struct BufferPool));
    if (!*pool) {
        return BUFFER_ERROR_MEMORY_ALLOCATION_FAILURE;
    }
    (*pool)->Buffers = (Buffer*)calloc(initialCapacity, sizeof(Buffer));
    if ((*pool)->Buffers == nullptr) {
        free(*pool);
        return BUFFER_ERROR_MEMORY_ALLOCATION_FAILURE;
    }
    (*pool)->Capacity = initialCapacity;
    (*pool)->UsedCount = 0;
    (*pool)->TotalAllocatedSize = bufferSize * initialCapacity;

    for (size_t i = 0; i < initialCapacity; ++i) {
        Buffer* buffer = buffer_create(bufferSize);
        if (!buffer) {
            free(*pool->Buffers);
            free(*pool);
            return BUFFER_ERROR_MEMORY_ALLOCATION_FAILURE;
        }
        (*pool)->Buffers[i] = *buffer;
    }
    return BUFFER_ERROR_SUCCESS;
}

static int bufferPoolAddBuffer(struct BufferPool* pool, const void* data, size_t length) {
    Buffer* buffer = buffer_find_unused(pool);
    if (!buffer) {
        // No unused buffers, resize the pool
        size_t newCapacity = pool->Capacity * 2;
        int result = allocateAndConfigureBufferPool(&pool->Buffers, newCapacity, pool->TotalAllocatedSize / newCapacity);
        if (result != BUFFER_ERROR_SUCCESS) {
            return result;
        }
        buffer = buffer_find_unused(pool);
    }
    if (!buffer) {
        // Failed to find an unused buffer and failed to resize the pool, return error
        return BUFFER_ERROR_MEMORY_ALLOCATION_FAILURE;
    }
    buffer->DataPointer = buffer_realloc(data, length);
    if (!buffer->DataPointer) {
        // Failed to allocate memory for data, free unused buffer and return error
        buffer_free(&buffer->Buffers[i]);
        return BUFFER_ERROR_MEMORY_ALLOCATION_FAILURE;
    }
    buffer->Length = length;
    buffer->UsageFlags = 1;
    ++pool->UsedCount;
    return BUFFER_ERROR_SUCCESS;
}
```

