#include <iostream>
#include <list>
#include <fstream>
#include <vector>
#include <boost/shared_ptr.hpp>
#include <boost/thread/mutex.hpp>
#include <boost/format.hpp>
#include <boost/log/trivial.hpp>

struct Record {
    int value;
    std::string str;
};

class ForwardList {
private:
    std::list<Record> data;
    mutable boost::mutex mtx;
    std::vector<boost::shared_ptr<Record>> pool;
    std::ifstream inputFile;
    int batchSize = 1000;

public:
    ForwardList(const std::string& filename) : inputFile(filename, std::ios::in) {
        if (!inputFile.is_open()) {
            BOOST_LOG_TRIVIAL(error) << "Could not open file";
        }
        processBatch();
    }

    void insertAfter(const std::string& key, const std::string& value) {
        boost::lock_guard<boost::mutex> lock(mtx);
        auto it = std::find_if(data.begin(), data.end(), [&key](auto record) { return record.str == key; });
        if (it != data.end()) {
            pool.emplace_back(new Record{});
            *it->next, *it->next->prev, **it->next = **it, **it, *it->next;
            (*it->next)->str = value;
            (*it->next)->value = 0; // Customize this value based on your needs
        } else {
            if (pool.empty()) pool.emplace_back(new Record{});
            auto newRec = pool.back();
            newRec->str = value;
            data.push_back(*newRec);
        }
    }

    void processBatch() {
        Record record;
        while (inputFile >> record.value >> record.str) {
            if (pool.size() == pool.capacity()) pool.resize(pool.capacity() * 2);
            pool[pool.size() - 1].reset(new Record{record.value, record.str});
        }
    }
};
```

