        }

        // Generate a unique identifier for each record
        uint64_t hash = boost::hash_range(data, len);
        auto hashIt = hashMap.get().find(hash);
        if (hashIt != hashMap.get().end()) {  // Deduplicate records within the stream
            ++hashIt->second;
            return;
        }
        hashMap.get()->emplace(hash, 1);

        // Process the data based on predefined rules
        DataRecord newData(data, len);
        // ... perform filtering, aggregating, or transforming data fields using memcpy and memset

        streamData.push_back(newData);  // Store the processed data
    };

    beast::flat_buffer chunkBuffer;  // Temporary buffer for parsing incoming data chunks
    while (!done) {
        read_some(read_some);
        auto it = res.body().cbegin();
        size_t len = res.body().cend() - it;

        while (len > 0) {
            if (chunkBuffer.max_size() <= len) {
                chunkBuffer.clear();  // Clear the temporary buffer when it exceeds its max capacity
                read_some(read_some);
                it = res.body().cbegin();
                len = res.body().cend() - it;
            }

            if (len > chunkBuffer.max_size()) {
                len = chunkBuffer.max_size();
            }

            beast::flat_buffer::const_iterator end(it + len);
            std::copy(it, end, std::back_inserter(chunkBuffer));
            it += len;
            len -= len;

