                }
                beast::flat_buffer::const_iterator endChunk(chunkBuffer.data());
                beast::flat_buffer::const_iterator newStart(++endChunk);
                std::advance(newStart, currentLen);
                std::copy(newStart, chunkBuffer.cend(), std::begin(chunkBuffer));
