```cpp
#include <iostream>
#include <fstream>
#include <forward_list>
#include <mutex>
#include <memory>

struct Record {
    int value;
    std::string str;
    size_t refCount;
};

class ObjectPool {
public:
    static ObjectPool& instance() {
        thread_local ObjectPool instance;
        return instance;
    }

    std::shared_ptr<Record> create() const {
        if (pool.empty())
            pool.emplace_back(new Record);
        auto record = pool.back();
        ++record->refCount;
        pool.pop_back();
        return std::shared_ptr<Record>(record);
    }

    void destroy(std::shared_ptr<Record> record) const {
        if (--record->refCount == 0) {
            delete record.get();
        }
    }

private:
    ObjectPool() = default;
    std::vector<std::unique_ptr<Record>> pool;
};

class ForwardList {
public:
    void insert(const std::string& key, const std::string& value) {
        auto it = list.begin();
        if (it != list.end() && it->str == key) {
            ++it;
            auto record = ObjectPool::instance().create();
            record->str = value;
            record->value = 0;
            record->refCount = 1;
            *it = *record;
        } else {
            list.insert(it, ObjectPool::instance().create());
            auto record = *it++;
            record->str = value;
            record->value = 0;
            record->refCount = 1;
        }
    }

private:
    std::forward_list<Record> list;
    mutex mtx;
};

