#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int key;
    long value;
    struct Node* next;
} Node;

Node* create_node(int min_key, int max_key, long min_value, long max_value) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    new_node->key = rand() % (max_key - min_key + 1) + min_key;
    new_node->value = rand() % (max_value - min_value + 1) + min_value;
    new_node->next = NULL;

    return new_node;
}

void insert_head(Node** head, Node* new_node) {
    new_node->next = *head;
    *head = new_node;
}

void insert_tail(Node** tail, Node* new_node) {
    if (*tail == NULL) {
        *tail = new_node;
        return;
    }

    (*tail)->next = new_node;
    *tail = new_node;
}

void delete_by_key(Node** head, int key_to_delete) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && current->key == key_to_delete) {
        *head = current->next;
        free(current);
        current = *head;
        previous = NULL;
    }

    if (current == NULL) return;

    while (current != NULL) {
        if (current->key == key_to_delete) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }

            free(current);
            current = previous ? previous->next : NULL;
        } else {
            previous = current;
            current = current->next;
        }
    }
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next_node;

    while (current != NULL) {
        next_node = current->next;
        free(current);
