#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int key;
    long value;
    struct Node* prev;
    struct Node* next;
} Node;

Node* create_node(int key, long value) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->key = key;
    new_node->value = value;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void insert_head(Node** head, Node* new_node) {
    if (!new_node || !head) return;
    if (*head) {
        (*head)->prev = new_node;
        new_node->next = *head;
        *head = new_node;
    } else {
        *head = new_node;
    }
}

void insert_tail(Node** tail, Node* new_node) {
    if (!new_node || !tail) return;
    if (*tail) {
        (*tail)->next = new_node;
        new_node->prev = *tail;
        (*tail) = new_node;
    } else {
        *tail = new_node;
    }
}

void insert_at(Node** list, size_t position, Node* new_node) {
    if (!new_node || !list) return;
    if (position == 0) insert_head(list, new_node);
    else {
        Node *current = *list;
        for (size_t i = 0; i < position - 1 && current; ++i) current = current->next;
        if (!current || !new_node) return;
        new_node->prev = current;
        new_node->next = current->next;
        if (current->next) current->next->prev = new_node;
        current->next = new_node;
    }
}

void delete_by_key(Node** list, int key) {
    Node* current = *list;
    while (current) {
        if (current->key == key) {
            if (current->prev) current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;
            if (*list == current) *list = current->next;
            free(current);
            return;
        }
        current = current->next;
    }
}

Node* find_by_key(Node* list, int key) {
    for (Node* current = list; current; current = current->next) {
        if (current->key == key) return current;
    }
    return NULL;
}

void delete_at(Node** list, size_t position) {
    Node *current = *list;
    for (size_t i = 0; i < position && current; ++i) current = current->next;
    if (!current || !*list) return;
    if (current->prev) current->prev->next = current->next;
    if (current->next) current->next->prev = current->prev;
    if (*list == current) *list = current->next;
    free(current);
}

void traverse_by_index(Node* list, size_t index) {
    for (Node* current = list; current && index; current = current->next, --index);
    if (!current) printf("Index out of bounds\n");
    else printf("%d: %ld\n", current->key, current->value);
}

void traverse_by_key(Node* list, int key) {
    for (Node* current = list; current; current = current->next) {
        if (current->key == key) printf("%d: %ld\n", current->key, current->value);
    }
}
```

