void writeChunk(const void* data, size_t size, FILE *file) {
    fwrite(data, size, 1, file);
}

void processData(void* data, const Rule* rule) {
    // Implement the logic to transform data based on the provided rules
}

void* parseFile(FILE *input, FILE *output, const Rule* rule) {
    char* buffer;
    size_t bytesRead;
    void* processedData = NULL;

    while ((bytesRead = fread(&buffer, CHUNK_SIZE, 1, input)) > 0) {
        // Process the chunk of data here

        if (processedData != NULL) {
            processData(processedData + bytesRead - CHUNK_SIZE, rule);
        }

        processedData = realloc(processedData, sizeof(char) * (bytesRead + CHUNK_SIZE));
        memcpy(processedData, buffer, bytesRead);
    }

    if (processedData != NULL) {
        processData(processedData + bytesRead - CHUNK_SIZE, rule);
    }

    // Write the processed data to output file here
}

void* worker(void* arg) {
    FILE *input = (FILE*)arg;
    FILE *output = NULL;
    Rule *rule = NULL;
    void *processedData = NULL;

    rule = parseRules(*((const char**)arg + 1));
    output = fopen(*((const char**)arg + 2), "wb");

    if (output == NULL) {
        free(rule);
        return NULL;
    }

    processedData = mmap(NULL, CHUNK_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (processedData == MAP_FAILED) {
