        fprintf(stderr, "Usage: %s inputFile outputFile rules\n", argv[0]);
        return EXIT_FAILURE;
    }

    pthread_t threads[omp_get_max_threads()];
    Rule *rule = parseRules(argv[3]);

    FILE *input = fopen(argv[1], "rb");
    if (input == NULL) {
        free(rule);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < omp_get_max_threads(); ++i) {
        pthread_create(&threads[i], NULL, worker, &argv[1]);
    }

    char buffer[CHUNK_SIZE];
    size_t bytesRead;

    FILE *output = fopen(argv[2], "wb");
    if (output == NULL) {
        for (int i = 0; i < omp_get_max_threads(); ++i) {
            pthread_join(threads[i], NULL);
        }

        free(rule);
        fclose(input);
        return EXIT_FAILURE;
    }

    while ((bytesRead = fread(&buffer, CHUNK_SIZE, 1, input)) > 0) {
        for (int i = 0; i < omp_get_max_threads(); ++i) {
            writeChunk(buffer, bytesRead, output);
        }
    }

    for (int i = 0; i < omp_get_max_threads(); ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(input);
    fclose(output);
    free(rule);

    return EXIT_SUCCESS;
}
