typedef struct Record {
    int value;
} Record;

void init_record_array(size_t key_count, size_t offset_count, size_t record_count, int* keys, long* offsets, Record** records) {
    if (!keys || !offsets || !records) return;

    // Allocate memory for keys and offset arrays
    *keys = malloc(key_count * sizeof(int));
    if (!*keys) {
        perror("Error allocating key array");
        return;
    }

    *offsets = malloc(offset_count * sizeof(long));
    if (!*offsets) {
        perror("Error allocating offset array");
        free(*keys);
        return;
    }

    // Initialize keys and offset arrays with sequential values starting from 0
    for (size_t i = 0; i < key_count; ++i) {
        (*keys)[i] = i;
        (*offsets)[i] = i;
    }

    // Align memory allocation for records array using posix_memalign
    size_t alignment = sizeof(Record);
    if (posix_memalign(*records, alignment, record_count * sizeof(**records)) != 0) {
        perror("Error allocating record array");
        free(*keys);
        free(*offsets);
        return;
    }

    // Initialize each record's int value to a random number within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < record_count; ++i) {
        (*records)[i].value = rand() % MAXIMUM_RANDOM_VALUE;
    }
}
