#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Maximum capacity for each array to avoid excessive reallocations
#define MAX_ARRAY_CAPACITY 1024

typedef struct Record {
    int value;
    char* key;
} Record;

// Thread-safe function for initializing and managing memory allocation of key-value records
void init_records(size_t offset_size, size_t record_size, void(*set_value)(int index, int value), int* error) {
    long* offsets = malloc(offset_size * sizeof(long));
    if (!offsets) {
        *error = 1;
        return;
    }
    memset(offsets, 0, offset_size * sizeof(long));

    int* keys = malloc(record_size * sizeof(int));
    if (!keys) {
        free(offsets);
        *error = 1;
        return;
    }
    memset(keys, 0, record_size * sizeof(int));

    Record* records = malloc(record_size * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        *error = 1;
        return;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    size_t current_offset = 0, current_key = 0;
    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = rand() % 100;
        records[i].key = malloc(32 * sizeof(char));
        if (!records[i].key) {
            free(offsets);
            free(keys);
            free(records);
            *error = 1;
            return;
        }
        memset(records[i].key, 0, 32 * sizeof(char));

        pthread_mutex_lock(&mutex);
        while (current_offset <= offsets[current_key] || keys[current_key] != current_key) {
            current_offset++;
            current_key = (current_key + 1) % offset_size;
        }
        pthread_mutex_unlock(&mutex);

        offsets[current_key] = current_offset;
        keys[current_key] = current_key;
    }

    if (set_value) {
        for (int i = 0; i < *error; ++i) {
            set_value(keys[i], records[i].value);
        }
    }
}

