#include <stdio.h>
#include <stdlib.h>
#include <uuid/uuid.h>
#include <pthread.h>
#include <time.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <geoip.h>

struct session {
    uuid_t id;
    char user_agent[256];
    time_t last_activity;
    struct sockaddr_in client_addr;
    GeoIP *geolocation_db;
    GeoIPRecord *record;
    void *metadata; // Custom metadata can be stored here
    pthread_mutex_t lock;
};

struct session_manager {
    struct session **sessions;
    size_t capacity;
    size_t count;
    time_t inactivity_timeout;
};

void uuid_generate(uuid_t id) {
    uuid_generate_time(id);
}

struct session* session_create() {
    struct session *session = malloc(sizeof(struct session));
    if (!session) return NULL;

    uuid_generate(session->id);
    memset(session->user_agent, 0, sizeof(session->user_agent));
    session->last_activity = 0;
    memset(&session->client_addr, 0, sizeof(session->client_addr));
    session->geolocation_db = GeoIP_open("GeoIP.dat", GEOIP_STANDARD);
    session->record = NULL;
    session->metadata = NULL;
    pthread_mutex_init(&session->lock, NULL);

    return session;
}

void session_update(struct session *session) {
    session->last_activity = time(NULL);
    pthread_mutex_lock(&session->lock);
    // Update geolocation data if available
    if (session->geolocation_db && !session->record)
        session->record = GeoIP_id2location(session->geolocation_db, ntohl(session->client_addr.sin_addr.s_addr));
    pthread_mutex_unlock(&session->lock);
}

void session_add_metadata(struct session *session, void *data) {
    session->metadata = data;
}

size_t session_get_metadata_size(const struct session *session) {
    return sizeof(session->metadata);
}

void* session_get_metadata(const struct session *session) {
    return session->metadata;
}

struct session_manager* session_manager_create(size_t capacity, time_t inactivity_timeout) {
    struct session_manager *manager = malloc(sizeof(struct session_manager));
    if (!manager) return NULL;

    manager->sessions = calloc(capacity, sizeof(struct session*));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    manager->capacity = capacity;
    manager->count = 0;
    manager->inactivity_timeout = inactivity_timeout;

    return manager;
}

void session_manager_resize(struct session_manager *manager, size_t new_capacity) {
    if (new_capacity <= manager->capacity) return;

    struct session **new_sessions = realloc(manager->sessions, new_capacity * sizeof(struct session*));
    if (!new_sessions) return;

    manager->sessions = new_sessions;
    manager->capacity = new_capacity;
}

void session_manager_insert(struct session_manager *manager, struct session *session, size_t index) {
    if (index >= manager->capacity) {
        session_manager_resize(manager, index + 1);
    }

    for (size_t i = manager->count; i > index; --i) {
        manager->sessions[i] = manager->sessions[i - 1];
    }

    manager->sessions[index] = session;
    ++manager->count;
}

void session_manager_delete(struct session_manager *manager, struct session *session) {
    size_t index;
    for (index = 0; index < manager->count; ++index) {
        if (manager->sessions[index] == session) break;
    }

    if (index == manager->count) return; // Not found

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->sessions[i] = manager->sessions[i + 1];
    }

    --manager->count;
}

void session_manager_clean(struct session_manager *manager) {
    time_t now = time(NULL);

    for (size_t i = 0; i < manager->count; ++i) {
        if (now - manager->sessions[i]->last_activity >= manager->inactivity_timeout) {
            session_manager_delete(manager, manager->sessions[i]);
        }
    }
}

void session_destroy(struct session *session) {
    if (!session) return;

    uuid_clear(session->id);
    free(session->user_agent);
    pthread_mutex_destroy(&session->lock);
    GeoIP_delete(session->geolocation_db);
    free(session);
}

void session_manager_destroy(struct session_manager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        session_destroy(manager->sessions[i]);
    }

    free(manager->sessions);
    free(manager);
}
```

