public class ReusableObjectPool<T> : IDisposable where T : new()
{
    private readonly ConcurrentStack<T> _freePool;
    private readonly SemaphoreSlim _usageSemaphore;
    private readonly IObjectValidator _validator;
    private readonly object _loggingLock = new object();
    private int _maxPoolSize;
    private int _poolSizeThreshold;
    private int _currentPoolSize;

    public event Action<long, long> OnResourceLeakDetected;
    public event Action<TimeSpan> OnObjectAcquisitionTimeLogged;

    public ReusableObjectPool(IObjectValidator validator, int initialPoolSize, int poolSizeThreshold)
    {
        _validator = validator ?? throw new ArgumentNullException(nameof(validator));
        _freePool = new ConcurrentStack<T>();
        _usageSemaphore = new SemaphoreSlim(initialPoolSize);
        _maxPoolSize = initialPoolSize;
        _poolSizeThreshold = poolSizeThreshold;
    }

    public T AcquireObject()
    {
        if (!_usageSemaphore.Wait(TimeSpan.FromMilliseconds(100)))
            return new T(); // Return a new instance if the semaphore wait times out

        while (_freePool.TryPeek(out var obj) && !_validator.Validate(obj))
            _freePool.Pop();

        return _freePool.Pop();
    }

    public void ReleaseObject(T obj)
    {
        if (Interlocked.Exchange(ref _currentPoolSize, _currentPoolSize + 1) > _maxPoolSize && CanExpandPool())
            ExpandPoolAsync().Wait();

        _freePool.Push(obj);
        Interlocked.Decrement(ref _currentPoolSize);
    }

    private bool CanExpandPool() => (_poolSizeThreshold * 2) <= _currentPoolSize || (double)_acquisitionRate > _poolUsageThreshold;

    public override string ToString()
    {
        var available = _freePool.Count;
        var inUse = _usageSemaphore.CurrentCount;
        return $"Object Pool ({typeof(T).Name}): Available={available}, In-use={inUse}, Total size: {_maxPoolSize}";
    }

