#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pthread.h>
#include <getopt.h>
#include <stdbool.h>
#include <stdatomic.t.h>
#include <errno.h>
#include <limits.h>
#include <ctype.h>

#define CHUNK_SIZE 10000
#define MAX_FILES 10000

struct file_stats {
    atomic_long_t lines;
    atomic_long_t chars;
};

struct output_format {
    const char *name;
    void (*print)(const struct file_stats *, const char *);
};

static struct output_format formats[] = {
    {"csv", print_csv},
    {"json", print_json},
    // Custom format specified by user via -f option
    {NULL, NULL}
};

static atomic_long_t num_files = 0;
static struct file_stats files[MAX_FILES];
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static bool parallel = true;
static const char *logfile = NULL;

void print_usage(const char *progname) {
    printf("Usage: %s [options] FILE...\n", progname);
    printf("Options:\n");
    printf("-l, --logfile=LOGFILE         Log errors and warnings to LOGFILE\n");
    printf("-f, --format=FORMAT           Output format (csv, json, or custom)\n");
    printf("-h, --help                   Show this help message and exit\n");
}

void print_errors(const char *progname) {
    if (logfile) {
        fprintf(stderr, "[%s] Error: ", logfile);
    } else {
        fprintf(stderr, "Error: ");
    }
    fflush(stderr);
}

void print_warnings(const char *progname) {
    if (logfile) {
        fprintf(stderr, "[%s] Warning: ", logfile);
    } else {
        fprintf(stderr, "Warning: ");
    }
    fflush(stderr);
}

int main(int argc, char *argv[]) {
    int opt;
    const char *log_file = NULL;
    const char *format = NULL;

    while ((opt = getopt(argc, argv, "l:f::h")) != -1) {
        switch (opt) {
            case 'l':
                log_file = optarg;
                break;
            case 'f':
                format = optarg;
                break;
            case 'h':
                print_usage(argv[0]);
                return 0;
            default:
                print_errors(argv[0]);
                fprintf(stderr, "Unknown option: %c\n", optopt);
                return 1;
        }
    }

    if (optind >= argc) {
        print_usage(argv[0]);
        return 1;
    }

    if (log_file && strcmp(log_file, "-")) {
        open_and_log(log_file, "w");
    }

    for (int i = optind; i < argc; ++i) {
        int fd = open(argv[i], O_RDONLY);
        if (fd == -1) {
            print_errors(argv[0]);
            perror(argv[i]);
            continue;
        }

        struct stat st;
        if (fstat(fd, &st) == -1) {
            close(fd);
            continue;
        }

        void *map_base = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
        if (map_base == MAP_FAILED) {
            close(fd);
            continue;
        }

        char *line = map_base;
        size_t chunk_len = 0;

        atomic_long_t index = num_files++;
        if (num_files >= MAX_FILES) {
            print_warnings(argv[0]);
            fprintf(stderr, "Warning: Processing limited to %d files\n", MAX_FILES);
        }

        struct file_stats *file = &files[index];
        memset(file, 0, sizeof(*file));
        pthread_mutex_lock(&mutex);
        files[index] = *file;
        pthread_mutex_unlock(&mutex);

        while ((chunk_len = getline(&line, &chunk_len, line)) != -1) {
            ++file->lines;
            file->chars += chunk_len;

            if (parallel && num_files < MAX_FILES) {
                pthread_t thread_id;
                int rc = pthread_create(&thread_id, NULL, process_line, &file);
                if (rc) {
                    print_errors(argv[0]);
                    perror("pthread_create");
                    break;
                }
            } else {
                process_line(file, line);
            }
        }

        munmap(map_base, st.st_size);
        close(fd);
    }

    if (!parallel) {
        for (int i = 0; i < num_files; ++i) {
            process_line(&files[i], NULL);
        }
    }

    for (int i = 0; i < num_files; ++i) {
        struct file_stats *file = &files[i];
        if (format && !formats[0].print) {
            print_errors(argv[0]);
            fprintf(stderr, "Error: Unsupported custom format: %s\n", format);
            return 1;
        }

        pthread_mutex_lock(&mutex);
        struct file_stats tmp = *file;
        pthread_mutex_unlock(&mutex);

        if (format) {
            formats[0].print(tmp.lines == 0 ? &empty_file_stats : &tmp, format);
        } else {
            for (const struct output_format *fmt = formats; fmt->name; ++fmt) {
                if (fmt->print) {
                    fmt->print(tmp.lines == 0 ? &empty_file_stats : &tmp, fmt->name);
                }
            }
        }
    }

    return 0;
}

struct file_stats empty_file_stats = { .lines = 0, .chars = 0 };

void *process_line(void *arg, const char *line) {
    struct file_stats *file = arg;
    if (line == NULL) return NULL;

    for (char c : line) {
        if (!isalnum(c) && c != '_') continue;
        ++file->chars;
    }

    return NULL;
}

void print_csv(const struct file_stats *file, const char *format) {
    printf("%d,\"%s\",%ld\n", file->lines, format, file->chars);
}

void print_json(const struct file_stats *file, const char *format) {
    const char *quotes = "\"";
    putchar('{' + 128); // JSON escape for ' character
    printf(",\"lines\":%d,", file->lines);
    printf(",\"filename\":\"%s\",", format);
    printf(",\"chars\":%ld}", file->chars);
}
