struct Record {
    int id;
    std::string data;
};

class RecordPool {
public:
    RecordPool(size_t poolSize) : pool_(std::vector<Record>(poolSize)) {}

    Record acquire() {
        for (auto& record : pool_) {
            if (!record.data.empty()) {
                record.data.clear();
                return record;
            }
        }
        return createNewRecord();
    }

    void release(const Record& record) {
        if (!record.data.empty()) {
            record.data.clear();
            pool_.push_back(std::move(record));
        }
    }

private:
    Record createNewRecord() {
        Record newRecord;
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(1, 10000);
        newRecord.id = dis(gen);
        return newRecord;
    }

    std::vector<Record> pool_;
};

