class Utility {
public:
    static int* read_ints(size_t& num) {
        int* array = nullptr;
        num = 0;
        std::cout << "Enter up to 1000 integers between -1000 and 1000, or enter 'q' to quit: ";
        int input;
        for (;;) {
            std::cin >> input;
            if (input == 'q') return nullptr;
            if ((input >= -1000 && input <= 1000)) {
                array = static_cast<int*>(realloc(array, sizeof(int) * ++num));
                array[num - 1] = input;
            } else {
                std::cout << "Invalid input. Please enter an integer between -1000 and 1000 or 'q' to quit.\n";
            }
        }
    }

    static void print_largest(const int* arr, size_t n) {
        if (n > 0)
            std::cout << "The largest number in the array is: " << *std::max_element(arr, arr + n) << '\n';
    }

    struct HashOption {
        const char* algorithm = "";
        bool salt = false;
        size_t rounds = 0;
    };

    static std::string generate_random_string(size_t length, const char* characters) {
        auto cset = characters;
        if (cset.empty())
            cset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_";
        std::string rand_str(length, 0);
        for (size_t i = 0; i < length; ++i) {
            size_t pos = static_cast<size_t>(std::rand() % cset.length());
            rand_str[i] = cset[pos];
        }
        return rand_str;
    }

    static std::string hash(const std::string& password, const HashOption& option) {
        // Implement SHA-256 using OpenSSL library
        auto algorithm = EVP_sha256();
