// Define severity levels
enum Severity { TRACE, DEBUG, INFO, NOTICE, WARN, ERROR, CRITICAL, ALERT, EMERGENCY };

typedef struct LogEntry {
    time_t timestamp;
    enum Severity severity;
    char message[4096];
} LogEntry;

// Configuration struct
typedef struct Config {
    size_t buffer_size;
    size_t max_entries;
    char *log_path;
    char *timestamp_format;
    enum Severity mask;
    int verbosity;
} Config;

sem_t log_mutex; // Mutex for thread-safe logging
Config config; // Configuration structure instance

// Utils
void timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    strftime(buf, len, config.timestamp_format, gmtime(&now));
}

void log_entry(LogEntry *entry) {
    char filename[256];
    snprintf(filename, sizeof(filename), "%s/%d_%03d.log", config.log_path, getpid(), entry->severity);
    int fd = open(filename, O_WRONLY | O_APPEND | O_CREAT | O_DIRECT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    write(fd, &entry->timestamp, sizeof(entry->timestamp));
    write(fd, " ", 1);
    write(fd, entry->message, strlen(entry->message));
    close(fd);
}

void performance_monitoring(const char *category) {
    // Implement performance monitoring feature here.
}

// Logging function with variadic arguments
void log(enum Severity severity, const char *format, ...) {
    va_list args;
    size_t entry_size = sizeof(LogEntry);
    LogEntry *entry = malloc(entry_size);
    if (!entry) return; // Memory allocation failure, bail out.

    time(&entry->timestamp);
    entry->severity = severity;
    va_start(args, format);
    vsnprintf(entry->message, sizeof(entry->message), format, args);
    va_end(args);

    sem_wait(&log_mutex); // Acquire mutex before accessing the log buffer.

    if ((config.max_entries > 0) && (++config.num_entries >= config.max_entries)) {
        // If max entries is set and we exceeded it, overwrite the oldest entry.
        size_t offset = (config.buffer_size - entry_size) % config.buffer_size;
        memmove(config.log_buffer + offset, config.log_buffer, config.num_entries * entry_size);
    }

    memcpy(config.log_buffer + config.num_entries * entry_size, entry, entry_size);
    ++config.num_entries %= config.buffer_size;

    if ((severity & config.mask) > 0) { // Filter log message based on the mask.
        performance_monitoring("Logging");
        log_entry(entry);
    }

    sem_post(&log_mutex); // Release mutex after updating the log buffer.
}

// Initialize function that sets up the logging configuration and resources.
void init_logging(Config *config) {
    setlocale(LC_ALL, "");

    config->buffer_size = 1024;
    config->max_entries = 8192;
    config->log_path = "/var/log";
    strcpy(config->timestamp_format, "%Y-%m-%d %H:%M:%S.%3u"); // Local time format.
    config->mask = TRACE;
    config->verbosity = 0;

    sem_init(&log_mutex, 0, 1);
}
