#include <zlib.h>

typedef struct _CompressContext {
    gzFile fp;
    char *buf;
    size_t bufSize;
    size_t posInBuf;
} CompressContext;

CompressContext* initCompressContext(size_t bufferSize) {
    CompressContext *ctx = (CompressContext *)malloc(sizeof(CompressContext));
    ctx->buf = (char *)malloc(bufferSize);
    ctx->bufSize = bufferSize;
    ctx->posInBuf = 0;
    ctx->fp = NULL;
    return ctx;
}

void destroyCompressContext(CompressContext *ctx) {
    free(ctx->buf);
    gzclose(ctx->fp);
    free(ctx);
}

gzFile openFileForWritingWithCompression(const char *path, CompressContext *ctx) {
    return gzopen(path, "wb9");
}

void analyzeDirectory(const char *dirPath, void (*processFile)(const char *, CompressContext *), int compressOnFile) {
    DIR *d;
    struct dirent *ent;
    d = opendir(dirPath);

    if (d) {
        while ((ent = readdir(d)) != NULL) {
            char path[4096];
            snprintf(path, sizeof(path), "%s/%s", dirPath, ent->d_name);

            struct stat st;
            if (lstat(path, &st) == 0) {
                if (S_ISDIR(st.st_mode)) {
                    analyzeDirectory(path, processFile, compressOnFile);
                } else if (compressOnFile && S_ISREG(st.st_mode)) {
                    CompressContext *ctx = initCompressContext(st.st_size / 1024 + 16); // Allocate buffer based on file size + some overhead
                    gzFile fp = openFileForWritingWithCompression(path, ctx);
                    if (fp != NULL) {
                        processFile(path, ctx);
                        destroyCompressContext(ctx);
                        gzclose(fp);
                    }
                } else if (!compressOnFile && S_ISREG(st.st_mode)) {
                    // Process uncompressed file here
                }
            }
        }
        closedir(d);
    }
}
