#include <fcntl.h>

#define MAX_THREADS 8
#define BUFFER_SIZE 4096

typedef struct {
    int fd;
    size_t line_count;
} input_data_t;

static pthread_mutex_t line_counter_mutex = PTHREAD_MUTEX_INITIALIZER;
static int threads[MAX_THREADS];
static pid_t current_pid;

void *worker(void *arg) {
    input_data_t *data = arg;
    char buffer[BUFFER_SIZE];
    ssize_t read_size;

    while ((read_size = read(data->fd, buffer, BUFFER_SIZE)) > 0) {
        size_t start = 0;
        while (start < read_size && buffer[start] != '\n') start++;

        if (start < read_size) {
            pthread_mutex_lock(&line_counter_mutex);
            data->line_count++;
            pthread_mutex_unlock(&line_counter_mutex);
        }

        if (buffer[start] == '\n') {
            buffer[start++] = '\0';
            pthread_mutex_lock(&line_counter_mutex);
            data->line_count++;
            pthread_mutex_unlock(&line_counter_mutex);
        }
    }

    if (read_size < 0) {
        perror("Error reading file");
        exit(EXIT_FAILURE);
    }
}

void init_thread_pool(int thread_count) {
    int err = pthread_attr_init(&(threads[0].attr));
    if (err != 0) {
        perror("Error initializing thread attribute");
        exit(EXIT_FAILURE);
    }

    for (int i = 1; i < thread_count; ++i) {
        err = pthread_attr_init(&(threads[i].attr));
        if (err != 0) {
            perror("Error initializing thread attribute");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        err = pthread_create(&threads[i].tid, &(threads[i].attr), worker, &input_data_t{current_pid > 1 ? dup(STDIN_FILENO) : -1, 0});
        if (err != 0) {
            perror("Error creating thread");
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_thread_pool() {
    for (int i = 0; i < MAX_THREADS; ++i) {
        if (threads[i].tid != 0) pthread_join(threads[i].tid, NULL);
    }

    for (int i = 1; i < MAX_THREADS; ++i) {
        pthread_attr_destroy(&(threads[i].attr));
    }
}

void print_usage() {
    printf("Usage: %s [options] input_file\n", current_pid > 1 ? program_invocation_name : "program");
    printf("\nOptions:\n");
    printf("-h, --help             Display this help and exit.\n");
    printf("-o output_file         Redirect the output to a specified file.\n");
    printf("-c, --codes            Print error codes instead of messages.\n");
}

int main(int argc, char *argv[]) {
    current_pid = getpid();
    int opt;
    const char *output_file = NULL;
    const char *input_file = NULL;

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"codes", no_argument, 0, 'c'},
        {"manpage", no_argument, 0, 'M'},
        {"output-file", required_argument, 0, 'o'},
        {0}
    };

    while ((opt = getopt_long(argc, argv, "hcm:o:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                print_usage();
                return EXIT_SUCCESS;
            case 'c':
                // Print error codes instead of messages
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'M':
                print_usage();
                return EXIT_SUCCESS;
        }
    }

    if (optind >= argc) {
        // No input file provided, display usage information
        print_usage();
        return EXIT_FAILURE;
    }

    input_file = argv[optind];

    int thread_count = 1;
    FILE *input_fp = fopen(input_file, "r");

    if (input_fp == NULL) {
        perror("Error opening the file");
        return EXIT_FAILURE;
    }

    if (fstat(fileno(input_fp), &current_fd_st) != 0) {
        perror("Error getting file statistics");
        fclose(input_fp);
        return EXIT_FAILURE;
    }

    if (S_ISFIFO(current_fd_st.st_mode)) thread_count = MAX_THREADS;

    init_thread_pool(thread_count);

    input_data_t input_data = {fileno(input_fp), 0};
    size_t line_count = 0;

    while ((fgets(buffer, BUFFER_SIZE, input_fp)) != NULL) line_count++;

    rewind(input_fp);
    init_thread_pool(thread_count);

    pthread_mutex_lock(&line_counter_mutex);
    line_count = input_data.line_count + line_count;
    pthread_mutex_unlock(&line_counter_mutex);

    fclose(input_fp);

    if (output_file != NULL) {
        FILE *output_fp = fopen(output_file, "w");
        if (output_fp == NULL) {
            perror("Error opening the output file");
            return EXIT_FAILURE;
        }

        fprintf(output_fp, "%zu\n", line_count);
        fclose(output_fp);
    } else {
        printf("%zu\n", line_count);
    }

    cleanup_thread_pool();
    return EXIT_SUCCESS;
}
