using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Newtonsoft.Json;

public class HttpRequestHelper
{
    private readonly IMemoryCache _cache;
    private readonly TimeSpan _cacheExpiration = TimeSpan.FromMinutes(5);

    public HttpRequestHelper(IMemoryCache cache)
    {
        _cache = cache;
    }

    public async Task<HttpResponseMessage> SendAsync(string baseUrl, Dictionary<string, string> headers, Dictionary<string, string> parameters, List<string> parameterValues)
    {
        var requestUri = $"{baseUrl}/{string.Join("/", parameterValues)}";
        var requestParametersString = string.Join("&", parameters.Select(kv => $"{HttpUtility.UrlEncode(kv.Key)}={HttpUtility.UrlEncode(kv.Value)}"));

        if (_cache.TryGetValue(requestUri, out HttpResponseMessage cachedResponse))
            return cachedResponse;

        var client = new HttpClient();
        client.DefaultRequestHeaders.Accept.Clear();
        client.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
        foreach (var header in headers)
            client.DefaultRequestHeaders.Add(header.Key, header.Value);

        var request = new HttpRequestMessage(HttpMethod.Get, requestUri);
        if (requestParametersString.Length > 0)
            request.SetQueryParams(parameters);

        try
        {
            var response = await client.SendAsync(request);
            if (!response.IsSuccessStatusCode)
            {
                // Handle rate limiting, authentication failures, and network timeouts here.
            }
            _cache.Set(requestUri, response, _cacheExpiration);
            return response;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error sending HTTP request: {ex.Message}");
            throw;
        }
    }

    private void HttpRequestMessage SetQueryParams(this HttpRequestMessage request, Dictionary<string, string> parameters)
    {
        var queryString = new System.Uri(request.RequestUri).Query;
        var queryParameters = HttpUtility.ParseQueryString(queryString);

        foreach (var parameter in parameters)
        {
            queryParameters[parameter.Key] = parameter.Value;
        }

        request.RequestUri = new Uri(new Uri(request.RequestUri.AbsoluteUri), queryParameters);
    }
}
```

