    std::lock_guard<std::mutex> lock(mtx);

    if (now - transactions[id].second > 10 || blacklist.find(id) != blacklist.end() || transactions[id].first < 1.0 || now - transactions[id].second > 5 * std::clock_t(CLOCKS_PER_SEC))
