  blueslip = new Blueslip();

  // Reset blueslip after each test execution
  testingFramework.beforeEach(() => {
    blueslip.reset();
  });

  let testsCount = 0, successfulTests = 0, failedTests = 0;

  // Execute tests in parallel using the testing framework
  const testGroup = testingFramework.group(`Testing ${moduleName}`);

  // Iterate over all exported functions from the module and assign them to test labels
