import java.io.*;
import java.nio.file.*;
import java.text.SimpleDateFormat;
import java.util.*;
import org.json.*;

public class DirectoryAnalyzer {
    private static final SimpleDateFormat TIME_FORMAT = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    private static final Map<String, Function<JsonNode, JsonNode>> JSON_FACTORY_REGISTRY = new HashMap<>();

    public static void addJsonFactory(String id, Function<JsonNode, JsonNode> factory) {
        JSON_FACTORY_REGISTRY.put(id, factory);
    }

    private static long analyzeDirectoryStructure(Path path, Map<Path, Long> result) throws IOException {
        long start = System.nanoTime();
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(path)) {
            for (Path entry : stream) {
                if (Files.isSymbolicLink(entry)) {
                    continue;
                }

                FileFileAttributes attrs = Files.readAttributes(entry, FileFileAttributeViews.SIZE);
                if (attrs.isHidden()) {
                    continue;
                }

                if (Files.isDirectory(entry)) {
                    analyzeDirectoryStructure(entry, result);
                } else {
                    result.mergePut(entry, 1L);
                }
            }
        }
        long end = System.nanoTime();
        long duration = (end - start) / 1_000_000;
        result.putIfAbsent(path, duration);
        System.out.printf("Analyzed directory %s in %d milliseconds%n", path, duration);
        return end - start;
    }

    public static JsonNode analyzeDirectoryStructure(List<Path> paths) throws IOException {
        Map<Path, Long> result = new TreeMap<>();
        long totalTime = 0;
        for (Path path : paths) {
            totalTime += analyzeDirectoryStructure(path, result);
        }
        JsonObject root = new JsonObject();
        root.put("total_time", totalTime);
        root.put("directories_with_two_files", createJsonArray(getTwoFilesDirectories(result)));
        return root;
    }

    private static List<Map.Entry<Path, Long>> getTwoFilesDirectories(Map<Path, Long> result) {
        return result.entrySet().stream()
            .filter(e -> e.getValue() == e.getKey().getParent().orElseThrow(() -> new IllegalStateException("Parent directory not found")).getValue())
            .filter(e -> e.getValue() == 2)
            .collect(Collectors.toList());
    }

    private static JsonArray createJsonArray(Collection<?> collection) {
        return new JsonArray(collection.stream().map(JsonValue::new).toList());
    }

    // JSON HANDLER

    public static class JsonHandler {
        public static JsonNode fromJson(String json) {
            try {
                return new JsonReader(new StringReader(json)).read();
            } catch (IOException e) {
                throw new RuntimeException("Failed to parse JSON", e);
            }
        }

        public static <T> T fromJson(String json, Class<T> clazz) {
            try {
                return Json.fromJson(json, clazz);
            } catch (IllegalAccessException | InstantiationException | JsonParseException e) {
                throw new RuntimeException("Failed to convert JSON to Java object", e);
            }
        }

        public static String toJson(Object obj) {
            try {
                return Json.stringify(obj);
            } catch (IllegalAccessException | InstantiationException e) {
                throw new RuntimeException("Failed to convert Java object to JSON", e);
            }
        }

        public static void registerJsonFactory(String id, Function<JsonNode, JsonNode> factory) {
            JSON_FACTORY_REGISTRY.putIfAbsent(id, factory);
        }

        public static <T> T createFromJson(String id, JsonNode json, Class<T> clazz) {
            if (!JSON_FACTORY_REGISTRY.containsKey(id)) {
                throw new IllegalArgumentException("Unknown JSON factory: " + id);
            }
            return JSON_FACTORY_REGISTRY.get(id).apply(json).map(JsonHandler::fromJson, clazz);
        }
    }
}
```

This code provides a `DirectoryAnalyzer` class that contains the functionality for analyzing a directory structure as specified. It also includes a `JsonHandler` class for handling JSON parsing and generation tasks, along with a registry of factory functions to create subclasses based on unique IDs. The implementation adheres to best practices such as proper error handling, resource management, and modularity.']

