        this.logger = LoggerFactory.getLogger("ConnectionPoolManager"); // replace with your actual logging configuration
    }

    public WebSocketConnection getConnection() {
        WebSocketConnection connection;
        try {
            connection = connectionQueue.poll(timeoutMillis, TimeUnit.MILLISECONDS);
            if (connection == null) {
                connection = createNewConnection();
            }
        } catch (InterruptedException e) {
            logger.error("Interrupted while waiting for connection", e);
            return null;
        }
        return connection;
    }

    private WebSocketConnection createNewConnection() {
