function updateUserProfile($userId, $email, $phone, $subscriptionStatus) {
    // Database connection and table schema assumed to be initialized elsewhere
    global $dbConnection, $userTable, $subscriptionTable;

    try {
        // Sanitize input data
        $email = filter_var($email, FILTER_SANITIZE_EMAIL);
        $phone = filter_var(trim($phone), FILTER_SANITIZE_NUMBER_INT);

        // Validate input data
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new Exception("Invalid email format.");
        }
        if (strlen($phone) !== 10) {
            throw new Exception("Phone number must be exactly 10 digits.");
        }

        // Check for unique email and phone number in the database
        $stmt = $dbConnection->prepare("SELECT COUNT(*) as count FROM {$userTable} WHERE email = ? AND id != ?");
        $stmt->execute([$email, $userId]);
        if ($stmt->fetchColumn() > 0) {
            throw new Exception("Email already in use.");
        }
        $stmt = $dbConnection->prepare("SELECT COUNT(*) as count FROM {$userTable} WHERE phone = ? AND id != ?");
        $stmt->execute([$phone, $userId]);
        if ($stmt->fetchColumn() > 0) {
            throw new Exception("Phone number already in use.");
        }

        // Update user's profile information
        $stmt = $dbConnection->prepare("UPDATE {$userTable} SET email = ?, phone = ?, subscription_status = ? WHERE id = ?");
        $stmt->execute([$email, $phone, $subscriptionStatus, $userId]);

        // Log the changes for auditing purposes
        logChange($userId, 'profile', 'email: ' . $email . ', phone: ' . $phone, 'updated');
    } catch (Exception $e) {
        // Handle exceptions and return error message
        return ['error' => $e->getMessage()];
    }

    // Return success message
    return ['success' => true];
}

function logChange($userId, $type, $details, $action) {
    // Database connection and table schema assumed to be initialized elsewhere
    global $logTable;

    // Sanitize sensitive information before logging
    $details = str_replace([':', "\n"], ['::', '***'), $details);

    // Insert log entry
    $stmt = $dbConnection->prepare("INSERT INTO {$logTable} (user_id, type, details, action) VALUES (?, ?, ?, ?)");
    $stmt->execute([$userId, $type, $details, $action]);
}
