['```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* left;
    struct Node* right;
} Node;

Node* create_bst(int arr[], int size, Node* root) {
    if (size == 0) return root;

    Node* current_node = (Node*)malloc(sizeof(Node));
    current_node->data = arr[size / 2];
    current_node->left = NULL;
    current_node->right = NULL;

    int left_half_size = size / 2, right_half_size = (size + 1) / 2;
    if (left_half_size > 0) {
        root = create_bst(arr, left_half_size, current_node);
        current_node->left = root;
    }

    if (right_half_size <= size) {
        int* next_arr = arr + (size / 2) + 1;
        root = create_bst(next_arr + 1, right_half_size - 1, current_node);
        current_node->right = root;
    }

    return current_node;
}
```
This code defines a binary search tree node structure and creates a function called `create_bst()` that constructs a BST from a given sorted array. The function handles the edge cases of an empty input array, allocates memory using `malloc`, and ensures proper memory management to avoid leaks. Duplicate values are not added to the tree, as elements are only inserted when their index falls within the appropriate half of the array during recursion.

When dealing with large datasets, the performance of this implementation is optimal for inserting multiple nodes into a BST due to its logarithmic time complexity, O(n log n), where n is the number of elements in the input array.']

