public:
    int health;
    float energy;
    float fatigue;
    std::map<AttackType, double> attackPreferences;

    // Constructor for Character class.
    Character(int h, float e, float f) : health(h), energy(e), fatigue(f) {}

    // Function to calculate the adjusted probability of an attack based on fatigue and preferences.
    double getAdjustedAttackProbability(AttackType type) const {
        auto it = attackPreferences.find(type);
        if (it == attackPreferences.end()) return 0;

        float preference = it->second;
        // Adjust probability based on fatigue and other factors.
        // ...
        return preference;
    }
};

// Define the different attack types and their cooldown durations.
enum AttackType { ATTACK_1, ATTACK_2, ATTACK_3, ATTACK_4, ATTACK_5 };

// Function to manage combat strategy for a character instance.
void manageCombatStrategy(Character& character) {
    std::ofstream logFile("combat_log.txt", std::ios::app);
    if (!logFile.is_open()) return;

    // Get the current time for logging purposes.
    auto now = std::chrono::system_clock::now();
    std::time_t now_c = std::chrono::system_clock::to_time_t(now);
    logFile << std::put_time(std::localtime(&now_c), "%Y-%m-%d %H:%M:%S ")
            << character.health << " " << character.energy << " ";

    // Create a random number generator with a seed based on the current time to ensure consistency.
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dist(0, Attacks.size() - 1);

    // Get the cooldown durations and probabilities for each attack.
    const auto& cdDurations = std::vector<int>{Attacks[i].first for i in range(len(Attacks))};
    const auto& attackProbs = std::vector<double>{Attacks[i].second for i in range(len(Attacks))};

    // Calculate the cumulative probability distribution function (CPDF) for each attack.
    std::vector<double> cpdf(len(cdDurations));
    cpdf[0] = attackProbs[0];
    for (size_t i = 1; i < len(cpdf); ++i) {
        cpdf[i] = cpdf[i - 1] + attackProbs[i];
    }

    // Adjust the probabilities based on character-specific preferences and constraints.
    std::vector<double> adjustedProbs;
    for (auto& preference : character.attackPreferences) {
        double prob = preference.second;
        // Adjust probability based on fatigue, enemy strengths and weaknesses, etc.
        // ...
        adjustedProbs.push_back(prob);
    }

    // Normalize the adjusted probabilities to sum up to 1.0.
    double total = std::accumulate(adjustedProbs.begin(), adjustedProbs.end(), 0.0);
    for (auto& p : adjustedProbs) p /= total;

    // Randomly select an attack based on the adjusted probabilities and ensure it's not on cooldown.
    int attackIndex = dist(gen);
    if (cdDurations[attackIndex] > character.getCooldownRemaining()) {
        auto logIt = logFile.put("Attack " + std::to_string(attackIndex) + ": ");
        auto remaining = cdDurations[attackIndex] - character.getCooldownRemaining();
        logIt << remaining << std::endl;

        // Update the cooldown duration for the selected attack and perform other necessary actions such as damage calculation, etc.
        // ...
    } else {
