struct trim_and_log_config {
    size_t default_size_limit = 256;
    size_t max_allocations = ULONG_MAX;
    bool enable_logging = true;
    std::mutex config_mutex;
};

static struct trim_and_log_config global_config;
std::map<std::thread::id, size_t> allocations_count;

void log(const char *format, ...) {
    if (global_config.enable_logging) {
        va_list args;
        va_start(args, format);
        const char *operation = "trim_and_log";
        vprintf(format, args);
        printf(" operation: %s, input string length: %, size limit: %, allocated buffer size: %, current memory usage: %d\n",
               (int)wcswlen(arg), global_config.default_size_limit, (int)(wcslen(result)), (int)get_memory_usage());
        va_end(args);
    }
}

size_t get_allocations_count() {
    size_t count = 0;
    for (const auto &pair : allocations_count)
        count += pair.second;
    return count;
}

wchar_t *trim_and_log(wchar_t *str, size_t size, void (*log_func)(const char*, ...)) {
    if (!str || size <= 0 || !log_func)
        return NULL;

    size_t str_len = wcslen(str);
    if (wcscpy_s(nullptr, 0, str) == SSIZE_MAX || str_len + 1 >= size) {
        log("Failed to allocate buffer or string exceeded the size limit");
        return NULL;
    }

    wchar_t *result = new wchar_t[str_len + (size > str_len ? 2 : 0)];
    if (!result || wcscpy_s(result, size, str) == SSIZE_MAX) {
        log("Failed to copy string to the buffer");
        delete[] result;
        return NULL;
    }

    if (str_len < size - 1) {
        result[str_len] = L' ';
        result[str_len + 1] = L'\0';
    }

    log("Allocated memory for trimming and logging");

    std::unique_lock<std::mutex> lock(global_config.config_mutex);
    global_config.allocations_count.emplace(std::this_thread::get_id(), 1);

    if (++global_config.allocations_count[std::this_thread::get_id()] > global_config.max_allocations) {
        log("Maximum number of allocations reached, disabling further trimming and logging.");
        global_config.enable_logging = false;
    }

    return result;
}
