NFAPI_CRC_INDICATION_PDU_T* generateNfaPduList(int num_pdus, const uint8_t *encryption_key, const uint8_t *IV, const uint8_t *ciphertext) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Memory allocation error");
        return NULL;
    }

    AES_KEY aes_key;
    AES_set_encrypt_key(encryption_key, 128, &aes_key);

    int i;
    for (i = 0; i < num_pdus; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i + 1;
        pdu_list[i].RNTI = i * 257 + 1;
        pdu_list[i].CRC_INDICATION_REL8_TAG[0] = (uint8_t)(rand() % 2);
        pdu_list[i].CRC_INDICATION_REL8_TAG[1] = (uint8_t)((pdu_list[i].CRC_INDICATION_REL8_TAG[0] << 7) | (rand() % 128));
        pdu_list[i].CRC_INDICATION_REL8_TAG[2] = (uint8_t)((pdu_list[i].CRC_INDICATION_REL8_TAG[1] << 7) | (rand() % 128));
        pdu_list[i].CRC_INDICATION_REL8_TAG[3] = (uint8_t)((pdu_list[i].CRC_INDICATION_REL8_TAG[2] << 7) | (rand() % 128));

        uint8_t decrypted_plaintext[16];
        AES_cbc_decrypt(ciphertext + i * 16, decrypted_plaintext, decrypted_plaintext, IV, &aes_key);
        memcpy(pdu_list[i].plaintext, decrypted_plaintext, 16);
    }

    free(aes_key.dk); // Free the key schedule after use

    return pdu_list;
}
