#include <fcntl.h>
#include <termios.h>
#include <zlib.h>

typedef struct {
    time_t timestamp;
    int sensor_id;
    float temperature;
} Metric;

int processAndStoreMetrics(int baud_rate, const char* data_format, const char* output_file) {
    struct termios options;
    tcgetattr(STDIN_FILENO, &options);
    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);
    tcsetattr(STDIN_FILENO, TCSANOW, &options);

    int fd = open("/dev/ttyUSB0", O_RDONLY | O_NONBLOCK); // Change to the correct serial port
    if (fd < 0) {
        perror("Cannot open serial port");
        return -1;
    }

    size_t metric_capacity = 1024;
    Metric* metrics = malloc(metric_capacity * sizeof(Metric));
    size_t num_metrics = 0;

    char buffer[1024];
    while (1) {
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read <= 0) {
            break;
        }

        char* line_start = buffer;
        for (char* current = buffer; *current != '\0'; ++current) {
            if (*current == '\n') {
                *current = '\0';
                processMetric(line_start, data_format, &metrics[num_metrics], num_metrics < metric_capacity);
                line_start = current + 1;
                num_metrics++;
                if (num_metrics >= metric_capacity) {
                    Metric* new_metrics = realloc(metrics, (metric_capacity *= 2) * sizeof(Metric));
                    if (!new_metrics) {
                        perror("Failed to reallocate memory");
                        break;
                    }
                    metrics = new_metrics;
                }
            }
        }
    }

    uLongf compressed_size;
    char* compressed_data = compress2((Bytef*)metrics, num_metrics * sizeof(Metric), &compressed_size, Z_DEFAULT_COMPRESSION);

    int file = open(output_file, W_ONLY | CREATE);
    if (file < 0) {
        perror("Failed to create output file");
        free(compressed_data);
        return -1;
    }

    ssize_t written = write(file, compressed_data, compressed_size);
    if (written != static_cast<ssize_t>(compressed_size)) {
        perror("Failed to write to output file");
        free(compressed_data);
        close(file);
        return -1;
    }

    free(metrics);
    free(compressed_data);
    close(file);
    close(fd);

    tcsetattr(STDIN_FILENO, TCSANOW, &options);

    return num_metrics;
}
```

