    if (strcmp(json_string_value(token_type), "Bearer") != 0 || json_integer_value(expires_in) <= 0) {
        fprintf(stderr, "Error: Invalid access token\n");
        json_decref(root);
        return;
    }

    // Implement DES encryption functions for the different cipher modes here
}

