    private List<NFAPI_CRC_INDICATION_PDU_T> pduList = new ArrayList<>();

    public void establishAndManageConnection(String oauth2Response, String serverAddress, MessagingSystem messagingSystem) throws NoSuchAlgorithmException, KeyManagementException {
        accessToken = processAccessToken(oauth2Response);
        this.serverAddress = new InetSocketAddress(serverAddress);
        this.messagingSystem = messagingSystem;
        cipher = getCipherInstance("DES/ECB"); // Set cipher mode as per requirement
        connectionState = ConnectionState.DISCONNECTED;
        executor = Executors.newSingleThreadExecutor();
        startService();
    }

    private String processAccessToken(String oauth2Response) {
        JsonNode rootNode = objectMapper.readTree(oauth2Response);
        if (rootNode.has("access_token") && rootNode.has("expires_in") && rootNode.get("token_type").asText().equalsIgnoreCase("Bearer")) {
            String accessToken = rootNode.get("access_token").asText();
            int expiresIn = rootNode.get("expires_in").asInt();
            return accessToken;
        } else {
            throw new IllegalArgumentException("Invalid OAuth2 access token response");
        }
    }

    private Cipher getCipherInstance(String algorithm) throws NoSuchAlgorithmException, KeyManagementException {
        SecretKeySpec keySpec = generateSecretKey();
        return Cipher.getInstance(algorithm);
    }

    private SecretKeySpec generateSecretKey() {
        byte[] keyBytes = new byte[8]; // 64-bit DES key
        SecureRandom random = new SecureRandom();
        random.nextBytes(keyBytes);
        return new SecretKeySpec(keyBytes, "DES");
    }

    private void startService() {
        Runnable serviceTask = () -> {
            while (!Thread.currentThread().isInterrupted()) {
                switch (connectionState) {
                    case DISCONNECTED:
                        connect();
                        break;
                    case CONNECTING:
                    case FAILED:
                        randomDelay();
                        checkConnectionState();
                        break;
                    case CONNECTED:
                        performServiceOperations();
                        break;
                }
            }
        };
        executor.execute(serviceTask);
    }

    private void connect() {
        // Establish connection to the serverAddress here
        connectionState = ConnectionState.CONNECTING;
    }

    private void checkConnectionState() {
        // Check for connection status and switch states accordingly
        // If disconnected or failed, simulate retrying with a delay
    }

    private void performServiceOperations() {
        // Implement service operations here with delays between operations
    }

    private void randomDelay() {
        try {
            executor.shutdown();
            executor.awaitTermination(new Random().nextInt(5000), TimeUnit.MILLISECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void stopService() {
        executor.shutdownNow();
        sendStopMessage();
    }

    private void sendStopMessage() {
        if (messagingSystem != null) {
            messagingSystem.sendStopMessage();
        }
    }

    public void populatePDUList(int size) {
        for (int i = 0; i < size; i++) {
            pduList.add(new NFAPI_CRC_INDICATION_PDU_T()
                    .setRxUeInformationTag((short) (Math.random() * Short.MAX_VALUE))
                    .setRnti((long) (Math.random() * Long.MAX_VALUE))
                    .setCrcIndicationRel8Tag(new CRC_INDICATION_REL8_TAG().setCrcflag((byte) (Math.random() > 0.5 ? 1 : 0)));
        }
    }

    public enum ConnectionState {
        DISCONNECTED,
        CONNECTING,
        CONNECTED,
        FAILED
    }
}
