#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int key;
    long value;
    struct Node* prev;
    struct Node* next;
} Node;

Node* create_node(void) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        perror("Memory allocation failed");
        return NULL;
    }
    node->key = rand() % 100;
    node->value = (long)rand() * RAND_MAX;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void insert_head(Node** head, Node* new_node) {
    if (*head == NULL) {
        *head = new_node;
        return;
    }
    new_node->next = *head;
    (*head)->prev = new_node;
    *head = new_node;
}

void insert_tail(Node** head, Node* new_node) {
    if (*head == NULL) {
        *head = new_node;
        return;
    }
    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
    new_node->prev = current;
}

Node* find_node_by_key(Node* node, int key) {
    for (Node* current = node; current != NULL; current = current->next) {
        if (current->key == key) {
            return current;
        }
    }
    return NULL;
}

void remove_node_by_key(Node** head, int key) {
    Node* node_to_remove = find_node_by_key(*head, key);
    if (!node_to_remove) {
        return;
    }
    if (node_to_remove == *head) {
        *head = node_to_remove->next;
        if (*head) {
            (*head)->prev = NULL;
        }
        free(node_to_remove);
        return;
    }
    Node* current = *head;
    while (current->next != node_to_remove) {
        current = current->next;
        if (!current->next) {
            break;
        }
    }
    if (!current->next) {
        return;
    }
    current->next = node_to_remove->next;
    if (node_to_remove->next) {
        node_to_remove->next->prev = current;
    }
    free(node_to_remove);
}

void free_list(Node* head) {
    Node* current;
    while ((current = head)) {
        head = head->next;
        free(current);
    }
}
```

This code defines a doubly-linked list of custom `Node` objects, where each node contains an `int` key, a `long` value, and pointers to the previous and next nodes. It provides functions for inserting nodes at both the head and tail, as well as removing nodes by their keys, while handling memory allocation failures, data corruption, and edge cases such as empty lists and duplicate keys.

The code also includes a helper function to find nodes by their keys, and one for freeing the list to properly handle deallocation order and circular references. For integrating external data sources for node key generation, you can modify the `create_node` function accordingly.

Performance optimization strategies are considered in terms of efficient memory management and linear search capabilities for key-based removal. Balancing the trade-off between time complexity and space utilization has been addressed by using a doubly-linked list, which supports frequent insertions and deletions while maintaining linear search capabilities.']

