#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mqueue_overview.h> // Asynchronous messaging queue for microservices communication

// Custom Node structure
typedef struct Node {
    int key;
    long value;
    struct Node *prev, *next;
} Node;

// Doubly-linked list structure
typedef struct DList {
    struct Node *head, *tail;
    size_t size;
    pthread_mutex_t lock;
    Node *cache; // LRU cache for recently deleted nodes
    size_t cache_size;
} DList;

// Initialize and clean up the list
void init_dlist(DList *list, size_t cache_size) {
    list->head = list->tail = NULL;
    list->size = 0;
    list->cache = NULL;
    list->cache_size = cache_size;
    pthread_mutex_init(&list->lock, NULL);
}

void free_dlist(DList *list) {
    Node *node, *temp;
    pthread_mutex_lock(&list->lock);
    node = list->head;
    while (node != NULL) {
        temp = node;
        node = node->next;
        free(temp);
    }
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
}

// Initialize a new node with random values and add it to the head of the list
void insert_head(DList *list, int key, long value) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }
    new_node->key = key;
    new_node->value = value;
    new_node->prev = NULL;
    new_node->next = list->head;

    if (list->head) {
        list->head->prev = new_node;
    }
    list->head = new_node;

    if (!list->tail) {
        list->tail = new_node;
    }
    list->size++;
}

// Add a new node to the tail of the list
void insert_tail(DList *list, int key, long value) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }
    new_node->key = key;
    new_node->value = value;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
        list->tail = new_node;
    } else {
        list->head = new_node;
    }
    list->size++;
}

// Insert a node at the specified position in the list, moving existing nodes if necessary
void insert(DList *list, int key, long value, size_t pos) {
    pthread_mutex_lock(&list->lock);
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->key = key;
    new_node->value = value;

    if (pos >= list->size) {
        insert_tail(list, key, value);
    } else {
        Node *current = list->head;
        for (size_t i = 0; i < pos && current != NULL; ++i) {
            current = current->next;
        }
        new_node->next = current->next;
        if (current->next) {
            current->next->prev = new_node;
        } else {
            list->tail = new_node;
        }
        new_node->prev = current;
        current->next = new_node;
        list->size++;
    }
    pthread_mutex_unlock(&list->lock);
}

// Remove a node from the list by key, returning its value or 0 if not found
long delete_by_key(DList *list, int key) {
    long value = 0;
    Node *current = list->head;
    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->key == key) {
            if (current->prev) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            value = current->value;
            // Cache the deleted node for potential reuse
            if (list->cache && list->cache_size > 0) {
                list->cache->key = key;
                list->cache->value = 0;
                list->cache->next = current;
                list->cache = current;
                --list->cache_size;
            }
            free(current);
            list->size--;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return value;
}

