#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jpeg/jpeglib.h>
#include <brotli/brotli.h>
#include <zstd.h>

typedef struct {
    JPEG_COMPONENT_INFO jpeg_info;
    int num_unsupported_orientations;
    int* unsupported_orientations;
    char* report;
    void* compressed_data;
    size_t compressed_size;
} ProcessedImage;

ProcessedImage* processImageAndCompress(const char* jpeg_file, const char* text_file, int quality, int compression_type) {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE * infile = fopen(jpeg_file, "rb");
    JSAMPARRAY buffer;
    size_t image_size;
    int num_components;
    int unsupported_orientations_count = 0;
    int* unsupported_orientations = NULL;
    ProcessedImage* result = malloc(sizeof(ProcessedImage));

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, infile);
    (void) jpeg_read_header(&cinfo, TRUE);

    if (quality < 0 || quality > 100) {
        result->report = strdup("Error: Unsupported JPEG compression quality.");
        free(result);
        return NULL;
    }

    if (cinfo.image_width > 8192 || cinfo.image_height > 8192) {
        result->report = strdup("Error: Image size exceeds the maximum supported limit.");
        free(result);
        return NULL;
    }

    if (cinfo.orientation == 90 || cinfo.orientation == 270) {
        unsupported_orientations_count++;
        unsupported_orientations = realloc(unsupported_orientations, unsupported_orientations_count * sizeof(int));
        unsupported_orientations[unsupported_orientations_count - 1] = cinfo.orientation;
    }

    while (cinfo.read_scanlines < cinfo.num_scanlines) {
        jpeg_read_scanlines(&cinfo, buffer, 1);
    }

    jpeg_finish_decompress(&cinfo);
    fclose(infile);

    if (cinfo.orientation == 90 || cinfo.orientation == 270) {
        unsupported_orientations_count++;
        unsupported_orientations = realloc(unsupported_orientations, unsupported_orientations_count * sizeof(int));
        unsupported_orientations[unsupported_orientations_count - 1] = cinfo.orientation;
    }

    result->num_unsupported_orientations = unsupported_orientations_count;
    result->unsupported_orientations = unsupported_orientations;

    FILE * text_file_ptr = fopen(text_file, "rb");
    fseeko64(text_file_ptr, 0L, SEEK_END);
    size_t text_size = ftello64(text_file_ptr);
    fclose(text_file_ptr);

    if (compression_type == BROTLI_COMPRESS_MODE_FAST) {
        BrotliEncoder encoder;
        brotli_encoder_init(&encoder, BROTLI_MODE_GENERIC);
        void* compressed_data = malloc(text_size + 1024); // Additional buffer for safety
