size_t find_last_index(char delimiter, char const *str) {
    size_t last_index = 0;
    for (size_t i = 0; str[i]; ++i) {
        if (str[i] == delimiter) {
            last_index = i;
        }
    }
    return last_index;
}

void append(Line *line, const char *value, size_t value_len) {
    line->length += value_len + 1; //+1 for comma or space delimiter
    line->capacity = (line->capacity < line->length) ? line->length * 2 : line->capacity;
    line->line = realloc(line->line, line->capacity);
    memcpy(line->line + line->length - value_len, value, value_len);
    line->line[line->length - 1] = ','; // append comma
    if (line->length > 2) {
        line->line[line->length - 2] = ' '; // append space between values
    }
}

