void apply_transformations(JsonObject *rules, char *data, size_t data_len, FILE *outfile);

// Autoscaling mechanism using semaphores and pthreads
pthread_mutex_t thread_mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t sem_threads;
