    if (infile == -1) {
        perror("Error opening input file");
        return -1;
    }

    int outfile = open(argv[2], O_CREAT | O_WRONLY | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (outfile == -1) {
