        bytes_read = read(infile, buffer, sizeof(buffer));
    }

    close(infile);
    close(outfile);

    // Wait for all worker threads to finish
    pthread_mutex_lock(&thread_mutex);
    shutdown = true;
    sem_post(&sem_threads);
    pthread_mutex_unlock(&thread_mutex);

