#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <time.h>
#include <pthread.h>
#include <libpng/png.h>
#include <tiffio.h>
#define MAX_PATH 256
#define BUFFER_SIZE 4096

typedef struct {
    char path[MAX_PATH];
    char new_path[MAX_PATH];
    time_t timestamp;
} FileInfo;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
uint64_t checksum(off_t inode);
char *generate_unique_id(const char *filename);
int process_file(const char *input_path, const char *output_path, const char *pattern);
int convert_png_to_tiff(const char *input_path, const char *output_path);
void *worker(void *arg);

int png_to_tiff(const char *input_dir, const char *output_dir, const char *filter) {
    DIR *input_dp = opendir(input_dir);
    if (!input_dp) return 1;

    struct dirent *entry;
    FileInfo *file_list = malloc(sizeof(FileInfo));
    int err = 0;

    pthread_t threads[BUFFER_SIZE];
    while ((entry = readdir(input_dp)) != NULL) {
        snprintf(file_list->path, MAX_PATH, "%s/%s", input_dir, entry->d_name);
        if (strcasestr(entry->d_name, filter)) {
            snprintf(file_list->new_path, MAX_PATH, "%s/%s", output_dir, generate_unique_id(entry->d_name));
            pthread_mutex_lock(&mutex);
            if (access(file_list->new_path, F_OK) == 0) {
                pthread_mutex_unlock(&mutex);
                continue;
            }
            pthread_create(&threads[err], NULL, worker, file_list);
            err++;
            pthread_mutex_unlock(&mutex);
        }
    }

    for (int i = 0; i < err; i++) {
        pthread_join(threads[i], NULL);
    }

    closedir(input_dp);
    free(file_list);

    return err > 0 ? 0 : 1;
}

void *worker(void *arg) {
    FileInfo *data = arg;
    int result = process_file(data->path, data->new_path, "");
    if (result == -1) {
        free(data);
        return NULL;
    }

    // Update the file's timestamp and checksum for consistency
    struct stat sb;
    if (stat(data->path, &sb) != 0 || stat(data->new_path, &sb) != 0) {
        free(data);
        return NULL;
    }

    data->timestamp = sb.st_mtime;
    char checksum_str[21];
    snprintf(checksum_str, sizeof(checksum_str), "%08lx", checksum(sb.st_ino));
    strcat(data->new_path, checksum_str);

    return NULL;
}

int process_file(const char *input_path, const char *output_path, const char *pattern) {
    if (convert_png_to_tiff(input_path, output_path)) return -1;

    // Modify the file's attributes here
    struct stat sb;
    if (stat(output_path, &sb) != 0) return -1;
    time_t current_time = time(NULL);
    struct tm *tm = localtime(&current_time);
    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm);

    mode_t old_mode = sb.st_mode;
    chmod(output_path, S_IRUSR | S_IWUSR | S_IXUSR);
    sb.st_atime = current_time;
    sb.st_mtime = current_time;

    char attrs[32 + 16];
    snprintf(attrs, sizeof(attrs), "%s %lu", timestamp_str, (unsigned long)sb.st_size);
    if (lsetxattr(output_path, "user.attributes", attrs, strlen(attrs)) != 0) return -1;

    return 0;
}

int convert_png_to_tiff(const char *input_path, const char *output_path) {
    FILE *input = fopen(input_path, "rb");
    if (!input) return 1;

    png_structp png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!png_ptr) {
        fclose(input);
        return 1;
    }

    png_infop info_ptr = png_create_info_struct(png_ptr);
    if (!info_ptr) {
        png_destroy_read_struct(&png_ptr, (png_infopp)NULL, (png_infopp)NULL);
        fclose(input);
        return 1;
    }

    if (setjmp(png_jmpbuf(png_ptr))) {
        png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
        fclose(input);
        return 1;
    }

    tdata tdatas[1];
    tdatas[0].buf = (char *) malloc(BUFFER_SIZE);
    if (!tdatas[0].buf) {
        png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
        fclose(input);
        return 1;
    }

    tdatas[0].size = BUFFER_SIZE;
    tdatas[0].next = NULL;

    png_init_io(png_ptr, input);
    png_set_read_fn(png_ptr, tdatas, read_data);
    png_read_info(png_ptr, info_ptr);

    FILE *output = fopen(output_path, "wb");
    if (!output) {
        png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
        png_destroy_write_struct(&tdatas[0].cinfo, (png_infopp)NULL);
        free(tdatas[0].buf);
        fclose(input);
        return 1;
    }

    tdatas[0].next = malloc(sizeof(*tdatas));
    if (!tdatas[0].next) {
        png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
        png_destroy_write_struct(&tdatas[0].cinfo, &tdatas[1].cinfo);
        fclose(input);
        free(tdatas[0].buf);
        return 1;
    }

    tdatas[0].next->buf = malloc(BUFFER_SIZE);
    if (!tdatas[0].next->buf) {
        png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
        png_destroy_write_struct(&tdatas[0].cinfo, &tdatas[1].cinfo);
        free(tdatas[0].buf);
        fclose(input);
        return 1;
    }

    tdatas[0].next->size = BUFFER_SIZE;
    tdatas[0].next->next = NULL;

    png_set_write_fn(png_ptr, tdatas[0], write_data, (png_fp)NULL);
    png_read_update_info(png_ptr, info_ptr);
    png_write_tiff(png_ptr);

    png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
    png_destroy_write_struct(&tdatas[0].cinfo, &tdatas[1].cinfo);
    free(tdatas[0].buf);
    fclose(input);
    free(tdatas[0].next->buf);
    free(tdatas[0].next);
    fclose(output);

    return 0;
}

uint64_t checksum(off_t inode) {
