    // For example, use the Lehman-Hellman algorithm or another suitable method
}

char *generate_unique_id(const char *filename) {
    static const char hex_digits[] = "0123456789ABCDEF";

    int len = strlen(filename);
    int uppercase_count = 0;
    for (int i = 0; i < len; ++i) {
        if (isupper(filename[i])) ++uppercase_count;
    }

    char *unique_id = malloc(32);
    snprintf(unique_id, sizeof(unique_id), "%c%08x", uppercase_count > 0 ? toupper(filename[0]) : 'Z', rand());

    FILE *file = fopen("/proc/self/fd/1", "r");
    if (file) {
        char buffer[32];
        ssize_t bytes_read;
        while ((bytes_read = getline(&buffer, sizeof(buffer), file)) != -1) {
            if (!strncmp(buffer, "inode:", 6)) {
                off_t inode_num = strtol(&buffer[6], NULL, 10);
                snprintf(unique_id + strlen(unique_id), sizeof(unique_id) - strlen(unique_id), "%lx", checksum(inode_num));
            }
        }
        fclose(file);
    }

    return unique_id;
}
