```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <pthread.h>

// Structure for network device configuration
typedef struct {
    char ip[INET_ADDRSTRLEN];
    char subnet_mask[INET_ADDRSTRLEN];
    char gateway[INET_ADDRSTRLEN];
    char mac_address[18];
} DeviceConfig;

// Custom validation function for device configurations
int validate(DeviceConfig config) {
    // Check for IPv4 address format using inet_pton()
    if (inet_pton(AF_INET, config.ip, NULL) <= 0) return -1;
    if (inet_pton(AF_INET, config.subnet_mask, NULL) <= 0) return -1;
    if (inet_pton(AF_INET, config.gateway, NULL) <= 0) return -1;

    // Check for MAC address format using sscanf()
    char mac[32];
    strcpy(mac, config.mac_address);
    if (sscanf(mac, "%2x:%2x:%2x:%2x:%2x:%2x",
        &config.mac_address[0], &config.mac_address[1],
        &config.mac_address[2], &config.mac_address[3],
        &config.mac_address[4], &config.mac_address[5]) != 6)
        return -1;

    return 0;
}

// Thread-safe dynamic list structure
typedef struct List {
    DeviceConfig* data;
    size_t size, capacity, max_size;
    pthread_mutex_t lock;
} List;

// Function to initialize the list with given maximum size
List* list_init(size_t max_size) {
    List* list = malloc(sizeof(List));
    list->data = calloc(max_size, sizeof(DeviceConfig));
    list->size = 0;
    list->capacity = max_size;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a device configuration to the list, validating it first
int list_add(List* list, DeviceConfig config) {
    if (validate(config)) return -1; // Validation failed

    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->data = realloc(list->data, sizeof(DeviceConfig) * list->capacity);
    }

    memcpy((void*)&list->data[list->size], &config, sizeof(DeviceConfig));
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Function to remove a device configuration by index from the list, returning the removed configuration
DeviceConfig list_remove(List* list, size_t index) {
    if (index >= list->size || index < 0) return (DeviceConfig){0}; // Index out of bounds

    pthread_mutex_lock(&list->lock);
    DeviceConfig config = list->data[index];
    memmove((void*)&list->data[index], &list->data[index + 1], sizeof(DeviceConfig) * (list->size - index - 1));
    list->size--;
    pthread_mutex_unlock(&list->lock);

    return config;
}

// Function to update a device configuration by index in the list, validating the new configuration first
int list_update(List* list, size_t index, DeviceConfig new_config) {
    if (validate(new_config)) return -1; // Validation failed

    pthread_mutex_lock(&list->lock);
    if (index >= list->size || index < 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Index out of bounds
    }

    memcpy((void*)&list->data[index], &new_config, sizeof(DeviceConfig));
    pthread_mutex_unlock(&list->lock);

    return 0;
}

