                if all([field in device for field in ['ip', 'subnet_mask', 'gateway', 'mac_address']]):
                    devices.append(device)
            except Exception as e:
                print(f'Error processing JSON: {e}')
    return devices

def export_csv(devices, file):
    with open(file, 'w', newline='') as f:
        writer = csv.DictWriter(f, fieldnames=['ip', 'subnet_mask', 'gateway', 'mac_address'])
        writer.writeheader()
        for device in devices:
            writer.writerow({k: v for k, v in device.items()})
```

