```csharp
public class CacheModule<T>
{
    private ConcurrentDictionary<string, T> _cache;

    public CacheModule()
    {
        _cache = new ConcurrentDictionary<string, T>();
    }

    public T GetOrCreate(string key, Func<string, T> creator)
    {
        if (_cache.TryGetValue(key, out var value))
            return value;

        value = creator(key);
        _cache[key] = value;
        return value;
    }
}
