public class ImageProcessor
{
    private List<Algorithm> _algorithms = new List<Algorithm>();
    private bool _performanceOptimizationMode;

    public byte[] ProcessAndEnhanceImageQuality(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException("The specified file does not exist.", filePath);

        using (FileStream fs = new FileStream(filePath, FileMode.Open, FileAccess.Read))
        using (var img = Image.FromStream(fs))
        {
            byte[] imageBytes = ImageToByteArray(img);
            EnhanceImageQuality(imageBytes);
            return imageBytes;
        }
    }

    public void RegisterAlgorithm(Algorithm algorithm)
    {
        _algorithms.Add(algorithm);
    }

    public void SetPerformanceOptimizationMode(bool isEnabled)
    {
        _performanceOptimizationMode = isEnabled;
    }

    private void EnhanceImageQuality(byte[] imageBytes)
    {
        using (MemoryStream ms = new MemoryStream(imageBytes))
        using (var img = Image.FromStream(ms))
        {
            var availableAlgorithms = _algorithms.Where(x => x.IsAvailable(_performanceOptimizationMode)).ToList();

            foreach (var algorithm in availableAlgorithms)
                algorithm.ApplyEnhancements(img);

            img.Save(ms, System.Drawing.Imaging.ImageFormat.Jpeg);
        }
