using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Org.BouncyCastle.Crypto.Parameters;
using Org.BouncyCastle.Paddings;
using Org.BouncyCastle.Security;

public class DecryptionHelper
{
    private static readonly byte[] DefaultIV = { 0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F };
    private static readonly byte[] PKCS7Padding = new PKCS7Padding().GenerateFunctionParameter();

    public byte[] Decrypt(byte[] ciphertext, string encryptionKey, string ivStr = null, string paddingScheme = "PKCS7")
    {
        var iv = ivStr ?? DefaultIV;
        ICryptoTransform cryptoTransform = Aes.Create();
        using (var rsa = RSA.Create())
        {
            rsa.ImportCspParameters(new RSACryptoServiceProvider().ExportCspParameters(false));
            cryptoTransform.Key = rsa.DecryptKeyParam(Encoding.UTF8.GetBytes(encryptionKey));
        }
        cryptoTransform = cryptoTransform.CreateDecryptor(cryptoTransform.Key, iv);

        IBlockCipher cipher = new CbcBlockCipher(cryptoTransform);
        PaddedBufferedBlockCipher paddedCipher;
        if (paddingScheme == "PKCS5")
            paddedCipher = new PaddedBufferedBlockCipher(new PKCS5Padding(), cipher);
        else if (paddingScheme == "PKCS7")
            paddedCipher = new PaddedBufferedBlockCipher(PKCS7Padding, cipher);
        else
            throw new ArgumentException("Invalid padding scheme");

        byte[] decryptedPlaintext = null;
        int maxChunkSize = 16 * 1024; // 16KB as per the requirement
        using (var inputStream = new MemoryStream(ciphertext))
        {
            var chunkSize = Math.Min(maxChunkSize, ciphertext.Length);
            var buffer = new byte[chunkSize];
            inputStream.Read(buffer, 0, chunkSize);
            decryptedPlaintext = paddedCipher.DoFinal(buffer);
        }

        if (!Array.Equals(iv, GetIVFromPlainText(decryptedPlaintext)))
            throw new Exception("Invalid data: IV does not match the expected initial vector.");

        return decryptedPlaintext;
    }

    private byte[] GetIVFromPlainText(byte[] plaintext)
    {
        if (plaintext.Length < 16)
            throw new ArgumentException("Plaintext is too short for the IV extraction.");
        Array.Copy(plaintext, 0, DefaultIV, 0, 16);
        return DefaultIV;
    }
}
