using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Bluebird;
using Logger = Serilog.ILogger; // Assuming you have a logger implementation like Serilog

public class DynamicFileUploader
{
    private readonly List<Tuple<float, float>> _ranges;
    private readonly object _lockObject;
    private string _currentUrl;
    private Logger _logger;

    public DynamicFileUploader(Logger logger)
    {
        _ranges = new List<Tuple<float, float>>();
        _lockObject = new object();
        _logger = logger;
        SetRange(0f, 100f);
    }

    public void SetRange(float min, float max)
    {
        lock (_lockObject)
        {
            var overlaps = _ranges.Any(r => (min < r.Item1 && min > r.Item2) || (max < r.Item1 && max > r.Item2));

            if (overlaps)
                throw new ArgumentException("Given range overlaps with an existing range.");

            _ranges.Add(new Tuple<float, float>(min, max));
        }
    }

    public float GetRandomFloat() => _ranges.Select(r => r.Item1 + (r.Item2 - r.Item1) * new Random().NextDouble()).First();

    public int GetRandomInt() => Convert.ToInt32(Math.Round(GetRandomFloat()));

    public override string ToString() => $"Current ranges: {string.Join(", ", _ranges)}";

    private async Task<string> UploadFileAsync(string url, string destinationPath)
    {
        try
        {
            _logger.Information("Uploading file to {Url}", url);

            using var uploader = FileUploaderFactory.Create(url); // Assuming you have a FileUploaderFactory implementation
            await uploader.UploadAsync(destinationPath, new TransferOptions
            {
                OnProgress = progress => _logger.Information("Progress: {Percentage}%", progress.Percentage),
                OnError = exception => _logger.Error(exception, "Error while uploading file.")
            });

            return url;
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Failed to upload file.");
            throw;
        }
    }

    public string UploadFile(string url, string destinationPath) => UploadFileAsync(url, destinationPath).Result;
}
```
