const axios = require('axios');
const cache = new Map();
const rateLimit = require('limiter').default({ max: 60, time: 1000 }); // Limit API calls to 60 per minute

class UserDataApi {
    async getUserData(query) {
        const limiter = rateLimit.wrap(this.getFromCacheOrFetch);
        return limiter(query);
    }

    async getFromCacheOrFetch(query) {
        if (cache.has(query)) {
            console.log(`Returning user data from cache: ${query}`);
            return cache.get(query);
        }

        try {
            const response = await axios.get(`https://api.example.com/users?query=${encodeURIComponent(query)}`);
            if (response.status === 200) {
                console.log(`Fetched user data from API: ${query}`);
                cache.set(query, response.data);
                return response.data;
            } else {
                throw new Error(`API returned error status code: ${response.status}`);
            }
        } catch (error) {
            console.error(`Error fetching user data from API: ${query} - ${error.message}`);
            throw new Error(`Failed to fetch user data: ${error.message}`);
        }
    }
}

module.exports = UserDataApi;
