        return [serialize_nested(item) for item in obj]
    elif isinstance(obj, dict):
        return {k: serialize_nested(v) for k, v in obj.items()}
    else:
        return obj

def deserialize_nested(data):
    if isinstance(data, list):
        return [deserialize_nested(item) for item in data]
    elif isinstance(data, dict):
        return {k: deserialize_nested(v) for k, v in data.items()}
    else:
        return data
