#include <sys/mman.h>
#include <openssl/sha.h>

#define MAX_PATH_LEN 256
typedef struct {
    char path[MAX_PATH_LEN];
    off_t size;
    time_t mtime;
} FileData;

static pthread_mutex_t filemap_lock = PTHREAD_MUTEX_INITIALIZER;
static FileData* filemap = NULL;
static size_t filemap_size = 0;

int compress_files(char *src_dir, char *dest_dir, char *pattern) {
    DIR *src_dp = opendir(src_dir);
    struct dirent *entry;
    if (!src_dp) return 1;

    struct stat st;
    char newpath[MAX_PATH_LEN];
    SHA256_CTX ctx;

    while ((entry = readdir(src_dp)) != NULL) {
        strcpy(newpath, src_dir);
        snprintf(&newpath[strlen(newpath)], MAX_PATH_LEN - strlen(newpath), "/%s", entry->d_name);
        if (stat(newpath, &st) == 0 && st.st_mode & S_IFREG && regexec(pattern, entry->d_name, 0, NULL) == 0) {
            // Check for duplicate in filemap
            pthread_mutex_lock(&filemap_lock);
            FileData *fd;
            for (size_t i = 0; i < filemap_size; ++i) {
                fd = &filemap[i];
                if (!strcmp(fd->path, newpath) && !strcmp(fd->path + strlen(newpath), entry->d_name)) {
                    pthread_mutex_unlock(&filemap_lock);
                    break;
                }
            }
            pthread_mutex_unlock(&filemap_lock);
            if (fd) continue; // Found duplicate, skip this file

            // Add to filemap for future reference
            FileData *new_fd = malloc(sizeof(FileData));
            strcpy(new_fd->path, newpath);
            new_fd->size = st.st_size;
            new_fd->mtime = st.st_mtime;
            filemap = realloc(filemap, sizeof(FileData) * (++filemap_size));
            memcpy(&filemap[filemap_size - 1], new_fd, sizeof(FileData));

            // Compress the file and modify its attributes
            compress_and_modify(newpath, dest_dir);
        }
    }

    closedir(src_dp);
    free(filemap);
    filemap = NULL;
    filemap_size = 0;

    return 0;
}

void compress_and_modify(char *path, char *dest_dir) {
    // ... Compression logic here ...

    SHA256_Init(&ctx);
    SHA256_Update(&ctx, (unsigned char*) path, strlen(path));

    // Generate unique identifier
    const char* hash = Sha256FinalHex(&ctx);
    char timestamp[16];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&now));

    const size_t unique_id_len = strlen(timestamp) + strlen(hash) + 10; // Add some margin
    char *unique_id = malloc(unique_id_len);
    snprintf(unique_id, unique_id_len, "%s%08x%s", timestamp, (unsigned int) Sha256FileChecksum(path), hash);

    // Construct the new file path in dest_dir
    char new_dest_path[MAX_PATH_LEN];
    snprintf(new_dest_path, MAX_PATH_LEN, "%s/%s.compressed", dest_dir, unique_id);

    pthread_mutex_lock(&filemap_lock);
    FileData *fd;
    for (size_t i = 0; i < filemap_size; ++i) {
        fd = &filemap[i];
        if (!strcmp(fd->path, path)) {
            strcpy(fd->path, new_dest_path);
            break;
        }
    }
    pthread_mutex_unlock(&filemap_lock);

    // Apply modifications to the file's metadata
    chmod(new_dest_path, S_IRUSR | S_IWUSR | S_IXUSR);
    utime(new_dest_path, NULL);
}
```

