// Function to find and print the largest integer in the array
void print_largest(int *arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; ++i) {
        if (max < arr[i]) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Function to check for duplicate integers in the array and report the count
int has_duplicates(int *arr, int size) {
    int counts[1001] = { 0 };
    for (int i = 0; i < size; ++i) {
        if (counts[arr[i]]++) {
            return true;
        }
    }
    return false;
}

// Function to read and process input from standard input
void read_and_process() {
    int max_num = 0;
    int num = 0;
    int *arr = NULL;
    char buffer[10000];
    int count = 0, index = 0;
    bool valid = true;

    validate_args(argc, argv);
    max_num = atoi(argv[1]);

    arr = (int *)malloc(max_num * sizeof(int));
    if (!arr) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    while ((fgets(buffer, sizeof(buffer), stdin)) && count < max_num) {
        sscanf(buffer, "%d", &num);
        if (num < -1000 || num > 1000) {
            printf("Invalid input: %s\n", buffer);
            valid = false;
            break;
        }
        arr[count++] = num;
    }

    if (!valid) {
        free(arr);
        exit(EXIT_FAILURE);
    }

    qsort(arr, count, sizeof(int), (void *)compare_ints);

    print_largest(arr, count);
    printf("Duplicates found: %d\n", has_duplicates(arr, count) ? count : 0);
    free(arr);
}

// Comparison function for qsort()
int compare_ints(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int main(int argc, char **argv) {
    read_and_process();
    return EXIT_SUCCESS;
}
