```cpp
#include <iostream>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <chrono>
#include <random>

const int MAX_INPUTS = 500;
const double MIN_RANGE = -10000.0;
const double MAX_RANGE = 10000.0;
const int PRECISION = 6;

class NumberUtilities {
public:
    float* readNumbers() {
        float *numbers = new float[MAX_INPUTS];
        for (int i = 0; i < MAX_INPUTS; ++i) {
            if (!std::cin >> numbers[i]) {
                std::cerr << "Error reading input. Please provide valid floating-point values." << std::endl;
                return nullptr;
            }
            if (numbers[i] < MIN_RANGE || numbers[i] > MAX_RANGE) {
                std::cerr << "Value out of range. Please provide a value between " << MIN_RANGE << " and " << MAX_RANGE << "." << std::endl;
                return nullptr;
            }
        }
        return numbers;
    }

    void printAverage(const float *numbers, int size) {
        double sum = 0.0;
        for (int i = 0; i < size; ++i)
            sum += numbers[i];
        double avg = sum / size;
        std::cout << "Average value: " << std::fixed << std::setprecision(PRECISION) << avg << std::endl;
    }

    float variance(const float *numbers, int size) {
        double mean = average(numbers, size);
        double sumOfSquares = 0.0;
        for (int i = 0; i < size; ++i)
            sumOfSquares += pow((numbers[i] - mean), 2);
        return sumOfSquares / (size - 1);
    }

    float standardDeviation(const float *numbers, int size) {
        return sqrt(variance(numbers, size));
    }

    std::vector<float> generateRandomNumbers(int count, double min, double max, int precision) {
        std::vector<float> randomNumbers;
        std::random_device rd;  //Will be used to obtain a seed for the random number engine
        std::mt19937 gen(rd()); //Standard mersenne_twister_engine seeded with rd()
        std::uniform_real_distribution<> dis(min, max); //Uniform distribution on [min,max) range

        for (int i = 0; i < count; ++i)
            randomNumbers.push_back(dis(gen));

        for (auto& number : randomNumbers)
            number = std::round(number * pow(10, precision)) / pow(10, precision);

        return randomNumbers;
    }

    ~NumberUtilities() {}
private:
    double average(const float *numbers, int size) {
        double sum = 0.0;
        for (int i = 0; i < size; ++i)
            sum += numbers[i];
        return sum / size;
    }
};
```

