['```c
#include <stdio.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <stdlib.h>
#include <sys/types.h>
#include <openssl/sha.h>

typedef struct {
    char src_path[256];
    char dest_path[256];
    char filter[256];
    int concurrency;
} Arguments;

struct file_metadata {
    time_t last_mod_time;
    off_t size;
    uint32_t checksum;
    char id[32];
};

typedef struct file_metadata FileMetadata;

int compare_file_ids(const void *a, const void *b) {
    return strcmp(((FileMetadata *) a)->id, ((FileMetadata *) b)->id);
}

pthread_mutex_t metadata_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t metadata_cond = PTHREAD_COND_INITIALIZER;
FileMetadata *metadata_list = NULL;
size_t num_files = 0;

void push_metadata(FileMetadata file) {
    pthread_mutex_lock(&metadata_mutex);
    metadata_list = realloc(metadata_list, sizeof(FileMetadata) * (num_files + 1));
    memcpy(metadata_list + num_files, &file, sizeof(FileMetadata));
    num_files++;
    pthread_mutex_unlock(&metadata_mutex);
    pthread_cond_signal(&metadata_cond);
}

void pop_metadata(FileMetadata *file) {
    pthread_mutex_lock(&metadata_mutex);
    memcpy(file, metadata_list + num_files - 1, sizeof(FileMetadata));
    num_files--;
    if (num_files == 0)
        metadata_list = NULL;
    pthread_mutex_unlock(&metadata_mutex);
}

void *compress_and_process_file(void *arg) {
    Arguments *args = arg;
    struct dirent *entry;
    DIR *dir = opendir(args->src_path);
    if (!dir) return NULL;

    FileMetadata file_metadata;
    while ((entry = readdir(dir)) != NULL) {
        char path[512];
        snprintf(path, sizeof(path), "%s/%s", args->src_path, entry->d_name);

        struct stat st;
        if (lstat(path, &st) == -1 || S_ISDIR(st.st_mode)) continue;

        if (strcasestr(entry->d_name, args->filter) != NULL) {
            file_metadata.last_mod_time = st.st_mtime;
            file_metadata.size = st.st_size;
            SHA256_CTX ctx;
            SHA256_Init(&ctx);
            SHA256_Update(&ctx, &st.st_ino, sizeof(st.st_ino));
            FILE *fp = fopen(path, "r");
            if (fp) {
                char buffer[1024];
                while (fgets(buffer, sizeof(buffer), fp)) SHA256_Update(&ctx, buffer, strlen(buffer));
                fclose(fp);
                SHA256_Final((unsigned char *)&file_metadata.checksum, &ctx);
            }

            // Generate unique identifier based on the file's name and inode number checksum
            snprintf(file_metadata.id, sizeof(file_metadata.id), "%.*s%08x%064x",
                     (int)strlen(entry->d_name) + 1, entry->d_name, file_metadata.checksum >> 32, file_metadata.checksum);

            push_metadata(file_metadata);
        }
    }
    closedir(dir);
    return NULL;
}

int process_files(Arguments *args) {
    pthread_t threads[args->concurrency];
    for (int i = 0; i < args->concurrency; ++i)
        if (pthread_create(&threads[i], NULL, compress_and_process_file, args)) return 1;

    FileMetadata file_metadata;
    while (num_files > 0) {
        pthread_mutex_lock(&metadata_mutex);
        while (num_files == 0 && metadata_list != NULL)
            pthread_cond_wait(&metadata_cond, &metadata_mutex);
        if (num_files == 0 && metadata_list == NULL) break;
        pop_metadata(&file_metadata);
        pthread_mutex_unlock(&metadata_mutex);

        char dest_path[512];
        snprintf(dest_path, sizeof(dest_path), "%s/%s", args->dest_path, file_metadata.id);
        mkdir(dirname(dest_path), 0755);
        char src_path[512], compressed_path[512];
        snprintf(src_path, sizeof(src_path), "%s/%s", args->src_path, file_metadata.id);
        snprintf(compressed_path, sizeof(compressed_path), "%s/%s.gz", dest_path, file_metadata.id);

        int src_fd = open(src_path, O_RDONLY);
        if (src_fd == -1) continue;
        int compressed_fd = open(compressed_path, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IXUSR);
        if (compressed_fd == -1) {
            close(src_fd);
            continue;
        }

        off_t offset = 0;
        ssize_t num_read;
        char buffer[1024];
        while ((num_read = read(src_fd, buffer, sizeof(buffer))) > 0) {
            if (write(compressed_fd, buffer, num_read) != num_read) break;
            offset += num_read;
        }
        close(src_fd);
        close(compressed_fd);

        struct stat st;
        lstat(compressed_path, &st);
        chmod(compressed_path, S_IRUSR | S_IWUSR | S_IXUSR);
        FILE *fp = fopen(compressed_path, "r");
        if (!fp) continue;

        // Calculate new checksum for the compressed file
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), fp)) SHA256_Update(&ctx, buffer, strlen(buffer));
        fclose(fp);
        SHA256_Final((unsigned char *)&file_metadata.checksum, &ctx);

        // Save the new file metadata with a timestamp and unique identifier
        time_t current_time = time(NULL);
        file_metadata.last_mod_time = current_time;
        strcpy(file_metadata.id + strlen(file_metadata.id), &current_time);

        // Write the updated metadata back to the metadata list, sorted by file ID
        qsort(metadata_list, num_files, sizeof(FileMetadata), compare_file_ids);
        for (size_t i = 0; i < num_files; ++i) {
            if (!strcmp(metadata_list[i].id, file_metadata.id)) {
                metadata_list[i] = file_metadata;
                break;
            }
        }
    }

    for (int i = 0; i < args->concurrency; ++i)
        pthread_join(threads[i], NULL);

    free(args);
    return num_files == 0 ? 0 : 1;
}
```']

