void processNfareAndAggregateLogs(int N, char *filename) {
    // Handle edge cases (zero or negative input sizes)
    if (N <= 0) return;

    // Memory pool for dynamically allocated memory blocks
    void **memoryPool = mmap(NULL, sizeof(void *) * N, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (memoryPool == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Semaphore for managing concurrent access to the memory pool
    sem_t *sem = sem_init(0, 1, N);
    if (sem == SEM_FAILED) {
        perror("sem_init");
        munmap(memoryPool, sizeof(void *) * N);
        exit(EXIT_FAILURE);
    }

    // File descriptor for the log file
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        sem_destroy(sem);
        munmap(memoryPool, sizeof(void *) * N);
        exit(EXIT_FAILURE);
    }

    // Logging function for debugging without generating excessive log messages
    void (*logFunction)(const char *, ...) = log_function;

    // Thread-safe aggregation data structure
    pthread_mutex_t aggDataMutex = PTHREAD_MUTEX_INITIALIZER;
    int64_t eventCount = 0;
    time_t rollingWindowStart = time(NULL) - 5 * 60; // Rolling window of the last 5 minutes

    // Process log file in threads, releasing memory and logging errors robustly
    for (int i = 0; i < N; ++i) {
        pthread_t thread;
        LogEntry_t *entry = malloc(sizeof(LogEntry_t));
        if (!entry) {
            perror("malloc");
            close(fd);
            sem_destroy(sem);
            munmap(memoryPool, sizeof(void *) * N);
            exit(EXIT_FAILURE);
        }
        read(fd, entry->data, sizeof(entry->data));

        struct timeval tv;
        gettimeofday(&tv, NULL);
        double timestamp = (double)tv.tv_sec + ((double)tv.tv_usec / 1000000);

        // Validate timestamps to ensure they fall within the past 24 hours
        if (timestamp > time(NULL) - 86400) {
            pthread_create(&thread, NULL, processLogEntryThread, (void *)entry);
            pthread_detach(thread);
        } else {
            logFunction("Invalid timestamp: %lf", timestamp);
            free(entry);
        }
    }

    close(fd);
    sem_destroy(sem);
    munmap(memoryPool, sizeof(void *) * N);

    // Process aggregated data and compute average frequency per minute
    pthread_mutex_lock(&aggDataMutex);
    double averageFrequency = eventCount > 0 ? (double)eventCount / ((double)(time(NULL) - rollingWindowStart + 60)) : 0;
    char summary[256];
    snprintf(summary, sizeof(summary), "Total events: %" PRId64 ", Average frequency: %.2f", eventCount, averageFrequency);
    pthread_mutex_unlock(&aggDataMutex);

    // Print the summary line formatted as a semicolon-separated string
    printf("%s\n", summary);
}

void* processLogEntryThread(void *entry) {
