#define LOG_FILE "nfpdu_log.txt"
#define MAX_LOG_SIZE 1048576 // 1MB

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint16_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_message(const char *message) {
    static FILE *log_file = NULL;
    static size_t total_written = 0;

    if (!log_file || total_written >= MAX_LOG_SIZE) {
        int flags = O_WRONLY | O_APPEND | O_CREAT | O_NOFOLLOW, mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH;
        log_file = fopen(LOG_FILE, flags, mode);
        total_written = 0;
    }

    if (log_file) {
        fprintf(log_file, "%s\n", message);
        total_written += strlen(message) + 1;
    }
}

NFAPI_CRC_INDICATION_PDU_T *init_pdus(size_t N) {
    if (N == 0) return NULL;

    size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (ptr == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = ptr;

    for (size_t i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = i + 1;
        pdus[i].RNTI = i + 2; // assuming unique RNTIs starting from 2 for better mapping to UE IDs
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 65536;
        pdus[i].CRCFLAG = (rand() % 2) == 0 ? 1 : 0;
    }

    log_message("Initialized PDUs array with size:");
    log_message(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    return pdus;
}

int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t N = 1024; // Input size can be adjusted here

    NFAPI_CRC_INDICATION_PDU_T *pdus = init_pdus(N);

    if (pdus) {
        // Use pdus array here...

        munmap(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    }

    return 0;
}
```

