class SecurityUtils {
    private $charSet = ['0-9', 'a-z', 'A-Z', '-', '_'];
    private $hashAlgorithm = 'sha256';
    private $saltLength = 16;
    private $masterKey;
    private $analytics;
    private $numThreads = 4;
    private $logEnabled = false;

    public function __construct($charSet = null, $hashAlgorithm = null, $saltLength = null, $masterKey = null, $analytics = null, $logEnabled = false) {
        if (!empty($charSet)) $this->charSet = $charSet;
        if (!empty($hashAlgorithm)) $this->hashAlgorithm = $hashAlgorithm;
        if (!empty($saltLength)) $this->saltLength = $saltLength;
        if (!empty($masterKey)) $this->masterKey = $masterKey;
        if (!empty($analytics)) $this->analytics = $analytics;
        $this->logEnabled = $logEnabled;
    }

    public function generateRandomString($length) {
        $str = '';
        for ($i = 0; $i < $length; $i++) {
            $str .= $this->charSet[mt_rand(0, count($this->charSet) - 1)];
        }
        if ($this->analytics) {
            $this->analytics->track('random_string_generation', ['length' => $length]);
        }
        return $str;
    }

    public function hashPassword($password) {
        if (!empty($this->masterKey)) {
            $encryptedPassword = openssl_encrypt($password, 'AES-256-CBC', $this->masterKey);
            $hashedEncryptedPassword = hash($this->hashAlgorithm, $encryptedPassword . $this->salt());
        } else {
            $hashedPassword = hash($this->hashAlgorithm, $password . $this->salt());
        }
        if ($this->analytics) {
            $this->analytics->track('password_hashing', ['algorithm' => $this->hashAlgorithm]);
        }
        return $hashedPassword;
    }

    public function salt() {
        return substr(base64_encode(random_bytes($this->saltLength)), 0, $this->saltLength);
    }

    public function checksumValidation($string, $checksum) {
        if (!empty($this->masterKey)) {
            $encryptedString = openssl_decrypt(base64_decode($string), 'AES-256-CBC', $this->masterKey);
            return hash($this->hashAlgorithm, $encryptedString) === $checksum;
        } else {
            return hash($this->hashAlgorithm, base64_decode($string)) === $checksum;
        }
    }

    // Other methods for digital signature generation and verification, dynamic thread adjustment, periodic key regeneration, etc. can be added here.
}
