#include <stdio.h>
#include <stdlib.h>
#include <json-c/json.h>
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <string.h>

typedef struct {
    int field1;
    // ... other fields up to field5
    int field6;
} Record;

Record *parse_record(const unsigned char *data, size_t length) {
    Record *record = malloc(sizeof(Record));
    memcpy(record, data, sizeof(Record));
    return record;
}

void append_sum(Record *record) {
    int sum = 0;
    for (int i = 5; i < 6; ++i) {
        if (record->field[i] != 0)
            sum += record->field[i];
    }
    record->field[6] = sum;
}

void validate_and_log(Record *record) {
    for (int i = 1; i <= 6; ++i) {
        if (!(record->field[i] >= -1000 && record->field[i] <= 1000)) {
            printf("Invalid field value: %d\n", record->field[i]);
        }
    }
}

EVP_CIPHER *get_cipher(const char *mode) {
    const EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;

    if (strcmp(mode, "NULL") == 0)
        return NULL; // Null encryption mode

    if (!(cipher = EVP_get_cipherbyname(mode))) {
        printf("Invalid cipher mode: %s\n", mode);
        return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_init(ctx, cipher, NULL);

    return cipher;
}

void encode_record_to_json(Record *record, json_object **json) {
    json_object *obj = json_object_new_object();
    for (int i = 1; i <= 6; ++i) {
        json_object *field = json_object_new_int(record->field[i]);
        json_object_object_add(obj, "field", field);
    }
    *json = obj;
}

void read_and_process_file(const char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) return;

    fseek(fp, 0, SEEK_END);
    size_t length = ftell(fp);
    rewind(fp);

    unsigned char *buffer = malloc(length);
    if (fread(buffer, 1, length, fp) != length) {
        free(buffer);
        fclose(fp);
        return;
    }

    Record *record_ptr = NULL;
    size_t records_count = 0;

    for (size_t i = 0; i < length; ) {
        Record *record = parse_record(&buffer[i]);
        append_sum(record);
        validate_and_log(record);

        json_object *json = NULL;
        encode_record_to_json(record, &json);

        const char *json_str = json_object_to_json_string(json);
        printf("%s\n", json_str);

        records_count++;
        i += sizeof(Record) + record->field[6];

        free(record);
        json_object_put(json);
    }

    free(buffer);
    fclose(fp);
}

int main() {
    const char *filename = "input.bin";
    const EVP_CIPHER *cipher = get_cipher("AES-128-CTR"); // Change this to your desired cipher

