int download_urls(const char *config_file, const char *cache_dir, int concurrency) {
    FILE *fp = fopen(config_file, "r");
    if (!fp) {
        return 1;
    }

    char line[4096];
    int errors = 0;
    int total = 0;
    pthread_t threads[concurrency];

    while (fgets(line, sizeof(line), fp)) {
        size_t len = strlen(line);
        if (len > 256) {
            continue;
        }

        memmove(line + len - 1, line, len);
        line[len - 1] = '\0';
        UrlData urlData = { line, "" };
        memcpy(urlData.checksum, SHA256((const unsigned char *)line, len, NULL), SHA256_DIGEST_LENGTH + 1);

        pthread_t thread = threads[total % concurrency];
        pthread_create(&thread, NULL, download_thread, &urlData);
        total++;
    }
    fclose(fp);

    for (int i = 0; i < concurrency; ++i) {
        pthread_join(threads[i], NULL);
    }

    return errors > 0 ? 1 : 0;
}

void *download_thread(void *data) {
    UrlData *urlData = static_cast<UrlData*>(data);
    char output_file[256];
    snprintf(output_file, sizeof(output_file), "%s/%s", cache_dir, urlData->url);

    int logged;
    CURLcode res = curl_download(urlData->url, output_file, urlData->checksum, &logged);

    if (res != CURLE_OK || logged) {
        pthread_mutex_lock(&lock);
        // Handle the error and log it here
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}
