}

void tune_categories() {
    // Implement tuning of category importances during peak hours
}

void log_entry(logger_t *logger, const char *format, ...) {
    va_list args;
    struct timespec ts;
    double entry_time = 0.0;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    entry_time = ts.tv_sec + ts.tv_nsec / 1_000_000_000.0;

    pthread_mutex_lock(&logger->mutex);
    if ((system_load > 75 && current_verbosity >= MAX_VERBOSITY) || logger->verbosity < current_verbosity) {
        pthread_mutex_unlock(&logger->mutex);
        return;
    }

    va_start(args, format);
    vfprintf(logger->log_file, format, args);
    va_end(args);

    if (entry_time > categories[0].last_entry_time) {
        categories[0].last_entry_time = entry_time;
    }

    if ((++logger->tail) >= logger->buffer_size) {
        logger->head = logger->tail - logger->buffer_size;
        sem_post(&buffer_semaphore);
    }
    pthread_mutex_unlock(&logger->mutex);
}

void loggers_init(char *log_path, char **env) {
    int i = 0;
    char *log_file_name = "log.txt";
    char *env_verbosity = getenv("LOG_VERBOSITY");
    char *env_load = getenv("SYSTEM_LOAD");
    int log_file_fd;

    if (env_verbosity) {
        current_verbosity = atoi(env_verbosity);
        current_verbosity = current_verbosity > MAX_VERBOSITY ? MAX_VERBOSITY : current_verbosity;
    }

    if (env_load) {
        system_load = atoi(env_load);
        adjust_verbosity();
    }

    log_file_fd = open((log_path ? log_path : ".") "/" log_file_name, O_WRONLY | O_APPEND | O_CREAT | O_SYNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (log_file_fd == -1) {
        perror("Failed to open log file");
        return;
    }

    loggers = realloc(loggers, sizeof(logger_t) * ++num_loggers);
    loggers[num_loggers - 1].buffer_size = MIN_BUFFER_SIZE;
    loggers[num_loggers - 1].verbosity = current_verbosity;
    loggers[num_loggers - 1].log_file = fdopen(log_file_fd, "a");

    sem_init(&buffer_semaphore, 0, logger->buffer_size);

    for (i = 0; i < num_loggers; ++i) {
        pthread_mutex_init(&loggers[i].mutex, NULL);
    }
}
