    if (!pool->data) {
        fprintf(stderr, "Failed to allocate initial memory for pool\n");
        exit(1);
    }
    pool->capacity = initial_size;
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

void* memory_pool_alloc(struct memory_pool* pool) {
    void* element;
    pthread_mutex_lock(&pool->mutex);
    if (pool->count < pool->capacity) {
        element = &pool->data[pool->count++];
    } else {
        // Handle expansion here, for example by doubling the capacity and reallocating.
        fprintf(stderr, "Memory pool is full. Increase capacity to accommodate more elements.\n");
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }
    pthread_mutex_unlock(&pool->mutex);
    return element;
}

void memory_pool_free(struct memory_pool* pool, void* ptr) {
    if (ptr) {
        pthread_mutex_lock(&pool->mutex);
        --pool->count;
        pthread_mutex_unlock(&pool->mutex);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(unsigned int N, unsigned int max_concurrent) {
    static struct memory_pool pool = {0};
