        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }
    for (unsigned int i = 0; i < N; ++i) {
        if ((pool.count + 1) >= max_concurrent) {
            fprintf(stderr, "Reached maximum allowed concurrent allocations.\n");
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        pdu_ptr = memory_pool_alloc(&pool);
        if (!pdu_ptr) {
            fprintf(stderr, "Failed to allocate memory for PDU\n");
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
    }
    pthread_mutex_unlock(&pool->mutex);

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for PDU array\n");
        return NULL;
