#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <time.h>

#define MAX_ENTRIES 5000

typedef struct Task {
    int id;
    int priority;
    time_t scheduled_time;
    time_t duration;
