} Task;

sem_t task_queue_mutex;
sem_t task_queue_not_full;
sem_t task_queue_not_empty;
pthread_mutex_t memory_cleanup_mutex;

struct MemoryBlock {
    size_t capacity;
    Task* tasks;
};

void cleanup_memory(struct MemoryBlock* block) {
    if (block == NULL || block->tasks == NULL) return;

    pthread_mutex_lock(&memory_cleanup_mutex);
    // Free allocated memory and reset pointers to avoid dangling references
    free(block->tasks);
    block->tasks = NULL;
    block->capacity = 0;
    pthread_mutex_unlock(&memory_cleanup_mutex);
}

struct MemoryBlock* allocate_memory(size_t size) {
    struct MemoryBlock* block = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (block == MAP_FAILED) {
        fprintf(stderr, "Memory allocation failure. Retrying...\n");
        // Retry on memory allocation failure after a short delay to avoid thrashing
        usleep(500000); // 500ms
        return allocate_memory(size);
    }

    return block;
}

void init_mutexes() {
    sem_init(&task_queue_mutex, 1, 1);
    sem_init(&task_queue_not_full, 0, MAX_ENTRIES);
    sem_init(&task_queue_not_empty, 0, 0);
    pthread_mutex_init(&memory_cleanup_mutex, NULL);
}

void add_task(Task task) {
    if (sem_wait(&task_queue_not_full) == -1) {
        perror("Semaphore wait failed");
        return;
    }

    struct MemoryBlock* block = allocate_memory(MAX_ENTRIES * sizeof(Task));
    if (block == NULL) return;

    block->capacity = MAX_ENTRIES;
    block->tasks = (Task*)((char*)block + (MAX_ENTRIES - 1) * sizeof(Task));

    // Move the new task to the front of the queue
    Task* current = block->tasks;
    while (current != &block->tasks[0]) {
        current--;
        *current = task;
    }

    *current = task;

    if (sem_post(&task_queue_not_empty) == -1) {
        perror("Semaphore post failed");
    }
}

Task get_next_task() {
    Task task;

    if (sem_wait(&task_queue_mutex) == -1) {
        perror("Semaphore wait failed");
        return (Task){0};
    }

    Task* current = NULL;
    struct MemoryBlock* block = NULL;

    sem_wait(&task_queue_not_empty);

    current = task_queue.tasks;
    if (current != NULL) {
        block = &task_queue;
    }

    if (current != NULL) {
        task = *current;
        if (sem_post(&task_queue_mutex) == -1) {
            perror("Semaphore post failed");
        }

        // Move the removed task to the end of the queue
        Task* end = &block->tasks[block->capacity - 1];
        while (current != end) {
            *current = *(end + 1);
            current++;
        }
        *current = (Task){0};
    }

    return task;
}
```

