// Memory pool structure definition
struct memory_pool {
    size_t size;
    void **data;
};

void init_memory_pool(struct memory_pool *pool, size_t initial_size) {
    pool->size = initial_size;
    pool->data = malloc(initial_size * sizeof(void*));
}

void *get_from_pool(struct memory_pool *pool) {
    if (pool->size == 0) return NULL;
    size_t index = (pool->size - 1) % pool->size;
    void *data = pool->data[index];
    pool->data[index] = NULL; // mark as free
    return data;
}

void put_back_to_pool(struct memory_pool *pool, void *data) {
    if (data != NULL) {
        size_t index = (pool->size + 1) % pool->size;
        pool->data[index] = data;
    }
}

