    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct list {
    unsigned int capacity;
    unsigned int size;
    Node *head;
    pthread_mutex_t mutex;
};

void init_list(struct list* list, unsigned int capacity) {
    list->capacity = capacity;
    list->size = 0;
    list->head = NULL;
    pthread_mutex_init(&(list->mutex), NULL);
}

bool push(struct list *list, const NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return false;
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&(list->mutex));
    if (list->size >= list->capacity) {
        // Resize the array when it's full
        unsigned int new_capacity = (list->capacity * 3) / 2 + 1;
        Node **nodes = realloc(list->head, sizeof(Node) * new_capacity);
        if (!nodes) {
            pthread_mutex_unlock(&(list->mutex));
            free(new_node);
            return false;
        }
        list->capacity = new_capacity;
        list->head = nodes;
    }

    Node* tail = list->head + list->size;
    *tail = *new_node;
    list->size++;
    pthread_mutex_unlock(&(list->mutex));
    return true;
}

NFAPI_CRC_INDICATION_PDU_T pop(struct list* list) {
    if (list->size == 0) return (NFAPI_CRC_INDICATION_PDU_T){};

    pthread_mutex_lock(&(list->mutex));
    Node* head = list->head;
    NFAPI_CRC_INDICATION_PDU_T data = head->data;
    list->size--;
    list->head = head->next;
    free(head);
    pthread_mutex_unlock(&(list->mutex));

    return data;
}

