void push_lte_pdu(LTE_LIST *list, LTE_PDU *pdu) {
    if (list->capacity == list->size) {
        if (list->capacity == 0) list->capacity = 4;
        else list->capacity *= 2;

        LTE_PDU **new_array = realloc(list->head, sizeof(LTE_PDU *) * list->capacity);
        if (!new_array) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        list->head = new_array;
    }

    pthread_mutex_lock(&list->mutex);

    if (list->size == 0) {
        list->head = pdu;
        list->tail = pdu;
    } else {
        list->tail->next = pdu;
        list->tail = pdu;
    }

    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

LTE_PDU* pop_lte_pdu(LTE_LIST *list) {
    if (list->size == 0) return NULL;

    LTE_PDU *tmp = list->head;
    pthread_mutex_lock(&list->mutex);

    list->head = list->head->next;
    if (list->head == NULL) list->tail = NULL;

    list->size--;
    pthread_mutex_unlock(&list->mutex);

