    table->size = 0;
    table->buckets = (cache_node**) calloc(capacity, sizeof(cache_node*));
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

uint32_t hash(const void* key) {
    const unsigned long c = 5381;
    unsigned long h = 0;
    const char *str = (char*) key;
    int len = strlen(str);

    for (int i = 0; i < len; ++i)
        h = (h * c + str[i]) & ((1UL << 32) - 1);

    return h % table->capacity;
