C Function (Using pthread library and libRedis):

```c
#include <pthread.h>
#include <redis/hiredis.h>
#include <tadam/tadam.h> // A C wrapper for Redis
#include <stdlib.h>
#include <stdbool.h>
#include <stdio.h>

typedef struct {
    int valid_srscfg;
    // Add other PDU structure fields here
} lte_pdu;

typedef struct pdu_cache_node {
    lte_pdu pdu;
    struct pdu_cache_node *next;
} pdu_cache_node;

struct pdu_list {
    pthread_mutex_t lock;
    int size;
    pdu_cache_node **data;
    redisContext *redis_context; // For remote data storage and caching
};

void pdu_list_init(struct pdu_list *list) {
    list->size = 0;
    list->data = NULL;
    list->redis_context = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void pdu_list_destroy(struct pdu_list *list) {
    int i;
    for (i = 0; i < list->size; ++i) {
        free(list->data[i]);
    }
    free(list->data);
    pthread_mutex_destroy(&list->lock);
}

void *pdu_list_reserve(struct pdu_list *list, int n) {
    void *new_data;
    if (n <= list->size)
        return list->data;

    new_data = realloc(list->data, sizeof(lte_pdu*) * n);
    if (!new_data)
        return NULL;

    list->data = new_data;
    while (list->size < n) {
        list->data[list->size] = NULL;
        ++list->size;
    }
    return list->data;
}

pdu_cache_node *pdu_list_get(struct pdu_list *list, const char* key) {
    pdu_cache_node *node, **head = &list->caches[hash(key) % CACHES_COUNT];
    redisReply *reply;

    pthread_mutex_lock(&list->lock);

    node = *head;
    while (node != NULL && strcmp(node->pdu.valid_srscfg, key)) {
        node = node->next;
    }

    if (node) {
        pthread_mutex_unlock(&list->lock);
        return node;
    }

    reply = list->redis_context->cmdArgument(CMD_GET, key);
    if (!reply || !reply->len) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    node = malloc(sizeof(pdu_cache_node));
    memcpy(&node->pdu, reply->str, sizeof(lte_pdu));

    *head = node;
    node->next = list->caches[hash(key) % CACHES_COUNT];
    list->caches[hash(key) % CACHES_COUNT] = node;

    pthread_mutex_unlock(&list->lock);
    return node;
}

