['1. Memory Pool Implementation (`memory_pool.h`, `memory_pool.c`)

```c
#ifndef MEMORY_POOL_H
#define MEMORY_POOL_H

#include <stdlib.h>
#include <pthread.h>

typedef struct memory_block {
    void* data;
    size_t capacity;
    struct memory_block* next;
} MemoryBlock;

typedef struct memory_pool {
    MemoryBlock* head;
    MemoryBlock* tail;
    pthread_mutex_t lock;
    size_t limit;
    size_t current;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size, size_t limit);
void* acquire_from_memory_pool(MemoryPool* pool);
void release_to_memory_pool(MemoryPool* pool, void* data);

#endif //MEMORY_POOL_H

// memory_pool.c
#include "memory_pool.h"

MemoryPool* create_memory_pool(size_t initial_size, size_t limit) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->head = NULL;
    pool->tail = NULL;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    pool->limit = limit;
    pool->current = 0;

    MemoryBlock* block = malloc(initial_size * sizeof(void*));
    if (!block) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        block[i] = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!block[i]) {
            free(pool);
            free(block);
            return NULL;
        }
    }

    pool->head = block;
    pool->tail = &pool->head[initial_size - 1];
    pool->tail->next = NULL;

    return pool;
}

void* acquire_from_memory_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->current < pool->limit && pool->head != NULL) {
        void* data = pool->head->data;
        pool->current++;
        pool->head = pool->head->next;
        pthread_mutex_unlock(&pool->lock);
        return data;
    } else {
        pthread_mutex_unlock(&pool->lock);
    }

    void* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        // Handle out-of-memory error here.
    }
    return data;
}

void release_to_memory_pool(MemoryPool* pool, void* data) {
    pthread_mutex_lock(&pool->lock);
    free(data);
    pool->current--;
    pool->tail->next = malloc(sizeof(MemoryBlock));
    if (!pool->tail->next) {
        // Handle out-of-memory error here.
    }
    MemoryBlock* new_block = pool->tail->next;
    new_block->data = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_block->data) {
        // Handle out-of-memory error here.
    }
    new_block->capacity = 1;
    new_block->next = NULL;
    pool->tail = new_block;
    pthread_mutex_unlock(&pool->lock);
}
```

