    if (N <= 0) return NULL;

    void** indications = malloc(N * sizeof(void*));
    if (!indications) {
        // Handle out-of-memory error here.
    }

    for (size_t i = 0; i < N; ++i) {
        indications[i] = acquire_from_memory_pool(pool);
        if (!indications[i]) {
            free(indications);
            // Handle out-of-memory error here.
        }
