// access_token_validation.c
#include "access_token_validation.h"
#include <json-c/json.h>
#include <stdbool.h>
#include <string.h>

bool is_valid_access_token(const char* token) {
    json_object *json = json_tokener_parse(token);
    if (json == NULL) return false;

    bool valid = true;
    json_object *access_token, *expires_in, *token_type;
    const char *refresh_token;

    access_token = json_object_get(json, "access_token");
    expires_in = json_object_get(json, "expires_in");
    token_type = json_object_get(json, "token_type");

    if (access_token == NULL || json_is_type(access_token, JSON_NONE) ||
        expires_in == NULL || json_is_type(expires_in, JSON_NONE) ||
        token_type == NULL || json_is_type(token_type, JSON_NONE)) {
        valid = false;
    } else if (!json_is_string(access_token) ||
                 !json_is_int64(expires_in) ||
                 !strcmp(json_object_get_string(token_type), "Bearer")) {
        valid = false;
    }

    if (valid && json_object_get_child(json, "refresh_token")) {
        refresh_token = json_object_get_string(json_object_get_child(json, "refresh_token"));
        if (!refresh_token || strlen(refresh_token) > 256) valid = false;
    }

    json_object_put(json);
    return valid;
}
