    struct config global_config = { NULL };
    int opt;
    while ((opt = getopt(argc, argv, "c:o:f:h")) != -1) {
        switch (opt) {
            case 'c':
                // Parse configuration string and set up global_config here
                break;
            case 'o':
                global_config.output_file = optarg;
                break;
            case 'f':
                if (strlen(optarg) != 1 || *(optarg + 1)) {
                    fprintf(stderr, "Invalid format option\n");
