#include <sys/mman.h>

// Data structures and configuration constants
struct config {
    char *input_file;
    char *output_file;
    char format; // 't' for text, 'b' for binary
    struct aiocbp *aio_buf;
    size_t aio_len;
    regex_t *pattern;
};

struct worker {
    pthread_t thread_id;
    int workload_index;
    struct config *workload;
};

// Functions to process the input and apply transformations
void* worker_process(void *arg);
void init_config(struct config *cfg, int argc, char **argv);
int parse_config(const char *line, struct config *cfg);

int main(int argc, char **argv) {
    // Parse input arguments and initialize configuration structures
    int opt;
    while ((opt = getopt(argc, argv, "i:o:f:p:")) != -1) {
        switch (opt) {
            case 'i':
                config[optind].input_file = optarg;
                break;
            case 'o':
                config[optind].output_file = optarg;
                break;
            case 'f':
                config[optind].format = optarg[0];
                break;
            case 'p':
                // Parse configuration file and add options to config array
                parse_config(optarg, &config[optind]);
                break;
            default:
                fprintf(stderr, "Usage: %s -i input_file -o output_file [-f format] [-p path/to/config_file]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize workers and start processing the workload concurrently
    pthread_t *workers = malloc(sizeof(struct worker) * num_workers);
    struct config *workloads = malloc(sizeof(struct config) * num_workers);
    int worker_index = 0;

    for (int i = 0; i < argc; ++i) {
        if (config[i].input_file && !config[i].pattern) {
            init_config(&workloads[worker_index], 1, &argv[i]);
            workloads[worker_index].aio_buf = mmap(NULL, config[i].aio_len, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            workers[worker_index].workload = &workloads[worker_index];
            workers[worker_index].workload_index = worker_index++;
            pthread_create(&workers[worker_index].thread_id, NULL, &worker_process, (void*)&workers[worker_index]);
        }
    }

    // Wait for all workers to finish their tasks and release resources
    for (int i = 0; i < worker_index; ++i) {
        pthread_join(workers[i].thread_id, NULL);
        munmap(workers[i].workload->aio_buf, workers[i].workload->aio_len);
    }
    free(workers);
    free(workloads);

    return EXIT_SUCCESS;
}
