class DataGenerator {
private:
    std::vector<std::unique_ptr<NFAPI_CRC_INDICATION_PDU>> dataPool;
    boost::circular_buffer<NFAPI_CRC_INDICATION_PDU> freeList;
    const int maxPoolSize;
    boost::mutex mutex;
    bool isFull;
public:
    DataGenerator(int maxPoolSize) : maxPoolSize(maxPoolSize), isFull(false) {}

    NFAPI_CRC_INDICATION_PDU* getData() {
        boost::lock_guard<boost::mutex> lock(mutex);
        if (!freeList.empty()) {
            NFAPI_CRC_INDICATION_PDU* data = &freeList.front();
            freeList.pop_front();
            return data;
        }
        if (!isFull) {
            dataPool.emplace_back(std::make_unique<NFAPI_CRC_INDICATION_PDU>());
            NFAPI_CRC_INDICATION_PDU* data = dataPool.back().get();
            isFull = true;
        }
        return dataPool.back().get();
    }

    void releaseData(NFAPI_CRC_INDICATION_PDU* data) {
        boost::lock_guard<boost::mutex> lock(mutex);
        freeList.push_back(*data);
        if (freeList.size() > maxPoolSize / 2 && isFull) {
            dataPool.pop_back();
            isFull = false;
        }
    }
};
