    CELL_CONFIG_T** new_cells = realloc(list->cells, sizeof(CELL_CONFIG_T) * (list->num_cells + 1));
    if (!new_cells) {
        log_error("Memory allocation failure");
        return NULL;
    }
    list->cells = new_cells;
    list->cells[list->num_cells] = *config;
    ++(list->num_cells);
    return &list->cells[list->num_cells - 1];
}

void remove_cell_config(CELL_CONFIG_LIST_T* list, size_t index) {
    if (index >= list->num_cells) {
        log_error("Invalid cell index");
        return;
    }

    // Shift all elements after the one to be removed
    for (size_t i = index + 1; i < list->num_cells; ++i) {
        list->cells[i - 1] = list->cells[i];
    }

    --list->num_cells;
}
```

