size_t writeFunc(void* buf, size_t size, size_t nmemb, void* userp) {
    rapidjson::Document& doc = *static_cast<rapidjson::Document*>(userp);
    doc.Parse(reinterpret_cast<char*>(buf), size * nmemb);

    const char* latitude = doc["coord"]["lat"].GetString();
    const char* longitude = doc["coord"]["lon"].GetString();

    WeatherData& weatherData = dataMap[std::string{latitude, latitude + 10} + ',' + std::string{longitude, longitude + 10}];
    weatherData.temperature += doc["main"]["temp"].GetDouble() / 50;
    weatherData.precipitation += doc["weather"][0]["precipitation"] * nmemb;
    weatherData.windSpeed += std::pow(doc["wind"]["speed"].GetDouble(), nmemb);

    return size * nmemb;
}

void processCoordinates(std::vector<std::string> coordinates, bool parallel) {
    std::vector<std::thread> threads;

    if (parallel) {
        for (size_t i = 0; i < coordinates.size(); ++i) {
            threads.emplace_back([coordinates, &threads, i]() {
                CURL* curl = curl_easy_init();
                curl_easy_setopt(curl, CURLOPT_URL, "https://api.openweathermap.org/data/2.5/weather?lat=" + coordinates[i].substr(0, coordinates[i].find(',')) + "&lon=" + coordinates[i].substr(coordinates[i].find(',') + 1) + "&appid=YOUR_API_KEY");
                curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeFunc);
                curl_easy_perform(curl);
                curl_easy_cleanup(curl);

                if (threads.size() > 1 && threads.size() % 5 == 0) {
                    threads[0].join();
                    threads.erase(threads.begin());
                }
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }
    } else {
        for (const auto& coordinate : coordinates) {
            CURL* curl = curl_easy_init();
            curl_easy_setopt(curl, CURLOPT_URL, "https://api.openweathermap.org/data/2.5/weather?lat=" + coordinate.substr(0, coordinate.find(',')) + "&lon=" + coordinate.substr(coordinate.find(',') + 1) + "&appid=YOUR_API_KEY");
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeFunc);
            curl_easy_perform(curl);
            curl_easy_cleanup(curl);
        }
    }
}

void exportResults(const std::string& outputFormat, const std::vector<std::pair<std::string, WeatherData>>& sortedData) {
    if (outputFormat == "CSV") {
        std::ofstream csvFile("output.csv");
        for (const auto& pair : sortedData) {
            csvFile << pair.first << "," << pair.second.temperature << "," << pair.second.precipitation << "," << pair.second.windSpeed << "\n";
        }
    } else if (outputFormat == "JSON") {
        rapidjson::Document jsonDoc(rapidjson::kObjectType);
        jsonDoc.AddMember("data", rapidjson::Value(rapidjson::kArrayType).Move(), allocator);

        for (const auto& pair : sortedData) {
            rapidjson::Value dataItem;
            dataItem.AddMember("location", pair.first, allocator);
            dataItem.AddMember("temperature", pair.second.temperature, allocator);
            dataItem.AddMember("precipitation", pair.second.precipitation, allocator);
            dataItem.AddMember("windSpeed", pair.second.windSpeed, allocator);
            jsonDoc["data"].PushBack(dataItem, allocator);
        }

        std::ofstream jsonFile("output.json");
        rapidjson::IStreamWriter<rapidjson::StringBuffer> writer(jsonDoc, allocator);
        writer.WriteTo(jsonFile);
    } else {
        // Implement custom format logic here based on the specified outputFormat using -f option
    }
}

void log(const std::string& message) {
    if (!logFilePath.empty()) {
        std::ofstream logFile(logFilePath, std::ios_base::app);
        logFile << message << "\n";
    } else {
        std::cerr << message << "\n";
    }
}

