    boost::program_options::options_description desc("Allowed options");
    desc.add_options()
        ("help,h", "Print help messages")
        ("coordinates,c", boost::program_options::value<std::vector<std::string>>()->multitoken(), "Comma-separated list of coordinates to fetch weather data for (e.g., 40.7128,-74.0060)")
        ("outputFormat,f", boost::program_options::value<std::string>(), "Output format (CSV, JSON, or custom)")
        ("logFile,l", boost::program_options::value<std::string>()->default_value(""), "Log file for errors and warnings")
        ("parallel,p", "Enable parallel processing");

    std::vector<std::string> coordinates;
    std::string outputFormat = "CSV";
    std::string logFilePath = "";
    bool parallel = true;

    boost::program_options::variables_map vm;
    try {
        boost::program_options::store(boost::program_options::parse_command_line(argc, argv, desc), vm);
        boost::program_options::notify(vm);
    } catch (const std::exception& ex) {
        log("Error: " + std::string{ex.what()});
        return 1;
    }

    if (vm.count("help")) {
        std::cout << desc << "\n";
        return 0;
    }

    processCoordinates(coordinates, parallel);

    // Calculate average temperature, precipitation, and wind speed across all locations
    double totalTemperature = 0.0;
    double totalPrecipitation = 0.0;
    double totalWindSpeed = 0.0;
    size_t count = 0;

    std::vector<std::pair<std::string, WeatherData>> sortedData;
    for (const auto& pair : dataMap) {
        totalTemperature += pair.second.temperature / coordinates.size();
        totalPrecipitation += pair.second.precipitation * coordinates.size();
        totalWindSpeed += std::pow(pair.second.windSpeed, 1.0 / coordinates.size());
        count++;

        sortedData.push_back(std::make_pair(pair.first, pair.second));
    }

    exportResults(outputFormat, sortedData);

    log("Average temperature: " + std::to_string(totalTemperature) + "\n"
        "Average precipitation: " + std::to_string(totalPrecipitation / count) + "\n"
        "Average wind speed: " + std::to_string(std::pow(totalWindSpeed, 1.0 / count)));

    return 0;
}
