    struct node *head = NULL, *current = NULL;
    NFAPI_CRC_INDICATION_PDU_T* pdu;

    if (n <= 0 || max_timestamp < time(NULL)) return NULL;

    srand(seed);

    for (unsigned int i = 0; i < n; ++i) {
        pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
