        pdu->rx_ue_information_tag.rnti = rand() % 0xFFFF + 1;
        pdu->length = rand() % MAX_LENGTH + MIN_LENGTH;
        pdu->crc_indication_rel8_tag.crcflag = (rand() % 2) == 1;
        pdu->timestamp = time(NULL) + rand() % (max_timestamp - time(NULL));

        if (!head) {
            head = current = malloc(sizeof(struct node));
            if (!head) {
                log_error("Failed to allocate memory for head node.");
                free(pdu);
                free_list(head);
                return NULL;
            }
            head->data = pdu;
            head->next = NULL;
        } else {
            current->next = malloc(sizeof(struct node));
            if (!current->next) {
                log_error("Failed to allocate memory for next node.");
                free(pdu);
                free_list(head);
                return NULL;
            }
            current = current->next;
            current->data = pdu;
            current->next = NULL;
        }
    }

    if (enable_logging && i % THROTTLE_RATE == 0) {
        log("Created %d PDUs.", n);
    }

    return head;
}

void free_list(struct node *head) {
    struct node *current, *temp;

    current = head;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
