} TickerListConfig;

TickerListConfig* ticker_list_config_init(size_t capacity, bool log_enabled, bool debug_log_enabled, bool compact, bool throttle, double throttle_interval) {
    TickerListConfig *config = malloc(sizeof(TickerListConfig));
    if (!config) {
        if (log_enabled)
            config->log("Error: Failed to allocate memory for configuration");
        return NULL;
    }

    config->event_capacity = capacity;
    config->events = calloc(capacity, sizeof(TickerEvent*));
    if (!config->events) {
        if (log_enabled)
            config->log("Error: Failed to allocate memory for event array");
        free(config);
        return NULL;
    }

    config->log_enabled = log_enabled;
    config->debug_log_enabled = debug_log_enabled;
    config->compact = compact;
    config->throttle = throttle;
    config->throttle_interval = throttle_interval;
    config->last_throttle_time = 0.0;

    return config;
}

TickerEvent* ticker_event_init(int id, time_t timestamp, size_t tag_count) {
    TickerEvent *event = malloc(sizeof(TickerEvent));
    if (!event) {
        if (ticker_list_config->log_enabled)
            ticker_list_config->log("Error: Failed to allocate memory for event");
        return NULL;
    }

    event->id = id;
    event->timestamp = timestamp;
    event->tags = calloc(tag_count, sizeof(struct Tag));
    if (!event->tags) {
        if (ticker_list_config->log_enabled)
            ticker_list_config->log("Error: Failed to allocate memory for event tags");
        free(event);
        return NULL;
    }

    event->tag_count = tag_count;
    return event;
}

void ticker_list_add(TickerListConfig *config, TickerEvent *event) {
    if (config->throttle && config->last_throttle_time + config->throttle_interval > clock())
        return;

    if (!config->events[config->current_index]) {
        config->events[config->current_index] = event;
        config->num_events++;
        config->last_throttle_time = clock();
    } else {
        TickerEvent **new_index_ptr = &config->events[(config->current_index + 1) % config->event_capacity];
        while (*new_index_ptr)
            new_index_ptr = &(*new_index_ptr)->next;

        event->next = *new_index_ptr;
        *new_index_ptr = event;
        config->num_events++;
    }

    if (config->compact && config->num_events > config->event_capacity / 2)
        ticker_list_compact(config);
}

void ticker_list_compact(TickerListConfig *config) {
    // Implement compacting logic here, removing infrequently accessed nodes and reallocating the event array if necessary.
}

void* ticker_list_delete(TickerListConfig *config, TickerEvent **event_ptr) {
    void *tag_value_to_free;

    if (!event_ptr || !*event_ptr)
        return NULL;

    tag_value_to_free = (*event_ptr)->tags;
    free((*event_ptr)->tags);
    free(*event_ptr);
    *event_ptr = NULL;
    config->num_events--;

    return tag_value_to_free;
}

TickerEvent* ticker_list_get(const TickerListConfig *config, size_t index) {
    if (index >= config->event_capacity || !config->events[index])
        return NULL;

    return config->events[index];
}
