#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <queue>
#include <filesystem>
#include <atomic>
#include <future>
#include <mutex>
#include <unordered_map>
#include <deque>
#include <thread>
#include <stdexcept>

namespace fs = std::filesystem;

struct Node {
    std::string id;
    std::vector<int> values;
    std::mutex nodeMutex;
    std::unordered_map<std::string, size_t> children;
    std::deque<Node*> pendingChildren;

    void addChild(const std::string& childId) {
        std::unique_lock<std::mutex> lock(nodeMutex);
        auto it = children.find(childId);
        if (it == children.end()) {
            children[childId] = pendingChildren.size();
            if (!pendingChildren.empty()) {
                (*pendingChildren.back()).children[childId] = children.size() - 1;
                pendingChildren.pop_back();
            }
        }
    }
};

class TreeParser {
public:
    explicit TreeParser(int maxConcurrentParsers);
    Node* parseNode(const fs::path& path, const std::unordered_map<std::string, std::vector<int>>& nodeData);
    void startParsing(const std::vector<fs::path>& paths);
    Node* getRoot();
private:
    int maxConcurrentParsers_;
    std::atomic<Node*> root_;
    std::mutex rootMutex;
    std::queue<std::future<Node*>> parsingTasks;
};

TreeParser::TreeParser(int maxConcurrentParsers) : maxConcurrentParsers_(maxConcurrentParsers), root_(nullptr) {}

void TreeParser::startParsing(const std::vector<fs::path>& paths) {
    for (const auto& path : paths) {
        parsingTasks.emplace_back(std::async(std::launch::async, [=]() -> Node* {
            Node nodeData;
            // Parse XML file and populate nodeData here
            return parseNode(path, nodeData);
        }));
    }

    while (parsingTasks.size() > maxConcurrentParsers_ && !parsingTasks.empty()) {
        parsingTasks.front().wait();
    }
}

Node* TreeParser::parseNode(const fs::path& path, const std::unordered_map<std::string, std::vector<int>>& nodeData) {
    Node* node = new Node();
    // Update node->id and node->values here using nodeData

    if (!node->values.empty()) {
        std::sort(node->values.begin(), node->values.end());
        node->values.erase(std::unique(node->values.begin(), node->values.end()), node->values.end());
    }

    // Add children and pendingChildren here using nodeData

    return node;
}

Node* TreeParser::getRoot() {
    std::unique_lock<std::mutex> lock(rootMutex);
    return root_.load();
}
```

