int dns_resolve(const char *hostname, u_char *ip) {
    struct hostent *he;
    struct in_addr **addr_list;

    if ((he = gethostbyname(hostname)) == NULL)
        return -1;

    addr_list = he->h_addr_list;
    if (addr_list == NULL)
        return -1;

    memcpy(ip, addr_list[0]->s_addr, sizeof(u_char) * 4);
    return 0;
}

void aes_init(struct aes_ctx *ctx, const char *password) {
    unsigned char digest[SHA_DIGEST_LENGTH];
    SHA1((unsigned char*)password, strlen(password), digest);

    AES_set_encrypt_key(digest, KEY_LENGTH, &ctx->cipher);
    ctx->cipher.iv = ((AES_KEY*)malloc(IV_LENGTH))->iv;
    memset(ctx->cipher.iv, 0, IV_LENGTH);
}

void aes_cleanup(struct aes_ctx *ctx) {
    free(ctx->cipher.iv);
}

