#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Thread-safe memory pool for efficient allocation
struct MemPool {
    void* buffer;
    size_t capacity;
    size_t used;
};

typedef struct LTE_PHY_Layer_Config {
    unsigned int cell_id;
    unsigned int bwp;
    enum ModulationScheme modulation;
} LTE_PHY_Layer_Config;

struct MemPool* create_mem_pool(size_t size) {
    struct MemPool *mp = malloc(sizeof(struct MemPool));
    if (!mp) return NULL;

    mp->buffer = malloc(size);
    if (!mp->buffer) {
        free(mp);
        return NULL;
    }

    mp->capacity = size;
    mp->used = 0;
    return mp;
}

void* mem_pool_alloc(struct MemPool *mp, size_t size) {
    if (mp->used + size > mp->capacity) return NULL;

    void* result = &((char*)mp->buffer)[mp->used];
    mp->used += size;
    return result;
}

void mem_pool_free(struct MemPool *mp, void* ptr) {
    if (!ptr || !mp) return;

    char* p = (char*)ptr - ((char*)mp->buffer - mp->used);
    mp->used -= p - (char*)mp->buffer;
}

// Thread-safe data structure for LTE PHY Layer Configurations
typedef struct LTE_PHY_Config_Pool {
    struct MemPool* configs;
    pthread_mutex_t lock;
} LTE_PHY_Config_Pool;

LTE_PHY_Config_Pool* create_config_pool(size_t capacity) {
    LTE_PHY_Config_Pool *cp = malloc(sizeof(LTE_PHY_Config_Pool));
    if (!cp) return NULL;

    cp->configs = create_mem_pool(capacity * sizeof(LTE_PHY_Layer_Config));
    if (!cp->configs) {
        free(cp);
        return NULL;
    }

    pthread_mutex_init(&cp->lock, NULL);
    return cp;
}

LTE_PHY_Layer_Config* get_config(LTE_PHY_Config_Pool *cp) {
    LTE_PHY_Layer_Config* config;

    pthread_mutex_lock(&cp->lock);
    config = mem_pool_alloc(cp->configs, sizeof(LTE_PHY_Layer_Config));
    if (config) memset(config, 0, sizeof(*config));
    pthread_mutex_unlock(&cp->lock);

    return config;
}

void put_config(LTE_PHY_Config_Pool *cp, LTE_PHY_Layer_Config* config) {
    if (!config || !cp) return;

    pthread_mutex_lock(&cp->lock);
    mem_pool_free(cp->configs, config);
    pthread_mutex_unlock(&cp->lock);
}

// Implement the function to generate and populate LTE PHY Layer Configurations here.
