void delete_event(unsigned int event_id) {
    TickerEvent *to_delete = find_event(event_id);
    if (to_delete == NULL) {
        return;
    }

    pthread_mutex_lock(&mutex);

    if (to_delete == head) {
        head = to_delete->next;
    } else if (to_delete->next != NULL) {
        TickerEvent *prev = head;
        while (prev->next != to_delete) {
            prev = prev->next;
        }
        prev->next = to_delete->next;
    }

    pthread_mutex_unlock(&mutex);

    free(to_delete->tags);
    free(to_delete);
}

