#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void *data;
    size_t size;
    size_t allocated;
    pthread_mutex_t lock;
    int max_concurrency;
} MemoryPool;

MemoryPool *memory_pool_init(size_t initial_size, int max_concurrency) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }
    pool->data = mmap(NULL, initial_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->data == MAP_FAILED) {
        fprintf(stderr, "Error: Failed to allocate memory for pool\n");
        free(pool);
        return NULL;
    }
    pool->size = initial_size;
    pool->allocated = 0;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    pool->max_concurrency = max_concurrency > 0 ? max_concurrency : 1;
    return pool;
}

void *pool_get(MemoryPool *pool) {
    void *ptr;
    pthread_mutex_lock(&pool->lock);
    if (pool->allocated < pool->size && (pool->allocated + N) <= pool->size) {
        ptr = (char *)pool->data + pool->allocated;
        pool->allocated += sizeof(NFAPI_CRC_INDICATION_PDU_T);
    } else {
        fprintf(stderr, "Error: Memory pool is full\n");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pthread_mutex_unlock(&pool->lock);
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)ptr;
    pdu->rx_ue_information.tag = RX_UE_INFORMATION_TAG_VALUE;
    pdu->rnti.value = rand(); // replace with a more suitable RNTI initialization
    pdu->crc_indication_rel8_tag.tag = CRC_INDICATION_REL8_TAG_VALUE;
    pdu->crc_indication_rel8_tag.crcflag = (rand() % 2) == 0 ? true : false; // randomize CRCFLAG value
    return pdu;
}

void memory_pool_deinit(MemoryPool *pool) {
    if (pool->data != MAP_FAILED) {
        munmap(pool->data, pool->size);
    }
    free(pool);
}

