static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

struct file_data {
    FILE *fp;
    size_t lines, chars;
};

void *process_file(void *arg) {
    struct file_data *data = arg;
    char buffer[4096];

    while (fgets(buffer, sizeof(buffer), data->fp)) {
        data->chars += strlen(buffer);
        data->lines++;
    }

    pthread_mutex_unlock(&log_mutex);
    return NULL;
}

void log_error(const char *fmt, ...) {
    if (log_file) {
        va_list args;
        va_start(args, fmt);
        vfprintf(log_file, fmt, args);
        va_end(args);
    }
    vwarn(fmt, args);
}

void usage() {
    fprintf(stderr, "Usage: program [options...] input_files...\n");
    fprintf(stderr, "\nOptions:\n");
    fprintf(stderr, "  --manpage           Display this help and exit\n");
    fprintf(stderr, "  -c, --count          Count lines and characters only\n");
    fprintf(stderr, "  -o, --output FILE    Write results to FILE (default: stdout)\n");
    fprintf(stderr, "  -l, --logfile FILE   Log errors and warnings to FILE\n");
}

int main(int argc, char **argv) {
    int count = 0, output = 1, log_errs = 0;
    const char *output_file = NULL;
    FILE *out = stdout;
    struct file_data *input_files = NULL;
    size_t num_threads = sysconf(_SC_NPROCESSORS_CONF);

    static struct option long_options[] = {
        {"manpage", no_argument, nullptr, 'h'},
        {"count", no_argument, nullptr, 'c'},
        {"output", required_argument, nullptr, 'o'},
        {"logfile", required_argument, nullptr, 'l'},
        {nullptr}
    };

    while (1) {
        int option_index = 0;
        int c = getopt_long(argc, argv, "hcl:o:", long_options, &option_index);

        if (c == -1)
            break;

        switch (c) {
        case 'h':
            usage();
            return 0;
        case 'c':
            count++;
            break;
        case 'l':
            log_errs++;
            if (log_file) {
                warnx("Multiple --logfile options are not allowed");
                return 1;
            }
            log_file = fopen(optarg, "w");
            if (!log_file) {
                log_error("Failed to open log file: %s\n", optarg);
                return 1;
            }
            pthread_mutex_init(&log_mutex, nullptr);
            break;
        case 'o':
            output = 0;
            output_file = optarg;
            break;
        default:
            usage();
            return 1;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Error: At least one input file required\n");
        return 1;
    }

    input_files = calloc(argc - optind, sizeof(*input_files));
    if (!input_files) {
        log_error("Failed to allocate memory for input files\n");
        return 1;
    }

    if (num_threads > argc - optind) {
        num_threads = argc - optind;
    }

    pthread_t threads[num_threads];
    size_t processed_files = 0;

    for (int i = optind; i < argc; ++i) {
        FILE *fp = fopen(argv[i], "r");

        if (!fp) {
            log_error("Failed to open file %s: %s\n", argv[i], strerror(errno));
            continue;
        }

        struct file_data *data = &input_files[processed_files++];
        data->fp = fp;
        data->lines = 0;
        data->chars = 0;

        if (num_threads > 0 && processed_files == num_threads) {
            for (int j = 0; j < num_threads; ++j) {
                pthread_create(&threads[j], nullptr, process_file, &input_files[j]);
            }
            while (processed_files < argc - optind) {}

            for (int j = 0; j < num_threads; ++j) {
                pthread_join(threads[j], NULL);
            }
        }
    }

    if (!count) {
        fprintf(out, "Cumulative statistics:\n");
    }

    size_t total_lines = 0, total_chars = 0;
    for (size_t i = 0; i < processed_files; ++i) {
        struct file_data *data = &input_files[i];
        if (count) {
            continue;
        }

        fprintf(out, "File %s:\n", argv[optind + i]);
        fprintf(out, "  Lines: %zu\n", data->lines);
        fprintf(out, "  Characters: %zu\n", data->chars);
        fprintf(out, "  Average line length: %.2f\n",
                (data->chars > 0) ? (float)data->chars / data->lines : 0.0);

        total_lines += data->lines;
        total_chars += data->chars;
    }

    if (!count) {
        fprintf(out, "  Total lines: %zu\n", total_lines);
        fprintf(out, "  Total characters: %zu\n", total_chars);
        fprintf(out, "  Average line length: %.2f\n",
                (total_chars > 0) ? (float)total_chars / total_lines : 0.0);
    }

    for (size_t i = 0; i < processed_files; ++i) {
        fclose(input_files[i].fp);
    }

    free(input_files);
    if (log_file) {
        fclose(log_file);
        pthread_mutex_destroy(&log_mutex);
    }

    return 0;
}
```

