#include <pthread.h>

#define MAX_POOL_SIZE 10000000
#define MAX_CONCURRENT 10000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

static NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
static size_t pool_size = 0;
static size_t allocated = 0;
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t notfull = PTHREAD_COND_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(size_t n) {
    size_t required = n > pool_size ? n : pool_size;

    pthread_mutex_lock(&pool_mutex);
    while (allocated + required > MAX_POOL_SIZE || allocated + required > pool_size) {
        pthread_cond_wait(&notfull, &pool_mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T *result = pool + allocated;
    allocated += required;
    pthread_mutex_unlock(&pool_mutex);

    for (size_t i = 0; i < required; ++i) {
        result[i].rx_ue = (RX_UE_INFORMATION_TAG){ .tag = RX_UE_INFORMATION };
        result[i].rnti = (RNTI){ .value = rand() % 0xFFFFFFFF };
        result[i].crc_indication.tag = CRC_INDICATION_REL8;
        result[i].crc_indication.crcflag = rand() % 2;
    }

    return result;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T *data, size_t n) {
    pthread_mutex_lock(&pool_mutex);
    allocated -= n;
    pthread_cond_signal(&notfull);
    pthread_mutex_unlock(&pool_mutex);
}

void* init_pool(void *arg) {
    pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for the pool.\n");
        return NULL;
    }

    pool_size = MAX_POOL_SIZE;
    allocated = 0;

    pthread_mutex_init(&pool_mutex, NULL);
    pthread_cond_init(&notfull, NULL);

    return NULL;
}

void cleanup_pool() {
    free(pool);
    pool = NULL;
    pool_size = 0;
    allocated = 0;

    pthread_mutex_destroy(&pool_mutex);
    pthread_cond_destroy(&notfull);
}
