['```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <unordered_map>
#include <boost/filesystem.hpp>
#include <boost/program_options.hpp>
#include <thread>
#include <mutex>
#include <atomic>

namespace fs = boost::filesystem;
namespace po = boost::program_options;

std::unordered_map<std::string, int> keywordFreqs;
std::unordered_map<std::string, int> cumulativeFreqs;
std::mutex mtx;
std::atomic<int> processedFiles{0};
std::vector<std::string> keywords;
std::string logFile, outputFile;
bool manpage = false, customKeywords = false, helpRequired = true;

void processKeywordFrequency(const fs::path& path) {
    std::ifstream file(path.string());
    if (!file) {
        if (logFile.empty()) {
            std::cerr << "Error: Could not open file: " << path << std::endl;
        } else {
            std::cout << "Log: Error: Could not open file: " << path << std::endl;
        }
        return;
    }
    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::string word;
        while (iss >> word) {
            std::transform(word.begin(), word.end(), word.begin(), ::tolower);
            if (keywords.count(word) && !isstopword(word)) {
                mtx.lock();
                ++keywordFreqs[word];
                mtx.unlock();
            }
        }
    }
    processedFiles++;
}

void analyzeAndPrintResults() {
    std::unordered_map<std::string, int> localCumulativeFreqs = keywordFreqs;
    for (const auto& pair : localCumulativeFreqs) {
        cumulativeFreqs[pair.first] += pair.second;
    }
    std::ofstream outFile(outputFile);
    if (!outFile) {
        std::cerr << "Error: Could not open output file." << std::endl;
        return;
    }
    for (const auto& [keyword, freq] : cumulativeFreqs) {
        outFile << keyword << ": " << freq << std::endl;
    }
}

int main(int argc, char* argv[]) {
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help,h", "Show this help message")
        ("manpage", "Display an extended help page")
        ("f,keywords", po::value<std::vector<std::string>>()->multitoken(), "Custom keywords (comma-separated)")
        ("o,output", po::value<std::string>(), "Output file for structured results")
        ("log,l", po::value<std::string>(), "Log errors and warnings to the specified file")
        ("directory", po::value<std::vector<std::string>>()->multitoken(), "Directories to process");

    po::variables_map vm;
    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);

    if (vm.count("manpage")) {
        std::cout << desc;
        return 0;
    }
    helpRequired = !vm.count("help") && !vm.count("directory");

    if (!helpRequired) {
        customKeywords = vm.count("keywords") > 0;
        keywords = customKeywords ? vm["keywords"].as<std::vector<std::string>>() : {"keyword1", "keyword2"};
        logFile = vm["log"].empty() ? "" : vm["log"].as<std::string>();
        outputFile = vm["output"].empty() ? "" : vm["output"].as<std::string>();
    }

    if (helpRequired) {
        std::cout << desc;
        return 0;
    }

    std::vector<fs::path> directories;
    for (const auto& dirStr : vm["directory"].as<std::vector<std::string>>()) {
        fs::path directoryPath(dirStr);
        if (!fs::exists(directoryPath) || !fs::is_directory(directoryPath)) {
            std::cerr << "Error: Specified directory does not exist or is not a valid directory." << std::endl;
            return 1;
        }
        directories.push_back(directoryPath);
    }

    if (directories.empty()) {
        if (!helpRequired) {
            std::cerr << "Error: No directories specified to process." << std::endl;
        }
        return 1;
    }

    std::vector<std::thread> threads;
    std::mutex mtx;
    int threadCount = std::max(1, std::thread::hardware_concurrency());
    for (int i = 0; i < threadCount; ++i) {
        threads.emplace_back([&]() {
            for (const auto& path : directories) {
                for (auto it = fs::recursive_directory_iterator(path); it != fs::recursive_directory_iterator(); ++it) {
                    if (!fs::is_regular_file(*it)) continue;
                    processKeywordFrequency(*it);
                }
            }
        });
    }

    for (auto& t : threads) t.join();

    analyzeAndPrintResults();
    return 0;
}
```

This code uses the Boost library to handle command-line arguments, file I/O, and recursive directory iteration. It leverages concurrent processing with multiple threads for efficient handling of thousands of files. Error handling is implemented for invalid file paths and directories. A log file can be specified using the -l option, and thread safety and consistency in shared resources are ensured using a mutex. The program also calculates cumulative keyword frequency statistics across all processed files.']

