#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    RRC_TRANSPORT_FORMAT_INFO format;
    TRANSPORT_CHANNEL_ID channel_id;
    PHY_MESSAGE_TAG tag;
} NFAPI_RRC_MESSAGE_T;

static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_RRC_MESSAGE_T* pool;
static size_t current_size = 0, max_elements = 1000000; // Set max_elements to desired limit

void deallocate() {
    if (pool) {
        free(pool);
        pool = NULL;
        current_size = 0;
    }
}

NFAPI_RRC_MESSAGE_T* allocate(size_t n) {
    if (!n || current_size + n >= max_elements) return NULL;

    NFAPI_RRC_MESSAGE_T* new_pool = NULL;

    pthread_mutex_lock(&pool_mutex);
    if (current_size + n < max_elements) {
        new_pool = realloc(pool, sizeof(NFAPI_RRC_MESSAGE_T) * (current_size + n));
        if (!new_pool) goto error;
    } else {
        size_t old_size = current_size;
        new_pool = realloc(pool, 2 * old_size * sizeof(NFAPI_RRC_MESSAGE_T));
        if (!new_pool) goto error;
        max_elements *= 2;
    }
    pool = new_pool;
    pthread_mutex_unlock(&pool_mutex);

    for (size_t i = current_size; i < current_size + n; ++i) {
        pool[i].format.init(); // Initialize each structure as needed
        pool[i].channel_id = 0;
        pool[i].tag = rand(); // Generate a random sequence identifier
    }

    current_size += n;
    return &pool[current_size - n];

error:
    if (new_pool) free(new_pool);
    pthread_mutex_unlock(&pool_mutex);
    return NULL;
}
