void readLog(const std::string& file, std::list<Record>& records, const std::string& target) {
    boost::iostreams::mapped_file_source source(file.c_str(), boost::iostreams::openmode::in | boost::iostreams::readonly);
    boost::iostreams::stream<boost::iostreams::mapped_file_source> inputStream(source);
    char buffer[65536]; // Adjust buffer size as needed
    std::string currentLine;
    Record* currentRecord = nullptr;
    bool targetFound = false;

    while (inputStream.readsome(buffer, sizeof(buffer))) {
        for (char* p = buffer; p < buffer + sizeof(buffer); ) {
            currentLine += *p++;
            if (*p == '\n') {
                processLine(currentLine, currentRecord, target, records);
                currentLine.clear();
            }
        }
    }

    processLine(currentLine, currentRecord, target, records); // Handle the last line
}

void processLine(const std::string& line, Record* currentRecord, const std::string& target, std::list<Record>& records) {
    if (!currentRecord)
        currentRecord = RecordsPool.construct();

    if (line.find(target) != std::string::npos && !targetFound) {
        currentRecord->id = rand() % MAX_RANDOM_NUMBER;
        targetFound = true;
        records.insert(std::next(records.begin(), records.size()), *currentRecord);
    } else if (targetFound && shouldIncludeErrors()) {
        currentRecord->errorLog += line + "\n";
    }
}

