#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct MemoryBlock {
    void *data;
    size_t capacity;
    size_t used;
};

struct MemoryPool {
    struct MemoryBlock *blocks;
    size_t num_blocks;
    size_t max_blocks;
    pthread_mutex_t lock;
};

void* allocate_memory(struct MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (size > pool->num_blocks) {
        if (size > pool->max_blocks) {
            void *new_blocks = mmap(NULL, size * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            if (new_blocks == MAP_FAILED) {
                pthread_mutex_unlock(&pool->lock);
                return NULL;
            }

            struct MemoryBlock new_block = {new_blocks, size, 0};
            void *prev_data = pool->blocks ? pool->blocks[pool->num_blocks - 1].data : NULL;

            if (prev_data) {
                memmove(new_blocks, prev_data, pool->num_blocks * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }

            pool->blocks = realloc(pool->blocks, (size + 1) * sizeof(struct MemoryBlock));
            if (!pool->blocks) {
                munmap(new_blocks, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                pthread_mutex_unlock(&pool->lock);
                return NULL;
            }

            pool->blocks[pool->num_blocks] = new_block;
            pool->max_blocks = size;
        }

        memmove(pool->blocks + pool->num_blocks, pool->blocks, (pool->num_blocks - 1) * sizeof(struct MemoryBlock));
    }

    struct MemoryBlock *memory_block = &pool->blocks[pool->num_blocks - 1];
    void *data = memory_block->data + memory_block->used;
    memory_block->used += size;

    pthread_mutex_unlock(&pool->lock);
    return data;
}

void free_memory(struct MemoryPool *pool, void *ptr) {
    if (!ptr || !pool->blocks)
        return;

    struct MemoryBlock *memory_block = (char *)ptr - ((char *)&pool->blocks[0] - (char *)pool->blocks);

    pthread_mutex_lock(&pool->lock);
    memory_block->used -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(struct MemoryPool *pool, size_t index) {
    if (index >= pool->blocks[0].capacity)
        return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_memory(pool, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu)
        return NULL;

    srand(time(NULL) + index);
    pdu->crc_indication.crcflag = rand() % 2;

    return pdu;
}

void destroy_pdus(struct MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free_memory(pool, pdus + i);
    }
}
```

