class MemoryPool {
public:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pool;
    size_t curSize = 0;

    MemoryPool() {
        pool.resize(MEMORY_POOL_SIZE);
    }

    NFAPI_CRC_INDICATION_PDU_T* allocate() {
        if (curSize >= MEMORY_POOL_SIZE) return nullptr;
        auto it = pool.end();
        std::advance(it, --curSize);
        *it = {}; // Initialize the structure
        return &*it;
    }

    void free(NFAPI_CRC_INDICATION_PDU_T* ptr) {
        if (ptr == nullptr) return;
        new (ptr) NFAPI_CRC_INDICATION_PDU_T(); // Reset the structure
        curSize++;
    }
};

MemoryPool memoryPool;
pthread_mutex_t mutex;

NFAPI_CRC_INDICATION_PDU_T* createPDUs(size_t N) {
