    if (!ptr) throw std::runtime_error("Memory pool exhausted.");

    ptr->crc_indication.crcflag = rand() % 2; // Set CRCFLAG randomly

    pthread_mutex_unlock(&mutex);

    return ptr;
}

void destroyPDUs(NFAPI_CRC_INDICATION_PDU_T* ptr, size_t N) {
