NFAPI_CRC_INDICATION_PDU_T* initialize_array(size_t N) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array = NULL;
    size_t array_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (!(pdu_array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(array_size))) {
        fprintf(stderr, "Error: Could not allocate memory for array.\n");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = i + 1;
        pdu_array[i].RNTI = i * 10 + 123456789;
        pdu_array[i].CRC_INDICATION_REL8_TAG = rand() % 2 == 0 ? (uint16_t)~((uint16_t)0 << 15 | 0x0080) : (uint16_t)0;
    }

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setscope(&attr, PTHREAD_SCOPE_SYSTEM);

    // Create a thread-safe data access helper function
    void* data_access(void *arg) {
        size_t index = (size_t)arg;
        pthread_mutex_lock(&mutex);
        NFAPI_CRC_INDICATION_PDU_T pdudata = pdu_array[index];
        pthread_mutex_unlock(&mutex);
        return &pdudata;
    }

    // Create a thread pool with a fixed number of threads (e.g., 4) for efficient resource utilization
    pthread_t threads[N];
    for (size_t i = 0; i < N; ++i) {
        void* result = NULL;
        int rc = pthread_create(&threads[i], &attr, data_access, (void*)i);
        if (rc) {
            fprintf(stderr, "Error: Could not create thread.\n");
            return NULL;
        }
    }

    // Wait for all threads to finish their execution
    for (size_t i = 0; i < N; ++i) {
        void* result;
        int rc = pthread_join(threads[i], &result);
        if (rc) {
            fprintf(stderr, "Error: Could not join thread.\n");
            return NULL;
        }
    }

    return pdu_array;
}
