typedef struct {
    void **elements; // array of element structures
    int size;
    pthread_mutex_t mutex;
} NODE_T;

void *load_data(const char *filename, NODE_T *node) {
    FILE *file = fopen(filename, "r");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    int size = ftell(file) / (sizeof(char *) + sizeof(int));
    rewind(file);

    node->elements = malloc(sizeof(void *) * size);
    if (!node->elements) {
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        char str[256];
        int value;
        fscanf(file, "%s %d\n", str, &value);
        node->elements[i] = malloc(sizeof(char *) + sizeof(int));
        if (!node->elements[i]) {
            for (int j = 0; j < i; ++j) free(node->elements[j]);
            free(node->elements);
            fclose(file);
            return NULL;
        }
        memcpy(node->elements[i], str, sizeof(char *) + sizeof(int));
        ((char **)node->elements[i])[0] = strdup(str); // Ensure data copy and not aliasing
        ((int *)&((char *)(node->elements[i]))[sizeof(char *)])[0] = value;
    }
    fclose(file);

    pthread_mutex_init(&node->mutex, NULL);
    return node->elements;
}

