[' Due to the complexity and extensive nature of the task, I'll provide a high-level design approach for your dynamic network device configuration function in C with pthreads for concurrency, using an atomic counter and lock-free linked list for thread safety.

```c
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct NetworkDeviceConfig {
    char ip[32];
    char subnet_mask[32];
    char gateway[32];
    char mac_address[64];
} NetworkDeviceConfig;

struct node {
    NetworkDeviceConfig config;
    struct node* next;
    volatile size_t index; // lock-free counter
};

static pthread_mutex_t init_mutex = PTHREAD_MUTEX_INITIALIZER;
static struct node *head = NULL, **tail = &head;

void* add_device(void* arg) {
    struct node* new_node = malloc(sizeof(struct node));
    if (!new_node) return NULL;

    printf("Enter IP address: ");
    fgets(new_node->config.ip, sizeof(new_node->config.ip), stdin);
    // ... fill the rest of the structure with user input

    new_node->next = NULL;
    pthread_mutex_lock(&init_mutex);
    if (*tail) {
        struct node* current = head;
        while (current->next != NULL) current = current->next;
        current->next = new_node;
    } else {
        head = new_node;
    }
    tail = &new_node->index; // update the tail pointer for the next insertion
    pthread_mutex_unlock(&init_mutex);

    return NULL;
}

void init_network_devices(size_t N) {
    if (N <= 0) return;

    pthread_t threads[N];
    for (size_t i = 0; i < N; ++i)
        if (pthread_create(&threads[i], NULL, add_device, NULL)) break;

    for (size_t i = 0; i < N; ++i) pthread_join(threads[i], NULL);
}
```

