    concurrent_allocations++;
    if (concurrent_allocations > max_concurrent_allocations) {
        fprintf(stderr, "Error: Maximum number of concurrent allocations exceeded.\n");
        pthread_mutex_unlock(&allocator_lock);
        return NULL;
    }
    pthread_mutex_unlock(&allocator_lock);

    size_t elements_in_pool = pool_length - pool_capacity;
    if (N <= elements_in_pool) {
        pool_length -= N;
        memmove((void*)memory_pool, (void*)(memory_pool + N), sizeof(NFAPI_CRC_INDICATION_PDU_T) * pool_length);
        return memory_pool;
    }

    size_t new_capacity = pool_capacity + N;
    if (new_capacity > pool_length) {
        while (new_capacity > pool_length) {
