            // Consider using asynchronous I/O operations, buffer pooling, and other optimization techniques.
            new_capacity *= 2;
        }

        NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)realloc(memory_pool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!temp) {
            fprintf(stderr, "Error: Failed to allocate memory.\n");
            pthread_mutex_lock(&allocator_lock);
            concurrent_allocations--;
            pthread_mutex_unlock(&allocator_lock);
            return NULL;
        }
        memory_pool = temp;
        pool_capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* result = memory_pool + pool_length;
    pool_length += N;
    for (size_t i = 0; i < N; ++i) {
        result[i].tag = 0xDEADBEEF; // Randomly set RX_UE_INFORMATION_TAG value
        result[i].rnti = rand() % 0xFFFF + 1; // Randomly set RNTI value
        result[i].crc_indication_tag.crcflag = (rand() % 2) ? 1 : 0; // Randomly set CRC_INDICATION_REL8_TAG.crcflag value
    }

    return result;
}

void deallocate_crc_indications(NFAPI_CRC_INDICATION_PDU_T* indications, size_t N) {
    if (N > pool_length - pool_capacity || !indications) {
        fprintf(stderr, "Error: Invalid input.\n");
        return;
    }

    pthread_mutex_lock(&allocator_lock);
    concurrent_allocations--;
    pthread_mutex_unlock(&allocator_lock);

    memmove((void*)(memory_pool), (void*)(indications), sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    pool_length -= N;
}
