import hashlib
import os

def md5_file(file_path):
    block_size = 65536
    hasher = hashlib.md5()

    with open(file_path, 'rb') as f:
        while True:
            data = f.read(block_size)
            if not data:
                break
            hasher.update(data)

    return hasher.digest()
