// Custom memory pool for efficient allocation and deallocation
struct mem_pool {
    void* data;
    size_t size;
    struct mem_pool* next;
};

struct mem_pool* memory_pool = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Custom memory allocator for small objects using buddy system
void* custom_malloc(size_t size) {
    if (!size) return NULL;

    // Implement your custom memory allocator here

    return calloc(1, size);
}

void custom_free(void* ptr) {
    free(ptr);
}

NFAPI_CRC_INDICATION_PDU_T* allocate(size_t N) {
    if (N <= 0) N = MAX_STRUCTURES;

    pthread_mutex_lock(&pool_lock);
    struct mem_pool* current = memory_pool;
    size_t total_allocated = 0;
    size_t required = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;

    while (current && current->size < required) {
        total_allocated += current->size;
        current = current->next;
    }

    if (!current || total_allocated < required) {
        struct mem_pool* new_pool = realloc(memory_pool, MEMORY_POOL_INITIAL_SIZE * sizeof(*new_pool));
        if (!new_pool) {
            pthread_mutex_unlock(&pool_lock);
            return NULL;
        }
        memory_pool = new_pool;
        memory_pool->size = MEMORY_POOL_INITIAL_SIZE;
        memory_pool->next = NULL;
    }

    void* data = (void*)((char*)current + current->size);
    size_t to_allocate = required - total_allocated;
    current->size += to_allocate;

    NFAPI_CRC_INDICATION_PDU_T* data_ptr = (NFAPI_CRC_INDICATION_PDU_T*)data;

    pthread_mutex_unlock(&pool_lock);

    // Initialize and validate the allocated memory
    for (size_t i = 0; i < N; ++i) {
        data_ptr[i].tag = INVALID_RX_UE_INFORMATION_TAG;
        data_ptr[i].RNTI = INVALID_RNTI;
        data_ptr[i].crc_indication.CRCFLAG = rand() % 2;
    }

    return data_ptr;
}

void deallocate(NFAPI_CRC_INDICATION_PDU_T* ptr) {
    pthread_mutex_lock(&pool_lock);

    for (size_t i = 0; i < MAX_STRUCTURES; ++i) {
        if (!ptr[i].tag || !ptr[i].RNTI || !ptr[i].crc_indication.CRCFLAG) continue;

        size_t index = (void*)ptr - (void*)allocate(MAX_STRUCTURES);
        struct mem_pool* current = memory_pool;

        pthread_mutex_lock(&current->lock);
        if (current->size >= sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            void* data = (void*)((char*)current + current->size - sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(data, ptr + index, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            current->size -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
        }
        pthread_mutex_unlock(&current->lock);
    }

    pthread_mutex_unlock(&pool_lock);
}
