void init_memory_pool(struct memory_pool *pool, size_t initial_size) {
    pool->capacity = initial_size;
    pool->used = 0;
    pool->data = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        fprintf(stderr, "Failed to allocate memory for the memory pool.\n");
        exit(EXIT_FAILURE);
    }
    memset(pool->data, 0, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(struct memory_pool *pool) {
    if (pool->used == pool->capacity) return NULL;

    pthread_mutex_lock(&pool->lock);

    NFAPI_CRC_INDICATION_PDU_T *element = &pool->data[pool->used];
    pool->used++;

    element->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG

    pthread_mutex_unlock(&pool->lock);
    return element;
}

void deallocate_to_pool(struct memory_pool *pool, NFAPI_CRC_INDICATION_PDU_T *element) {
    if (!element) return;

    pthread_mutex_lock(&pool->lock);

    pool->used--;

    element = NULL; // Set to NULL to avoid dangling pointers
    pthread_mutex_unlock(&pool->lock);
}

void free_memory_pool(struct memory_pool *pool) {
    if (pool->data) {
        free(pool->data);
        pool->data = NULL;
        pool->used = 0;
        pool->capacity = 0;
