#define MAX_ALLOWED 10000000
pthread_mutex_t packet_queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t packet_queue_cv = PTHREAD_COND_INITIALIZER;
int num_processed = 0, num_dropped = 0, total_time = 0;
packet_data* packet_queue = NULL;
size_t queue_size = 0, queue_capacity = 0;

void* process_and_log_rapid_packets(void* arg) {
    uint32_t interface_ids[16];
    char* protocols[8] = {"TCP", "UDP", "ICMP", "SCTP", "SPD", "MPLS", "GRE", "L2TP"};

    // Allocate memory for packet_data array with predefined size
    packet_data* packets = mmap(NULL, sizeof(packet_data) * 100000, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!packets) return NULL;

    // Initialize each packet's payload size to a random value within [1, 1024] range
    for (size_t i = 0; i < 100000; ++i) {
        packets[i].payload_size = rand() % 1025 + 1;
    }

    // Process N number of packets or MAX_ALLOWED, whichever comes first
    size_t n = *(size_t*)arg;
    for (size_t i = 0; i < n && num_processed < MAX_ALLOWED; ++i) {
        pthread_mutex_lock(&packet_queue_mutex);

        // Dequeue a packet from the queue, or wait if empty
        while (queue_size == 0) {
            pthread_cond_wait(&packet_queue_cv, &packet_queue_mutex);
        }
        size_t idx = (queue_size - 1) % queue_capacity;
        packet_data packet = packet_queue[idx];
        queue_size--;
        pthread_mutex_unlock(&packet_queue_mutex);

        // Validate the integrity of each packet structure before processing it
        if (packet.payload_size <= 0) continue;

        // Process the packet and log its details asynchronously using callback function
        log_callback callback = *(log_callback*)arg + 1; // Skip the first argument (pointer to packet data)
        callback(&packet);

        num_processed++;
        total_time += packet.payload_size;
    }

    munmap(packets, sizeof(packet_data) * 100000); // Deallocate the memory for the packets array

    return NULL;
}

void enqueue_packet(const packet_data* packet) {
    pthread_mutex_lock(&packet_queue_mutex);

    if (queue_size >= queue_capacity) {
        num_dropped++;
        pthread_mutex_unlock(&packet_queue_mutex);
        return;
    }

    packet_queue[queue_size] = *packet;
    queue_size++;
    pthread_cond_signal(&packet_queue_cv);
    pthread_mutex_unlock(&packet_queue_mutex);
}

void resize_queue(size_t new_capacity) {
    packet_data* tmp = realloc(packet_queue, sizeof(packet_data) * new_capacity);
    if (!tmp) return;
    packet_queue = tmp;
    queue_capacity = new_capacity;
}
