#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <syslog.h>

typedef struct {
    time_t timestamp;
    char source[256];
    int severity;
    char description[4096];
} LOG_ENTRY;

typedef struct {
    const char *source;
    unsigned long count;
    double average_severity;
} LOG_SUMMARY;

#define MAX_LOG_ENTRIES 1024

void warn(const char *fmt, ...) {
    va_list args;
    char log_msg[4096];

    va_start(args, fmt);
    vsnprintf(log_msg, sizeof(log_msg), fmt, args);
    va_end(args);

    openlog("analyze_and_aggregate_logs", LOG_PERROR | LOG_NDELAY, LOG_WARNING);
    syslog(LOG_WARNING, "%s", log_msg);
    closelog();
}

LOG_SUMMARY* analyze_and_aggregate_logs(const char *filename, const char *source, int severity) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        warn("Failed to open log file: %s", filename);
        return NULL;
    }

    LOG_ENTRY entries[MAX_LOG_ENTRIES];
    unsigned long num_entries = 0;

    while (num_entries < MAX_LOG_ENTRIES && fscanf(file, "%ld %255s %d %4095[^\n]", &entries[num_entries].timestamp, entries[num_entries].source, &entries[num_entries].severity, entries[num_entries].description) != EOF) {
        num_entries++;
    }

    if (num_entries == 0) {
        warn("Log file is empty");
        fclose(file);
        return NULL;
    }

    LOG_SUMMARY *summary = malloc(sizeof(LOG_SUMMARY));
    if (!summary) {
        warn("Failed to allocate memory for summary struct");
        fclose(file);
        return NULL;
    }

    memset(summary, 0, sizeof(LOG_SUMMARY));
    summary->source = source;

    unsigned long matching_entries = 0;
    double total_severity = 0.0;

    for (unsigned long i = 0; i < num_entries; i++) {
        if (strcmp(entries[i].source, source) != 0 || entries[i].severity != severity) continue;

        matching_entries++;
        total_severity += entries[i].severity;
    }

    if (matching_entries == 0) {
        warn("No matching log entries found for specified criteria");
        free(summary);
        fclose(file);
        return NULL;
    }

    summary->count = matching_entries;
    summary->average_severity = total_severity / matching_entries;

    fclose(file);
    return summary;
}
