dynamic_array_t* initialize_dynamic_array(size_t max_size, const char* env_var) {
    dynamic_array_t *da = malloc(sizeof(dynamic_array_t));
    if (!da) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    da->capacity = atoi(getenv(env_var));
    if (da->capacity == 0) {
        fprintf(stderr, "Invalid max size for dynamic array\n");
        exit(EXIT_FAILURE);
    }

    da->length = 0;
    da->data = calloc(da->capacity, sizeof(NFAPI_CRCI_INDICATION_PDU_T));
    if (!da->data) {
        perror("calloc");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&da->lock, NULL);

