}

void add_to_dynamic_array(dynamic_array_t* da, const NFAPI_CRC_INDICATION_PDU_T* item) {
    if (da->length >= da->capacity) {
        da->capacity *= 2;
        da->data = realloc(da->data, sizeof(NFAPI_CRCI_INDICATION_PDU_T) * da->capacity);
        if (!da->data) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_lock(&da->lock);
    memcpy((void*)&da->data[da->length], item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->length++;
    pthread_mutex_unlock(&da->lock);
}

