    // Implement your recovery or error logging mechanism here
}

// Thread-safe synchronization attempts triggering function
void trigger_sync(dynamic_array_t* da, int interval_secs) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += interval_secs;

    while (1) {
        pthread_mutex_lock(&da->lock);
        if (da->length > 0 && timespecdiff(ts, clock_gettime(CLOCK_REALTIME)) >= timespecmake(interval_secs, 0)) {
