        last_log = current_time;

        pthread_mutex_lock(&log_mutex);

        if (error_count > ERROR_THRESHOLD) {
            char log_message[1024];
            snprintf(log_message, sizeof(log_message), "Error count exceeded threshold: %u\n", error_count);
