    if (list->head == NULL) {
        list->head = node;
    } else {
        NFAPI_LIST_NODE* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }

    if (list->length == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_LIST_NODE** nodes = realloc(list->head, sizeof(NFAPI_LIST_NODE) * new_capacity);
        if (nodes == NULL) {
            pthread_mutex_unlock(&list->list_lock);
            return;
        }
        list->head = nodes;
        list->capacity = new_capacity;
    }

    list->length++;
    pthread_mutex_unlock(&list->list_lock);
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_list_pop(NFAPI_LIST* list) {
    pthread_mutex_lock(&list->list_lock);

    if (list->length == 0) {
        pthread_mutex_unlock(&list->list_lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* data = &list->head->data;
    NFAPI_LIST_NODE* temp = list->head;
    list->head = list->head->next;
    free(temp);

    list->length--;

