        NFAPI_LIST_NODE** nodes = realloc(list->head, sizeof(NFAPI_LIST_NODE) * new_capacity);
        if (nodes == NULL) {
            pthread_mutex_unlock(&list->list_lock);
            return data;
        }
        list->head = nodes;
        list->capacity = new_capacity;
    }

