    if (now - config.start_maint >= config.end_maint) { // maintenance window check
        if (config.log_freq > 0 && now % config.log_freq == 0) {
            pthread_mutex_lock(&log_stats_mutex);
            printf("Maintenance mode: Logging statistics\n");
            printf("Total indications processed: %zu\n", stats.total_indications);
            printf("Valid indications: %zu\n", stats.valid_indications);
