        }
        ++stats.total_indications;
        if (++stats.valid_indications >= config.error_threshold) {
            char error_msg[256];
            snprintf(error_msg, sizeof(error_msg), "Error: Too many valid CRC indications in a short time span. RNTI=%u", indications[i].RNTI);
            log_error(error_msg);
        }
    }
}

