#include <stdlib.h>
#include <sys/socket.h>
#include <time.h>

typedef struct {
    int sockfd;
    struct sockaddr_in addr;
    time_t last_active;
} Connection;

struct connection_manager {
    Connection **connections;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

ConnectionManager new_connection_manager(size_t initial_capacity) {
    ConnectionManager cm = {.connections = NULL, .capacity = initial_capacity,
                            .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER};
    cm.connections = calloc(initial_capacity, sizeof(Connection *));
    return cm;
}

void add_connection(ConnectionManager *cm, int sockfd, struct sockaddr_in addr) {
    pthread_mutex_lock(&cm->lock);
    for (size_t i = 0; i < cm->capacity; ++i) {
        if (!cm->connections[i]) {
            cm->connections[i] = malloc(sizeof(Connection));
            memcpy(&((cm->connections[i])->addr), &addr, sizeof(struct sockaddr_in));
            (cm->connections[i])->sockfd = sockfd;
            (cm->connections[i])->last_active = time(NULL);
            cm->count++;
            pthread_mutex_unlock(&cm->lock);
            return;
        }
    }
    pthread_mutex_unlock(&cm->lock);

    resize_connection_manager(cm, cm->capacity * 2);
    add_connection(cm, sockfd, addr);
}

void remove_connection(ConnectionManager *cm, int sockfd) {
    pthread_mutex_lock(&cm->lock);
    for (size_t i = 0; i < cm->capacity; ++i) {
        if (cm->connections[i] && cm->connections[i]->sockfd == sockfd) {
            free(cm->connections[i]);
            memmove(cm->connections + i, cm->connections + i + 1,
                    --cm->capacity * sizeof(Connection *));
            cm->count--;
            pthread_mutex_unlock(&cm->lock);
            return;
        }
    }
    pthread_mutex_unlock(&cm->lock);
}

void clean_inactive_connections(ConnectionManager *cm) {
    time_t now = time(NULL);
    for (size_t i = 0; i < cm->capacity; ++i) {
        if (!cm->connections[i]) continue;
        if (now - cm->connections[i]->last_active > 60) { // or any other desired timeout
            free(cm->connections[i]);
            memmove(cm->connections + i, cm->connections + i + 1,
                    --cm->capacity * sizeof(Connection *));
            cm->count--;
        }
    }
}

void resize_connection_manager(ConnectionManager *cm, size_t new_capacity) {
    Connection **new_arr = realloc(cm->connections, new_capacity * sizeof(Connection *));
    if (!new_arr) return;
    cm->connections = new_arr;
    cm->capacity = new_capacity;
}
