  2. For calculating MD5 hash in Python, you can use python-hashlib library:

```python
def md5_hash(filepath):
    chunk_size = min(10485760, os.sysconf("SC_PAGE_SIZE"))  # Optimize based on system memory
    hasher = hashlib.md5()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            hasher.update(chunk)
    return hasher.hexdigest()
```

  3. For Java, you can create a class `MD5Hasher` to calculate the MD5 hash of a large file:

```java
import java.io.*;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MD5Hasher {
    private static final int CHUNK_SIZE = 10485760; // Optimize based on system memory

    public String calculate(File file) throws IOException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        try (FileInputStream inputStream = new FileInputStream(file)) {
            ByteBuffer buffer = ByteBuffer.allocateDirect(CHUNK_SIZE);
            while (inputStream.read(buffer) != -1) {
                digest.update(buffer.array());
                buffer.clear();
            }
        }
        byte[] md5Hash = digest.digest();
        StringBuilder sb = new StringBuilder();
        for (byte b : md5Hash) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
