// Function to manage dynamic array of TCP connection metadata structures
Connection* connections = NULL;
size_t num_connections = 0, capacity = 0;

void init() {
    if (capacity) free(connections);
    capacity = 16;
    connections = calloc(capacity, sizeof(Connection));
}

void add_connection(int sockfd, const struct sockaddr* addr) {
    if (num_connections == capacity) {
        capacity *= 2;
        Connection* tmp = realloc(connections, capacity * sizeof(Connection));
        if (!tmp) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
        connections = tmp;
    }
    connections[num_connections].sockfd = sockfd;
    memcpy(&connections[num_connections].addr, addr, sizeof(sockaddr));
    ++num_connections;
}

void remove_connection(int sockfd) {
    for (size_t i = 0; i < num_connections; ++i) {
        if (connections[i].sockfd == sockfd) {
            memmove(&connections[i], &connections[i + 1], (num_connections - i - 1) * sizeof(Connection));
            --num_connections;
            break;
        }
    }
}

const Connection* get_connection(int sockfd) {
    for (size_t i = 0; i < num_connections; ++i) {
        if (connections[i].sockfd == sockfd) return &connections[i];
    }
    return NULL;
}

void cleanup() {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < num_connections; ++i) {
        if (difftime(current_time, connections[i].addr.tv_usec / 1000000 + connections[i].addr.tv_sec) > 60) { // 1-minute idle disconnect
            close(connections[i].sockfd);
            memmove(&connections[i], &connections[i + 1], (num_connections - i - 1) * sizeof(Connection));
            --num_connections;
        }
    }
}
