    std::vector<NFAPI_CRC_INDICATION_PDU_T> data_;
    std::mutex mtx_;
    size_t max_entries_;

public:
    explicit NFAPI_CRC_INDICATION_PDU_Container(size_t max_entries) : max_entries_(max_entries) {}

    // Add an element to the container
    int add_element() {
        std::unique_lock<std::mutex> lock(mtx_);

        if (data_.size() >= max_entries_)
            return -1;  // Container is full, no more elements can be added

        data_.emplace_back();
        auto& item = data_.back();
        item.RX_UE_INFORMATION_TAG = std::random_device{}() >> 16;  // Ensure a valid tag value
        item.RNTI = std::random_device{}() % 0xffff;  // Random RNTI between 0 and 65535
        item.CRC_INDICATION_REL8_TAG = static_cast<uint8_t>(std::random_device{}() >> 24);  // Random CRCFLAG value
        return 0;  // Successful addition of an element
    }

    // Access the data without locking the mutex, returns const reference for read access and reference for write access.
    const NFAPI_CRC_INDICATION_PDU_T& get(size_t index) {
        assert(index < data_.size());
        return data_[index];
    }

    NFAPI_CRC_INDICATION_PDU_T& operator[](size_t index) {
        assert(index < data_.size());
        std::unique_lock<std::mutex> lock(mtx_);
        return data_[index];
