#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_VERSION 3
#define COMPRESSION_FLAG 1
#define CRITICAL_EVENT 1 << 0
#define NON_CRITICAL_EVENT 1 << 1

typedef struct {
    char *data;
    size_t len;
    int version;
    int compressed;
    pthread_mutex_t mutex;
} StringBuffer;

typedef void (*CriticalCallback)(const char*, const int);
typedef void (*NonCriticalCallback)(const char*, const int);

StringBuffer* create_string_buffer(size_t size_limit, int enable_compression, CriticalCallback critical_cb, NonCriticalCallback non_critical_cb) {
    StringBuffer *buf = (StringBuffer *)malloc(sizeof(StringBuffer));
    if (!buf) {
        critical_cb("Memory allocation failure", CRITICAL_EVENT);
        return NULL;
    }

    buf->data = malloc(size_limit + 1);
    if (!buf->data) {
        free(buf);
        critical_cb("Memory allocation failure", CRITICAL_EVENT);
        return NULL;
    }

    pthread_mutex_init(&buf->mutex, NULL);
    buf->len = size_limit;
    buf->version = 0;
    buf->compressed = enable_compression;
    memset(buf->data, 0, size_limit + 1);
    buf->data[size_limit] = '\0';

    if (critical_cb) critical_cb("String buffer created", CRITICAL_EVENT);
    if (non_critical_cb) non_critical_cb("String buffer created", NON_CRITICAL_EVENT);

    return buf;
}

void destroy_string_buffer(StringBuffer **buf_ptr) {
    StringBuffer *buf = *buf_ptr;
    if (buf) {
        free(buf->data);
        pthread_mutex_destroy(&buf->mutex);
        free(buf);
        if (buf_ptr) *buf_ptr = NULL;
    }
}

char* append_slash(StringBuffer *buf, pthread_mutex_t *mutex) {
    char *ret;
    pthread_mutex_lock(mutex);
    size_t new_len = buf->len + 2;
    if (new_len > buf->len) {
        ret = realloc(buf->data, new_len);
        if (!ret) {
            pthread_mutex_unlock(mutex);
            return NULL;
        }
        buf->data = ret;
    }
    buf->data[buf->len] = '/';
    buf->data[buf->len + 1] = '\0';
    buf->len++;
    pthread_mutex_unlock(mutex);
    return buf->data;
}

void compress_buffer(StringBuffer *buf, size_t compression_algorithm) {
    // Implement custom compression algorithm here
}

int get_string_size(const StringBuffer *buf) {
    return buf ? buf->len : 0;
}

char* read_string(const StringBuffer *buf) {
    char *ret = NULL;
    pthread_mutex_lock(&buf->mutex);
    ret = strdup(buf->data);
    pthread_mutex_unlock(&buf->mutex);
    return ret;
}

void update_version(StringBuffer *buf, int new_version) {
