void* compress(const void *src, size_t src_len, void *dst, size_t dst_len) {
    z_stream strm;
    int err = deflateInit(&strm, ZLIB_COMPRESSION);
    if (err != Z_OK) return NULL;
    strm.next_in = src;
    strm.avail_in = src_len;
    strm.next_out = dst;
    strm.avail_out = dst_len;
    err = deflate(&strm, Z_FINISH);
    deflateEnd(&strm);
    if (err != Z_STREAM_END) return NULL;
    return dst;
}

void* decompress(const void *src, size_t src_len, void *dst, size_t dst_len) {
    z_stream strm;
    int err = inflateInit(&strm);
    if (err != Z_OK) return NULL;
    strm.next_in = src;
    strm.avail_in = src_len;
    strm.next_out = dst;
    strm.avail_out = dst_len;
    err = inflate(&strm, Z_FINISH);
    inflateEnd(&strm);
    if (err != Z_STREAM_END) return NULL;
    return dst;
}

