    FILE *file = fopen(filename, "rb");
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    if (!file) goto cleanup;
    size_t data_len = 0;
    void *data = NULL;
    fseek(file, 0, SEEK_END);
    data_len = ftell(file);
    rewind(file);
    void *compressed_data = malloc(data_len);
    if (!compressed_data) goto cleanup;
    fread(compressed_data, data_len, 1, file);
    pthread_mutex_unlock(&mutex);
    size_t uncompressed_len = 0;
    void *uncompressed_data = decompress(compressed_data, data_len, (void *)&uncompressed_len, 0);
    if (!uncompressed_data) goto cleanup;
    void **list = malloc(uncompressed_len / sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(list, uncompressed_data, uncompressed_len);
    *out_len = uncompressed_len / sizeof(NFAPI_CRC_INDICATION_PDU_T);
cleanup:
    free(compressed_data);
    if (file) fclose(file);
    return list;
}

