void load_resource_bundle(const char* path, u_char* ip) {
    FILE* file = fopen(path, "rb");
    if (!file) {
        fprintf(stderr, "Error: Could not open resource bundle file '%s'\n", path);
        *ip = 0;
        return;
    }

    size_t header_size = sizeof(uint32_t) + sizeof(uint16_t); // Fixed header consists of item count and total size
    fseek(file, header_size, SEEK_SET); // Move to the start of bundle entries

    struct resource_bundle rb;
    rb.item_count = 0;
    rb.items = NULL;

    while (!feof(file)) {
        BUNDLE_ITEM_T* item = malloc(sizeof(BUNDLE_ITEM_T));
        if (fread(&item->type, sizeof(char), 1, file) != 1 || fread(&item->length, sizeof(size_t), 1, file) != 1) {
            fprintf(stderr, "Error: Corrupted resource bundle entry\n");
            free(item);
            continue;
        }

        item->data = malloc(item->length);
        if (fread(item->data, item->length, 1, file) != 1) {
            fprintf(stderr, "Error: Could not read resource bundle entry data\n");
            free(item->data);
            free(item);
            continue;
        }

        rb.items = realloc(rb.items, sizeof(BUNDLE_ITEM_T*) * (rb.item_count + 1));
        rb.items[rb.item_count++] = item;
    }

    fclose(file);
    *ip = inet_addr("0.0.0.0"); // Placeholder IP address
}

