    return 0;
}

void add_to_list(struct list *list, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (list->length >= list->capacity) return;

    sem_wait(&list->add_sem); // Wait for notification about changes

    pthread_mutex_lock(&list->lock);

    if (pdu->RNTI > 65535 || list->data[list->length].RNTI == pdu->RNTI) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    list->data[list->length] = *pdu;
    list->length++;

    pthread_mutex_unlock(&list->lock);
    sem_post(&list->add_sem); // Notify other parts of the application about changes
}

void serialize(const struct list *list, FILE *file) {
    gzFile gzf = gzopen(fileno(file), "w" );

    for (size_t i = 0; i < list->length; ++i) {
        fwrite(&list->data[i].RX_UE_INFORMATION_TAG, sizeof(uint16_t), 1, gzf);
        fwrite(&list->data[i].RNTI, sizeof(uint16_t), 1, gzf);
        fwrite(&list->data[i].CRC_INDICATION_REL8_TAG, sizeof(uint32_t), 1, gzf);
    }

    gzflush(gzf);
}

struct list *deserialize(FILE *file) {
    struct list *list = create_list(1024);
    if (!list) return NULL;

    gzFile gzf = gzopen(fileno(file), "r" );

    for (size_t i = 0; i < list->capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        fread(&pdu.RX_UE_INFORMATION_TAG, sizeof(uint16_t), 1, gzf);
        fread(&pdu.RNTI, sizeof(uint16_t), 1, gzf);
        fread(&pdu.CRC_INDICATION_REL8_TAG, sizeof(uint32_t), 1, gzf);

        list->data[i] = pdu;
    }

    return list;
}
