} Connection;

struct ConnectionPool {
    Connection *connections;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
};

ConnectionPool *create_connection_pool(size_t capacity) {
    ConnectionPool *pool = malloc(sizeof(ConnectionPool));
    pool->connections = calloc(capacity, sizeof(Connection));
    pool->capacity = capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void free_connection_pool(ConnectionPool *pool) {
    for (size_t i = 0; i < pool->size; ++i)
        close(pool->connections[i].socket);
    free(pool->connections);
    free(pool);
}

void add_connection(ConnectionPool *pool, int socket, struct sockaddr_in addr) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size == pool->capacity) {
        fprintf(stderr, "Connection pool is full.\n");
        pthread_mutex_unlock(&pool->mutex);
        return;
    }
    memmove(&(pool->connections[pool->size]), &{socket, addr}, sizeof(Connection));
    pool->size++;
    pthread_mutex_unlock(&pool->mutex);
}

int get_connection_by_socket(const ConnectionPool *pool, int socket) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->connections[i].socket == socket) {
            Connection c = pool->connections[i];
            memmove(pool->connections, &c, sizeof(Connection));
            --pool->size;
            pthread_mutex_unlock(&pool->mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

void cleanup_connections(ConnectionPool *pool) {
    time_t now = time(NULL);
    struct timespec ts = {0, 500000000}; // 0.5 seconds timeout

    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->size; ++i) {
        if ((now - pool->connections[i].addr.tv_sec) > 60) { // 1 minute inactive connection cleanup
            close(pool->connections[i].socket);
            memmove(&(pool->connections[i]), &(pool->connections[pool->size]), sizeof(Connection) * (pool->size - i));
            --pool->size;
        } else {
            nanosleep(&ts, NULL); // sleep for 500ms before checking again
        }
    }
    pthread_mutex_unlock(&pool->mutex);
}

