typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ENTRIES 1024

int init_pdu_array(NFAPI_CRC_INDICATION_PDU_T ***pdus, int *size) {
    *pdus = (NFAPI_CRC_INDICATION_PDU_T **)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (*pdus == NULL) {
        perror("Memory allocation failure");
        return 1;
    }

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        (*pdus)[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if ((*pdus)[i] == NULL) {
            perror("Memory allocation failure");
            return 1;
        }
    }

    *size = MAX_ENTRIES;
    return 0;
}

void populate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->tag.id = RX_UE_INFORMATION;
    pdu->tag.len = sizeof(RNTI);
    pdu->rnti.value = rand() % 0xFFFF;
    pdu->crc_indication.id = CRC_INDICATION_REL8;
    pdu->crc_indication.len = sizeof(CRCFLAG);
    pdu->crc_indication.crcflag = (char)(rand() % 2);
}

void incremental_update(NFAPI_CRC_INDICATION_PDU_T ***pdus, int *size, int index) {
    if (index >= *size) {
        NFAPI_CRC_INDICATION_PDU_T **new_pdus;
        int new_size = *size * 2;

        if (init_pdu_array(&new_pdus, &new_size)) return;

        for (int i = *size; i < new_size; ++i) {
            (*new_pdus)[i] = NULL;
        }

        for (int i = 0; i < *size; ++i) {
            (*new_pdus)[i] = (*pdus)[i];
        }

        free(*pdus);
        *pdus = new_pdus;
        *size = new_size;
    }

    populate_pdu((*pdus)[index]);
}
