// Router for handling user login and logout
app.use('/auth', router);

function router() {
  const router = express.Router();

  // Login route (generate new session token upon successful authentication)
  router.post('/login', async (req, res) => {
    const username = req.body.username;
    const password = req.body.password;

    if (!validateCredentials(username, password)) {
      return res.status(401).send('Invalid credentials');
    }

    // Generate a new session token and store user details in session metadata
    const payload = { role: getUserRole(username) };
    const token = await generateJWT(payload);

    req.session.user = { id: getUserId(username), role: payload.role };
    res.cookie('sessionId', req.sessionID, { maxAge: sessionExpirationPolicy() });
    res.json({ token });
  });

  // Logout route (invalidate current session upon logout)
  router.get('/logout', (req, res) => {
    req.session.destroy((err) => {
      if (err) return res.status(500).send('Error logging out');
      res.clearCookie('sessionId').send('Logged out');
