int initialize_array(size_t max_entries, struct data_pipeline_listener *listener, bool compress) {
    NFAPI_CRC_INDICATION_PDU_T *data;
    CompressedData *compressed = NULL;
    size_t num_entries = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    sem_t semaphore;

    data = calloc(max_entries, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        return 1;
    }

    sem_init(&semaphore, 0, num_entries);

    if (compress) {
        compressed = calloc(1, sizeof(CompressedData));
        if (!compressed) {
            free(data);
            return 2;
        }

        compressed->stored_size = 0;
        compressed->next_block = NULL;
        compressed->current_block = NULL;
        deflateInit(&compressed->stream, Z_DEFAULT_COMPRESSION);
    }

    while (num_entries < max_entries) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &data[num_entries];
        entry->tag = rand() % 0xFFFF;
        entry->rnti = rand() % 0x7FFFFFFF;
        entry->crc_indication.crcflag = (rand() % 2) == 0 ? 1 : 0;

        if (compress) {
            uLongf flen = compressBound(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            compressed->current_block = realloc(compressed->current_block, flen);
            if (!compressed->current_block) {
                free(data);
                sem_destroy(&semaphore);
                if (compressed) free(compressed);
                return 3;
            }

            compressed->next_block = compressed->current_block + sizeof(NFAPI_CRC_INDICATION_PDU_T);
            deflate(&compressed->stream, Z_NO_FLUSH, (Bytef *)entry, sizeof(NFAPI_CRC_INDICATION_PDU_T),
                    Z_NULL, 0, Z_DEFLATED, compressed->current_block);

            compressed->stored_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
            num_entries++;
        } else {
            num_entries++;
        }
    }

    if (compress) {
        deflateEnd(&compressed->stream);
    }

    void process_data(NFAPI_CRC_INDICATION_PDU_T *entry, size_t i) {
        pthread_mutex_lock(&mutex);
        (*listener->on_data)(entry, i);
        pthread_mutex_unlock(&mutex);
    }

    struct data_pipeline {
        sem_t semaphore;
        pthread_t thread_id;
        bool running;
    };

    struct data_pipeline *data_pipeline = calloc(1, sizeof(struct data_pipeline));
    if (!data_pipeline) {
        free(data);
        if (compress) sem_destroy(&semaphore);
        if (compressed) free(compressed);
        return 4;
    }

    sem_init(&data_pipeline->semaphore, 0, 0);
    data_pipeline->running = true;

    pthread_create(&data_pipeline->thread_id, NULL, process_pipeline_thread, data_pipeline);

    return 0;
}

void *process_pipeline_thread(void *arg) {
    struct data_pipeline *dp = arg;

    while (dp->running) {
        sem_wait(&dp->semaphore);

        // Process data here, call process_data on each entry in the array

        sem_post(&dp->semaphore);
    }

    return NULL;
}
