typedef struct {
    uint32_t rxi;
    uint16_t rnti;
    uint16_t crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ALLOWED 1000000
#define LOG_TIMEOUT 5000 // in milliseconds

void generate_and_log_crc_indications(int N, int* offsets, int* keys, int num_records) {
    pthread_t threads[num_records];
    NFAPI_CRC_INDICATION_PDU_T *indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize and validate each indication structure
    for (int i = 0; i < N; ++i) {
        indications[i].rxi = offsets[i % num_records];
        indications[i].rnti = keys[i % num_records];
        indications[i].crc_indication = rand() % 2;
    }

    int generated_count = 0, dropped_count = 0;
    clock_t start = clock();

    // Concurrently generate CRC indications for different UEs
    #pragma omp parallel for default(shared) firstprivate(N, indications, offsets, keys) reduction(+: generated_count, dropped_count) num_threads(num_records)
    for (int i = 0; i < N; ++i) {
        int id = omp_get_thread_num();
        if (generated_count + 1 > MAX_ALLOWED) {
            dropped_count++;
            continue;
        }

        // Simulate asynchronous logging mechanism
        pthread_create(&threads[id], NULL, log_indication, &indications[i]);
        generated_count++;
    }

    for (int i = 0; i < num_records; ++i) {
        pthread_join(threads[i], NULL);
    }

    clock_t end = clock();
    double elapsed_secs = ((double)(end - start)) / CLOCKS_PER_SEC;

    printf("Generated: %d, Dropped: %d, Time taken: %.2fs\n", generated_count, dropped_count, elapsed_secs);
    free(indications);
}

void* log_indication(void *data) {
    NFAPI_CRC_INDICATION_PDU_T *indication = (NFAPI_CRC_INDICATION_PDU_T *) data;
    // Send the log to an external logging service here
    sleep(LOG_TIMEOUT);
    return NULL;
}

