// Function to initialize dynamic list
void dynamic_list_init(dynamic_list_t *list, size_t capacity) {
    // Initialize mutex
    pthread_mutex_init(&list->mutex, NULL);

    // Allocate memory for list and set length and capacity
    list->list = malloc(capacity * sizeof(NFAPI_CRCI_INDICATION_PDU_T));
    list->length = 0;
    list->capacity = capacity;
}

// Function to add an element to the dynamic list (thread-safe)
void dynamic_list_add(dynamic_list_t *list, const NFAPI_CRCI_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->mutex);

    // Check if list is full, if so double the capacity and reallocate memory
    if (list->length == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRCI_INDICATION_PDU_T *new_list = realloc(list->list, new_capacity * sizeof(NFAPI_CRCI_INDICATION_PDU_T));
        if (!new_list) {
            // Handle memory allocation error
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    // Add the element to the list and increment length
    list->list[list->length] = *element;
    list->length++;

    pthread_mutex_unlock(&list->mutex);
}

