    if (!file) return -1;  // Handle error: file not found or unable to open

    // Code to resolve DNS for hostname and get IP address
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int result = getaddrinfo(hostname, NULL, &hints, &res);
    if (result != 0) {
        freeaddrinfo(res);
        return -1;  // Handle error: DNS resolution failed
    }

    memcpy(ip_addr, ((struct sockaddr_in *) res->ai_addr)->sin_addr.s_addr, sizeof(u_char));

    freeaddrinfo(res);

    fclose(file);

