    RNTI rnti;
    CRC_INDICATION_REL8_TAG ctag;
};

static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *buffer_pool[MAX_CONCURRENT + 1];
static int num_allocated = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate(int n) {
    if (n <= 0) {
        fprintf(stderr, "Error: Invalid input N must be positive\n");
        return NULL;
    }

    pthread_mutex_lock(&pool_lock);

    // Allocate memory from the buffer pool
    for (int i = MAX_CONCURRENT; i >= 0; --i) {
        if (!buffer_pool[i]) {
            buffer_pool[i] = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!buffer_pool[i]) {
                pthread_mutex_unlock(&pool_lock);
                fprintf(stderr, "Error: Failed to allocate memory\n");
                return NULL;
            }
            memset(buffer_pool[i], 0, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            num_allocated++;
            break;
        }
    }

    pthread_mutex_unlock(&pool_lock);

    // Initialize the structure with random CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T *data = buffer_pool[i];
    for (int j = 0; j < n; ++j) {
        data[j].ctag.crcflag = rand() % 2;
    }

    return data;
}

void deallocate(NFAPI_CRC_INDICATION_PDU_T *data) {
    if (!data) {
        fprintf(stderr, "Error: Trying to deallocate null pointer\n");
        return;
    }

    pthread_mutex_lock(&pool_lock);

    // Free the memory back to the buffer pool
    free(data);
    num_allocated--;

    pthread_mutex_unlock(&pool_lock);
}
