void optimizedDataPipelineManager_process_packet(struct optimizedDataPipelineManager* self) {
    pthread_mutex_lock(&self->buffer_lock);
    if (self->buffer_offset >= self->buffer_size) {
        pthread_mutex_unlock(&self->buffer_lock);
        return;
    }
    const size_t packet_size = sizeof(packet_t);
    memcpy(self->buffer + self->buffer_offset, &current_packet, packet_size);
    self->buffer_offset += packet_size;
    pthread_mutex_unlock(&self->buffer_lock);

