#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    char session_id[32];
    bool auth_status;
    time_t last_active;
    size_t num_permissions;
    int *permissions;
} Session;

struct session_manager {
    size_t capacity;
    size_t size;
    Session *sessions;
};

SessionManager* create_session_manager(size_t initial_capacity) {
    SessionManager* manager = malloc(sizeof(SessionManager));
    if (!manager) return NULL;
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->sessions = calloc(initial_capacity, sizeof(Session));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }
    return manager;
}

void resize_session_manager(SessionManager* manager, size_t new_capacity) {
    Session* temp_sessions = realloc(manager->sessions, new_capacity * sizeof(Session));
    if (!temp_sessions) return;
    manager->sessions = temp_sessions;
    manager->capacity = new_capacity;
}

void free_session_manager(SessionManager* manager) {
    free(manager->sessions);
    free(manager);
}

Session* find_session_by_id(const SessionManager* manager, const char *session_id) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->sessions[i].session_id, session_id) == 0) return &manager->sessions[i];
    }
    return NULL;
}

Session* add_session(SessionManager* manager, const char *session_id, bool auth_status, time_t last_active, size_t num_permissions, ...) {
    if (manager->size >= manager->capacity) resize_session_manager(manager, manager->capacity * 2);

    Session* new_session = &manager->sessions[manager->size];
    strcpy(new_session->session_id, session_id);
    new_session->auth_status = auth_status;
    new_session->last_active = last_active;
    new_session->num_permissions = num_permissions;
    new_session->permissions = malloc(new_session->num_permissions * sizeof(int));

    va_list args;
    va_start(args, num_permissions);
    for (size_t i = 0; i < new_session->num_permissions; ++i) {
        new_session->permissions[i] = va_arg(args, int);
    }
    va_end(args);

    manager->size++;
    return new_session;
}

void update_session(Session* session, bool auth_status, time_t last_active) {
    session->auth_status = auth_status;
    session->last_active = last_active;
}

bool remove_session_by_id(SessionManager* manager, const char *session_id) {
    Session* found_session = find_session_by_id(manager, session_id);
    if (!found_session) return false;

    memmove(&manager->sessions[found_session - manager->sessions], &manager->sessions[found_session + 1], (manager->size - 1 - found_session) * sizeof(Session));
    --manager->size;
    free(found_session->permissions);
    return true;
}

void clean_expired_sessions(SessionManager* manager, time_t timeout_in_seconds) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < manager->size; ++i) {
        if ((current_time - manager->sessions[i].last_active) > timeout_in_seconds) remove_session_by_id(manager, manager->sessions[i].session_id);
    }
}

int validate_user_ids(const char *input, size_t *num_valid_ids) {
    FILE* file = fopen(input, "r");
    if (!file) return 0;

    size_t num_read_ids = 0;
    int valid_ids[1024];
    char line[256];

    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, " \n");
        if (!token) continue;

        size_t id_len = strlen(token);
        if (id_len < 1 || id_len > 31) continue;

        valid_ids[num_read_ids] = atoi(token);
        ++num_read_ids;
    }
    fclose(file);

    *num_valid_ids = num_read_ids;
    return num_read_ids;
}
```']

