typedef struct {
    int session_id;
    bool authenticated;
    time_t last_active;
    char** permissions; // dynamically allocated array of strings
    int ref_count;
} SessionMetadata;

// Custom allocator function for minimizing fragmentation
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Custom free function for handling memory reclamation
void custom_free(void* ptr) {
    free(ptr);
}

pthread_mutex_t sessions_mutex = PTHREAD_MUTEX_INITIALIZER;
static SessionMetadata** sessions = NULL;
static size_t num_sessions = 0, capacity = 0;

// Helper function to read user IDs from standard input and validate them
int read_and_validate_ids(char* id_list) {
    int valid_count = 0, failed_count = 0;
    char* token = strtok(id_list, ",");
    while (token != NULL) {
        // Implement validation logic here
        if (is_valid_id(token)) {
            valid_count++;
        } else {
            failed_count++;
        }
        token = strtok(NULL, ",");
    }
    return valid_count;
}

// Function to initialize and manage dynamic array of session metadata structures
void init_sessions() {
    if (sessions) return; // check if already initialized
    sessions = (SessionMetadata**)custom_malloc(sizeof(SessionMetadata*) * 16);
    capacity = 16;
}

// Function to add a new session to the dynamic array
void add_session(int session_id, bool authenticated, time_t last_active) {
    pthread_mutex_lock(&sessions_mutex);
    if (num_sessions >= capacity) {
        // Resize array when it reaches its capacity
        capacity *= 2;
        SessionMetadata** new_sessions = (SessionMetadata**)custom_malloc(sizeof(SessionMetadata*) * capacity);
        memcpy(new_sessions, sessions, num_sessions * sizeof(SessionMetadata*));
        custom_free(sessions);
        sessions = new_sessions;
    }
    SessionMetadata* session = (SessionMetadata*)custom_malloc(sizeof(SessionMetadata));
    session->session_id = session_id;
    session->authenticated = authenticated;
    session->last_active = last_active;
    session->permissions = NULL; // dynamically allocate permissions array later as needed
    session->ref_count = 1;
    sessions[num_sessions++] = session;
    pthread_mutex_unlock(&sessions_mutex);
}

// Function to update an existing session by its session ID
void update_session(int session_id, bool authenticated, time_t last_active) {
    SessionMetadata* session;
    pthread_mutex_lock(&sessions_mutex);
    for (size_t i = 0; i < num_sessions; ++i) {
        if (sessions[i]->session_id == session_id) {
            session = sessions[i];
            break;
        }
    }
    if (!session) {
        pthread_mutex_unlock(&sessions_mutex);
        return; // Session not found, do nothing
    }
    session->authenticated = authenticated;
    session->last_active = last_active;
    pthread_mutex_unlock(&sessions_mutex);
}

// Function to remove a session by its session ID and decrease the reference count
void remove_session(int session_id) {
    SessionMetadata* session;
    pthread_mutex_lock(&sessions_mutex);
    for (size_t i = 0; i < num_sessions; ++i) {
        if (sessions[i]->session_id == session_id) {
            session = sessions[i];
            break;
        }
    }
    if (!session) {
        pthread_mutex_unlock(&sessions_mutex);
        return; // Session not found, do nothing
    }
    --session->ref_count;
    if (session->ref_count == 0) {
        size_t j = 0;
        for (size_t i = 0; i < num_sessions; ++i) {
            if (sessions[i] != session) continue;
            SessionMetadata* temp = sessions[j];
            memcpy(sessions + j, sessions + i, sizeof(SessionMetadata*));
            j++;
            custom_free(session);
            --num_sessions;
            break;
        }
    }
    pthread_mutex_unlock(&sessions_mutex);
}

// Function to retrieve session details based on the session ID
SessionMetadata* get_session(int session_id) {
    SessionMetadata* session;
    pthread_mutex_lock(&sessions_mutex);
    for (size_t i = 0; i < num_sessions; ++i) {
        if (sessions[i]->session_id == session_id) {
            session = sessions[i];
            break;
        }
    }
    pthread_mutex_unlock(&sessions_mutex);
    return session;
}

// Periodic cleanup function to clean up expired sessions, merge duplicates, and reclaim resources
void cleanup() {
    // Implement the logic for cleaning up expired sessions here
}
