}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: ./program N" << std::endl;
        return 1;
    }

    int N = std::stoi(argv[1]);
    pthread_t threads[MAX_CONCURRENT];

    for (int i = 0; i < MAX_CONCURRENT && N > 0; ++i) {
        pthread_create(&threads[i], nullptr, processDataThread, &N);
        N -= (MAX_CONCURRENT - i); // Reduce 'N' by the number of created threads
    }

    for (int i = 0; i < MAX_CONCURRENT; ++i) {
