int* generate_pdus(size_t N) {
    size_t element_size       = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int* result               = (int*)malloc((N + 1) * element_size);
    if (!result) return -1;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    size_t allocated_elements = 0;
    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&lock);
        if (allocated_elements >= N) break;
        void* ptr             = result + (allocated_elements * element_size);
        NFAPI_CRC_INDICATION_PDU_T* pdu = ptr;
        populate_pdu(pdu);
        allocated_elements++;
        pthread_mutex_unlock(&lock);
    }
    pthread_mutex_destroy(&lock);

    return (int*)calloc(allocated_elements, element_size);
}
