    const size_t max_n = 100000; // Maximum limit defined by system resources
    if (n > max_n) {
        fprintf(stderr, "Error: Invalid array size exceeds the maximum allowed value.\n");
        *out_size = 0;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* buffer = (NFAPI_CRC_INDICATION_PDU_T*)calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!buffer) {
