class MemoryPool {
public:
    MemoryPool(size_t blockSize, size_t numBlocks) : _blockSize(blockSize), _numBlocks(numBlocks) {
        _mem = static_cast<NFAPI_CRCI_PDU_T*>(std::malloc(_numBlocks * _blockSize));
        if (!_mem) throw std::bad_alloc();
    }

    ~MemoryPool() {
        std::free(_mem);
    }

    NFAPI_CRCI_PDU_T* acquire() {
        if (_freeIndex >= _numBlocks) _resetFreeIndex();
        auto result = &_mem[_freeIndex++];
        return result;
    }

    void release(NFAPI_CRCI_PDU_T* pdu) {
        new (pdu) NFAPI_CRCI_PDU_T(); // Construct an empty PDUs to clean up any user data
        _freeIndex--;
    }

private:
    size_t _blockSize;
    size_t _numBlocks;
    size_t _freeIndex = 0;
    NFAPI_CRCI_PDU_T* _mem;

    void _resetFreeIndex() {
        _freeIndex = 0;
        for (size_t i = 1; i < _numBlocks; ++i) {
            _mem[i - 1] = _mem[_freeIndex++];
        }
    }
};

