typedef struct _custom_allocator {
    void* pool;
    size_t size;
    size_t count;
    pthread_mutex_t mutex;
} CustomAllocator;

CustomAllocator* custom_allocator_init(size_t block_size, size_t num_blocks) {
    CustomAllocator *ca = malloc(sizeof(CustomAllocator));
    ca->pool = malloc(block_size * num_blocks);
    ca->size = block_size;
    ca->count = num_blocks;
    pthread_mutex_init(&ca->mutex, NULL);
    return ca;
}

void* custom_allocator_alloc(CustomAllocator* ca) {
    void* result;
    pthread_mutex_lock(&ca->mutex);
    if (ca->count > 0) {
        result = &((char *)ca->pool)[ca->size * (--ca->count)];
    } else {
        result = NULL;
    }
    pthread_mutex_unlock(&ca->mutex);
    return result;
}

void custom_allocator_free(CustomAllocator* ca, void* ptr) {
    if (ptr == NULL)
        return;

    pthread_mutex_lock(&ca->mutex);
    ((char *)ca->pool)[ca->size * ca->count] = '\0'; // Mark the freed block
    ca->count++;
    pthread_mutex_unlock(&ca->mutex);
}

