// Function to generate the array
void* generate_array(size_t n) {
    // Acquire the mutex before accessing the memory pool
    pthread_mutex_lock(&mem_pool_mutex);

    struct mem_pool *current = mem_pool_head;
    NFAPI_CRC_INDICATION_PDU_T *array = NULL;

    // Check if there's enough capacity in the memory pool
    while (current && current->capacity < n) {
        current = current->next;
