void init_id_pool(struct id_pool* pool, size_t size, size_t max_duplicates) {
    pool->size = size;
    pool->used = 0;
    pool->max_duplicates = max_duplicates;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
}

int find_available_rnti(const struct id_pool* pool) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size; ++i) {
        if (!pool->pool[i].rnti) {
            pthread_mutex_unlock(&pool->lock);
            return i;
        }
    }
    pthread_mutex_unlock(&pool->lock);

    // If all IDs are in use, randomly select an available one from the pool.
    int index = rand() % pool->size;
    while (pool->pool[index].rnti) {
        if (--index == 0) index = pool->size - 1;
    }
    pthread_mutex_lock(&pool->lock);
    return index;
}

void reset_id_pool(struct id_pool* pool) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size; ++i) {
        pool->pool[i].rnti = 0;
    }
    pool->used = 0;
    pthread_mutex_unlock(&pool->lock);
}

void flush_id_pool(struct id_pool* pool) {
