static unsigned long flushes = 0;
static double average_time = 0.0;

void network_event_init(size_t capacity) {
    events = malloc(capacity * sizeof(NetworkEvent));
    if (!events) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    this->capacity = capacity;
}

void network_event_add(const void* payload, const size_t data_size) {
    NetworkEvent* event;
    unsigned long id;

    // Lock ID pool and obtain a unique ID
    pthread_mutex_lock(&id_lock);
    do {
        id = next_id++;
    } while (find_duplicate(id));
    pthread_mutex_unlock(&id_lock);

