```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct SessionState {
    int session_id;
    time_t start_time;
    time_t duration;
    void* session_data;
    struct SessionState *next, *prev;
} SessionState;

SessionState* create_session(int id, void* data) {
    SessionState* new_node = (SessionState*) malloc(sizeof(SessionState));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    memset(new_node, 0, sizeof(SessionState));
    new_node->session_id = id;
    new_node->session_data = data;
    return new_node;
}

void initialize_list(size_t N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid list size: %zu\n", N);
        exit(1);
    }
    SessionState* head = NULL;
    for (size_t i = 0; i < N; ++i) {
        head = create_session(i, NULL);
        if (!head) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        head->prev = (head == head ? NULL : head->prev);
        if (head->prev)
            head->prev->next = head;
        else
            head->next = head;
    }
}

void update_session_duration(SessionState* node, time_t timestamp) {
    if (!node) return;
    node->duration = timestamp - node->start_time;
    if (node->prev)
        update_session_duration(node->prev, timestamp);
}

void iterate_list(SessionState* head, void(*func)(SessionState*)) {
    SessionState* current = head->next;
    while (current != head) {
        func(current);
        current = current->next;
    }
}
```

