        std::unique_lock<std::mutex> lock(mutex_); // lock critical section for thread safety
        if (buffer_.size() == buffer_.capacity()) { // resize the buffer when it's full to prevent overflow
            buffer_.resize(buffer_.capacity() * 2);
        }
        buffer_[buffer_.size() - 1] = data;
    }

    NFAPI_CRC_INDICATION_PDU_T getData() {
        std::unique_lock<std::mutex> lock(mutex_); // lock critical section for thread safety
        auto data = buffer_[0];
        std::rotate(buffer_.begin(), buffer_.begin() + 1, buffer_.end()); // rotate the buffer to remove the first element
        if (data.CRCFLAG) {
            resourcePool_.release(std::move(data)); // release the data and obtain a new one from the pool if necessary
            data = resourcePool_.acquire();
        }
        return data;
    }

private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> buffer_;
    ResourcePool resourcePool_; // manages resources for the dynamic array
    mutex mutex_; // protects access to the buffer and resource pool
};
