    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    int PROTOCOL_TYPE;
};

static const size_t MAX_PACKETS = 10000;
static semaphore_t sem; // Semaphore for limiting the number of packets
static mmap_t* buffer; // Mapped memory region for packet processing records
static size_t current_count = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

PACKET_PROCESSING_RECORD* allocate_and_process_packets(size_t N) {
    if (N <= 0 || N > MAX_PACKETS) {
        fprintf(stderr, "Invalid number of packets: %zu\n", N);
        return NULL;
    }

    sem_wait(&sem); // Acquire a permit to create new packets

    PACKET_PROCESSING_RECORD* packets = buffer + current_count;
    size_t batch_size = (N < MAX_PACKETS - current_count) ? N : (MAX_PACKETS - current_count);

    for (size_t i = 0; i < batch_size; ++i) {
        memset(packets[i].SOURCE_IP, '\0', sizeof(packets[i].SOURCE_IP));
        memset(packets[i].DESTINATION_IP, '\0', sizeof(packets[i].DESTINATION_IP));
        packets[i].PROTOCOL_TYPE = 0;
    }

    current_count += batch_size;

    // Perform packet processing here

    sem_post(&sem); // Release the permit to create new packets

    return packets;
}

void deallocate_packets(PACKET_PROCESSING_RECORD* packets, size_t count) {
    memmove(buffer, packets, sizeof(*packets) * count);
    current_count -= count;
}

