void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->pool = malloc(sizeof(Node*) * capacity);
    for (size_t i = 0; i < capacity; ++i)
        pool->pool[i] = NULL;
    pool->head = pool->tail = 0;
    pthread_mutex_init(&pool->mutex, NULL);
}

Node* acquireFromPool(struct MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    Node* node = pool->pool[pool->head];
    if (node != NULL) {
        pool->head = (pool->head + 1) % pool->capacity;
    }
    pthread_mutex_unlock(&pool->mutex);
    return node;
}

