struct MemoryPool {
    int capacity;
    int size;
    Node **array;
    pthread_mutex_t mutex;
};

void destroy_memory_pool(struct MemoryPool *pool) {
    for (int i = 0; i < pool->capacity; ++i) {
        if (pool->array[i]) {
            free(pool->array[i]);
        }
    }
    free(pool->array);
}

struct MemoryPool* create_memory_pool(int capacity) {
    struct MemoryPool *pool = malloc(sizeof(struct MemoryPool));
    pool->capacity = capacity;
    pool->size = 0;
    pool->array = calloc(capacity, sizeof(Node*));
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

Node* get_node_from_pool(struct MemoryPool *pool) {
    if (pool->size == pool->capacity) {
        return NULL; // All nodes are in use, no more available.
    }

    pthread_mutex_lock(&pool->mutex);

    for (int i = 0; i < pool->capacity; ++i) {
        if (!pool->array[i]) {
            pool->array[i] = malloc(sizeof(Node));
            pool->size++;
            Node *node = pool->array[i];
            node->next = NULL;
            pthread_mutex_unlock(&pool->mutex);
            return node;
        }
    }

    pthread_mutex_unlock(&pool->mutex);
    return NULL; // No available nodes found.
}

void return_node_to_pool(struct MemoryPool *pool, Node *node) {
    if (!node) {
        return;
    }

    pthread_mutex_lock(&pool->mutex);

    node->next = pool->array[0];
    pool->array[0] = node;

    pthread_mutex_unlock(&pool->mutex);
}

