typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void *data;
    size_t size;
    size_t capacity;
    struct MemoryPool *next;
} MemoryPool;

MemoryPool *memory_pool = NULL;
const int MAX_CONCURRENT_STRUCTURES = 100000;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_array(size_t N) {
    if (N <= 0) {
        fprintf(stderr, "Error: Invalid input size\n");
        return NULL;
    }

    MemoryPool *pool = memory_pool;
    while (pool && pool->capacity < N)
        pool = pool->next;

    if (!pool) {
        size_t pool_size = (N + sizeof(NFAPI_CRC_INDICATION_PDU_T)) >> 2; // Round up to the nearest power of 2
        MemoryPool *new_pool = (MemoryPool*)malloc(sizeof(MemoryPool));
        if (!new_pool) {
            fprintf(stderr, "Error: Out of memory\n");
            return NULL;
        }

        new_pool->data = malloc(pool_size);
        if (!new_pool->data) {
            free(new_pool);
            fprintf(stderr, "Error: Out of memory\n");
            return NULL;
        }
        new_pool->size = pool_size;
        new_pool->capacity = pool_size >> 2; // Number of NFAPI_CRC_INDICATION_PDU_T structures
        new_pool->next = memory_pool;
        memory_pool = new_pool;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)pool->data;
    for (size_t i = pool->capacity; i < N; ++i) {
        array[i].rx_ue_info.tag = RX_UE_INFORMATION_TAG_INVALID;
        array[i].rnti = 0;
        array[i].crc_indication.crcflag = rand() % 2;
    }

    return array;
}

void destroy_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t N) {
    if (!array || N <= 0)
        return;

    pthread_mutex_lock(&pool_mutex);
    MemoryPool *pool = memory_pool;
    while (pool && pool->capacity >= N)
        pool = pool->next;
    if (pool && pool->data == array) {
        if (N < pool->capacity) {
            memmove(array, &array[N], (pool->capacity - N)*sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pool->capacity -= N;
        } else {
            free(pool->data);
            MemoryPool *temp = pool->next;
            free(pool);
            memory_pool = temp;
        }
    }
    pthread_mutex_unlock(&pool_mutex);
}
```

