struct AES_ctx {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
};

// Function to initialize the AES context with provided key and IV
void AES_init(struct AES_ctx *ctx, const unsigned char *key, const unsigned char *iv) {
    AES_set_encrypt_key(key, 128, &ctx->key);
    memcpy(ctx->iv, iv, sizeof(ctx->iv));
}

// Function to decrypt the imsi value using AES-CBC with padding
void decrypt_imsi(UEState *ue, struct AES_ctx *ctx) {
    unsigned char ciphertext[AES_BLOCK_SIZE + 16];
    memcpy(ciphertext, &ue->imsi, sizeof(ue->imsi));
    ue->imsi = 0; // Clear the original imsi value before decryption

    int len = AES_DECryptCBC(ciphertext + 16, ciphertext, sizeof(ciphertext), &ctx->key, ctx->iv);
    if (len <= 0) {
        ue->imsi = -1; // Set error flag for decryption failure
    } else {
        memcpy(&ue->imsi, ciphertext, len);
    }
}

// Function to manage the dynamic array of UEState structures
int manage_UEs(int numUes, const unsigned char *key, const unsigned char *iv) {
    struct AES_ctx aesCtx = { { 0 } };
    AES_init(&aesCtx, key, iv);

    UEState *ues = malloc(numUes * sizeof(UEState));
    if (!ues) return -1; // Allocate memory error

    for (int i = 0; i < numUes; ++i) {
        ues[i].imsi = i + 1; // Encrypt imsi value for testing purposes
        ues[i].rrcConnectionState = RRC_CONNECTED;
        ues[i].cellInfo = get_cell_info(i); // Replace with actual cell info generation function
    }

    for (UEState *ue : ues) {
        decrypt_imsi(ue, &aesCtx);
        if (ue->imsi < 0) {
            free(ues);
            return -2; // Decryption error
        }
    }

    for (const UEState *ue : ues) {
        printf("UE %ld: RRC Connection State: %d, Cell Info:\n", ue->imsi, ue->rrcConnectionState);
        print_cell_info(ue->cellInfo); // Replace with actual cell info printing function
    }

    free(ues);
    return 0;
}
