            free(record);
            EVP_CIPHER_free(cipher);
            continue;
        }

        memcpy(modified_record, record, st.st_size * sizeof(record_t));
        modified_record[st.st_size / sizeof(record_t) - processed_records + 1].fieldN = sum;

