            EVP_CipherParams* params = EVP_CIPHER_params_new();
            EVP_EncryptInit_ex(cipher, NULL, NULL, config.encryption_key, config.encryption_iv);
            int len = st.st_size / sizeof(record_t) + encrypt;
            unsigned char* out = malloc(len * sizeof(unsigned char));
            if (!out) {
                perror("malloc");
                free(modified_record);
                EVP_CIPHER_free(cipher);
                continue;
            }

            int ret = EVP_EncryptUpdate(cipher, out, &len, modified_record, len * sizeof(unsigned char), NULL, NULL);
            if (ret < 0) {
                perror("EVP_EncryptUpdate");
                free(out);
                free(modified_record);
                EVP_CIPHER_free(cipher);
                continue;
            }

            ret = EVP_EncryptFinal_ex(cipher, out + len - ret, &len);
            if (ret < 0) {
                perror("EVP_EncryptFinal_ex");
                free(out);
                free(modified_record);
                EVP_CIPHER_free(cipher);
                continue;
            }

            modified_record = realloc(modified_record, (len + 1) * sizeof(record_t));
            if (!modified_record) {
                perror("realloc");
                free(out);
                free(modified_record);
                EVP_CIPHER_free(cipher);
                continue;
            }

            memcpy(modified_record + (st.st_size / sizeof(record_t) - processed_records), out, len * sizeof(unsigned char));
            free(out);
        }

        // Save the modified record to a new file
        char output_filename[256];
        snprintf(output_filename, sizeof(output_filename), "./processed/%s", entry->d_name);
        FILE* output_file = fopen(output_filename, "wb+");
        if (!output_file) {
            perror("fopen");
            free(modified_record);
            EVP_CIPHER_free(cipher);
            continue;
        }

        fwrite(modified_record, 1, len * sizeof(record_t), output_file);
        fclose(output_file);

        // Increment processed count and notify all threads
        pthread_mutex_lock(&mutex);
        num_processed++;
        pthread_cond_broadcast(&mutex);
        pthread_mutex_unlock(&mutex);

        free(modified_record);
