#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    int sum;
    size_t count;
} LineStat;

int is_number(const char* str) {
    for (size_t i = 0; str[i]; ++i) {
        if (!isdigit(str[i]) && str[i] != '.')
            return 0;
    }
    return 1;
}

void process_line(LineStat* stats, const char* line) {
    double num = 0.0;
    size_t i = 0;
    size_t len = strlen(line);
    for (size_t j = 0; j < len && i < len; ++j) {
        if (isdigit(line[j]) || line[j] == '.') {
            num = num * 10.0 + (line[j] - '0');
            if (line[++i] == '.')
                num += (line[i++] - '0') / 10.0;
        } else if (i) {
            if (!num) i = 0; // reset number parsing for next number on line
            else break;    // no need to continue processing this line
        }
    }

    if (num && !isnan(num)) {
        stats->sum += num;
        ++stats->count;
    }
}

void final_report(const LineStat* stats, size_t line_count) {
    double avg = stats->sum / line_count;
    printf("Summary report:\n");
    printf("Total sum: %.2f\n", stats->sum);
    printf("Total count: %zu\n", stats->count);
    printf("Average per line: %.2f\n", avg);
}

int main() {
    FILE* file = fopen("large_text_file.txt", "r");
    if (!file) {
        fprintf(stderr, "Error opening file.\n");
        return 1;
    }

    LineStat* stats = malloc(sizeof(LineStat));
    stats->sum = stats->count = 0;

    char line[4096];
    size_t line_count = 0;

    while (fgets(line, sizeof(line), file)) {
        LineStat* current_stats = realloc(stats, sizeof(LineStat) * (line_count + 1));
        if (!current_stats) {
            fprintf(stderr, "Memory allocation error.\n");
            free(stats);
            fclose(file);
            return 1;
        }
        stats = current_stats;

        process_line(&stats[line_count], line);
        ++line_count;
    }

    final_report(&stats[0], line_count);
    free(stats);
    fclose(file);

    return 0;
}
