int is_valid(double value, size_t max_value) {
    if (value <= 0 || value > max_value)
        return -1;

    return 1;
}

void handle_error(const char* message) {
    fprintf(stderr, "%s\n", message);
    ERR_print_errors_fp(stderr);
    exit(EXIT_FAILURE);
}

Event* read_event(FILE* fp) {
    Event* event = malloc(sizeof(*event));
    size_t len;

    // Read event id and other components...

    fread(&len, sizeof(len), 1, fp);
    event->numeric_fields[0] = fread_double(fp, &len);
    event->numeric_fields[1] = fread_double(fp, &len);
    event->numeric_fields[2] = fread_double(fp, &len);

    if (feof(fp)) {
        free(event);
        return NULL;
    }

    handle_error("Error reading event");
}

void write_event(const Event* event, FILE* fp) {
    // Write event id and other components...

    fwrite(&event->numeric_fields[0], sizeof(double), 3, fp);

    if (ferror(fp))
        handle_error("Error writing event");
}

void* process_file(void* arg) {
    char* filename = (char*)arg;
    FILE* fp = fopen(filename, "r+");

    if (!fp)
        return NULL;

    Event* event;

    while ((event = read_event(fp))) {
        double average = event->numeric_fields[2] ? average(event->numeric_fields, 3) : 0.0;
        event->numeric_fields[3] = average;

        for (size_t i = 0; i < 4; ++i) {
            if (is_valid(event->numeric_fields[i], 10000) == -1) {
                fprintf(stderr, "Invalid numeric field value: %lf\n", event->numeric_fields[i]);
            }
        }

        write_event(event, fp);
        free(event);
    }

    fclose(fp);

    return NULL;
}

int main(int argc, char** argv) {
    if (argc < 2)
        handle_error("Please provide a log file to process");

    EVP_CIPHER* cipher = get_cipher(argv[1]);

    pthread_t threads[argc - 1];

    for (size_t i = 1; i < argc; ++i) {
        if (pthread_create(&threads[i - 1], NULL, process_file, argv[i]))
            handle_error("Error creating thread");
    }

    // Wait for all threads to finish...
}
