struct memory_pool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    pthread_mutex_t lock;
};

typedef struct memory_pool MEMORY_POOL;

MEMORY_POOL* create_memory_pool(size_t block_size, size_t num_blocks) {
    MEMORY_POOL* pool = malloc(sizeof(MEMORY_POOL));
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->pool = mmap(NULL, block_size * num_blocks, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->pool == MAP_FAILED) {
        free(pool);
        return NULL;
    }
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MEMORY_POOL* pool) {
    if (pool != NULL && pool->pool != MAP_FAILED) {
        munmap(pool->pool, pool->block_size * pool->num_blocks);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

void* memory_pool_alloc(MEMORY_POOL* pool) {
    void* result;
    pthread_mutex_lock(&pool->lock);
    if (pool->num_blocks > 0) {
        result = pool->pool + (--pool->num_blocks * pool->block_size);
    } else {
        result = NULL;
    }
    pthread_mutex_unlock(&pool->lock);
    return result;
}

void memory_pool_free(MEMORY_POOL* pool, void* ptr) {
    if (ptr != NULL && pool != NULL && pool->pool != MAP_FAILED) {
        pthread_mutex_lock(&pool->lock);
        size_t index = (size_t)(ptr - pool->pool) / pool->block_size;
        pool->num_blocks++;
        pthread_mutex_unlock(&pool->lock);
    }
}

