    MEMORY_POOL* large_pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1024, 64);
    NFAPI_CRC_INDICATION_PDU_T* indications;

    if (small_pool == NULL || large_pool == NULL) {
        destroy_memory_pool(small_pool);
        destroy_memory_pool(large_pool);
        return NULL;
    }

    indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (indications == NULL) {
        destroy_memory_pool(small_pool);
        destroy_memory_pool(large_pool);
        return NULL;
    }

    int total_filled = 0;
    pthread_t threads[N];

    for (int i = 0; i < N; ++i) {
        pthread_create(&threads[i], NULL, process_pdu, &indications[total_filled]);
        total_filled++;
    }

    // Wait for all threads to finish
    for (int i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_memory_pool(small_pool);
    destroy_memory_pool(large_pool);
    free(indications);
    return indications;
}

void* process_pdu(void* pdu_ptr) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = pdu_ptr;

    if (validate_rx_ue_information(pdu)) {
        void* memory = NULL;
        size_t index = 0;

        // Tiered allocation strategy
        if ((index = find_first_empty_index(&indications, N)) == -1) {
            memory = memory_pool_alloc(small_pool);
        } else {
            memcpy(&indications[index], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }

        if (memory != NULL) {
            memcpy(memory, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }

    return NULL;
}

int find_first_empty_index(const NFAPI_CRC_INDICATION_PDU_T* indications, int size) {
    for (int i = 0; i < size; ++i) {
        if (!indications[i].present) {
            return i;
        }
    }
    return -1;
}
