void *custom_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL && LOGGING_ENABLED) {
        fprintf(stderr, "Memory allocation failed: %zu bytes\n", size);
    }
    return ptr;
}

void custom_free(void *ptr) {
