        fprintf(stdout, "Memory deallocation: %p\n", ptr);
    }
    free(ptr);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(size_t N) {
    if (N > MAX_ELEMENTS || N <= 0) {
        fprintf(stderr, "Invalid input size: %zu\n", N);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)custom_malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        return NULL;
