int read_from_file(struct external_data* data, RX_UE_INFORMATION_TAG* tag, RNTI* rnti) {
    char buffer[256];
    ssize_t bytes_read = read(data->fd, buffer, sizeof(buffer));
    if (bytes_read < 0) return -1; // Error reading file
    if (sscanf(buffer, "%d %d", tag, rnti) != 2) {
        if (--MAX_TRIES > 0) {
            usleep(100000); // Retry after a short delay
