#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <cstdlib>
#include <iterator>
#include <chrono>
#include <system_error>
#include <stdexcept>
#include <format>
#include <iomanip>

class CsvProcessor {
public:
    void process(const std::string& filename) {
        auto start = std::chrono::high_resolution_clock::now();

        std::ifstream file(filename);
        if (!file.is_open()) {
            throw std::system_error(errno, std::generic_category(), "Failed to open the CSV file: " + filename);
        }

        std::string line;
        size_t line_number = 0;
        while (std::getline(file, line)) {
            ++line_number;
            processLine(line);
        }

        auto duration = std::chrono::high_resolution_clock::now() - start;
        std::cout << "Processing time: " << std::chrono::duration_cast<std::chrono::milliseconds>(duration).count() << " ms" << std::endl;
    }

private:
    void processLine(const std::string& line) {
        std::istringstream iss(line);
        std::vector<std::string> tokens;
        std::copy(std::istream_iterator<std::string>(iss), std::istream_iterator<std::string>(), std::back_inserter(tokens));

        if (tokens.size() < 3) {
            logError("Invalid number of fields in line " + std::to_string(line_number));
            return;
        }

        int integer = -1;
        float floatValue = 0.0f;

        try {
            integer = std::stoi(tokens[0]);
            if (std::stof(tokens[1]).exceptions() & std::ios_base::failbit) {
                logError("Invalid float value in line " + std::to_string(line_number));
                return;
            }
            floatValue = std::stof(tokens[1]);
        } catch (const std::invalid_argument& e) {
            logError("Invalid data type in line " + std::to_string(line_number) + ": " + e.what());
            return;
        }

        if (missingValueChecker(tokens[2])) {
            logWarning("Missing value detected in line " + std::to_string(line_number));
            return;
        }

        integers_.push_back(integer);
        floats_.push_back(floatValue);
    }

    void logError(const std::string& message) {
        std::cerr << "[ERROR] " << message << std::endl;
    }

    void logWarning(const std::string& message) {
        std::cout << "[WARNING] " << message << std::endl;
    }

    bool missingValueChecker(const std::string& value) const {
        return value.empty() || (value == "?") || (value == "-");
    }

    std::vector<int> integers_;
    std::vector<float> floats_;
};

void printSummaryReport(const std::vector<int>& integers, const std::vector<float>& floats) {
    auto totalIntegers = std::accumulate(integers.begin(), integers.end(), 0);
    auto averageIntegers = static_cast<double>(totalIntegers) / integers.size();

    auto totalFloats = std::accumulate(floats.begin(), floats.end(), 0.0f);
    auto averageFloats = static_cast<double>(totalFloats) / floats.size();

    for (size_t i = 0; i < integers.size() && i < floats.size(); ++i) {
        std::cout << "Line " << i + 1 << ": ";
        std::cout << "Int: " << integers[i] << ", Float: " << floats[i] << ", AvgInt: " << averageIntegers << ", AvgFloat: " << averageFloats << std::endl;
    }

    std::cout << "\nOverall Totals:" << std::endl;
    std::cout << "Total integers: " << totalIntegers << ", Average int: " << averageIntegers << std::endl;
    std::cout << "Total floats: " << totalFloats << ", Average float: " << averageFloats << std::endl;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <csv_file>" << std::endl;
        return EXIT_FAILURE;
    }

    CsvProcessor processor;
    processor.process(argv[1]);
    printSummaryReport(processor.integers_, processor.floats_);
    return EXIT_SUCCESS;
}
```

