typedef enum { LINE_COUNT, CHAR_COUNT } line_type;

int main(int argc, char *argv[]) {
    int opt = 0;
    const char* input_file = NULL;
    const char* output_file = NULL;
    line_type count_type = LINE_COUNT;

    static struct option long_options[] = {
        {"help", no_argument, NULL, 'h'},
        {"count-chars", no_argument, NULL, 'c'},
        {"output", required_argument, NULL, 'o'},
        {NULL, 0, NULL, 0}
    };

    while ((opt = getopt_long(argc, argv, "hcc:o:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                usage();
                return 0;
            case 'c':
                count_type = CHAR_COUNT;
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                usage();
        }
    }

    if (!input_file) {
        fprintf(stderr, "Error: No input file specified.\n");
        usage();
    }

    FILE* fp = fopen(input_file, "r");
    if (!fp) {
        perror("Error opening the input file.");
        return 1;
    }

    long total = 0;
    char c;
    size_t lines = 0;

    while ((c = fgetc(fp)) != EOF) {
        if (count_type == CHAR_COUNT) {
            total++;
        } else {
            lines++;
            if (total > UINT32_MAX) {
                fprintf(stderr, "Error: Large file encountered. Cannot process more than %u characters per line.\n", UINT32_MAX);
                return 1;
            }
            total = 0;
        }
    }

    if (count_type == CHAR_COUNT) {
        if (output_file) {
            FILE* ofp = fopen(output_file, "w");
            if (!ofp) {
                perror("Error opening the output file.");
                return 1;
            }

            fprintf(ofp, "%lu\n", total);
            fclose(ofp);
        } else {
            printf("%lu\n", total);
        }
    } else {
        if (output_file) {
            FILE* ofp = fopen(output_file, "w");
            if (!ofp) {
                perror("Error opening the output file.");
                return 1;
            }

            fprintf(ofp, "%lu\n", lines);
            fclose(ofp);
        } else {
            printf("%lu\n", lines);
        }
    }

    fclose(fp);
    return 0;
}

void usage() {
    printf("Usage: %s [options] <input_file>\n", argv[0]);
    printf("\nOptions:\n");
    printf("-h, --help           Display this help message.\n");
    printf("-c, --count-chars    Count characters instead of lines.\n");
    printf("-o, --output=FILE    Save the results to a specified file.\n");
}
