typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ELEMENTS 10000
#define MEMORY_POOL_SIZE (MAX_ELEMENTS * 2)

NFAPI_CRC_INDICATION_PDU_T* memory_pool = NULL;
size_t pool_used = 0, pool_free = MEMORY_POOL_SIZE;
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indications(size_t N) {
    pthread_mutex_lock(&pool_mutex);
    if (N <= pool_free) {
        size_t elements = N;
        void* start = memory_pool + pool_used;
        memory_pool += elements;
        pool_used += elements;
        pool_free -= elements;
        pthread_mutex_unlock(&pool_mutex);
        return (NFAPI_CRC_INDICATION_PDU_T*)start;
    } else {
        pthread_mutex_unlock(&pool_mutex);
        NFAPI_CRC_INDICATION_PDU_T* new_memory = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
        if (!new_memory) {
            perror("malloc");
            return NULL;
        }
        memset(new_memory, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
        return new_memory;
    }
}

