    int capacity;
};

void* memoryPoolInit(int capacity) {
    struct MemoryPool* pool = (struct MemoryPool*)malloc(sizeof(struct MemoryPool));
    pool->freeList = NULL;
    pool->capacity = capacity;
    return pool;
}

Transaction_Record* memoryPoolPop(struct MemoryPool* pool) {
    if (!pool->freeList) return malloc(sizeof(Transaction_Record));
    Transaction_Record* record = pool->freeList;
    pool->freeList = record->transactionID == 0 ? pool->freeList : record;
    return record;
}

void memoryPoolPush(struct MemoryPool* pool, Transaction_Record* record) {
    record->transactionID = 0;
    if (pool->freeList) {
        record->next = pool->freeList;
        pool->freeList = record;
    } else {
        pool->freeList = record;
    }
}

void logInvalidTransaction(long amount) {
    // Logging implementation goes here
}

void processTransactions(FILE* file, struct MemoryPool* memoryPool, int maxAmount) {
    Transaction_Record* currentTransaction = NULL;
    Transaction_Record previousTransactions[5] = {0};
    int transactionCount = 0;

    while (fread(&currentTransaction, sizeof(Transaction_Record), 1, file)) {
        if (!maxAmount || currentTransaction->amount <= maxAmount && currentTransaction->amount >= -maxAmount) {
            currentTransaction->transactionID = transactionCount++;
            previousTransactions[transactionCount % 5] = *currentTransaction;
            long sum = (transactionCount > 5) ? sumOfPreviousTransactions(previousTransactions, transactionCount) : 0;
            currentTransaction->sum = sum;
            printJson(currentTransaction);
        } else {
            logInvalidTransaction(currentTransaction->amount);
        }
        memoryPoolPush(memoryPool, currentTransaction);
    }
}

