struct list {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    sem_t sem;
    pthread_mutex_t lock;
};

void compress(const unsigned char* src, size_t length, unsigned char* dest) {
    z_stream strm;
    memset(&strm, 0, sizeof(z_stream));
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    deflateInit(&strm, Z_DEFAULT_COMPRESSION);
    strm.next_in = src;
    strm.avail_in = length;
    char* dest_ptr = dest;
    size_t totalOut = 0;
    unsigned have = 0;

    while (strm.avail_in && (strm.avail_out >= 65535 || strm.total_out <= 65535 - length)) {
        strm.next_out = dest_ptr;
        strm.avail_out = 65535 - (strm.total_out + have);
        deflate(&strm, Z_NO_FLUSH);
        totalOut += (strm.total_out + have);
        have = 0;
        dest_ptr += strm.total_out;
        strm.avail_in -= strm.total_out;
    }
    deflateEnd(&strm);
}

unsigned char* serialize(struct list* list) {
    size_t totalSize = 0;
    for (size_t i = 0; i < list->size; ++i) {
        const NFAPI_CRC_INDICATION_PDU_T* item = &(list->data[i]);
        totalSize += sizeof(RX_UE_INFORMATION_TAG) + sizeof(RNTI) + sizeof(CRC_INDICATION_REL8_TAG);
    }
    unsigned char* buffer = mmap(NULL, totalSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    char* ptr = buffer;

    for (size_t i = 0; i < list->size; ++i) {
        const NFAPI_CRC_INDICATION_PDU_T* item = &(list->data[i]);
        memcpy(ptr, &item->ue_information, sizeof(RX_UE_INFORMATION_TAG));
        ptr += sizeof(RX_UE_INFORMATION_TAG);
        memcpy(ptr, &item->rnti, sizeof(RNTI));
        ptr += sizeof(RNTI);
        item->crc_indication.crcflag = rand();
        memcpy(ptr, &item->crc_indication, sizeof(CRC_INDICATION_REL8_TAG));
        ptr += sizeof(CRC_INDICATION_REL8_TAG);
    }

    compress(buffer, totalSize, buffer);

    return buffer;
}

struct list* init_and_populate_crc_indications() {
    struct list* list = malloc(sizeof(struct list));
    if (!list) return NULL;

    list->data = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
