#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#define MAX_FRAMES 10000 // Maximum number of frames allowed
#define MIN_TX_POWER -87 // Minimum TX Power Level
#define MAX_TX_POWER 23 // Maximum TX Power Level
#define MIN_SINR 0.0     // Minimum SINR
#define MAX_MCS 15      // Maximum MCS

typedef struct {
    uint8_t TX_POWER_LEVEL;
    float SINR;
    uint8_t MCS;
} PHY_LAYER_FRAME_INFO;

sem_t frame_mutex;          // Semaphore for thread safety
uint32_t allocated_frames = 0; // Counter for number of allocated frames
pthread_mutex_t resource_mutex; // Mutex for resource monitoring and adaptation

PHY_LAYER_FRAME_INFO* create_frame(uint32_t index) {
    PHY_LAYER_FRAME_INFO *frame = (PHY_LAYER_FRAME_INFO *)calloc(1, sizeof(PHY_LAYER_FRAME_INFO));
    if (!frame) {
        fprintf(stderr, "Error: Failed to allocate memory for frame %d\n", index);
        return NULL;
    }

    sem_wait(&frame_mutex); // Lock the frame mutex
    if (index >= MAX_FRAMES || allocated_frames >= MAX_FRAMES) {
        fprintf(stderr, "Error: Maximum number of frames reached\n");
        free(frame);
        sem_post(&frame_mutex); // Unlock the frame mutex
        return NULL;
    }
    allocated_frames++;
    sem_post(&frame_mutex); // Unlock the frame mutex

    if (frame->TX_POWER_LEVEL < MIN_TX_POWER || frame->TX_POWER_LEVEL > MAX_TX_POWER ||
        frame->SINR < MIN_SINR || frame->MCS < 0 || frame->MCS > MAX_MCS) {
        fprintf(stderr, "Error: Invalid data input for frame %d\n", index);
        free(frame);
        return NULL;
    }

    return frame;
}

void destroy_frames() {
    PHY_LAYER_FRAME_INFO *frame;
    pthread_mutex_lock(&resource_mutex);
    for (uint32_t i = 0; i < allocated_frames; ++i) {
        frame = (PHY_LAYER_FRAME_INFO *)calloc(1, sizeof(PHY_LAYER_FRAME_INFO));
        if (!frame) {
            fprintf(stderr, "Error: Failed to allocate temporary memory for freeing frames\n");
            pthread_mutex_unlock(&resource_mutex);
            return;
        }
        frame = (PHY_LAYER_FRAME_INFO *)malloc(allocated_frames * sizeof(PHY_LAYER_FRAME_INFO));
        if (!frame) {
            fprintf(stderr, "Error: Failed to allocate memory for freeing all frames\n");
            free(frame);
            pthread_mutex_unlock(&resource_mutex);
            return;
