    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRCI_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    size_t size;
    NFAPI_CRCI_PDU_T* array;
} PDU_POOL;

void pdu_pool_init(PDU_POOL* pool, size_t size) {
    pool->size = size;
    pool->array = malloc(sizeof(NFAPI_CRCI_PDU_T) * size);
    if (!pool->array) {
        fprintf(stderr, "Error: Failed to allocate memory for PDU pool.\n");
        exit(1);
    }
    memset(pool->array, 0, sizeof(NFAPI_CRCI_PDU_T) * size);
    pthread_mutex_init(&pool->lock, NULL);
}

void* pdu_generator(void* arg) {
    PDU_POOL* pool = (PDU_Pool*)arg;
    for (size_t i = 0; i < pool->size; ++i) {
        pthread_mutex_lock(&pool->lock);
        while (pool->array[i].RX_UE_INFORMATION_TAG != 0) {
            pthread_mutex_unlock(&pool->lock);
            sched_yield();
            pthread_mutex_lock(&pool->lock);
        }
        pool->array[i].RX_UE_INFORMATION_TAG = i;
        pool->array[i].RNTI = rand() % 0xFFFF + 1;
        pool->array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
        pool->array[i].CRCFLAG = rand() % 2;
        pthread_mutex_unlock(&pool->lock);
    }
    return NULL;
}

void generate_pdus(PDU_POOL* pool, size_t n) {
    if (n > pool->size) {
        fprintf(stderr, "Error: Requested number of PDUs exceeds pool size.\n");
        exit(1);
    }
    pthread_t threads[n];
    for (size_t i = 0; i < n; ++i) {
        pthread_create(&threads[i], NULL, pdu_generator, pool);
    }
    for (size_t i = 0; i < n; ++i) {
        pthread_join(threads[i], NULL);
    }
}
```

