#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    in_port_t tcp_connection_id;
    struct sockaddr_in source_ip;
    struct sockaddr_in destination_ip;
    int syn_flag;
    uint16_t sequence_number;
    uint16_t acknowledgment_number;
} TCP_CONNECTION_INFO;

typedef struct thread_data {
    TCP_CONNECTION_INFO* connections;
    size_t num_connections;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
} THREAD_DATA;

TCP_CONNECTION_INFO* create_connection(void) {
    TCP_CONNECTION_INFO* connection = malloc(sizeof(TCP_CONNECTION_INFO));
    if (!connection) {
        fprintf(stderr, "Error: Failed to allocate memory for new TCP_CONNECTION_INFO\n");
        return NULL;
    }

    memset(connection, 0, sizeof(TCP_CONNECTION_INFO));

    connection->tcp_connection_id = rand() % 65536;
    connection->source_ip.sin_addr.s_addr = htonl(rand() >> 16 | 0x7f000000); // Random source IP within the private address space (RFC 1918)
    connection->destination_ip.sin_addr.s_addr = htonl(rand() >> 24 | 0x7f000001); // Random destination IP within the public address space
    connection->syn_flag = rand() % 2;
    connection->sequence_number = rand() % 65536;
    connection->acknowledgment_number = rand() % 65536;

    return connection;
}

void delete_connection(TCP_CONNECTION_INFO* connection) {
    free(connection);
}

void lock(THREAD_DATA* data) {
    pthread_mutex_lock(&data->mutex);
}

void unlock(THREAD_DATA* data) {
    pthread_mutex_unlock(&data->mutex);
}

void notify(THREAD_DATA* data) {
    pthread_cond_signal(&data->cond_var);
}

void wait(THREAD_DATA* data) {
    pthread_cond_wait(&data->cond_var, &data->mutex);
}

TCP_CONNECTION_INFO** generate_connections(size_t num_connections) {
    TCP_CONNECTION_INFO** connections = calloc(num_connections, sizeof(TCP_CONNECTION_INFO*));
    THREAD_DATA data;

    if (!connections) {
        fprintf(stderr, "Error: Failed to allocate memory for connection array\n");
        return NULL;
    }

    data.connections = connections;
    data.num_connections = num_connections;
    pthread_mutex_init(&data.mutex, NULL);
    pthread_cond_init(&data.cond_var, NULL);

    for (size_t i = 0; i < num_connections; ++i) {
        lock(&data);
        while (data.num_connections > 0 && connections[data.num_connections - 1] != NULL) {
            wait(&data);
        }
        if (data.num_connections == num_connections) {
            unlock(&data);
            break;
        }

        TCP_CONNECTION_INFO* connection = create_connection();
        if (!connection) {
            fprintf(stderr, "Error: Failed to allocate memory for new TCP_CONNECTION_INFO\n");
            return NULL;
        }
        connections[data.num_connections++] = connection;
        unlock(&data);
    }

    pthread_mutex_destroy(&data.mutex);
    pthread_cond_destroy(&data.cond_var);

    return connections;
}
