#include <sys/mman.h>
#include <semaphore.h>

// Define structures and constants
struct TCP_CONNECTION_INFO {
    uint32_t id;
    struct sockaddr_in src, dest;
    bool syn_flag;
    uint16_t seq, ack;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t tag;
    uint16_t rnti;
    struct CRC_INDICATION_REL8_TAG crc;
};

#define MAX_SIZE 10000000
#define MIN_SIZE 0
#define BUFFER_SIZE (4 * sizeof(struct TCP_CONNECTION_INFO) + sizeof(struct NFAPI_CRC_INDICATION_PDU_T))
#define LOCK_COUNT 4

typedef struct {
    void* buffer;
    size_t capacity;
    size_t count;
    pthread_mutex_t locks[LOCK_COUNT];
    sem_t sem_prod, sem_cons;
} data_pool_t;

data_pool_t* init_data_pool(size_t size) {
    if (size < MIN_SIZE || size > MAX_SIZE) {
        fprintf(stderr, "Error: Invalid pool size\n");
        return NULL;
    }

    data_pool_t* pool = malloc(sizeof(data_pool_t));
    if (!pool) {
        perror("Error: Memory allocation failure");
        return NULL;
    }

    pool->buffer = mmap(NULL, BUFFER_SIZE * size, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (pool->buffer == MAP_FAILED) {
        perror("Error: Memory mapping failure");
        free(pool);
        return NULL;
    }

    pool->capacity = size;
    pool->count = 0;
    for (size_t i = 0; i < LOCK_COUNT; ++i) {
        if (pthread_mutex_init(&pool->locks[i], NULL)) {
            perror("Error: Mutex initialization failure");
            munmap(pool->buffer, BUFFER_SIZE * size);
            free(pool);
            return NULL;
        }
    }
    sem_init(&pool->sem_prod, 0, LOCK_COUNT);
    sem_init(&pool->sem_cons, 0, 0);

    return pool;
}

void* get_data(data_pool_t* pool) {
    void* data = NULL;
    pthread_mutex_lock(&pool->locks[pool->count % LOCK_COUNT]);
    if (pool->count < pool->capacity) {
        data = ((char*)pool->buffer + BUFFER_SIZE * pool->count);
        memset(data, 0, BUFFER_SIZE);
        ++pool->count;
        sem_post(&pool->sem_prod);
    }
    pthread_mutex_unlock(&pool->locks[pool->count % LOCK_COUNT]);
    return data;
}

void put_data(data_pool_t* pool, void* data) {
    sem_wait(&pool->sem_cons);
    pthread_mutex_lock(&pool->locks[(pool->count - 1) % LOCK_COUNT]);
    // Fill in TCP_CONNECTION_INFO and NFAPI_CRC_INDICATION_PDU_T structures here
    ++pool->count;
    sem_post(&pool->sem_prod);
    pthread_mutex_unlock(&pool->locks[(pool->count - 1) % LOCK_COUNT]);
}

void destroy_data_pool(data_pool_t* pool) {
    munmap(pool->buffer, BUFFER_SIZE * pool->capacity);
    for (size_t i = 0; i < LOCK_COUNT; ++i) {
        pthread_mutex_destroy(&pool->locks[i]);
    }
    sem_destroy(&pool->sem_prod);
    sem_destroy(&pool->sem_cons);
    free(pool);
}
