                    return -1;
                }
                break;
            default:
                usage(argv[0]);
                return -1;
        }
    }

    struct NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(MAX_UE * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    size_t pdu_count = 0;

    if (process_ue(input_file, &pdus, &pdu_count) != 0) return -1;

