#include <zlib/zlib.h>

class Node {
public:
    int key;
    long value;
    std::unique_ptr<Node> next, prev;

    Node(int key, long value) : key(key), value(value) {}
};

class RAN {
public:
    boost::circular_buffer<NFAPI_CRC_INDICATION_PDU_T> pduBuffer;
    std::deque<std::unique_ptr<Node>> nodes;
    std::mutex mtx;

    void add_node(int key, long value) {
        std::unique_ptr<Node> node = std::make_unique<Node>(key, value);
        std::unique_lock<std::mutex> lock(mtx);
        if (nodes.empty()) {
            node->next = node;
            node->prev = node;
            nodes.push_back(std::move(node));
        } else {
            auto it = nodes.begin();
            while (it != --nodes.end() && it->key < key) ++it;
            node->next = it->next.get();
            node->prev = it.get();
            if (it == nodes.begin()) {
                nodes.push_back(std::move(node));
                nodes.front()->prev = node.get();
            } else {
                it->next = std::move(node);
            }
        }
    }

    // Other functions for managing RAN, such as remove_node, serialize, deserialize etc.
};

std::vector<RAN> manage_rans(int numRans) {
    std::vector<RAN> rans(numRans);
    std::default_random_engine generator;
    std::uniform_int_distribution<> distribution(1, 10000);

