void* process_file(void* arg) {
    // Cast the argument to thread_data_t* and access thread-specific data
    thread_data_t* td = (thread_data_t*)arg;

    pthread_mutex_lock(&td->mutex);

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(td->line_len * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        // Handle memory allocation error
        pthread_mutex_unlock(&td->mutex);
        return NULL;
    }

    size_t index = 0;
    char* token = strtok(td->line_buf, "\n");
    while (token) {
        sscanf(token, "%hhu %hhu", &pdus[index].rx_ue_information_tag, &pdus[index].rnti);
        if (!validate_data(pdus[index].rx_ue_information_tag, pdus[index].rnti)) {
            // Handle validation failure
            free(pdus);
            pthread_mutex_unlock(&td->mutex);
            return NULL;
        }

        pdus[index].crc_indication_rel8_tag = (pdus[index].rx_ue_information_tag + pdus[index].rnti) & 0xFFFF; // Calculate CRC_INDICATION_REL8_TAG

        token = strtok(NULL, "\n");
        index++;
    }
    free(td->line_buf);

    pthread_mutex_unlock(&td->mutex);

