}

void read_and_process_file(const char* file_path) {
    FILE* fp = fopen(file_path, "r");
    if (!fp) {
        // Handle file open error
        return;
    }

    fseek(fp, 0, SEEK_END);
    size_t file_size = ftell(fp);
    rewind(fp);

    thread_data_t* td = malloc(sizeof(thread_data_t));
    if (!td) {
        // Handle memory allocation error
        fclose(fp);
        return;
    }

    td->file = fp;
    td->line_len = (size_t)(file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)) + 1; // Account for the last line that may have fewer PDUs than others
    td->line_buf = malloc(td->line_len * sizeof(char));
    if (!td->line_buf) {
        // Handle memory allocation error
        fclose(fp);
        free(td);
        return;
    }

    pthread_mutex_init(&td->mutex, NULL);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_file, td) != 0) {
        // Handle thread creation error
        free(td->line_buf);
        fclose(fp);
        free(td);
        return;
    }

    char buffer[4096];
    size_t bytes_read = fread(buffer, 1, sizeof(buffer), fp);
    while (bytes_read > 0) {
        memcpy(td->line_buf + td->line_len - bytes_read, buffer, bytes_read);
        bytes_read = fread(buffer, 1, sizeof(buffer), fp);
    }

    if (pthread_join(thread_id, NULL) != 0) {
        // Handle thread join error
        free(td->line_buf);
        fclose(fp);
        free(td);
        return;
    }

    fclose(fp);
    free(td->line_buf);
    free(td);
}
