    for (int i = 0; i < line->len; ++i) {
        if (!is_number((unsigned char)line->data[i])) {
            log(message);
            break;
        }

        sum += line->data[i];
        count++;

        if (count >= 3) {
            int avg = (sum - line->data[i]) / (count - 1);
            line->data[i] = avg;
        }
    }
