    EventNotification* event = malloc(sizeof(EventNotification));
    if (!event) {
        log("Failed to allocate memory for event.");
        return NULL;
    }

    memset(event, 0, sizeof(EventNotification));
    return event;
}

Pool* create_pool(size_t capacity) {
    Pool* pool = malloc(sizeof(Pool));
    if (!pool) {
        log("Failed to allocate memory for pool.");
        return NULL;
    }

    pool->events = calloc(capacity, sizeof(EventNotification*));
    if (!pool->events) {
        free(pool);
        log("Failed to allocate memory for pool's events array.");
        return NULL;
    }

    pool->capacity = capacity;
    pool->size = 0;
    sem_init(&pool->lock, 0, 1);

    return pool;
}

void destroy_pool(Pool* pool) {
    if (pool) {
        for (size_t i = 0; i < pool->capacity; ++i) {
            if (pool->events[i]) {
                free(pool->events[i]);
            }
        }
        free(pool->events);
        sem_destroy(&pool->lock);
        free(pool);
    }
}

void* read_and_process_file(const char* filepath, Pool* pool, IdPool* id_pool) {
    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        log(sprintf("Failed to open file: %s", filepath));
        return NULL;
    }

    char buffer[4096];
    ssize_t bytes_read;
    EventNotification* event = create_event();
    if (!event) {
        close(fd);
        return NULL;
    }

    while ((bytes_read = read(fd, buffer, sizeof(buffer))) > 0) {
        char* token = strtok(buffer, " \t\n");
        size_t count = 0;

        event->id = -1;
        event->timestamp = time(NULL);
        event->data_type = INT;

        while (token) {
            if (event->size >= ARRAY_SIZE(event->value)) {
                log("Exceeded maximum number of values for a line.");
                break;
            }

            double value = atof(token);
            if (!isfinite(value)) {
                log(sprintf("Invalid numerical value: %s", token));
                continue;
            }

            if (count == 0) {
                event->id = pthread_mach_time() * gettid(); // Generate a unique identifier.
            } else if (count >= 3 && count < event->size + 3) {
                if (event->data_type != FLOAT && value > 100 || event->data_type == FLOAT && value > 100 * 100) {
                    log(sprintf("Value %s exceeded the specified range for data type: %s", token, (event->data_type == INT) ? "INT" : "FLOAT"));
                } else {
                    event->value[count - 3] = value;
                }
            }

            if (event->data_type == INT && value < 0 || event->data_type == FLOAT && !isnormal(value)) {
                log("Invalid numerical value.");
                break;
            }

            event->size++;
            event->data_type = (count > 0) ? event->data_type : INT; // Set the data type to the one used for the first non-empty token.
            count++;
            token = strtok(NULL, " \t\n");
        }

        if (count >= 3 && event->size > 2) {
            double average = 0;
            for (size_t i = event->size - 4; i < event->size - 1; ++i) {
                average += event->value[i];
            }
            average /= (event->size - 3);

            event->value[event->size - 1] = average;
        }

        if (!sem_trywait(&pool->lock)) {
            sem_post(&pool->lock); // Release the lock and try again later.
            continue;
        }

        if (pool->size == pool->capacity) {
            sem_post(&pool->lock); // Release the lock and try again later.
            break;
        }

        pool->events[pool->size++] = event;
        sem_post(&pool->lock);
    }

    close(fd);
    free(event);
    return NULL;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        log("Usage: ./program input_file1 [input_file2 ...]");
        return EXIT_FAILURE;
    }

    Pool* pool = create_pool(NUM_THREADS * 2); // Assume a constant number of threads.
    if (!pool) {
        log("Failed to allocate memory for the event pool.");
        return EXIT_FAILURE;
    }

    IdPool id_pool = { MIN_ID_POOL_SIZE, MAX_DUPLICATES };
    // Initialize the id pool.

    pthread_t threads[NUM_THREADS];

    for (size_t i = 1; i < argc; ++i) {
        if (!read_and_process_file(argv[i], pool, &id_pool)) {
            return EXIT_FAILURE;
        }
    }

    destroy_pool(pool);
    return EXIT_SUCCESS;
}
