#include <string.h>
#include <getopt.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <inttypes.h>

static const char *usage = "Usage: program [options] input_file\n"
                           "\n"
                           "Options:\n"
                           "  -h, --help             Display this help and exit.\n"
                           "  --manpage              Display detailed documentation.\n"
                           "  -c, --count             Print the total number of characters across all lines in input_file.\n"
                           "  -s, --stats              Provide statistical information about the file content.\n"
                           "  -o, --output=OUTPUT     Specify an output file where results should be written instead of printed to standard output.\n";

static const struct option long_options[] = {
    {"help", no_argument, nullptr, 'h'},
    {"manpage", no_argument, nullptr, 'M'},
    {"count", no_argument, nullptr, 'c'},
    {"stats", no_argument, nullptr, 's'},
    {"output", required_argument, nullptr, 'o'},
    {0, 0, 0, 0}
};

int main(int argc, char *argv[]) {
    int opt;
    FILE *input_file = stdin;
    FILE *output_file = stdout;
    bool count = false, stats = false, manpage = false;

    while ((opt = getopt_long(argc, argv, "hMcso:", long_options, nullptr)) != -1) {
        switch (opt) {
            case 'h':
                printf("%s", usage);
                return EXIT_SUCCESS;
            case 'M':
                manpage = true;
                break;
            case 'c':
                count = true;
                break;
            case 's':
                stats = true;
                break;
            case 'o':
                output_file = fopen(optarg, "w");
                if (!output_file) {
                    fprintf(stderr, "Error: Unable to open output file '%s'\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            default:
                printf("%s", usage);
                return EXIT_FAILURE;
        }
    }

    if (argc - optind > 1) {
        fprintf(stderr, "Error: Too many non-option arguments.\n");
        return EXIT_FAILURE;
    }

    char *input_filename = argv[optind];
    struct stat file_stat;

    if (stat(input_filename, &file_stat) == -1) {
        fprintf(stderr, "Error: Unable to access input file '%s'\n", input_filename);
        return EXIT_FAILURE;
    }

    if (!S_ISREG(file_stat.st_mode)) {
        fprintf(stderr, "Error: Input file '%s' is not a regular file.\n", input_filename);
        return EXIT_FAILURE;
    }

    int fd = open(input_filename, O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Error: Unable to open input file '%s'\n", input_filename);
        return EXIT_FAILURE;
    }

    char buffer[4096];
    size_t lines = 0;
    uintmax_t chars = 0, max_line_length = 0, words = 0, avg_line_length = 0, total_words = 0;

    while (ssize_t read_bytes = read(fd, buffer, sizeof(buffer))) {
        if (read_bytes == -1 && errno != EINTR) {
            fprintf(stderr, "Error: Read error from input file '%s'\n", input_filename);
            close(fd);
            return EXIT_FAILURE;
        }

        for (size_t i = 0; i < read_bytes; ++i) {
            chars++;
            if (buffer[i] == '\n') {
                lines++;
                words = 0;
                avg_line_length = (lines > 0) ? (uintmax_t)(chars - total_words) / lines : 0;
                max_line_length = (chars > max_line_length) ? chars : max_line_length;
                total_words += words;
                chars = 0;
            } else if (buffer[i] == ' ') {
                words++;
            }
        }
    }

    close(fd);

    if (!count && !stats) {
        fprintf(output_file, "%" PRIuMAX "\n", lines);
    } else if (count) {
        fprintf(output_file, "%" PRIuMAX "\n", chars);
    } else {
        fprintf(output_file, "Lines: %" PRIuMAX "\nWords: %" PRIuMAX "\nAvg Line Length: %.2f\nMax Line Length: %" PRIuMAX "\n",
                lines, total_words, avg_line_length > 0 ? (double)avg_line_length : 0.0, max_line_length);
    }

    if (manpage) {
        // Implement detailed documentation here.
    }

    return EXIT_SUCCESS;
}
