    memset(&up, 0, sizeof(UserProfile));

    char sql[256];
    snprintf(sql, sizeof(sql), "SELECT * FROM user_profiles WHERE email='%s';", email);

    sqlite3_stmt *stmt;
    int rc = sqlite3_prepare_v2(db, sql, -1, &stmt, 0);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
        return up;
    }

    rc = sqlite3_step(stmt);

    if (rc == SQLITE_ROW) {
        strcpy(up.name, (char *)sqlite3_column_text(stmt, 1));
        strcpy(up.email, email);
        strcpy(up.phone, (char *)sqlite3_column_text(stmt, 2));
    }

    sqlite3_finalize(stmt);

    return up;
}

