static pthread_mutex_t id_pool = PTHREAD_MUTEX_INITIALIZER;
static size_t id_pool_size = 1024;
static size_t max_duplicates = 64;
static size_t id_counter = 0;

void initialize_config_settings(size_t N) {
    CONFIG_SETTING_T* settings = malloc(sizeof(CONFIG_SETTING_T) * N);
    if (!settings) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&id_pool);
        while (id_counter >= id_pool_size || get_duplicates(settings, id_counter) >= max_duplicates) {
            id_pool_size *= 2;
            resize_id_pool();
        }
        snprintf(settings[i].id, sizeof(settings[i].id), "%lu", id_counter++);
        settings[i].timestamp = time(NULL);
        settings[i].payload = NULL;
        settings[i].avg_timestamp = 0.0;
        pthread_mutex_unlock(&id_pool);
