void process_line(char *line, size_t line_len) {
    char *token;
    int values[MAX_VALUES];
    int num_values = 0;
    for (int i = 0; i < line_len; ++i) {
        if ((token = strchr(line + i, ' ')) != NULL) {
            *token++ = '\0';
            validate_number(atoi(line + i), 0, 100);
            values[num_values++] = atoi(line + i);
        }
    }

    double average;
    if (num_values >= 3) {
        average = (double)((values[num_values - 3] + values[num_values - 2] + values[num_values - 1]) / 3);
        values[num_values++] = average;
    }

    char *modified_line = malloc(sizeof(char) * (num_values + 1));
    sprintf(modified_line, "%d", values[0]);
    for (int i = 1; i < num_values; ++i) {
        strcat(modified_line, ", ");
        sprintf(modified_line + strlen(modified_line), "%d", values[i]);
    }

    printf("%s\n", modified_line);
    free(modified_line);
}

void* read_and_process(void *arg) {
    char line[MAX_LINE_LENGTH];
    size_t line_len;
    int fd = *(int *) arg;

    while ((line_len = read(fd, line, sizeof(line))) > 0) {
        process_line(line, line_len);
    }

    close(fd);
    free(arg);
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        log("Usage: %s <file_path>", argv[0]);
        return 1;
    }

    sem_init(&event_id_lock, 0, 1);

    int files_count = argc - 1;
    pthread_t *threads = malloc(sizeof(pthread_t) * files_count);
    for (int i = 1; i <= files_count; ++i) {
        int *arg = malloc(sizeof(int));
        *arg = open(argv[i], O_RDONLY);
        pthread_create(&threads[i - 1], NULL, read_and_process, arg);
    }

    for (int i = 0; i < files_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&event_id_lock);
    free(threads);
    return 0;
}

CRC_INDICATION_PDU_T* allocate_PDUs(int N) {
    CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        log("Memory allocation failed for %d PDUs", N);
        return NULL;
    }
