3. Implement the `load_bundle()` function as specified:

```c
void load_bundle(const char* path, BundleItem** items, size_t* count) {
    FILE *file = fopen(path, "rb");
    if (!file) {
        perror("Error opening file");
        return;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    *count = file_size / (sizeof(BundleItem) + sizeof(uint8_t));
    *items = malloc(*count * sizeof(BundleItem));

    if (!*items) {
        perror("Error allocating memory");
        fclose(file);
        return;
    }

    BundleItem* current_item = *items;
    size_t read = 0;

    while (read < file_size) {
        size_t read_this_time = fread(&current_item->type, sizeof(uint32_t), 1, file);
        if (read_this_time != 1) {
            perror("Error reading type");
            free(*items);
            fclose(file);
            return;
        }

        read += sizeof(uint32_t);
        read_this_time = fread(&current_item->length, sizeof(size_t), 1, file);
        if (read_this_time != 1) {
            perror("Error reading length");
            free(*items);
            fclose(file);
            return;
        }

        read += sizeof(size_t);
        current_item->data = malloc(current_item->length);
        if (!current_item->data) {
            perror("Error allocating memory for data");
            free(*items);
            fclose(file);
            return;
        }

        read += sizeof(size_t);
        size_t to_read = current_item->length - (file_offset(file) - read);
        if (to_read > 0) {
            read_this_time = fread(current_item->data, to_read, 1, file);
            if (read_this_time != 1) {
                perror("Error reading data");
                free(current_item->data);
                free(*items);
                fclose(file);
                return;
            }
        }

        current_item++;
    }

    fclose(file);
}
```

