struct memory_pool create_memory_pool(size_t capacity) {
    struct memory_pool pool;
    pool.capacity = capacity;
    pool.elements = malloc(sizeof(DATA_ELEMENT) * capacity);
    if (!pool.elements) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        exit(1);
    }
    pool.allocated = 0;
    return pool;
}

DATA_ELEMENT* allocate_data_element(struct memory_pool *pool) {
    if (pool->allocated >= pool->capacity) {
        pool->capacity *= 2;
        pool->elements = realloc(pool->elements, sizeof(DATA_ELEMENT) * pool->capacity);
        if (!pool->elements) {
            fprintf(stderr, "Failed to reallocate memory for the memory pool\n");
            exit(1);
        }
    }

    DATA_ELEMENT *element = &pool->elements[pool->allocated];
    element->power = 0;
    element->sequence_number = 0;
    element->channel = NULL;
    pool->allocated++;
    return element;
}

