    if (feof(fp)) {
        fclose(fp);
        return 0;
    }

    // Allocate memory for the bundle and its items dynamically
    MyResource* bundleItems = calloc(headerLength, sizeof(MyResource));
    if (!bundleItems) {
        fclose(fp);
        return 0;
    }

    size_t numItems = 0;
    for (size_t i = 0; i < headerLength; ++i) {
        uint16_t type, length;
        fread(&type, sizeof(uint16_t), 1, fp);
        if (feof(fp)) break;

        fread(&length, sizeof(uint16_t), 1, fp);
        if (feof(fp)) {
            fclose(fp);
            free(bundleItems);
            return numItems;
        }

        // Read the item data and set its type in bundleItems[i]
        // ...

        ++numItems;
    }

    *bundle = bundleItems;
    fclose(fp);
    return numItems;
}
