namespace fs = std::filesystem;
using namespace boost::program_options;

std::map<std::string, unsigned long> line_counts;
unsigned long total_lines = 0;
std::string output_file;
bool help, manpage, count, summarize, show_errors;

void process_file(const std::string& file) {
    std::ifstream inFile(file);
    if (!inFile.is_open()) {
        if (show_errors) {
            std::cerr << "Error: Cannot open file: " << file << std::endl;
        }
        return;
    }

    unsigned long lines_in_file = 0;
    std::string line;
    while (std::getline(inFile, line)) {
        ++lines_in_file;
        if (!count) total_lines += lines_in_file;
        if (count) line_counts[file] = lines_in_file;
    }

    if (summarize) total_lines += lines_in_file;
}

void* worker(void* arg) {
    auto file = static_cast<const std::string*>(arg);
    process_file(*file);
    return nullptr;
}

int main(int argc, char** argv) {
    options_description desc("Allowed options");
    desc.add_options()
        ("help", "Show this help message")
        ("manpage", "Show the man page")
        ("count,c", "Count lines in each file separately")
        ("summarize,s", "Summarize total lines across all files")
        ("output,o", value<std::string>(&output_file)->default_value("report.txt"), "Specify the output file for report generation")
        ;

    positional_options_description p;
    p.add("files...", -1);

    variables_map vm;
    store(parse_command_line(argc, argv, desc, p), vm);
    notify(vm);

    show_errors = !vm.count("help") && !vm.count("manpage");
    help = vm.count("help");
    manpage = vm.count("manpage");
    count = vm.count("count");
    summarize = vm.count("summarize");

    std::vector<std::thread> workers;
    std::vector<const char*> files;

    for (auto i = 0u; i < argc - p.positional().size(); ++i) {
        if (!fs::is_regular_file(argv[i])) {
            if (show_errors) {
                std::cerr << "Error: Invalid file path: " << argv[i] << std::endl;
            }
            continue;
        }
        files.push_back(argv[i]);
    }

    for (auto& file : files) {
        workers.emplace_back(worker, &file);
    }

    for (auto& thread : workers) {
        thread.join();
    }

    if (manpage) {
        std::cout << desc;
        return 0;
    }

    if (!help && output_file.empty()) output_file = "report.txt";

    if (!help && !output_file.empty()) {
        std::ofstream outFile(output_file);
        if (outFile.is_open()) {
            if (count) {
                for (auto& it : line_counts) {
                    outFile << it.first << ": " << it.second << "\n";
                }
            }

            if (summarize) {
                outFile << "Total lines: " << total_lines << "\n";
            }
        } else {
            std::cerr << "Error: Cannot open output file: " << output_file << std::endl;
        }
    }

    return 0;
}
