typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG cind_tag;
} NFAPI_CRC_INDICATION_PDU_T;

struct mem_pool_node {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct mem_pool_node *next;
};

typedef struct mem_pool_node MemPoolNode;

struct mem_pool {
    size_t capacity;
    size_t cur_size;
    MemPoolNode *head;
    pthread_mutex_t mutex;
    pthread_cond_t notempty;
};

void init_mem_pool(struct mem_pool *mp, size_t initial_capacity) {
    mp->capacity = initial_capacity;
    mp->cur_size = 0;
    mp->head = NULL;
    pthread_mutex_init(&mp->mutex, NULL);
    pthread_cond_init(&mp->notempty, NULL);
}

MemPoolNode* alloc_from_pool(struct mem_pool *mp) {
    MemPoolNode *node;

    if (mp->cur_size >= mp->capacity && mp->capacity != 0) {
        resize_mem_pool(mp, mp->capacity * 2);
    }

    pthread_mutex_lock(&mp->mutex);
    node = mp->head;
    if (node) {
        mp->head = node->next;
        mp->cur_size--;
    }
    pthread_mutex_unlock(&mp->mutex);

    return node;
}

void free_to_pool(struct mem_pool *mp, MemPoolNode *node) {
    pthread_mutex_lock(&mp->mutex);
    node->next = mp->head;
    mp->head = node;
    mp->cur_size++;
    pthread_cond_signal(&mp->notempty);
    pthread_mutex_unlock(&mp->mutex);
}

void resize_mem_pool(struct mem_pool *mp, size_t new_capacity) {
    MemPoolNode **current = &mp->head;
    MemPoolNode *temp;
    size_t i;

    for (i = mp->cur_size; i < new_capacity - 1; ++i) {
        temp = malloc(sizeof(MemPoolNode));
        if (!temp) {
            // Handle out-of-memory situation
        }
        temp->pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp->pdu) {
            // Handle out-of-memory situation
        }
        temp->next = NULL;
        *current = temp;
        current = &temp->next;
    }

    mp->capacity = new_capacity;
}

NFAPI_CRC_INDICATION_PDU_T* init_pdus(size_t N) {
    size_t i;
    struct mem_pool pdu_pool;
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;

    if (N <= 0) {
        // Handle negative or zero input, for example by returning a predefined empty array.
    }

    init_mem_pool(&pdu_pool, DEFAULT_MEM_POOL_SIZE);
    for (i = 0; i < N; ++i) {
        MemPoolNode *node = alloc_from_pool(&pdu_pool);
        if (!node) {
            // Handle out-of-memory situation
        }
        node->pdu->tag = INITIAL_TAG;
        node->pdu->rnti = INITIAL_RNTI;
        node->pdu->cind_tag.crcflag = rand();
    }

    pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        // Handle out-of-memory situation
    }

    for (i = 0; i < N; ++i) {
        pdus[i] = pdu_pool.head->pdu;
        free_to_pool(&pdu_pool, pdu_pool.head);
    }

    return pdus;
}
