typedef struct Pool {
    EventNotification **events;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    int id_pool[MAX_ID];
    size_t id_pool_index;
} Pool;

Pool *init_pool(size_t capacity) {
    Pool *pool = malloc(sizeof(Pool));
    pool->capacity = capacity;
    pool->count = 0;
    pool->id_pool_index = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    pool->events = calloc(capacity, sizeof(EventNotification*));
    return pool;
}

void free_pool(Pool *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->events[i]) {
            free(pool->events[i]->value.s);
            free(pool->events[i]);
        }
    }
    free(pool->events);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

EventNotification *alloc_event(Pool *pool) {
    if (pool->count >= pool->capacity) {
        pool->capacity *= 2;
        pool->events = realloc(pool->events, pool->capacity * sizeof(EventNotification*));
    }
    EventNotification **event = &pool->events[pool->count];
    event->id = pool->id_pool[pool->id_pool_index++];
    event->timestamp = time(NULL);
    event->data_type = INT; // Initialize as integer by default
    event->value.i = 0;
    pool->count++;
    return event;
}

