    char line[4096];
    size_t line_len;
    while ((line_len = getdelim(&line, sizeof(line), '\n', file)) != -1) {
        EventNotification *event = alloc_event(pool);

        char *token = strtok(line, " ");
        int i = 0;
        while (token) {
            if (i >= 4 || !isdigit(*token)) {
                fprintf(stderr, "Invalid format: %s\n", line);
                log_invalid_entry(event->id);
                free(event);
                break;
