                case 2: event->data_type = (enum { INT, FLOAT, STRING })get_data_type(token); break;
                case 3: event->value.i = atoi(token); break;
            }
            token = strtok(NULL, " ");
            ++i;
        }

        if (i < 4) { // Incomplete line
            free(event);
            continue;
        }

        int values_count = i - 3;
        float average;
        if (values_count >= 5) {
            average = compute_average(event->value.i, values_count - 4);
            event->value.f = average;
