class CRCIndicationPdu {
public:
    RX_UE_INFORMATION_TAG tag;
    std::uint32_t rnti;
    CRCI_REL8_TAG crcIndicationTag;

    // Default constructor sets all fields to zero, for convenience in memory allocation functions
    CRCIndicationPdu() : tag(0), rnti(0), crcIndicationTag({ 0 }) {}
};

class MemPool {
public:
    std::unique_ptr<CRCIndicationPdu[]> allocate(size_t count) {
        if (count > availableBlocks_) {
            // Add more blocks to the memory pool when needed
            auto newMemory = std::make_unique<CRCIndicationPdu[]>(count + BUFFER_SIZE);
            std::copy(memory_.get(), memory_.get() + availableBlocks_, newMemory.get());
            memory_ = std::move(newMemory);
            availableBlocks_ += BUFFER_SIZE;
        }

        auto result = std::unique_ptr<CRCIndicationPdu[]>(memory_.get() + availableBlocks_ - count);
        availableBlocks_ -= count;
        return result;
    }

private:
    std::unique_ptr<CRCIndicationPdu[]> memory_;
    size_t availableBlocks_;
    static constexpr size_t BUFFER_SIZE = 1024; // Adjust as necessary
};

class Worker {
public:
    explicit Worker(std::atomic<size_t>* pNumWorkers) : numWorkers_(pNumWorkers), taskQueue_(maxThreads_) {}

    void operator()() {
        while (true) {
            auto task = taskQueue_.pop_front();
            if (!task) break; // signifies shutdown request

            processTask(task);
        }
    }

private:
    std::atomic<size_t>* numWorkers_;
    std::deque<std::shared_ptr<CRCIndicationPdu>> taskQueue_;
    static constexpr size_t maxThreads_ = 16; // Adjust as necessary
};

void initializeList(size_t count, std::list<CRCIndicationPdu>& list) {
    MemPool memPool;
    auto pdus = memPool.allocate(count);

    for (auto& pdu : *pdus) {
        // Fetch RX_UE_INFORMATION_TAG and RNTI from the external data source
        if (!pDataSource->getData(pdu.tag, pdu.rnti)) continue;

        // Generate a random CRCFLAG for each CRCIndication_REL8_TAG
        std::mt19937 gen(std::random_device{}());
        std::uniform_int_distribution<> dist(0, 1);
        pdu.crcIndicationTag.crcFlag = dist(gen);

        list.push_back(std::move(pdu));
    }
}

void processTasks(size_t count, std::list<CRCIndicationPdu>& list) {
    // Initialize and manage threads
    std::vector<std::unique_ptr<Worker>> workers;
    std::atomic<size_t> numWorkers{ static_cast<size_t>(workers.capacity()) };

    for (auto& pdu : list) {
        // Add tasks to the worker queue and signal a new task is available
        auto& taskQueue = workers[workers.size() % maxThreads_]->taskQueue_;
        taskQueue.push_back(std::make_shared<CRCIndicationPdu>(pdu));
        ++numWorkers;
    }

    // Wait for all tasks to be completed before freeing resources
    for (auto& worker : workers) {
        if (worker->numWorkers_ > 0) {
            worker->numWorkers_->wait(0); // Blocks until there are no more tasks
        }
    }

    // Free memory and destroy threads
    for (auto& worker : workers) {
        worker.reset();
    }
}
