using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Xml.Linq;
using System.Linq;

public class Transaction
{
    public int TransactionId { get; set; }
    public int UserId { get; set; }
    public decimal Amount { get; set; }
    public DateTime Timestamp { get; set; }
    public string Status { get; set; }
}

public class Configuration
{
    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public double CameraSpeed { get; set; }
}

public static void Main()
{
    var config = LoadConfiguration();
    var transactions = new List<Transaction>();
    var transactionMemoryPool = new Stack<Transaction>(new Transaction[config.TileSize]); // Dynamically allocate memory for each transaction

    using (var reader = new StreamReader("transactions.csv"))
    {
        string line;
        while ((line = reader.ReadLine()) != null)
        {
            var values = line.Split(',');
            if (values.Length < 5) continue; // Skip invalid lines

            var transaction = new Transaction
            {
                TransactionId = int.Parse(values[0]),
                UserId = int.Parse(values[1]),
                Amount = decimal.Parse(values[2]),
                Timestamp = DateTime.Parse(values[3]),
                Status = values[4]
            };

            if (transaction.Timestamp > GetStartDate() && transaction.Timestamp < GetEndDate())
            {
                if (transaction.Status == "pending") transaction.Status = "processed";
                transactions.Add(transaction); // Add transaction to the list

                // Reuse memory from transactionMemoryPool if possible
                if (transactionMemoryPool.Count > 0)
                    transactionMemoryPool.Pop().AssignValues(transaction);
                else
                    transactionMemoryPool.Push(transaction); // Allocate new memory if the pool is empty
            }
        }
    }

    var outputLines = transactions.Select(t => $"{t.TransactionId}\t{t.UserId}\t{t.Amount}\t{t.Timestamp}\t{t.Status}");

    using (var writer = new StreamWriter("output.tsv"))
    {
        foreach (var line in outputLines) writer.WriteLine(line);
    }

    void AssignValues(Transaction transaction, Transaction source)
    {
        transaction.TransactionId = source.TransactionId;
        transaction.UserID = source.UserID;
        transaction.Amount = source.Amount;
        transaction.Timestamp = source.Timestamp;
        transaction.Status = source.Status;
    }

    static DateTime GetStartDate() => LoadConfiguration().StartDate;
    static DateTime GetEndDate() => LoadConfiguration().EndDate;

    static Configuration LoadConfiguration()
    {
        var xdoc = XDocument.Load("config.xml");
        return new Configuration
        {
            TileSize = int.Parse(xdoc.Element("Configuration").Element("TileSize").Value),
            WorldWidth = int.Parse(xdoc.Element("Configuration").Element("WorldWidth").Value),
            WorldHeight = int.Parse(xdoc.Element("Configuration").Element("WorldHeight").Value),
            CameraSpeed = double.Parse(xdoc.Element("Configuration").Element("CameraSpeed").Value),
            StartDate = DateTime.Parse(xdoc.Element("Configuration").Element("StartDate").Value),
            EndDate = DateTime.Parse(xdoc.Element("Configuration").Element("EndDate").Value)
        };
    }
}
