['```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <semaphore.h>
#include <time.h>

typedef struct {
    char name[64];
    void* (*impl)(void*);
    void* params;
    int PDCP_SN;
    pthread_mutex_t lock;
} func_info;

struct mem_pool {
    func_info** data;
    size_t capacity;
    size_t used;
    sem_t semaphore;
};

func_info* alloc_func_info(const char* name, void* (*impl)(void*), void* params) {
    func_info* info = malloc(sizeof(func_info));
    if (!info) return NULL;

    strcpy(info->name, name);
    info->impl = impl;
    info->params = params;
    info->PDCP_SN = time(NULL);
    pthread_mutex_init(&info->lock, NULL);

    return info;
}

struct mem_pool* create_mem_pool(size_t capacity) {
    struct mem_pool* pool = malloc(sizeof(struct mem_pool));
    if (!pool) return NULL;

    pool->data = calloc(capacity, sizeof(func_info*));
    if (!pool->data) goto fail;
    pool->capacity = capacity;
    pool->used = 0;
    sem_init(&pool->semaphore, 0, pool->capacity);

    return pool;
fail:
    free(pool);
    return NULL;
}

func_info* get_func_info_from_mem_pool(struct mem_pool* pool) {
    func_info* info = NULL;
