struct MemoryPool {
    size_t size;
    void* data;
    size_t allocated;
    sem_t sem;
};

struct Config {
    char** enabled;
    int num_enabled;
};

void log(const char*, ...); // implementation details omitted for brevity

struct MemoryPool* createMemoryPool(size_t size) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) return NULL;

    pool->size = size;
    pool->data = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->data == MAP_FAILED) {
        free(pool);
        return NULL;
    }

    pool->allocated = 0;
    sem_init(&pool->sem, 0, size);
    return pool;
}

void* memPoolAlloc(struct MemoryPool* pool) {
    void* result;

    if (sem_wait(&pool->sem) < 0) {
        log("Semaphore wait failed");
        return NULL;
    }

    result = pool->data + pool->allocated;
    pool->allocated++;

    return result;
}

void memPoolFree(struct MemoryPool* pool, void* ptr) {
    if (ptr < pool->data || ptr >= (pool->data + pool->size)) {
        log("Invalid memory pointer");
        return;
    }

    pool->allocated--;
    sem_post(&pool->sem);
}

