#define NFAPI_CRC_INDICATION_PDU_T_SIZE 40
typedef struct {
    uint32_t rxiit;
    uint16_t rnti;
    uint32_t crcflag;
    uint8_t reserved[3];
    uint32_t crcindicationrel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocate_aligned(size_t size, size_t alignment) {
    void *ptr = mmap(NULL, size + alignment - 1, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return ((uint8_t*)ptr + alignment - 1 & ~(alignment - 1));
}

NFAPI_CRC_INDICATION_PDU_T* generate_pdus(size_t count) {
    if (count > 10000) {
        fprintf(stderr, "Error: Too many PDUs to generate.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = calloc(count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        perror("calloc");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T* aligned_pdus = allocate_aligned((size_t)(count * sizeof(NFAPI_CRC_INDICATION_PDU_T)), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!aligned_pdus) {
        perror("mmap");
        free(pdu_array);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = aligned_pdus + i;
        pdu->rxiit = htonl(i); // Replace with actual value calculation
        pdu->rnti = htons((uint16_t)(i % 65536)); // Replace with actual RNTI generation logic
        pdu->crcflag = rand() % 2;
        pdu->crcindicationrel8_tag = htonl(pdu - aligned_pdus); // Replace with actual value calculation
    }

    return pdu_array;
