void* process_line(void *arg) {
    struct thread_data *data = (struct thread_data*) arg;
    size_t line_index = data->line_index;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = data->pdu_list;
    sem_t *line_sem = data->line_sem;

    // Read a single line from the input file
    char line[256];
    ssize_t bytes_read = getline(&line, sizeof(line), stdin);
    if (bytes_read == -1) {
        log_error("Failed to read from input file");
        return NULL;
    }

    // Validate RX_UE_INFORMATION_TAG and RNTI values with external service
    // Handle delays or failures in data acquisition gracefully

    // Parse the line into individual PDUs
    char *token = strtok(line, "\n");
    int pdu_count = 0;
    while (token != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdu_list[pdu_count];
        sscanf(token, "%d %d %u", &pdu->tag, &pdu->rnti, &pdu->crc_indication.crcflag);
        // Calculate the average of the last two fields in each line and store it in the CRC_INDICATION_REL8_TAG
        pdu->crc_indication.crc16 = ((pdu->crc_indication.crcflag * 2 + pdu_count) % MAX_CRC16);
        token = strtok(NULL, "\n");
        pdu_count++;
    }

    sem_post(line_sem);
    return NULL;
}

void read_and_process_file(const char *filename, size_t num_threads) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        log_error("Failed to open input file");
        return;
    }

    struct stat file_stats;
    fstat(fd, &file_stats);
    off_t file_size = file_stats.st_size;
    char *line_buffer = malloc(file_size + 1); // Additional space for null terminator

    sem_t *line_semaphores = calloc(num_threads, sizeof(sem_t));

    pthread_t threads[num_threads];
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc((size_t)(file_size / 256 + 1) * num_threads * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    size_t line_index = 0;
    for (size_t i = 0; i < num_threads; ++i) {
        struct thread_data *thread_data = malloc(sizeof(struct thread_data));
        thread_data->line_index = line_index;
        thread_data->pdu_list = &pdu_list[(size_t)(file_size / 256 + 1) * i];
        thread_data->line_sem = &line_semaphores[i];

        if (pthread_create(&threads[i], NULL, process_line, thread_data)) {
            log_error("Failed to create thread");
            return;
        }
        line_index += (size_t)(file_size / (num_threads * 256) + 1);
    }

    // Read the file into line_buffer and notify each thread of a new line when finished
    ssize_t bytes_read;
    while ((bytes_read = read(fd, &line_buffer[line_index], file_size - line_index)) > 0) {
        line_index += bytes_read;
        line_buffer[line_index] = '\0';
        for (size_t i = 0; i < num_threads; ++i) {
            sem_wait(line_semaphores[i]);
        }
    }

    // Wait for all threads to finish processing their lines
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(line_buffer);
    free(pdu_list);
    for (size_t i = 0; i < num_threads; ++i) {
        free(threads[i]);
    }
    free(line_semaphores);
}
