    }

    for (int i = 0; i < num_threads; ++i) {
        sem_wait(num_available_semaphores + i); // Wait for a thread slot to become available

        pthread_detach(threads[i]); // Detach the thread from the calling process, so it doesn't interfere with thread cleanup
    }

    // Wait for all threads to finish processing queries
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(should_run); // Free dynamically allocated memory
