    bool* should_run = (bool*)arg;
    int index = -1;

    // Find the current thread's index in the array of operations
    for (int i = 0; i < num_operations; ++i) {
        if (!should_run[i]) continue;

        if (index == -1 || (*operations)[i].query_id < (*operations)[index].query_id)
            index = i;
    }

    if (index == -1) return NULL; // No more operations to process

    // Process the query and update its result_cache field
    DB_OPERATION_T* operation = &(*operations)[index];
    external_database_validate(operation->query_id, operation->shard_id);
    calculate_average_execution_time(operation->result_cache);

    // Mark the processed operation as completed and move on to the next one
    should_run[index] = false;

    return NULL;
}
