typedef struct {
    size_t capacity;
    size_t length;
    int *data;
} Line;

void init_line(Line *line) {
    line->capacity = 10;
    line->length = 0;
    line->data = malloc(line->capacity * sizeof(int));
}

void resize_line(Line *line) {
    if (line->length >= line->capacity) {
        line->capacity *= 2;
        line->data = realloc(line->data, line->capacity * sizeof(int));
    }
}

void push_back(Line *line, int value) {
    resize_line(line);
    line->data[line->length++] = value;
}

double average(const Line *line, size_t n) {
    double sum = 0.0;
    for (size_t i = line->length - n; i < line->length; ++i) {
        sum += line->data[i];
    }
    return sum / n;
}

