    init_line(&line);

    char buffer[4096];
    size_t bytes_read;
    while ((bytes_read = fgets(buffer, sizeof(buffer), file)) != 0) {
        if (strspn(buffer, " \t\r\n") == bytes_read) {
            log("Error: Empty line found in %s", filename);
            continue;
        }

        char *token = strtok(buffer, " ");
        size_t count = 0;
        while (token != NULL) {
            int value = atoi(token);
            if (value < 0 || value > 100) {
                log("Error: Value %d out of range [0, 100] in line %s", value, filename);
                continue;
            }
            push_back(&line, value);
            count++;
            if (count == 5) {
                double avg = average(&line, 5);
                push_back(&line, avg);
                count = 0;
            }
            token = strtok(NULL, " \t\r\n");
        }
    }

    fclose(file);

    size_t line_size = line.length + 1;
    int *new_data = malloc(line_size * sizeof(int));
    memcpy(new_data, line.data, line.length * sizeof(int));
    new_data[line_size - 1] = average(&line, line.length);

    free(line.data);

    printf("%s\n", new_data);
    free(new_data);
    return NULL;
}

int main(int argc, char **argv) {
