        log("Error: No input file specified.");
        return EXIT_FAILURE;
    }

    // Initialize multithreading and parallel processing here.

    for (size_t i = 1; i < argc; ++i) {
        process_file(argv[i]);
    }

    return EXIT_SUCCESS;
}
