struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG = 0;
    uint16_t RNTI = 0;
    uint32_t CRC_INDICATION_REL8_TAG = 0;
    int CRCFLAG = rand() % 2; // Randomly set CRCFLAG to either 0 or 1
};

std::atomic<int> numErrors = 0;

void validate(double value) {
    if (value < 0 || value > 100) {
        ++numErrors;
        std::cerr << "Invalid value: " << value << "\n";
    }
}

std::deque<NFAPI_CRC_INDICATION_PDU_T> processLine(const std::vector<double>& numbers, const std::mutex& mutex) {
    auto averages = numbers.size() < 3 ? std::vector<double>{numbers.back(), 0, 0} : std::vector<double>(numbers.crbegin(), numbers.crend());
    std::sort(averages.begin(), averages.end());
    averages[2] = (averages[2] + averages[1]) / 2.0;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 12345678;
    pdu.RNTI = 98765432;
    pdu.CRC_INDICATION_REL8_TAG = averages[2];

    // Validate the PDU before returning it
    if (!pdu.RX_UE_INFORMATION_TAG || !pdu.RNTI || !pdu.CRC_INDICATION_REL8_TAG) {
        ++numErrors;
        std::cerr << "Invalid PDU: RX_UE_INFORMATION_TAG, RNTI, or CRC_INDICATION_REL8_TAG is null\n";
    }

    mutex.lock();
    auto pdus = std::move(std::deque<NFAPI_CRC_INDICATION_PDU_T>{pdu});
    mutex.unlock();
    return pdus;
}

void processFile(const std::string& fileName) {
    std::ifstream fileStream(fileName, std::ios::binary);
    if (!fileStream.is_open()) {
        ++numErrors;
        std::cerr << "Error opening file: " << fileName << "\n";
        return;
    }

    unsigned char buffer[65536];
    gz_decompressor zlibStream;
    int error = zlibStream.dictStart(buffer, sizeof(buffer));
    if (error != Z_OK) {
        ++numErrors;
        std::cerr << "Error initializing zlib stream: " << fileName << "\n";
        return;
    }

    std::string line;
    double numbers[3] = {0};
    unsigned long index = 0;
    while (getline(fileStream, line)) {
        istringstream ss(line);
        if (!(ss >> numbers[index])) {
            ++numErrors;
            std::cerr << "Error reading number from file: " << fileName << "\n";
            return;
        }
        validate(numbers[index]);

        error = zlibStream.avail_in() < sizeof(buffer);
        if (error != Z_OK) {
            ++numErrors;
            std::cerr << "Error reading compressed data: " << fileName << "\n";
            return;
        }

        index = (index + 1) % 3;
        error = zlibStream.next_out(buffer, sizeof(buffer));
        if (error != Z_OK && error != Z_BUF_ERROR) {
            ++numErrors;
            std::cerr << "Error processing compressed data: " << fileName << "\n";
            return;
        }
    }

    auto mutex = std::mutex();
    auto pdus = processLine({numbers[0], numbers[1], numbers[2]}, mutex);
    for (auto& pdu : pdus) {
        // Here you can send the PDU to other components using an API or message format
    }
}

int main() {
    std::vector<std::string> fileNames;
    // Add your file names here

    std::thread pool[std::thread::hardware_concurrency()];
    gz_decompressor zlibStream;
    for (auto& fileName : fileNames) {
        auto& thread = pool[static_cast<unsigned long>(std::this_thread::get_id()) % std::thread::hardware_concurrency()];
        thread = std::thread(processFile, fileName);
    }

    for (auto& thread : pool) {
        if (thread.joinable()) {
            thread.join();
        }
    }

    std::cout << "Number of errors: " << numErrors << "\n";
}
