#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <inttypes.h>
#include <limits.h>

typedef struct {
    int64_t amount;
    char* date;
    char* description;
} Transaction;

void parse_transaction(const char* line, Transaction* transaction) {
    char delimiter[] = ",\"\s+";
    char buffer[512];
    sscanf(line, "%" SCNu64 ",\"%s\",\"%s\"", &transaction->amount, buffer);
    transaction->date = strdup(strtok(buffer, delimiter));
    transaction->description = strdup(strtok(NULL, delimiter));
}

int compare_transactions(const void* a, const void* b) {
    return ((Transaction*)a)->amount - ((Transaction*)b)->amount;
}

void print_summary_header(const char* format, bool include_breakdowns) {
    printf("Summary Report:\n");
    if (include_breakdowns) {
        printf("%s\n", format);
    } else {
        const char* summary_format = strstr(format, "|") != NULL ? "%-15s | %10" PRId64 " | %-25s" : "%-30s";
        printf(summary_format, "Transaction Date", "Amount", "Description");
    }
}

void print_transaction(const Transaction* transaction, bool include_breakdowns) {
    if (include_breakdowns) {
        printf("%s: %" PRId64 ", %s\n", transaction->date, transaction->amount, transaction->description);
    } else {
        const char* summary_format = strstr(format, "|") != NULL ? "%-15s | %10" PRId64 " | %-25s" : "%-30s";
        printf(summary_format, transaction->date, transaction->amount, transaction->description);
    }
}

void generate_summary_report(const char* input_file, const char* output_file, const char* format, bool include_breakdowns, int64_t threshold) {
    FILE* input = fopen(input_file, "r");
    FILE* output = fopen(output_file, "w");

    if (!input || !output) {
        fprintf(stderr, "Failed to open files.\n");
        exit(1);
    }

    size_t buffer_size = 4096;
    char* line = malloc(buffer_size);
    Transaction transactions[INT_MAX];
    int transaction_count = 0;

    while (getline(&line, &buffer_size, input)) {
        if (transaction_count == sizeof(transactions) / sizeof(Transaction)) {
            Transaction* new_transactions = realloc(transactions, buffer_size * 2);
            if (!new_transactions) {
                fprintf(stderr, "Memory allocation failed.\n");
                exit(1);
            }
            transactions = new_transactions;
        }

        Transaction transaction;
        parse_transaction(line, &transaction);
        transactions[transaction_count++] = transaction;
    }

    qsort(transactions, transaction_count, sizeof(Transaction), compare_transactions);

    print_summary_header(format, include_breakdowns);

    for (int i = 0; i < transaction_count; ++i) {
        const Transaction* transaction = &transactions[i];
        if (transaction->amount > threshold && !include_breakdowns) continue;
        print_transaction(transaction, include_breakdowns);
    }

    fclose(input);
    fclose(output);
}

int main(int argc, char* argv[]) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <log_file> <summary_file> <format> <include_breakdowns> <threshold>\n", argv[0]);
        exit(1);
    }

    const char* input_file = argv[1];
    const char* output_file = argv[2];
    const char* format = argv[3];
    bool include_breakdowns = atoi(argv[4]) != 0;
    int64_t threshold = atoll(argv[5]);

    generate_summary_report(input_file, output_file, format, include_breakdowns, threshold);

    return 0;
}
