typedef struct {
    time_t timestamp;
    double value;
    int location_id;
    char priority;
} sensorEvent;

typedef struct {
    NFAPI_CRCI_PDU_T *data;
    size_t size;
    size_t capacity;
    sem_t mutex;
    sem_t notFull;
    sem_t notEmpty;
} buffer;

void generateRandomCRCFlag(NFAPI_CRCI_PDU_T *pdu) {
    pdu->crcFlag = rand() % 2;
}

buffer* createBuffer(size_t capacity) {
    buffer *buf = malloc(sizeof(buffer));
    buf->data = malloc(capacity * sizeof(NFAPI_CRCI_PDU_T));
    buf->size = 0;
    buf->capacity = capacity;
    sem_init(&buf->mutex, 0, 1);
    sem_init(&buf->notFull, 0, capacity);
    sem_init(&buf->notEmpty, 0, 0);
    return buf;
}

void enqueue(buffer *buf, sensorEvent event) {
    NFAPI_CRCI_PDU_T *pdu = &buf->data[buf->size];
    memset(pdu, 0, sizeof(NFAPI_CRCI_PDU_T));
    pdu->rxUEInformationTag.RX_UE_INFORMATION_TAG.tagType = htons(RX_UE_INFORMATION_TAG);
    pdu->rxUEInformationTag.RX_UE_INFORMATION_TAG.tagLength = sizeof(RX_UE_INFORMATION_TAG) - 1;
    pdu->rxUEInformationTag.RX_UE_INFORMATION_TAG.ueId = event.location_id;
    generateRandomCRCFlag(pdu);

    pdu->rnTITag.RNTI.tagType = htons(RNTI);
    pdu->rnTITag.RNTI.tagLength = sizeof(RNTI) - 1;
    pdu->rnTITag.RNTI.temporaryIdentity = event.location_id;
    generateRandomCRCFlag(&pdu->rnTITag);

    pdu->crcIndicationRel8Tag.tagType = htons(CRC_INDICATION_REL8_TAG);
    pdu->crcIndicationRel8Tag.tagLength = sizeof(CRC_INDICATION_REL8_TAG) - 1;
    generateRandomCRCFlag(&pdu->crcIndicationRel8Tag);

    sem_wait(&buf->notFull);
    buf->data[buf->size] = pdu;
    buf->size++;
    sem_post(&buf->notEmpty);
}

