struct record {
    int id;
    std::string data;
};

class RecordPool final : private boost::noncopyable {
public:
    RecordPool(size_t capacity) : pool_(capacity), head_(pool_.begin()), tail_(pool_.end()) {}

    record* acquire() {
        if (head_ != tail_) {
            auto result = head_;
            ++head_;
            return &*result;
        }
        return new record();
    }

    void release(record* rec) {
        if (tail_ != head_) {
            *tail_ = *rec;
            --tail_;
        } else {
            delete rec;
        }
    }

private:
    std::forward_list<record> pool_;
    record* head_;
    record* tail_;
};

