// Function to read a file and process each line
void processFile(const char *filename, int minValue, int maxValue) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "[ERROR] Failed to open file: %s\n", filename);
        return;
    }

    int lineCount = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%d%n", &number, &n) != 1) continue; // Skip invalid lines
        number = fmin(fmax(number, minValue), maxValue); // Validate numerical values
        lineCount++;

        int *values = calloc(lineCount, sizeof(int));
        if (!values) {
            fprintf(stderr, "[ERROR] Out of memory\n");
            continue;
        }

        int i = 0;
        for (const char *token = strtok(line, " "); token; token = strtok(NULL, " ")) {
            if (sscanf(token, "%d", &number) != 1) continue; // Skip invalid tokens
            values[i++] = number;
        }

        int average = i >= 5 ? computeAverage(values + i - 5, 5) : 0;
        values[i] = average;

        for (int j = 0; j < lineCount; j++) printf("%d", values[j]);
        printf(", %d\n", average);

        free(values);
    }

    fclose(file);
}

// Function to compute the average of an array
int computeAverage(const int *arr, size_t n) {
    int sum = 0;
    for (size_t i = 0; i < n; i++) sum += arr[i];
    return sum / n;
}

// Main function to start processing files
int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <minValue> <maxValue> <filename>\n", argv[0]);
        return 1;
    }

    int min = atoi(argv[1]);
    int max = atoi(argv[2]);
    const char *filename = argv[3];

    processFile(filename, min, max);

    return 0;
}
```

This code reads a file line by line, validates the numerical values within a specified range, and appends the average of the last five numbers (if available) at the end of each line. The memory usage is dynamically managed using `calloc()`, and error handling is implemented for invalid lines and failed file access.

For large datasets or when using a third-party library to handle compressed files, you may want to consider using malloc() instead of calloc(), as it allows for more efficient memory allocation in those cases. Additionally, implementing concurrent file processing would require the use of pthreads or other concurrency libraries.']

