#include "nfapi.h" // NFAPI library
#include "rtsp_module.h" // Real-time signal processing module

typedef struct {
    unsigned int index;
    NFAPI_CRC_INDICATION_PDU_T pdu;
} PDU_STRUCT;

static pthread_mutex_t pdu_list_mutex = PTHREAD_MUTEX_INITIALIZER;
static PDU_STRUCT* pdu_list = NULL;
static unsigned int pdu_count = 0;
static unsigned int max_pdu_count = 0;
static bool reconfigure = false;
static bool interrupt = false;

void init_pdu_list(unsigned int max_pdus) {
    if (max_pdus <= pdu_count || !max_pdus) return;

    reconfigure = true;
    max_pdu_count = max_pdus;
}

void free_pdu_list() {
    if (!pdu_list) return;

    for (unsigned int i = 0; i < pdu_count; ++i) {
        free(pdu_list[i].pdu.buffer);
    }

    free(pdu_list);
    pdu_list = NULL;
    pdu_count = 0;
}

void create_pdus() {
    if (reconfigure && max_pdu_count) {
        free_pdu_list();

        pdu_list = calloc(max_pdu_count, sizeof(PDU_STRUCT));
        if (!pdu_list) {
            log_error("Failed to allocate memory for PDUs.");
            return;
        }

        pthread_mutex_init(&pdu_list_mutex, NULL);
        reconfigure = false;
    }

    if (interrupt || !max_pdu_count) return;

    for (unsigned int i = pdu_count; i < max_pdu_count && i < NUM_THREADS; ++i) {
        PDU_STRUCT* pdu = &pdu_list[i];

        pdu->index = i;
        pdu->pdu.tag = RX_UE_INFORMATION_TAG;
        pdu->pdu.rnti = i + 1;
        pdu->pdu.crc_indication_rel8.crcflag = rand() % 2;

        pthread_mutex_lock(&pdu_list_mutex);
        pdu_count++;
        pthread_mutex_unlock(&pdu_list_mutex);
    }
}

void process_packet(NFAPI_PACKET_T* packet) {
    if (!interrupt && packet->length > 0) {
        PDU_STRUCT* pdu = NULL;

        pthread_mutex_lock(&pdu_list_mutex);
        if (pdu_count > 0) {
            pdu = &pdu_list[packet->index % pdu_count];
        }
        pthread_mutex_unlock(&pdu_list_mutex);

        if (pdu && packet->length <= pdu->pdu.size) {
            memcpy(pdu->pdu.buffer, packet->data, packet->length);
            process_crc_indication(packet->length, pdu->pdu.crc_indication_rel8.crcflag);
        } else {
            log_error("Invalid or missing PDU structure for packet.");
        }
    }
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) interrupt = true;
}
