static PDU_LIST_NODE *head = NULL;
static PDU_LIST_NODE *tail = NULL;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_pdu(RX_UE_INFORMATION_TAG tag, RNTI rnti) {
    // Acquire the list mutex to ensure thread safety.
    pthread_mutex_lock(&list_mutex);

    PDU_LIST_NODE *new_node = (PDU_LIST_NODE*)malloc(sizeof(PDU_LIST_NODE));
    if (!new_node) {
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    new_node->pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node->pdu) {
        free(new_node);
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    new_node->pdu->tag = tag;
    new_node->pdu->rnti = rnti;
    // Generate CRCFLAG here using a random number generator function.

    if (!head) {
        head = new_node;
        tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

void free_pdu_list() {
    // Acquire the list mutex to ensure thread safety.
    pthread_mutex_lock(&list_mutex);

    PDU_LIST_NODE *current = head;
    while (head) {
        head = current->next;
        free(current->pdu);
        free(current);
        current = head;
    }

    head = tail = NULL;
    pthread_mutex_unlock(&list_mutex);
}
