static Node* cache = NULL;
static unsigned int cache_size = 0;
static unsigned int cache_hits = 0;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    pthread_mutex_lock(&list_mutex);
    if (num_elements >= MAX_ELEMENTS) {
        free(new_node);
        pthread_mutex_unlock(&list_mutex);
        fprintf(stderr, "List is full\n");
        return;
    }

    if (!head) {
        head = new_node;
    } else {
        Node* current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    num_elements++;
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_node(RX_UE_INFORMATION_TAG tag) {
    pthread_mutex_lock(&list_mutex);
    if (!cache || cache->data.tag != tag) {
        Node* current = head;
        while (current && current->data.tag != tag) {
            current = current->next;
        }

        if (current) {
            if (!cache || cache->data.tag == tag) {
                if (cache) free(cache);
                cache = current;
                cache_size++;
            }
            cache_hits++;
        } else {
            if (cache) {
                free(cache);
                cache = NULL;
                cache_size--;
            }
        }
    }
    pthread_mutex_unlock(&list_mutex);

    return &cache ? &cache->data : NULL;
}

