    Node* filtered_head = NULL;
    Node* filtered_tail = NULL;

    while (current) {
        if (current->data.tag == tag) {
            if (!filtered_head) {
                filtered_head = current;
                filtered_tail = current;
            } else {
                filtered_tail->next = current;
                filtered_tail = current;
            }
        }

        current = current->next;
    }

    if (filtered_head) {
        head = filtered_head;
        num_elements = 0;
        Node* temp = head;
        while (temp) {
            temp = temp->next;
            num_elements++;
        }
    }
}

void cleanup() {
    pthread_mutex_lock(&list_mutex);
    Node* current = head;
    Node* next;

    while (current) {
