            RNTI = rNTI;
            CRC_INDICATION_REL8_TAG = cRCIoIndicationRel8Tag;
            CRCFLAG = false;
        }
    }

    public struct RX_UE_INFORMATION_TAG
    {
        public byte TAI_Length;
        public byte SIB13_Presence;
        // ... other properties
    }

    public struct CRC_INDICATION_REL8_TAG
    {
        public ushort CRC_Indication_Value;
        // ... other properties
    }

    public class WebsiteManager
    {
        private const int MaxElements = 1000;
        private ConcurrentQueue<NFAPI_CRC_INDICATION_PDU_T> dataPool;
        private BlockingCollection<NFAPI_CRC_INDICATION_PDU_T> workQueue;

        public WebsiteManager()
        {
            dataPool = new ConcurrentQueue<NFAPI_CRC_INDICATION_PDU_T>();
            for (int i = 0; i < MaxElements; i++)
                dataPool.Enqueue(new NFAPI_CRC_INDICATION_PDU_T());
            workQueue = new BlockingCollection<NFAPI_CRC_INDICATION_PDU_T>();
        }

        public void addWebsiteAndStartWithCrcIndications(string directoryPath, string siteName)
        {
            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");

            var webConfigFile = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigFile))
                return;

            // Perform website-specific configurations here...

            ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
            int elementsToProcess = Math.Min(MaxElements, File.ReadLines(webConfigFile).Count());

            CancellationTokenSource cts = new CancellationTokenSource();
            using (var workLoop = new ParallelLoopState())
            {
                WorkLoopWorker(cts.Token, elementsToProcess, workQueue);

                if (!workLoop.ShouldExitCurrentIteration)
                    cts.Cancel();
            }
        }

        private void WorkLoopWorker(CancellationToken cancellationToken, int numElements, BlockingCollection<NFAPI_CRC_INDICATION_PDU_T> workQueue)
        {
            Parallel.ForEach(Enumerable.Range(0, numElements), options, i =>
            {
                if (cancellationToken.IsCancellationRequested)
                    return;

                var dataItem = dataPool.TryDequeue(TimeSpan.FromMilliseconds(1));
                if (dataItem == null)
                {
                    workQueue.Add(new NFAPI_CRC_INDICATION_PDU_T());
                    return;
                }

                // Populate the dataItem with the required values for each element...

                workQueue.Add(dataItem);
            });
        }
    }
}
