struct global {
    TIME_SLOT* time_slots;
    size_t num_time_slots;
    pthread_mutex_t global_lock;
};

void init_global(struct global* glob) {
    glob->num_time_slots = 0;
    pthread_mutex_init(&glob->global_lock, NULL);
}

void add_time_slot(struct global* glob, int slot_id) {
    if (glob->num_time_slots >= MAX_TIME_SLOTS) {
        fprintf(stderr, "Warning: Maximum number of time slots reached.\n");
        return;
    }

    TIME_SLOT* new_slot = malloc(sizeof(TIME_SLOT));
    if (!new_slot) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    pthread_mutex_init(&new_slot->lock, NULL);
    new_slot->slot_id = slot_id;
    new_slot->num_ue = 0;
    new_slot->ue_list = NULL;

    glob->time_slots = realloc(glob->time_slots, (glob->num_time_slots + 1) * sizeof(TIME_SLOT));
    if (!glob->time_slots) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(new_slot);
        return;
    }

    glob->time_slots[glob->num_time_slots++] = new_slot;
}

