        {
            if (_cache.TryGetValue(filePath, out var cachedHash))
                return cachedHash;

            using (var sha256 = SHA256.Create())
            {
                using var stream = File.OpenRead(filePath);
                var hashBytes = await Task.Run(() =>
                {
