    std::map<RNTI, NFAPI_CRC_INDICATION_PDU_T> indications;
    std::mutex mutex;
    std::queue<std::function<void()>> tasks;
    std::condition_variable cv;
    int processedCount = 0;
    int failedCount = 0;

public:
    explicit CRCManager(std::shared_ptr<ExternalData> dataSource) : dataSource(dataSource) {}

    void addIndication(const NFAPI_CRC_INDICATION_PDU_T& indication) {
        std::unique_lock<std::mutex> lock(mutex);
        indications[indication.rnti] = indication;
        lock.unlock();
        cv.notify_one();
    }

    void processIndications() {
        auto updatedUeInfo = dataSource->getUeInfo();

        std::unique_lock<std::mutex> lock(mutex);
        while (!indications.empty()) {
            auto it = indications.begin();
            RNTI rnti = it->first;
            NFAPI_CRC_INDICATION_PDU_T indication = it->second;

            if (rnti < MIN_RNTI || rnti > MAX_RNTI) {
                ++failedCount;
                continue;
            }

            auto foundIt = updatedUeInfo.find(indication.ueTag);
            if (foundIt == updatedUeInfo.end() || indication.crcFlag != foundIt->second.crcFlag) {
                ++failedCount;
                continue;
            }

            indications.erase(it);
            ++processedCount;
            lock.unlock();

            tasks.emplace_back([this, indication]() mutable { this->updateStatistics(indication); });
        }
        lock.unlock();
        cv.notify_all();
