            cv.wait(lock, [this]() { return !indications.empty() || !tasks.empty(); });

            if (!indications.empty()) {
                processIndications();
            }

            while (!tasks.empty()) {
                tasks.front()();
                tasks.pop();
            }
        }
    }

    int getProcessedCount() const { return processedCount; }
    int getFailedCount() const { return failedCount; }

