void init_dynamic_array(int N, callback_func create_crc_indication, void* external_data) {
    NFAPI_CRC_INDICATION_PDU_T *arr;
    clock_t start = clock();
    size_t memory_used = 0;
    int processed = 0;

    arr = (NFAPI_CRC_INDICATION_PDU_T*) malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr) {
        fprintf(stderr, "Failed to allocate memory for dynamic array\n");
        return;
    }

