        arr[i].RX_UE_INFORMATION_TAG = *((uint32_t*) external_data);
        arr[i].RNTI = *(int*) ((char*)external_data + sizeof(uint32_t));
        if (!create_crc_indication(&arr[i], i)) {
            processed++;
        }
        memory_used += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        external_data = ((char*)external_data + sizeof(uint32_t) + sizeof(int)); // Move to the next element in the data source

        if (memory_used > MAX_MEMORY || clock() - start > MAX_TIME) {
            fprintf(stderr, "Memory or time constraints exceeded, reducing batch size and deferring processing\n");
            BATCH_SIZE = min(BATCH_SIZE, N);
            break;
        }
    }

    // Process any remaining items in a batch
    for (int i = processed; i < N && memory_used + sizeof(NFAPI_CRC_INDICATION_PDU_T) * (N - i) <= MAX_MEMORY; ++i) {
        arr[i].RX_UE_INFORMATION_TAG = *((uint32_t*) external_data);
