#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>

typedef struct Connection {
    uint64_t id;
    void *metadata;
    time_t timestamp;
    pthread_mutex_t mutex;
} Connection;

typedef struct Connections {
    Connection **connections;
    size_t capacity;
    size_t count;
    sem_t batch_sem;
    sem_t mem_sem;
    sem_t lock;
    const size_t BATCH_SIZE;
    const size_t MAX_MEMORY;
} Connections;

Connections *connections_init(size_t n, void (*cleanup)(Connection*), size_t bs, size_t mm) {
    Connections *c = mmap(NULL, sizeof(Connections), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    c->BATCH_SIZE = bs;
    c->MAX_MEMORY = mm;
    pthread_mutex_init(&c->lock, NULL);
    sem_init(&c->batch_sem, 0, bs);
    sem_init(&c->mem_sem, 0, (mm / sizeof(Connection)) - n);
    return c;
}

void connections_destroy(Connections *c) {
    for (size_t i = 0; i < c->capacity; ++i) {
        if (c->connections[i]) {
            (*cleanup)(c->connections[i]);
            free(c->connections[i]->metadata);
            free(c->connections[i]);
        }
    }
    munmap(c, sizeof(*c));
}

Connection *connections_alloc(void *metadata) {
    Connection *conn = malloc(sizeof(Connection));
    conn->id = 0; // External service to set this value
    conn->metadata = metadata;
    pthread_mutex_init(&conn->mutex, NULL);
    return conn;
}

void connections_push(Connections *c, Connection *conn) {
    if (c->count + 1 > c->capacity && sem_trywait(&c->mem_sem) != 0) {
        // Failed to allocate memory. Handle gracefully.
    }
    c->connections[c->count++] = conn;
}

void connections_process(Connections *c, void (*callback)(Connection*)) {
    size_t start = sem_wait(&c->batch_sem);
    size_t end = (start + c->BATCH_SIZE > c->count) ? c->count : start + c->BATCH_SIZE;
    for (size_t i = start; i < end; ++i) {
        Connection *conn = c->connections[i];
        pthread_mutex_lock(&conn->mutex);
        if (time(NULL) - conn->timestamp > MAX_TIME) {
            // Session expired. Cleanup and continue.
            (*callback)(conn);
            continue;
        }
        pthread_mutex_unlock(&conn->mutex);
    }
    sem_post(&c->batch_sem);
}

Connections *connections_create(size_t n, void (*cleanup)(Connection*), size_t bs, size_t mm) {
    Connections *c = connections_init(n, cleanup, bs, mm);
    c->connections = calloc(n, sizeof(Connection*));
    return c;
}
```

