#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>
#include <limits.h>
#include <syslog.h>

enum LogLevel { DEBUG, INFO, WARN, ERROR };

typedef struct LineData {
    size_t capacity;
    size_t length;
    char* data;
} LineData;

void log(enum LogLevel level, const char *msg) {
    openlog("data-pipeline", LOG_PID, LOG_DAEMON);
    switch (level) {
        case DEBUG: syslog(LOG_DEBUG, "%s", msg); break;
        case INFO: syslog(LOG_INFO, "%s", msg); break;
        case WARN: syslog(LOG_WARNING, "%s", msg); break;
        case ERROR: syslog(LOG_ERR, "%s", msg); break;
    }
    closelog();
}

LineData* line_data_new() {
    LineData* ld = malloc(sizeof(LineData));
    if (!ld) {
        log(ERROR, "Failed to allocate memory for LineData");
        return NULL;
    }
    ld->capacity = 16;
    ld->length = 0;
    ld->data = malloc(ld->capacity * sizeof(char));
    if (!ld->data) {
        log(ERROR, "Failed to allocate memory for LineData data");
        free(ld);
        return NULL;
    }
    return ld;
}

void line_data_resize(LineData* ld) {
    size_t new_capacity = ld->capacity * 2;
    char* new_data = realloc(ld->data, new_capacity * sizeof(char));
    if (!new_data) {
        log(ERROR, "Failed to reallocate memory for LineData data");
        return;
    }
    ld->data = new_data;
    ld->capacity = new_capacity;
}

void line_data_append(LineData* ld, const char c) {
    if (ld->length >= ld->capacity) {
        line_data_resize(ld);
    }
    ld->data[ld->length++] = c;
    ld->data[ld->length] = '\0';
}

void process_line(LineData* line, int min, int max) {
    int count = 0;
    double sum = 0.0;
    for (size_t i = 0; i < line->length - 1; ++i) {
        if (!isdigit((int)line->data[i]) || !isdigit((int)line->data[i+1]) || !isdigit((int)line->data[i+2])) {
            log(WARN, "Invalid line format at position %zu", i);
            continue;
        }
        int val = atoi(&(line->data[i]));
        if (val < min || val > max) {
            log(ERROR, "Value out of range: %d at position %zu", val, i);
            line_data_append(line, '#');
            line_data_append(line, ' ');
            line_data_append(line, line->data + i);
            continue;
        }
        sum += val;
        ++count;
        if (count == 3) {
            double avg = sum / count;
            line_data_append(line, ' ');
            line_data_append(line, *(int*)&avg);
            break;
        }
    }
    if (count < 3) {
        double max_val = -1;
        for (size_t i = 0; i < ld->length - 1; ++i) {
            int val = atoi(&(line->data[i]));
            if (val > max_val) {
                max_val = val;
            }
        }
        line_data_append(line, ' ');
        line_data_append(line, *(int*)&max_val);
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        log(ERROR, "Usage: %s file", argv[0]);
        return -1;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        log(ERROR, "Failed to open file %s for reading", argv[1]);
        return -1;
    }

    size_t total_invalid = 0;
    LineData* current_line = line_data_new();

    char c;
    while ((c = fgetc(file)) != EOF) {
        if (c == '\n') {
            process_line(current_line, 0, 100);
            total_invalid += current_line->data[current_line->length - 1] - '0';
            current_line = line_data_new();
        } else {
            line_data_append(current_line, c);
        }
    }

    process_line(current_line, 0, 100);
    total_invalid += current_line->data[current_line->length - 1] - '0';

    fclose(file);
    free(current_line->data);
    free(current_line);

    log(INFO, "Total invalid entries: %zu", total_invalid);

    return 0;
}
```

