    double fpoint;

    for (i = 0; i < strlen(str); ++i) {
        if (!isdigit(str[i]) && str[i] != '.' && str[i] != '-') return false;
        if (str[i] == '.') {
            if (i > 0 && str[i - 1] == '.') return false;
        }
        if (str[0] == '-' && i != 0) sign *= -1;
    }

    fpoint = atof(str);

    // Check for range of numbers
    if (fpoint < -10000 || fpoint > 10000) return false;

    return true;
}

double average(const double* arr, size_t size) {
    double sum = 0.0;

    for (size_t i = 0; i < size; ++i) sum += arr[i];

    return sum / size;
}

int countDuplicates(const double* arr, size_t size) {
    int counts[10001] = {0};
    for (size_t i = 0; i < size; ++i) counts[(int)(arr[i] * 100)]++;

    int duplicateCount = 0;
    for (size_t i = 0; i < 10001; ++i) {
        duplicateCount += (counts[i] > 1);
    }

    return duplicateCount;
}

int main(int argc, char** argv) {
    if (argc != 2 || atoi(argv[1]) <= 0 || atoi(argv[1]) > MAX_INPUT) {
        printf("Usage: %s <number of inputs>\n", argv[0]);
        return 1;
    }

    size_t numInputs = atoi(argv[1]);
    double* arr;
    size_t size = 0;

    char buffer[BUFFER_SIZE];
    char* token;
    int count = 0;

    while (count < numInputs) {
        if (fgets(buffer, BUFFER_SIZE, stdin) == NULL) return 1;

        token = strtok(buffer, " \t\n");
        if (!token) continue;

        // Remove trailing newline character from fgets
        size_t len = strlen(token);
        if (len > 0 && token[len - 1] == '\n') token[len - 1] = '\0';

        if (!isValidNumber(token)) {
            printf("Invalid input: '%s'\n", token);
            return 1;
        }

        if (size >= numInputs) break; // We have reached the specified number of inputs, stop filling the array

        double* temp = realloc(arr, sizeof(double) * (size + 1));
        if (!temp) {
            printf("Memory allocation error\n");
            clearArray(&arr, &size);
            return 1;
        }
        arr = temp;

        arr[size] = atof(token);
        size++;
    }

    if (count != numInputs) {
        printf("Reached end of input before specified number\n");
        clearArray(&arr, &size);
        return 1;
    }

    double avg = average(arr, size);
    int duplicates = countDuplicates(arr, size);

    printf("Average: %.6f\n", avg);
    printf("Number of duplicates: %d\n", duplicates);

    clearArray(&arr, &size);
    return 0;
}
