bool parse_line(char *line, TokenData *data) {
    json_t *root;
    json_error_t error;
    root = json_loads(line, 0, &error);

    if (!root || !json_is_object(root)) {
        return false;
    }

    json_t *access_token_raw = json_object_get(root, "access_token");
