    json_t *token_type_raw = json_object_get(root, "token_type");
    json_t *refresh_token_raw = json_object_get(root, "refresh_token");

    if (!json_is_string(access_token_raw) || !json_is_integer(expires_in_raw) || !json_is_string(token_type_raw)) {
        return false;
    }

    data->access_token = strdup(json_string_value(access_token_raw));
    data->expires_in = json_integer_value(expires_in_raw);
    data->token_type = strdup(json_string_value(token_type_raw));
    data->refresh_token = refresh_token_raw ? strdup(json_string_value(refresh_token_raw)) : NULL;

    if (strcmp(data->token_type, "Bearer") != 0 || data->expires_in <= 0) {
        return false;
    }

    return true;
}

