                if (indexes[i] == -1) {
                    pthread_spin_unlock(&lock);
                    break;
                }
                free_indexes[indexes[i]] = -1;
            }
            pthread_spin_unlock(&lock);
        }

        if (batch_size != indexes[0]) {
            free(batch);
            continue; // Incomplete batch, handle gracefully or skip processing
        }

        for (int i = 0; i < batch_size; ++i) {
            pthread_spin_lock(&records[indexes[i]].lock);
            Connection c = records[indexes[i]].conn;
            time_t t = c.timestamp + MAX_TIME; // Simulate session expiration
            if (t < current_time) {
                callback(c.session_id);
            }
            pthread_spin_unlock(&records[indexes[i]].lock);
        }

        pthread_spin_lock(&lock);
        for (int i = 0; i < batch_size; ++i) {
            int j;
            for (j = current_index + i; j < N && free_indexes[j] == -1; ++j) {}
            if (j != N) {
                memcpy(&records[j], &batch[i], sizeof(Record));
                free_indexes[j] = indexes[i];
            } else { // Handle memory exhaustion or reallocation logic here }
        }
        pthread_spin_unlock(&lock);

        current_index += batch_size;
    }

    free(records);
    return NULL;
}

// Find an available index in the free_indexes array
int find_available(long* free_indexes, int size) {
    for (int i = 0; i < size; ++i) {
        if (free_indexes[i] == -1)
            return i;
    }
    return -1; // No available index found
}
