#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>
#include "check_data.h" // External data validation function

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    PDU_TYPE pdu_type;
    struct node *next;
} NODE;

typedef struct {
    NODE *head;
    sem_t mutex;
    sem_t queue_not_empty;
} LIST;

LIST* list_create() {
    LIST *list = (LIST*)malloc(sizeof(LIST));
    if (!list) return NULL;

    list->head = NULL;
    sem_init(&list->mutex, 0, 1);
    sem_init(&list->queue_not_empty, 0, 0);

    return list;
}

void list_free(LIST *list) {
    NODE* current = list->head;
    NODE* temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    sem_destroy(&list->mutex);
    sem_destroy(&list->queue_not_empty);
    free(list);
}

void list_insert(LIST *list, NODE *node) {
    sem_wait(&list->mutex);
    node->next = list->head;
    list->head = node;
    sem_post(&list->queue_not_empty);
    sem_post(&list->mutex);
}

NODE* list_retrieve(LIST *list) {
    NODE* result = NULL;
    sem_wait(&list->queue_not_empty);
    sem_wait(&list->mutex);

    if (list->head != NULL) {
        result = list->head;
        list->head = list->head->next;
    }

    sem_post(&list->mutex);
    sem_post(&list->queue_not_empty);
    return result;
}
