struct Summary processLogsAndAggregate() {
    FILE *file;
    struct Event *events = NULL;
    int event_count = 0, window_event_count = 0, window_time = 0;
    time_t current_time, previous_event_timestamp;

    // open log file and read events line by line
    if ((file = fopen("logfile.txt", "r")) == NULL) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // validate timestamps, allocate memory for events, and aggregate metrics
    while (fscanf(file, "%*[^,],%ld,%d\n", &events[event_count].timestamp, &events[event_count].event_code) == 2) {
        // validate timestamps, increment event count and window count if necessary
        current_time = time(NULL);
        if (events[event_count].timestamp < previous_event_timestamp + 86400) {
            printf("Invalid timestamp: %s\n", ctime(&events[event_count].timestamp));
            continue;
        }
        if ((current_time - events[event_count].timestamp) <= ROLLING_WINDOW) {
            window_event_count++;
        }

        // dynamically allocate memory for events and increment event count
        events = realloc(events, (event_count + 1) * sizeof(struct Event));
        previous_event_timestamp = events[event_count].timestamp;
        event_count++;
    }

    fclose(file);

    // compute average frequency and other relevant aggregations
    struct Summary summary = { .total_events = event_count,
                               .window_events = window_event_count,
                               .average_frequency = (double) window_event_count / ((current_time - previous_event_timestamp) / 60.0) };
    free(events);

    return summary;
}
