struct Token {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
    int average;
};

int count_valid = 0, count_invalid = 0;
long long sum_expires = 0;

void process_line(char *line) {
    struct Token token;
    json_object *json = json_tokener_parse(line);

    if (json == NULL || !json_object_get_string(json, "access_token") ||
        !json_object_get_int(json, "expires_in") > 0 ||
        !json_object_get_string(json, "token_type") ||
        strcmp(json_object_get_string(json, "token_type"), "Bearer") != 0) {
        count_invalid++;
        json_object_put(json);
        return;
    }

    token.access_token = strdup(json_object_get_string(json, "access_token"));
    token.expires_in = json_object_get_int(json, "expires_in");
    token.token_type = strdup(json_object_get_string(json, "token_type"));
    token.refresh_token = json_object_get_string_ex(json, "refresh_token", NULL);

    count_valid++;
    sum_expires += token.expires_in;

    if (count_valid > 2) {
        int avg = (sum_expires - token.expires_in + count_valid - 1) / (count_valid - 1);
        token.average = avg < token.expires_in ? avg : token.expires_in;
    } else {
        token.average = 0;
    }

    free(json);
}

