    while (fgets(line, sizeof(line), file)) {
        process_line(strdup(line));
        free(line);
    }

    fclose(file);

    printf("Number of valid tokens: %d\n", count_valid);
    printf("Number of invalid tokens: %d\n", count_invalid);

    return 0;
}
