}

void* mem_alloc(struct memory_pool* pool, size_t size) {
    void* data;
    pthread_mutex_lock(&pool->lock);
    if (pool->size + size > pool->capacity) {
        pool->data = realloc(pool->data, pool->capacity * 2);
        pool->capacity *= 2;
    }
    data = pool->data + pool->size;
    pool->size += size;
    pthread_mutex_unlock(&pool->lock);
    return data;
}

