    struct NODE *left_child;
    struct NODE *right_child;
} node_t;

typedef struct CONFIG {
    size_t max_depth;
    // Add other configuration parameters as needed
} config_t;

node_t* tree_manager(config_t* config) {
    if (config->max_depth < 0 || config->max_depth > 10) {
        fprintf(stderr, "Error: Maximum depth must be between 0 and 10.\n");
        exit(EXIT_FAILURE);
    }

    node_t* root = mmap(NULL, sizeof(node_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (root == MAP_FAILED) {
        perror("mmap: ");
        exit(EXIT_FAILURE);
    }

    root->value = 0;
    root->left_child = NULL;
    root->right_child = NULL;

    node_t** current_node = &root;
    size_t depth = 0;
    int value;

    sem_t lock;
    sem_init(&lock, 0, 1);

    void add_node(int v) {
        if (depth >= config->max_depth || value < MIN_VALUE || value > MAX_VALUE) {
            fprintf(stderr, "Error: Cannot add node with invalid value or depth.\n");
            exit(EXIT_FAILURE);
        }

        // Check for duplicate nodes at the same level
        if (current_node != root && current_node->value == v) {
            fprintf(stderr, "Error: Duplicate value detected at the same level.\n");
            exit(EXIT_FAILURE);
        }

        // Check for adjacent duplicates at the same depth
        node_t* sibling;
        if (current_node->left_child) {
            sibling = current_node->left_child;
        } else if (current_node->right_child) {
            sibling = current_node->right_child;
        } else {
            fprintf(stderr, "Error: Cannot find a sibling node.\n");
            exit(EXIT_FAILURE);
        }

        if (sibling && sibling->value == v) {
            fprintf(stderr, "Error: Duplicate value detected adjacent to the current node.\n");
            exit(EXIT_FAILURE);
        }

        // Allocate new node and initialize it
        node_t* new_node = mmap(NULL, sizeof(node_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_node == MAP_FAILED) {
            perror("mmap: ");
            exit(EXIT_FAILURE);
        }

        sem_wait(&lock);
        value = v;
        new_node->value = value;
        new_node->left_child = NULL;
        new_node->right_child = NULL;
        sem_post(&lock);

        if (depth % 2 == 0) { // Insert as left child
            current_node->left_child = new_node;
        } else {
            current_node->right_child = new_node;
        }
        depth++;
        current_node = current_node->left_child ? current_node->left_child : current_node->right_child;
    }

    // Implement function for iterating over the tree and printing details of each node...

    // Implement performance testing mechanism...

    // Synchronize access to the tree using semaphores or mutexes when necessary

    return root;
}
