class FrameList {
public:
    FrameList() : list_(std::less<MAC_FRAME_T*>()), mutex_() {}

    void addFrame(const MAC_FRAME_T& frame) {
        if (frame.sequenceNumber < 0) throw std::invalid_argument("Sequence number must be non-negative.");

        MAC_FRAME_T* newFrame = new MAC_FRAME_T(frame);
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = list_.insert(list_.end(), newFrame);
        ++seqCounter_;
        newFrame->sequenceNumber = seqCounter_;
    }

    MAC_FRAME_T* removeFrame(uint32_t sequenceNumber) {
        if (sequenceNumber < 0) throw std::invalid_argument("Sequence number must be non-negative.");

        std::unique_lock<std::mutex> lock(mutex_);
        auto it = list_.equal_range([&](const MAC_FRAME_T* frame) { return frame->sequenceNumber == sequenceNumber; });
        if (it.first != it.second) {
            MAC_FRAME_T* frameToRemove = *it.first;
            list_.erase(it.first);
            delete frameToRemove;
            return frameToRemove;
        }
        return nullptr;
    }

    const MAC_FRAME_T* getFrame(uint32_t sequenceNumber) {
        if (sequenceNumber < 0) throw std::invalid_argument("Sequence number must be non-negative.");

        std::unique_lock<std::mutex> lock(mutex_);
        auto it = list_.equal_range([&](const MAC_FRAME_T* frame) { return frame->sequenceNumber == sequenceNumber; });
        if (it.first != it.second) return *it.first;
        return nullptr;
    }

private:
    std::list<MAC_FRAME_T*, std::function<bool(const MAC_FRAME_T*)>> list_;
    std::mutex mutex_;
    std::atomic<uint32_t> seqCounter_{0};
};
