    long value;
    struct Node* next;
    struct Node* prev;
} Node;

static Node* head = NULL;
static Node* tail = NULL;
static size_t num_nodes = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static void log_alloc(size_t bytes, const char* operation) {
    if (bytes > 0) {
        printf("%s: Allocated %zu bytes\n", operation, bytes);
    } else {
        printf("%s: Failed to allocate memory\n", operation);
    }
}

Node* create_node() {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        log_alloc(sizeof(Node), "node creation");
        return NULL;
    }

    node->key = rand() % 10000;
    node->value = (long)rand() * RAND_MAX;
    log_alloc(sizeof(*node), "node initialization");
    return node;
}

void insert_head(Node* node) {
    pthread_mutex_lock(&mutex);
    if (!head) {
        head = tail = node;
    } else {
        node->next = head;
        head->prev = node;
        head = node;
    }
    num_nodes++;
    pthread_mutex_unlock(&mutex);
}

void insert_tail(Node* node) {
    pthread_mutex_lock(&mutex);
    if (!head) {
        head = tail = node;
    } else {
        node->prev = tail;
        tail->next = node;
        tail = node;
    }
    num_nodes++;
    pthread_mutex_unlock(&mutex);
}

Node* find_node_by_key(int key) {
    Node* current = head;
    while (current != NULL) {
        if (current->key == key) {
            break;
        }
        current = current->next;
    }
    return current;
}

Node* remove_node_by_key(int key) {
    pthread_mutex_lock(&mutex);
    Node* current = head;
    while (current != NULL) {
        if (current->key == key) {
            break;
        }
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    if (current == head) {
        head = current->next;
        if (head) {
            head->prev = NULL;
        } else {
            tail = NULL;
        }
    } else if (current == tail) {
        tail = current->prev;
        tail->next = NULL;
    } else {
        current->prev->next = current->next;
        current->next->prev = current->prev;
    }

    free(current);
    num_nodes--;
    pthread_mutex_unlock(&mutex);
    return current;
}
