    void enqueueTask(const std::string& name) {
        auto task = std::make_unique<Task>();
        task->name = name;
        task->lastUpdate = std::chrono::system_clock::now().time_since_epoch().count();
        task->priority = getPriorityLevel(task->name);

        // Log allocation attempts and handle errors
        if (!task) {
            std::cerr << "Allocation failure: " << sizeof(Task) << " bytes requested." << std::endl;
            return;
        }

        taskQueue_.push(std::move(task));
    }

    Task* dequeueHighestPriorityTask() {
        auto now = std::chrono::system_clock::now().time_since_epoch().count();

        while (!taskQueue_.pop(task_, true)) {
            if (task_) {
                task_->lastUpdate = now;
                return task_.exchange(nullptr);
            }
        }

        return nullptr;
    }

private:
    boost::lockfree::spsc_queue<std::unique_ptr<Task>> queue_;
    size_t maxTasks_;
    std::unique_ptr<Task> task_;
};
```

