            return;
        }

        std::ofstream outputStream(*fileGuard2);
        outputStream << format << '\n';
        for (const auto& entry : data) {
            if (!m_includeErrors && entry->value > 50) {
                continue;
            }
            outputStream << *entry << '\n';
        }
    }

private:
