    std::string m_inputFile, m_outputFile, m_format, m_target, m_secondData, m_secondId;
    bool m_includeErrors;
};

int main(int argc, char* argv[]) {
    if (argc != 7) {
        std::cerr << "Usage: log_processor <inputFile> <outputFile> <format> [includeErrors] [target] [threshold]\n";
        return -1;
    }

    LogProcessor processor(std::stoi(argv[6]), argv[1], argv[2], atoi(argv[3]) != 0, argv[4], argv[5]);
    std::vector<std::thread> threads;
    for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
        threads.emplace_back(processor);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
