            // If the node to be removed is the head, update the head pointer directly
            if (current == *head) {
                *head = current->next;
            } else {
                // Otherwise, update the prev node's next pointer to skip the node to be removed
                current->prev->next = current->next;
            }

            // If the node to be removed was the last one in the list, update the tail pointer
            if (current == *head) {
                *head = NULL;
            }

