#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <sys/mman.h>
#include <string.h>
#include <pthread.h>
#include <syslog>

typedef struct {
    time_t timestamp;
    uint32_t sequence_number;
} Header;

typedef struct {
    void *data;
    size_t size;
} Payload;

typedef struct {
    Header header;
    Payload payload;
    uint32_t checksum;
} MessageBuffer;

#define BUFFER_SIZE 4096

void rolling_hash(const void *data, size_t len, uint32_t *checksum) {
    const unsigned char *buf = (const unsigned char *) data;
    for (size_t i = 0; i < len; ++i) {
        *checksum = (*checksum << 8) ^ *buf++ ^ ((*checksum >> 24) & 0xff);
    }
}

MessageBuffer* create_message_buffer(int fd1, int fd2, const char *logfile) {
    MessageBuffer *msg_buf = malloc(sizeof(MessageBuffer));
    if (!msg_buf) {
        syslog(LOG_ERR, "Out of memory error");
        return NULL;
    }

    if (fd1 < 0 || fd2 < 0) {
        syslog(LOG_ERR, "Invalid file descriptor error");
        free(msg_buf);
        return NULL;
    }

    int fp1 = dup(fd1);
    int fp2 = dup(fd2);

    if (fp1 == -1 || fp2 == -1) {
        syslog(LOG_ERR, "Failed to duplicate file descriptor error");
        free(msg_buf);
        return NULL;
    }

    off_t offset1 = lseek(fp1, 0, SEEK_CUR);
    off_t offset2 = lseek(fp2, 0, SEEK_CUR);

    if (offset1 == -1 || offset2 == -1) {
        syslog(LOG_ERR, "Failed to get current offset error");
        close(fp1);
        close(fp2);
        free(msg_buf);
        return NULL;
    }

    void *payload_data = mmap(NULL, BUFFER_SIZE, PROT_READ, MAP_PRIVATE, fp1, offset1);
    if (payload_data == MAP_FAILED) {
        syslog(LOG_ERR, "mmap error");
        close(fp1);
        close(fp2);
        free(msg_buf);
        return NULL;
    }

    void *payload_data2 = mmap(NULL, BUFFER_SIZE, PROT_READ, MAP_PRIVATE, fp2, offset2);
    if (payload_data2 == MAP_FAILED) {
        syslog(LOG_ERR, "mmap error");
        munmap(payload_data, BUFFER_SIZE);
        close(fp1);
        close(fp2);
        free(msg_buf);
        return NULL;
    }

    size_t payload_size = BUFFER_SIZE;
    uint32_t checksum = 0;
    rolling_hash(payload_data, payload_size, &checksum);
    rolling_hash(payload_data2, payload_size, &checksum);

    msg_buf->header.timestamp = time(NULL);
    msg_buf->header.sequence_number++;
    msg_buf->payload.data = malloc(payload_size * 2);
    if (!msg_buf->payload.data) {
        syslog(LOG_ERR, "Out of memory error");
        munmap(payload_data, BUFFER_SIZE);
        munmap(payload_data2, BUFFER_SIZE);
        close(fp1);
        close(fp2);
        free(msg_buf);
        return NULL;
    }

    memcpy(msg_buf->payload.data, payload_data, payload_size);
    memcpy((char *) msg_buf->payload.data + payload_size, payload_data2, payload_size);

    msg_buf->checksum = checksum;

    close(fp1);
    close(fp2);
    return msg_buf;
}
```

This code defines a `MessageBuffer` struct containing a header, payload, and checksum. The `create_message_buffer()` function takes two file descriptors as arguments, dups them for reading purposes, calculates the payload size and checksum, and dynamically allocates memory for the message buffer. It also logs errors using syslog to the specified logfile. The function handles invalid file descriptors, out-of-memory conditions, and corrupted payload data. Upon completion, it frees all allocated memory.']

