```cpp
#include <deque>

class RollingAverage {
public:
    void Add(int value) {
        currentValues_.push_back(value);
        if (currentValues_.size() > maxValues_) {
            currentValues_.pop_front();
        }
        CalculateAverage();
    }

    int GetAverage() const { return average_; }

private:
    void CalculateAverage() {
        average_ = 0;
        for (const auto& value : currentValues_) {
            average_ += value;
        }
        if (!currentValues_.empty()) {
            average_ /= static_cast<int>(currentValues_.size());
        }
    }

    int currentValues_[60]; // 1 minute rolling average buffer
    std::deque<int> currentValues_;
    int maxValues_ = 60;
    int average_ = 0;
};
