typedef struct NetworkEntity {
    sockaddr_in addr;
    int port;
    bool isConnected;
    pthread_mutex_t lock;
} NetworkEntity;

void log(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] %s\n", timestamp, message);
}

void validate_and_populate(NetworkEntity *entity, const char *ip, int port) {
    memset(entity, 0, sizeof(NetworkEntity));

    if (strlen(ip) != INET_ADDRSTRLEN || inet_pton(AF_INET, ip, &entity->addr.sin_addr) <= 0) {
        log("Invalid IP address.");
        return;
    }

    entity->addr.sin_family = AF_INET;
    entity->addr.sin_port = htons(port);

    if (port < 1 || port > 65535) {
        log("Invalid port number.");
        return;
    }

    pthread_mutex_init(&entity->lock, NULL);
}

NetworkEntity *initialize_and_populate(const char *ip, int port) {
    NetworkEntity *entity = malloc(sizeof(NetworkEntity));

    if (!entity) {
        log("Out of memory.");
        return NULL;
    }

    validate_and_populate(entity, ip, port);

    return entity;
}
```

