#include <boost/property_tree/json_parser.hpp>

class NetworkEvent {
public:
    uint64_t id;
    std::chrono::steady_clock::time_point timestamp;
    std::string payloadType;
    std::vector<double> values;

    NetworkEvent(uint64_t id, std::chrono::steady_clock::time_point timestamp, const std::string& payloadType)
        : id(id), timestamp(timestamp), payloadType(payloadType), values() {}

    void appendValue(double value) {
        if (values.size() >= 5)
            values.pop_front();
        values.push_back(value);
    }
};

class EventPool {
public:
    std::map<uint64_t, NetworkEvent*> events;
    std::vector<uint64_t> availableIds;
    uint64_t maxIdPoolSize = 1000;
    uint64_t maxDuplicateCountBeforeFlush = 100;
    uint64_t idPoolFlushInterval = 1000; // in milliseconds

    EventPool() { reset(); }

    void reset() {
        events.clear();
        availableIds.clear();
        if (availableIds.size() < maxIdPoolSize)
            std::generate_n(std::inserter(availableIds, availableIds.end()), maxIdPoolSize - availableIds.size(), []() { return ++idCounter; });
    }

    uint64_t allocateEventId() {
        if (availableIds.empty())
            reset();
        auto id = availableIds.back();
        availableIds.pop_back();
        return id;
    }

    void deallocateEventId(uint64_t id) {
        events.erase(id);
        if (events.size() > maxDuplicateCountBeforeFlush && std::chrono::steady_clock::now().time_since_epoch().count() - lastResetTime.time_since_epoch().count() > idPoolFlushInterval)
            reset();
    }

private:
    static uint64_t idCounter;
    std::chrono::steady_clock::time_point lastResetTime;
};

