struct NetworkEntity {
    char ip[32];
    int port;
    int connectionStatus; // 0: disconnected, 1: connected
    pthread_mutex_t mutex;
};

typedef struct NetworkEntity *NetworkEntityPtr;

void log_event(const char *message) {
    openlog("NetworkEntity", LOG_PID | LOG_CONS, LOG_INFO);
    syslog(LOG_INFO, message);
}

NetworkEntityPtr createNetworkEntity(const char *ip, int port) {
    NetworkEntityPtr entity = malloc(sizeof(struct NetworkEntity));
    if (!entity) {
        log_event("Error: Memory allocation failure");
        return NULL;
    }

    memcpy(entity->ip, ip, sizeof(entity->ip));
    entity->port = port;
    entity->connectionStatus = 0;
    pthread_mutex_init(&entity->mutex, NULL);

    log_event("Created network entity: IP " IP_STR ", Port " PORT);
    return entity;
}

void destroyNetworkEntity(NetworkEntityPtr entity) {
    if (!entity) return;

    pthread_mutex_destroy(&entity->mutex);
    free(entity);

    log_event("Destroyed network entity: IP " IP_STR ", Port " PORT);
}

int addToNetworkEntities(NetworkEntityPtr **entities, NetworkEntityPtr entity) {
    int size = 0;

    if (!entities || !entity) return -1;

    for (; size < *(&entities + 1); ++size) {
        if (!(*entities)[size]) break;
    }

    *(&entities[size]) = entity;
    (*(&entities + 1))++;
    return 0;
}

NetworkEntityPtr findNetworkEntityByIP(const char *ip, NetworkEntityPtr *entities, int size) {
    for (int i = 0; i < size; ++i) {
        if (!(*entities)[i]) continue;
        if (strcmp((*entities)[i]->ip, ip) == 0) return (*entities)[i];
    }
    return NULL;
}

