typedef struct {
    uint32_t rxi;
    uint32_t rnti;
    uint32_t crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct array_s {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} Array;

Array* create_array() {
    Array* array = malloc(sizeof(Array));
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->data = calloc(array->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        perror("Failed to allocate memory for data array");
        free(array);
        return NULL;
    }
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void resize_array(Array* array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to reallocate memory for data array");
        return;
    }
    array->data = new_data;
    array->capacity = new_capacity;
}

void init_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->rxi = 12345678; // Set RX_UE_INFORMATION_TAG value appropriately
    pdu->rnti = 98765432; // Set RNTI value appropriately
    pdu->crc_indication = rand();
}

void* populate_array(void* data) {
    Array* array = (Array*)data;
    for (size_t i = array->size; i < array->capacity; ++i) {
        pthread_mutex_lock(&array->mutex);
        if (array->size == array->capacity) resize_array(array);
        NFAPI_CRC_INDICATION_PDU_T* pdu = &array->data[array->size];
        init_pdu(pdu);
        array->size++;
        pthread_mutex_unlock(&array->mutex);
    }
    return NULL;
}

void populate_and_initialize_array(Array* array) {
    pthread_t threads[NUM_THREADS];
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, populate_array, array)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Failed to join thread");
            exit(EXIT_FAILURE);
        }
    }
}
