    NFIXML_MESSAGE_T** messageList;
    size_t totalAllocated;
    size_t maxStructures;
    pthread_mutex_t mutex;
} ThreadData;

void NFIPDU_HEADER_T_init(NFIPDU_HEADER_T* header, uint16_t len) {
    memset(header, 0, sizeof(NFIPDU_HEADER_T));
    header->length = len;
}

NFIXML_MESSAGE_T* createMessage() {
    NFIXML_MESSAGE_T* msg = mmap(NULL, sizeof(NFIXML_MESSAGE_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (msg == MAP_FAILED) {
        perror("mmap: ");
        return NULL;
    }
