Element* create_list(int N) {
    if (N <= 0 || N > 10000) {
        perror("Invalid list size");
        return NULL;
    }

    Element *head = NULL, *tail = NULL, *current;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; ++i) {
        current = (Element*) malloc(sizeof(Element));
        if (!current) {
            perror("Memory allocation error");
            return NULL;
        }
        current->index = i;
        current->next = NULL;

        pthread_mutex_lock(&mutex);
        if (!head) {
            head = current;
            tail = current;
        } else {
            tail->next = current;
            tail = current;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Parallel population using threads
    const int threadCount = (N > 500) ? N / 5 : 10;
    Element **elements = calloc(threadCount, sizeof(Element*));
