import hashlib
import os
from functools import lru_cache

@lru_cache(maxsize=None)
def chunked_read(filepath, size=8192):
    with open(filepath, 'rb') as file:
        while True:
            data = file.read(size)
            if not data:
                break
            yield data

def md5sum(filepath):
    hasher = hashlib.md5()
    for chunk in chunked_read(filepath):
        hasher.update(chunk)
    return hasher.hexdigest()
