**C++ Log Manager Implementation (log_manager.cpp)**

```cpp
#include "log_manager.h"

void LogManager::push(const LogEntry& entry) {
  std::unique_lock<std::mutex> lock(mutex_);
  queue_.push(entry);
  if (!worker_) {
    worker_ = std::thread(&LogManager::flush, this);
  }
  lock.unlock();
}

void LogManager::flush() {
  while (true) {
    // Adaptive logging rate based on system resources and network latency
    std::this_thread::sleep_for(std::chrono::milliseconds(100));

    std::unique_lock<std::mutex> lock(mutex_);
    if (queue_.empty()) {
      lock.unlock();
      return;
    }

    LogEntry entry = queue_.front();
    logs_.push_back(entry);
    if (logs_.size() > capacity_) {
      // Dynamic resizing based on load conditions
      resize();
    }
    queue_.pop();
  }
}
