NFIXML_MESSAGE_T* create_message(size_t payload_length) {
    NFIXML_MESSAGE_T *msg = malloc(sizeof(NFIXML_MESSAGE_T));
    if (!msg) return NULL;

    msg->payload_length = payload_length;
    msg->message_payload = calloc(payload_length, 1);
    if (!msg->message_payload) {
        free(msg);
        return NULL;
    }

    return msg;
}

NFIXML_MESSAGE_T* create_messages(size_t num_msgs) {
    NFIXML_MESSAGE_T *msgs = malloc(num_msgs * sizeof(NFIXML_MESSAGE_T));
    if (!msgs) return NULL;

    for (size_t i = 0; i < num_msgs; ++i) {
        msgs[i] = create_message((rand() % MAX_PAYLOAD_LENGTH) + MIN_PAYLOAD_LENGTH);
        if (!msgs[i]) {
            free(msgs);
            return NULL;
        }
    }

    return msgs;
}

void free_messages(NFIXML_MESSAGE_T *msgs, size_t num_msgs) {
    for (size_t i = 0; i < num_msgs; ++i) {
        free(msgs[i].message_payload);
        free(msgs[i]);
    }
    free(msgs);
}
