typedef struct NODE {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct NODE *next;
} NODE;

void init_list(NODE **head) {
    *head = NULL;
}

void push_back(NODE **head, NFAPI_CRC_INDICATION_PDU_T data) {
    NODE *newNode = malloc(sizeof(NODE));
    if (!newNode) return;

    newNode->data = data;
    newNode->next = NULL;

    if (*head == NULL) {
        *head = newNode;
        return;
    }

    NODE *current = *head;
    while (current->next != NULL) current = current->next;
    current->next = newNode;
}

NFAPI_CRC_INDICATION_PDU_T* get_by_index(NODE **head, size_t index) {
    NODE *current = *head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    if (current == NULL) return NULL;
    else return &current->data;
}
