    crc_capacity = max_crcs;
    messages = calloc(message_capacity, sizeof(Node*));
    crcs = calloc(crc_capacity, sizeof(Node*));
    pthread_mutex_init(&messages_lock, NULL);
    pthread_mutex_init(&crcs_lock, NULL);
}

void resize_collections() {
    int new_capacity;
    if (message_size / message_capacity >= 0.75)
        new_capacity = message_capacity * 2;
    else
        new_capacity = message_capacity + 1000;
    messages = realloc(messages, new_capacity * sizeof(Node*));
    crcs = realloc(crcs, new_capacity * sizeof(Node*));
}

void add_message(NFIXML_MESSAGE msg) {
    pthread_mutex_lock(&messages_lock);
    if (message_size == message_capacity) resize_collections();
    messages[message_size] = malloc(sizeof(Node));
    messages[message_size]->data = msg;
    messages[message_size]->next = NULL;
    message_size++;
    pthread_mutex_unlock(&messages_lock);
}

// Other operations for messages and crcs, like update and remove

// Cache mechanism for frequently accessed structures
