int cache_head, cache_tail;

void add_to_cache(int index) {
    if (cache_tail - cache_head >= MAX_CACHE_SIZE) {
        for (int i = cache_head; i < cache_tail; i++) cache[i % MAX_CACHE_SIZE] = 0;
        cache_tail = 0;
    }
    cache[cache_tail++] = index;
}
