import secrets

class DeviceRegistration:
    def __init__(self, device_id):
        self.device_id = device_id
        self.session_token = None

def handle_client(websocket, path):
    device = DeviceRegistration(path)
    asyncio.create_task(register_and_handle_messages(websocket, device))

async def register_and_handle_messages(websocket, device):
    try:
        await websocket.send("Welcome to the system! Send your messages.")
        received_msg = await websocket.recv()
        # Store session token in persistent storage
        device.session_token = secrets.token_hex(16)
        # Handle device reconnections and retries with exponential backoff
    except Exception as e:
        print(f"Error occurred: {e}")

if __name__ == "__main__":
    server = serve(handle_client, 'localhost', 8765)
    asyncio.get_event_loop().run_until_complete(server)
    asyncio.get_event_loop().run_forever()
