#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

typedef struct {
    size_t total;
    size_t uploaded;
} UploadProgress;

size_t WriteMemChunk(void *ptr, size_t size, size_t nmemb, void *userp) {
    UploadProgress *up = static_cast<UploadProgress *>(userp);
    up->uploaded += size * nmemb;
    return size * nmemb;
}

CURLcode upload_file(const char *url, const char *filename, UploadProgress *up) {
    CURL *curl;
    FILE *fp;
    CURLcode res;
    struct curl_httppost *formpost = NULL;
    struct curl_httppart *lastpart = NULL;
    struct curl_slist *headers = NULL;

    // Initialize the curl session
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize curl\n");
        return CURLE_FAILED_INIT;
    }

    // Open the file for reading
    fp = fopen(filename, "rb");
    if (!fp) {
        fprintf(stderr, "Could not open %s\n", filename);
        curl_easy_cleanup(curl);
        return CURLE_COULDNT_READ_FILE;
    }

    // Prepare the multipart form data using curl_formadd() and add our file to it.
    curl_formadd(&formpost, &lastpart, CURLFORM_COPYNAME, "file",
                  CURLFORM_CONTENTTYPE, "application/octet-stream",
                  CURLFORM_FILENAME, filename,
                  CURLFORM_FILE, fp);

    // Set up our progress callback and limit the data size and rate.
    curl_easy_setopt(curl, CURLOPT_UPLOAD, 1L);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemChunk);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, up);
    curl_easy_setopt(curl, CURLOPT_READDATA, fp);
    curl_easy_setopt(curl, CURLOPT_INFILESIZE, up->total = strlen((char*)fp)+1); // Calculate file size without considering null terminator for curl_formadd() call.
    curl_easy_setopt(curl, CURLOPT_LOW_SPEED_LIMIT, 100L); // Set the minimum transfer speed in bytes per second (bps).
    curl_easy_setopt(curl, CURLOPT_LOW_SPEED_TIME, 5L);     // Set the time in seconds to pause when we drop below the speed limit.

    // Set the URL and other headers if required.
    curl_easy_setopt(curl, CURLOPT_URL, url);
    headers = curl_slist_append(headers, "Expect:");  // Disable Expect header to improve compatibility with some servers.
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Perform the HTTP POST request and clean up.
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to upload %s: %s\n", filename, curl_easy_strerror(res));
    } else {
        printf("Uploaded %s successfully.\n", filename);
    }

    // Clean up and return the result code.
    fclose(fp);
    curl_easy_cleanup(curl);
    curl_formfree(formpost);
    curl_slist_free_all(headers);
    curl_global_cleanup();

    return res;
}
