#include <limits>
#include <memory>

using boost::asio::io_service;
using boost::asio::aio_some;
using boost::filesystem::path;
using boost::container::small_vector;

struct Line {
    small_vector<std::string, 10> fields; // Growable vector for line components
    double average = std::numeric_limits<double>::max(); // Flag to mark unprocessed lines
};

class Processor {
public:
    explicit Processor(double threshold) : threshold_(threshold) {}

    void processLines() {
        while (true) {
            Line line;
            auto it = processedLines_.insert(line);
            if (!it.second) continue; // Skip processing already processed lines

            for (auto& field : line.fields) field.clear(); // Reset fields for reuse

            std::ifstream file(filePath_, std::ios::in);
            if (!file) {
                log_(LogLevel::Error, "Cannot open file: ", filePath_);
                continue;
            }

            // Asynchronously read line by line
            boost::asio::aio_read(file, boost::asio::transfer_exactly(std::streamsize(4096)), AIOCB(&line, &it));
        }
    }

private:
    void AIOCB(Line* line, std::pair<iterator, bool>* result, const boost::system_error* error) {
        if (error) {
            log_(LogLevel::Error, "Read error in file: ", filePath_, ": ", error->what());
            return;
        }

        char buf[4096];
        std::streamsize bytesTransferred = *result->first - result->second;
        if (bytesTransferred == 0) { // EOF reached
            if (!file_.is_open()) return; // Check if file is still open
            processLine(line, buf, bytesTransferred);
            return;
        }

        std::copy_n(buf, static_cast<std::streamsize>(bytesTransferred), std::back_inserter(line->fields));

        // Asynchronously read more data from the file
        boost::asio::aio_read(file_, boost::asio::transfer_exactly(std::streamsize(4096)), AIOCB(line, result, nullptr));
    }

    void processLine(Line* line, const char* data, std::streamsize length) {
        std::istringstream iss(data);
        small_vector<double, 10> numbers; // Growable vector for numerical values
        double currentValue;

        while (iss >> currentValue) {
            if (currentValue < 0 || currentValue > 100) {
                currentValue = 0;
                log_(LogLevel::Warning, "Invalid value: ", currentValue, " in file: ", filePath_);
            }
            numbers.push_back(currentValue);
        }

        if (numbers.size() < 5) {
            double average = std::accumulate(numbers.begin(), numbers.end(), 0.0, [](double a, double b) { return a + b; });
            average /= static_cast<double>(numbers.size());
            line->fields.push_back(std::to_string(average));
        } else {
            double sum = std::accumulate(numbers.rbegin(), numbers.rend(), 0.0, [](double a, double b) { return a + b; });
            double average = sum / 5;
            line->fields.push_back(std::to_string(average));
        }

        // Convert comma-separated format
        std::stringstream ss;
        for (const auto& field : line->fields) {
            if (!ss.empty()) ss << ',';
            ss << field;
        }
        line->fields[0] = ss.str();

        file_.close(); // Release file resource
    }

    void log_(LogLevel level, const std::string& message, const std::string& args = "") {
        // Implement logging functionality here
    }

    path filePath_;
    double threshold_;
    io_service ioservice_;
    std::ifstream file_;
    std::multimap<Line, std::pair<iterator, bool>> processedLines_;
};

enum class LogLevel { Info, Warning, Error };
```

