typedef struct Bucket {
    NFAPI_CRC_INDICATION_PDU_T data[BUCKET_SIZE];
    pthread_mutex_t mutex;
    size_t count;
} Bucket;

struct ExtensibleArray {
    Bucket *buckets;
    size_t num_buckets;
    size_t current_index;
    pthread_mutex_t mutex;
};

void init_extensible_array(struct ExtensibleArray *ea) {
    ea->num_buckets = 1;
    ea->current_index = 0;
    ea->buckets = mmap(NULL, sizeof(Bucket) * ea->num_buckets, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ea->buckets == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < ea->num_buckets; ++i) {
        pthread_mutex_init(&ea->buckets[i].mutex, NULL);
        ea->buckets[i].count = 0;
    }

    pthread_mutex_init(&ea->mutex, NULL);
}

void resize_extensible_array(struct ExtensibleArray *ea) {
    if (ea->current_index + BUCKET_SIZE >= MAX_ELEMENTS) return;

    Bucket *new_buckets = realloc(ea->buckets, sizeof(Bucket) * (2 * ea->num_buckets));
    if (!new_buckets) {
        perror("realloc failed");
        exit(EXIT_FAILURE);
    }

    ea->buckets = new_buckets;
    ea->num_buckets *= 2;
}

NFAPI_CRC_INDICATION_PDU_T *get_next_element(struct ExtensibleArray *ea) {
    while (true) {
        pthread_mutex_lock(&ea->mutex);

        if (ea->current_index + BUCKET_SIZE >= MAX_ELEMENTS) break;

        size_t index = ea->current_index;
        if (ea->buckets[index].count < BUCKET_SIZE) {
            ea->current_index++;
            pthread_mutex_unlock(&ea->mutex);
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T *element = &ea->buckets[index].data[ea->buckets[index].count - 1];
        ea->current_index++;
        ea->buckets[index].count--;
        pthread_mutex_unlock(&ea->mutex);

        element->crc_indication.crcflag = rand();

        return element;
    }

    resize_extensible_array(ea);
    return get_next_element(ea);
}

void insert_element(struct ExtensibleArray *ea, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&ea->mutex);

    size_t index = ea->current_index % ea->num_buckets;
    pthread_mutex_lock(&ea->buckets[index].mutex);

    if (ea->buckets[index].count < BUCKET_SIZE) {
        memcpy(&ea->buckets[index].data[ea->buckets[index].count], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        ea->buckets[index].count++;
    } else {
        pthread_mutex_unlock(&ea->buckets[index].mutex);
        resize_extensible_array(ea);
        insert_element(ea, element);
    }

    pthread_mutex_unlock(&ea->buckets[index].mutex);
    pthread_mutex_unlock(&ea->mutex);
}

void print_stats(struct ExtensibleArray *ea) {
    printf("Current size: %zu\n", ea->current_index);
    printf("Available capacity: %zu\n", (MAX_ELEMENTS - ea->current_index) + BUCKET_SIZE * ea->num_buckets - ea->current_index);
}

int main() {
    struct ExtensibleArray ea;
    init_extensible_array(&ea);

    NFAPI_CRC_INDICATION_PDU_T *element = get_next_element(&ea);

    // Periodic monitoring and reporting of the current size and available capacity
    print_stats(&ea);

    // Save and load data from disk for long-running applications
    save_data(&ea);
    struct ExtensibleArray loaded_ea;
    load_data(&loaded_ea);

    // Other components of the system can call insert_element() to add more elements
    insert_element(&ea, element);

    return 0;
}
