    struct NFAPI_CRC_INDICATION_PDU_T* newList = mmap(NULL, capacity * 2 * sizeof(struct NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, fd, 0);
