    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

void* mmap(size_t length, int prot, int flags, int fd, off_t offset);

struct sync_array* sync_array_init(size_t initial_size) {
    struct sync_array* array = malloc(sizeof(struct sync_array));
    if (!array) return NULL;

    array->data = mmap(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0, 0);
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_size;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void sync_array_push(struct sync_array* array, const NFAPI_CRC_INDICATION_PDU_T* item) {
    pthread_mutex_lock(&array->lock);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = mmap(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0, 0);
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return;
        }

        memcpy(new_data, array->data, array->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(array->data);

        array->data = new_data;
        array->capacity = new_capacity;
    }

    memcpy((array->data + array->size), item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++array->size;

    pthread_mutex_unlock(&array->lock);
}

