**Function for managing Network Configuration Parameters (NCP)**
```c
#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int NCPID;
    size_t num_RATs;
    int* RATs;
    size_t num_modes;
    const char** modes;
} NCP_T;

typedef struct Node {
    NCP_T data;
    struct Node* next;
} Node_T;

Node_T* head = NULL;
pthread_mutex_t lock;
extern void update_from_config_service(NCP_T ncp);

void insert_ncp(int id, size_t num_RATs, const int* RATs, size_t num_modes, const char** modes) {
    Node_T* new_node = malloc(sizeof(Node_T));
    if (!new_node) return;

    new_node->data.NCPID = id;
    new_node->data.num_RATs = num_RATs;
    new_node->data.RATs = malloc(num_RATs * sizeof(int));
    if (!new_node->data.RATs) return;
    memcpy(new_node->data.RATs, RATs, num_RATs * sizeof(int));

    new_node->data.num_modes = num_modes;
    new_node->data.modes = malloc(num_modes * sizeof(const char*));
    if (!new_node->data.modes) return;
    memcpy(new_node->data.modes, modes, num_modes * sizeof(const char*));

    pthread_mutex_lock(&lock);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&lock);
}

void remove_ncp(int id) {
    Node_T* current, *prev;

    pthread_mutex_lock(&lock);
    current = head;
    prev = NULL;

    while (current != NULL && current->data.NCPID != id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current->data.RATs);
    size_t num_modes = current->data.num_modes;
    for (size_t i = 0; i < num_modes; ++i) {
        free(current->data.modes[i]);
    }
    free(current->data.modes);
    free(current);
    pthread_mutex_unlock(&lock);
}

NCP_T* get_ncp(int id) {
    Node_T* current = head;

    while (current != NULL && current->data.NCPID != id) {
        current = current->next;
    }

    if (current == NULL) return NULL;

    return &current->data;
}
