extern void validate_pdus(LTE_RRC_CONFIGURATION_UPDATE_PDU_T pdu);

void insert_pdu(int cell_id, LTE_PHYSICAL_LAYER_PARAMETERS_T physical_layer_params, const char* sib1_data) {
    PDU_Node_T* new_node = malloc(sizeof(PDU_Node_T));
    if (!new_node) return;

    new_node->data.CELL_ID = cell_id;
    new_node->data.PHYSICAL_LAYER_PARAMS = physical_layer_params;
    new_node->data.SIB1_DATA = sib1_data;

    pthread_mutex_lock(&lock);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&lock);
}

void remove_pdu(int cell_id) {
    PDU_Node_T* current, *prev;

    pthread_mutex_lock(&lock);
    current = head;
    prev = NULL;

    while (current != NULL && current->data.CELL_ID != cell_id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    pthread_mutex_unlock(&lock);
}

LTE_RRC_CONFIGURATION_UPDATE_PDU_T* get_pdu(int cell_id) {
    PDU_Node_T* current = head;

    while (current != NULL && current->data.CELL_ID != cell_id) {
        current = current->next;
    }

    if (current == NULL) return NULL;

    return &current->data;
}
