public:
    void add(const UserProfile& profile) {
        std::unique_lock<std::mutex> lock(mtx);
        profiles.insert(profile);
    }

    void update(const std::string& name, const UserProfile& profile) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = profiles.find(name);
        if (it != profiles.end()) {
            it->second = profile;
        }
    }

    void remove(const std::string& name) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = profiles.find(name);
        if (it != profiles.end()) {
            profiles.erase(it);
        }
    }

    const UserProfile* get(const std::string& name) const {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = profiles.find(name);
        if (it != profiles.end()) {
