#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void free_fields(char** fields) {
    for (size_t i = 0; fields[i]; ++i) {
        free(fields[i]);
    }
    free(fields);
}

int get_fields_count(const char* line, const char delimiter) {
    int count = 0;
    for (char c = *line++; c != '\0'; c = *(line++)) {
        if (c == delimiter) ++count;
    }
    return ++count;
}

char** split_line(const char* line, const char delimiter, size_t* fields_count) {
    size_t len = strlen(line);
    size_t num_fields = get_fields_count(line, delimiter);
    char** fields = malloc((num_fields + 1) * sizeof(char*));
    char* token = malloc((len + 1) * sizeof(char));

    size_t current_field = 0;
    int in_field = 0;
    for (char c = *line++; c != '\0'; c = *(line++)) {
        if (c == delimiter && !in_field) {
            token[current_field] = '\0';
            fields[current_field++] = strdup(token);
            in_field = 1;
            current_field %= num_fields + 1;
            memset(token, 0, sizeof(token));
        } else if (c != delimiter && in_field) {
            token[current_field++] = c;
        }
    }
    if (in_field) fields[current_field - 1] = NULL;
    *fields_count = num_fields;
    free(token);
    return fields;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s delimiter file\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char delimiter = argv[1][0];
    FILE* file = fopen(argv[2], "r");
    if (!file) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    size_t line_size = 0;
    char* line = malloc(line_size * sizeof(char));
    char** fields = NULL;
    int fields_count;

    while (getdelim(&line_size, &line_size, delimiter, file) != EOF) {
        if ((fields_count = get_fields_count(line, delimiter)) < 3) {
            int sum = 0;
            for (int i = 0; i < fields_count; ++i) {
                sum += atoi(fields[i]);
            }
            float avg = static_cast<float>(sum) / fields_count;
            sprintf(fields[fields_count], "%f", avg);
        } else {
            int* arr = calloc(3, sizeof(int));
            for (int i = 0; i < fields_count - 1; ++i) {
                arr[i] = atoi(fields[i]);
            }
            qsort(arr, 3, sizeof(int), intComparator);
            float sum = arr[0] + arr[1] + arr[2];
            sprintf(fields[fields_count - 1], "%f", sum / 3.0);
        }
        free_fields(fields);
        fields = split_line(line, delimiter, &fields_count);
    }

    free(line);
    fclose(file);

    return EXIT_SUCCESS;
}

int intComparator(const void* a, const void* b) {
    return *(static_cast<const int*>(a)) - *(static_cast<const int*>(b));
}
```

