#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>

struct transaction {
    char* fields;
    size_t len;
};

void read_csv(const char* filename, const char delimiter) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    size_t line_len = 0;
    char c;
    while ((c = fgetc(file)) != EOF) {
        line_len++;
    }
    rewind(file);

    struct transaction* transactions = malloc((line_len + 1) * sizeof(struct transaction));
    size_t num_transactions = 0;

    char line[line_len];
    size_t field_count = 0;
    while (fgets(line, line_len + 1, file)) {
        size_t i = 0;
        struct transaction* current_transaction = transactions + num_transactions++;
        current_transaction->fields = malloc((strlen(line) + 1) * sizeof(char));
        strcpy(current_transaction->fields, line);
        current_transaction->len = strlen(line);

        char* token = strtok(line, &delimiter);
        while (token) {
            if (field_count >= 3) break;
            size_t new_len = current_transaction->len + strlen(token) + 2; // for delimiter and null terminator
            current_transaction->fields = realloc(current_transaction->fields, new_len);
            strcat(current_transaction->fields, token);
            strcat(current_transaction->fields, &delimiter);
            field_count++;
            token = strtok(NULL, &delimiter);
        }
    }

    fclose(file);

    // Process transactions and calculate totals
    struct transaction* last_three = transactions + (num_transactions - 4 < 0 ? num_transactions : num_transactions - 3);
    double total = 0;
    for (size_t i = 0; i < 3 && i < num_transactions; ++i) {
        sscanf(last_three[i].fields, "%lf", &total);
        last_three[i].len += sprintf(last_three[i].fields + last_three[i].len, "\tTotal: %.2f\n", total);
    }

    free(transactions);
}

int main(int argc, char** argv) {
    const char delimiter = ',';
    const char* filename;

    static struct option long_options[] = {
        {"delimiter", required_argument, 0, 'd'},
        {"help", no_argument, 0, 'h'},
        {0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "d:h", long_options, NULL)) != -1) {
        switch (opt) {
            case 'd': delimiter = optarg[0]; break;
            case 'h': printf("Usage: %s [-d delimiter] filename\n", argv[0]); return 0;
            default: printf("Unknown option: -%c\n", optopt); return 1;
        }
    }

    if (optind >= argc) {
        printf("Missing argument: filename\n");
        return 1;
    }

    filename = argv[optind];
    read_csv(filename, delimiter);

    return 0;
}
```
