        printf("Usage: %s [options] <file|directory> ...\n", argv[0]);
        return 1;
    }

    // Initialize the regex pattern for excluding directories
    regcomp(&exclude_pattern, ".*/(exclude)/", REG_EXTENDED | REG_ICASE);

    Bundle* bundle = load_bundle(argv[argc - 1]);

    if (!bundle) {
        return 1;
    }

    // Process each input file or directory, recursively processing subdirectories
    for (int i = argc - 2; i >= 0; --i) {
        struct stat st;
        if (stat(argv[i], &st) < 0 || S_ISDIR(st.st_mode)) {
            batch_process_directory(argv[i], true, "");
