    if (!sc) return NULL;

    const char *name, *port_str, *protocol, *timeout_str;
    int port, timeout;
    bool ssl_enabled, is_http;
    char *cert_path = NULL, *key_path = NULL;

    name = json_object_get_string_member(service_node, "service_name");
    if (!name || !is_valid_service_name(name)) {
        free(sc);
        return NULL;
