    port = atoi(port_str);
    if (!is_valid_port(port)) {
        free(sc);
        return NULL;
    }

    protocol = json_object_get_string_member(service_node, "protocol");
    if (!protocol) {
        free(sc);
        return NULL;
    }

    timeout_str = json_object_get_string_member(service_node, "timeout");
    if (!timeout_str) {
        free(sc);
        return NULL;
    }
    timeout = atoi(timeout_str);
    if (!is_valid_timeout(timeout)) {
        free(sc);
        return NULL;
    }

    sc->service_name = name;
    sc->port_number = port;
    sc->protocol_version = "HTTP/1.1"; // Default value
    sc->timeout = timeout;
    sc->ssl_enabled = false;
    sc->cert_path = NULL;
    sc->key_path = NULL;

