        const char *pv = json_object_get_string_member(service_node, "protocol_version");
        if (strcmp(pv, "HTTP/1.1") == 0 || strcmp(pv, "HTTP/2") == 0 || strcmp(pv, "HTTP/3") == 0) {
            sc->protocol_version = pv;
        }
    }

    if (json_object_has_member(service_node, "ssl_enabled")) {
        const char *enabled_str = json_object_get_string_member(service_node, "ssl_enabled");
        ssl_enabled = strcmp(enabled_str, "true") == 0;

        if (ssl_enabled) {
            sc->cert_path = json_object_get_string_member(service_node, "cert_path");
            sc->key_path = json_object_get_string_member(service_node, "key_path");

            if (!sc->cert_path || !sc->key_path) {
