// Custom memory pool structure
struct mem_pool {
    void *memory;
    size_t capacity;
    size_t allocated;
    pthread_mutex_t lock;
};

void mem_pool_init(struct mem_pool *pool, size_t size) {
    pool->capacity = size;
    pool->allocated = 0;
    pool->memory = malloc(size);
    if (!pool->memory) {
        fprintf(stderr, "Error: Failed to allocate memory for memory pool\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pool->lock, NULL);
}

void *mem_pool_get(struct mem_pool *pool) {
    void *ptr;
    pthread_mutex_lock(&pool->lock);
    if (pool->allocated < pool->capacity) {
        ptr = ((char *)pool->memory + pool->allocated);
        pool->allocated++;
    } else {
        fprintf(stderr, "Error: Memory pool is full\n");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void mem_pool_put(struct mem_pool *pool, void *ptr) {
    pthread_mutex_lock(&pool->lock);
    pool->allocated--;
    pthread_mutex_unlock(&pool->lock);
}

// External data source connection and validation functions (assume these are implemented elsewhere)
