} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t lock;
} node_t;

static node_t* head = NULL;
static size_t count = 0;
static bool error = false;

node_t* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    node_t *new_node = (node_t*) malloc(sizeof(node_t));
    if (!new_node) return NULL;

    new_node->data = *data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);

    return new_node;
}

void insert(const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!head) {
        head = create_node(data);
        count++;
        return;
    }

    node_t *current = head, *new_node = create_node(data);
    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        error = true;
        return;
    }

    pthread_mutex_lock(&current->lock);
    while (current->next && current->next->rnti < new_node->rnti) current = current->next;
    new_node->next = current->next;
    current->next = new_node;
    count++;
    pthread_mutex_unlock(&current->lock);
}

void delete(uint32_t rnti) {
    node_t *current = head, **prev = &head;
    while (current && current->rnti != rnti) {
        prev = &current->next;
        pthread_mutex_lock(&current->lock);
        current = current->next;
        pthread_mutex_unlock(&current->lock);
    }

    if (!current) return;

    pthread_mutex_lock(&current->lock);
    *prev = current->next;
    free(current);
    count--;
    pthread_mutex_unlock(&current->lock);
}

void clear() {
    node_t *current, *temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
    count = 0;
}

size_t get_count() {
    size_t count_local = 0;
    node_t *current = head;
    while (current) {
        pthread_mutex_lock(&current->lock);
        current = current->next;
        pthread_mutex_unlock(&current->lock);
        count_local++;
    }
    return count_local;
}

size_t get_unique_rntis() {
    size_t unique_rntis = 0, rnti_local = 0;
    node_t *current = head;
    while (current) {
        pthread_mutex_lock(&current->lock);
        current = current->next;
        if (current) pthread_mutex_unlock(&current->lock);

        rnti_local = current ? current->rnti : 0;
        if (rnti_local != rnti_local) continue; // ignore NULL rntis or invalid data

        pthread_mutex_lock(&current->lock);
        if (!current || current->next && current->next->rnti == rnti_local) {
            pthread_mutex_unlock(&current->lock);
            continue;
        }
        unique_rntis++;
        pthread_mutex_unlock(&current->lock);
    }
    return unique_rntis;
}

NFAPI_CRC_INDICATION_PDU_T* find(uint32_t rnti) {
    node_t *current = head;
    while (current) {
        pthread_mutex_lock(&current->lock);
        if (current->rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* data = &current->data;
            pthread_mutex_unlock(&current->lock);
            return data;
        }
        current = current->next;
        pthread_mutex_unlock(&current->lock);
    }
    return NULL;
}
