#include <iostream>
#include <unordered_map>
#include <vector>
#include <random>
#include <mutex>
#include <cstdlib>

const int MAX_RNTIS = 1000;
const int BLOCK_SIZE = 1024;

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
};

class DynamicList {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::unordered_map<uint32_t, int> rntiMap;
    std::mutex mtx;
    int capacity = 0;

public:
    DynamicList(int N) {
        if (N <= 0 || BLOCK_SIZE <= 0) {
            throw std::invalid_argument("Invalid input parameters");
        }

        capacity = (N / BLOCK_SIZE) * BLOCK_SIZE;
        data.reserve(capacity);
    }

    ~DynamicList() {
        std::cout << "Freeing memory..." << std::endl;
        data.clear();
    }

    void insert(const NFAPI_CRC_INDICATION_PDU_T& entry) {
        std::unique_lock<std::mutex> lock(mtx);

        if (rntiMap.count(entry.rnti)) {
            throw std::invalid_argument("RNTI already exists in the list");
        }

        data.push_back(entry);
        rntiMap[entry.rnti] = data.size() - 1;
    }

    void remove(uint32_t rnti) {
        std::unique_lock<std::mutex> lock(mtx);

        auto it = rntiMap.find(rnti);
        if (it == rntiMap.end()) {
            throw std::invalid_argument("RNTI not found in the list");
        }

        data[it->second] = data.back();
        data.pop_back();
        rntiMap.erase(it);
    }

    const NFAPI_CRC_INDICATION_PDU_T* getEntry(uint32_t rnti) {
        std::unique_lock<std::mutex> lock(mtx);

        auto it = rntiMap.find(rnti);
        if (it == rntiMap.end()) {
            return nullptr;
        }

        return &data[it->second];
    }
};
```

This example demonstrates a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures, using an unordered map and a mutex for thread-safe access. The constructor checks for valid input parameters and reserves memory based on the given N value. The insert and remove functions manage adding and deleting entries based on RNTI, ensuring data integrity through the use of a mutex. The getEntry function retrieves an entry based on RNTI, and a null pointer is returned if the RNTI is not found in the list.']

