```cpp
#include <vector>
#include <mutex>
#include <cstdlib>
#include <iostream>
#include <stdexcept>
#include <cassert>

struct LTE_RRC_MEASUREMENT_REPORT_T {
    int MEASUREMENT_REPORT_ID;
    int CELL_ID;
    int RSRP_LEVEL;
};

class MeasurementReportManager {
private:
    std::vector<LTE_RRC_MEASUREMENT_REPORT_T> reports_;
    const int MAX_ENTRIES = 1000;
    std::mutex mtx_;
    int rsrp_threshold_ = -125; // Default value for RSRP threshold

public:
    MeasurementReportManager(int rsrp_threshold) : rsrp_threshold_(rsrp_threshold) {}

    int initialize(size_t num_entries) {
        if (num_entries > MAX_ENTRIES) {
            std::cerr << "Error: Maximum number of entries exceeded" << std::endl;
            return -1;
        }

        reports_.resize(num_entries);

        // Dynamic memory allocation for each report structure
        LTE_RRC_MEASUREMENT_REPORT_T* reports_ptr = &reports_[0];
        for (size_t i = 0; i < num_entries; ++i) {
            reports_ptr[i].MEASUREMENT_REPORT_ID = i;
            reports_ptr[i].CELL_ID = std::rand() % 100 + 1;
            reports_ptr[i].RSRP_LEVEL = std::rand() % (rsrp_threshold_ - 50) + 50; // RSRP values within the specified threshold range
            ++reports_ptr;
        }

        return 0;
    }

    int addReport(const LTE_RRC_MEASUREMENT_REPORT_T& report) {
        std::unique_lock<std::mutex> lock(mtx_);
        if (reports_.size() >= MAX_ENTRIES) {
            // Replace the least recently added report with the new one
            reports_[0] = report;
            return 1;
        }

        reports_.push_back(report);
        return 0;
    }

    const LTE_RRC_MEASUREMENT_REPORT_T* getReportByID(int id) {
        std::unique_lock<std::mutex> lock(mtx_);
        for (const auto& report : reports_) {
            if (report.MEASUREMENT_REPORT_ID == id) {
                return &report;
            }
        }
        return nullptr;
    }

    void setRSRPTreshold(int threshold) { rsrp_threshold_ = threshold; }
};

// Unit tests for MeasurementReportManager
void test_MeasurementReportManager() {
    MeasurementReportManager mgr(-125);

    int rc = mgr.initialize(10);
    assert(rc == 0);

    // Verify that all reports are initialized correctly
    for (const auto& report : mgr.reports_) {
        assert(report.MEASUREMENT_REPORT_ID >= 0 && report.MEASUREMENT_REPORT_ID < 10);
        assert(report.CELL_ID >= 1 && report.CELL_ID <= 100);
        assert(report.RSRP_LEVEL >= -125 && report.RSRP_LEVEL <= 95);
    }

    rc = mgr.addReport({11, 101, -75}); // Should replace the least recently added report
    assert(rc == 1);

    LTE_RRC_MEASUREMENT_REPORT_T* found = mgr.getReportByID(9);
    assert(found != nullptr);

    // Test RSRP threshold filtering
    mgr.setRSRPTreshold(-130);
    rc = mgr.addReport({12, 102, -85}); // Should be filtered out due to RSRP_LEVEL below the new threshold
    assert(rc == 0);
    found = mgr.getReportByID(12);
    assert(found == nullptr);
}
```

This implementation provides a simple MeasurementReportManager class that can dynamically allocate memory for an array of LTE_RRC_MEASUREMENT_REPORT_T structures and supports efficient thread-safe access through the use of mutex locking. Additionally, it includes unit tests to verify correctness, robustness, and performance implications.']

