typedef struct {
    int id;
    time_t start;
} UserSession;

int atoi(const char *str) {
    int result = 0;
    while (*str && isdigit(*str)) {
        result = result * 10 + (*str++ - '0');
    }
    return result;
}

time_t strtotime(const char *str, const char *format) {
    struct tm result;
    time_t time = mktime(&result);
    strptime(str, format, &result);
    return time;
}

void read_csv(FILE *input, FILE **output) {
    char line[4096];
    UserSession *sessions = NULL;
    int session_count = 0;
    size_t len;

    while (fgets(line, sizeof(line), input)) {
        char *token = strtok(line, ",");
        if (!token) continue;

        UserSession *session = malloc(sizeof(UserSession));
        session->id = atoi(token);
        token = strtok(NULL, ",");
        session->start = strtotime(token, "%Y-%m-%d %H:%M:%S");
        session_count++;

        if (session_count == 3) {
            sessions = realloc(sessions, session_count * sizeof(UserSession));
            sessions[session_count - 3].start = sessions[session_count - 2].start - sessions[session_count - 1].start;
            sessions[session_count - 3].start /= (double)SESSIONS_PER_GROUP;

            fprintf(*output, "%d,%ld,%.6f\n", sessions[session_count - 3].id, sessions[session_count - 3].start,
                    (double)sessions[session_count - 3].start / CLOCKS_PER_SEC);

            free(session);
            session_count--;
            sessions = realloc(sessions, session_count * sizeof(UserSession));
        } else {
            sessions = realloc(sessions, (session_count + 1) * sizeof(UserSession));
            memcpy(&sessions[session_count], session, sizeof(UserSession));
        }
    }

    free(sessions);
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s input.csv output.csv\n", argv[0]);
        return 1;
    }

