        return 2;
    }

    FILE *output = tmpfile();
    read_csv(input, &output);
    fclose(input);
    fseek(output, -1L, SEEK_END);
    fputc('\0', output); // Ensure the last line ends with newline.
    ftruncate(fileno(output), ftell(output));
    fclose(output);

    return 0;
}
