import hashlib
import os
from threading import Thread

def calculate_md5(file_path):
    chunksize = int(os.environ.get('CHUNKSIZE', 8192))
    with open(file_path, "rb") as f:
        hasher = hashlib.md5()
        while True:
            chunk = f.read(chunksize)
            if not chunk:
                break
            hasher.update(chunk)
        return hasher.hexdigest()
