struct MemoryPool *memory_pool_init(size_t initial_capacity) {
    struct MemoryPool *pool = malloc(sizeof(*pool));
    pool->buffer = malloc(initial_capacity);
    pool->capacity = initial_capacity;
    pool->used = 0;
    return pool;
