void init_crc_data(CRC_DATA *crcData) {
    crcData->capacity = 1024;
    crcData->used = 0;
    crcData->crcFlag = (bool *)calloc(crcData->capacity, sizeof(bool));
}

void update_crc_data(CRC_DATA *crcData) {
    if (crcData->used == crcData->capacity) {
        crcData->capacity *= 2;
        bool *temp = (bool *)realloc(crcData->crcFlag, crcData->capacity * sizeof(bool));
        if (!temp) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        crcData->crcFlag = temp;
    }
    crcData->crcFlag[crcData->used] = rand() % 2;
    crcData->used++;
}

NFAPI_CRC_INDICATION_PDU_T *allocate_and_initialize(int *N) {
    CRC_DATA crcData;
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    init_crc_data(&crcData);

    pdus = (NFAPI_CRC_INDICATION_PDU_T *)calloc(*N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < *N; ++i) {
        pdus[i].ueTag = rand() % MAX_UE_TAG + MIN_UE_TAG;
        pdus[i].rnti = rand() % 16384 + 128;
        pdus[i].crcIndication.crcFlag = crcData.crcFlag[i];
    }
    pthread_mutex_unlock(&lock);

    // Validate CRCFLAG values and reallocate/correct as necessary
    bool allValid = true;
    for (int i = 0; i < *N && allValid; ++i) {
        if (!pdus[i].crcIndication.crcFlag) {
            allValid = false;
        } else {
            // Ensure CRCFLAG is either 0 or 1
            if (pdus[i].crcIndication.crcFlag != 0 && pdus[i].crcIndication.crcFlag != 1) {
                allValid = false;
            }
        }
    }

    while (!allValid) {
        free(pdus);
        pthread_mutex_destroy(&lock);
        update_crc_data(&crcData);
        pdus = (NFAPI_CRC_INDICATION_PDU_T *)calloc(*N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_init(&lock, NULL);
        allValid = true;
        for (int i = 0; i < *N && allValid; ++i) {
            if (!pdus[i].crcIndication.crcFlag) {
                allValid = false;
            } else {
                // Ensure CRCFLAG is either 0 or 1
                if (pdus[i].crcIndication.crcFlag != 0 && pdus[i].crcIndication.crcFlag != 1) {
                    allValid = false;
                }
            }
        }
    }

    return pdus;
