class MemoryManager {
public:
    MemoryManager(size_t initial_chunk_size, bool conservative_mode)
        : _initial_chunk_size(initial_chunk_size), _conservative_mode(conservative_mode) {}

    LTE_ENB_RRC_MESSAGE_T* allocate() {
