            auto new_allocation = static_cast<LTE_ENB_RRC_MESSAGE_T*>(::operator new(sizeof(LTE_ENB_RRC_MESSAGE_T) * _initial_chunk_size));
            _free_list.insert(new_allocation, new_allocation + _initial_chunk_size);
        }

        LTE_ENB_RRC_MESSAGE_T* result = _free_list.begin();
        _free_list.erase(result);
        memset(result, 0, sizeof(*result));
        return result;
    }

