    if (rc != SQLITE_OK) {
        logError("Failed to prepare statement.");
        return NULL;
    }

    // Bind arguments
    for (int i = 0; i < va_arg_count(args); ++i) {
        rc = sqlite3_bind_value(statement, i + 1, va_arg(args, sqlite3_value));
        if (rc != SQLITE_OK) {
            logError("Failed to bind argument.");
            return NULL;
        }
    }

    result.stmt = statement;
    result.row = sqlite3_step(result.stmt);

    return result;
}

