// Custom logging protocol function
void custom_log(LOGGER_T *logger, const char *format, ...) {
    va_list args;
    time_t now;
    struct tm *tm;
    char log_entry[512];

    time(&now);
    tm = localtime(&now);
    snprintf(log_entry, sizeof(log_entry), "%4d-%02d-%02d %02d:%02d:%02d - ",
             tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
             tm->tm_hour, tm->tm_min, tm->tm_sec);

    va_start(args, format);
    vsnprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry), format, args);
    va_end(args);

    fprintf(logger->logfile, "%s\n", log_entry);
}

