// Function to read binary configuration file
int read_config(FILE *file, NFAPI_CRC_INDICATION_PDU_T **array, size_t *count) {
    if (fseek(file, 0, SEEK_SET)) return -1; // Seek to the start of the file

    fread(*array, sizeof(**array), 1, file); // Read first structure

    size_t current = 1;
    while (!feof(file) && !ferror(file)) {
        *count += 1;
        *array = realloc(*array, (*count) * sizeof(**array));
        if (!*array) return -1; // Handle memory allocation failures gracefully

        fread(&((*array)[current]), sizeof(**array), 1, file);

        current++;
    }

    return 0;
}

// Function to dynamically allocate and initialize the array
NFAPI_CRC_INDICATION_PDU_T *init_array(size_t max_structures, size_t *count) {
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(max_structures * sizeof(**array));
    if (!array) return NULL; // Handle memory allocation failures gracefully

    *count = 0;
    return array;
}

// Function to perform the task
NFAPI_CRC_INDICATION_PDU_T *perform_task(const char *config_path, size_t max_structures, float load_threshold) {
    FILE *file = fopen(config_path, "rb");
    if (!file) return NULL; // Handle file opening failures gracefully

    LOGGER_T logger;
    strcpy(logger.log_path, "/path/to/your-app-log.txt");
    logger.fd = -1;
    logger.logfile = fopen(logger.log_path, "a+");
    if (!logger.logfile) return NULL; // Handle file opening failures gracefully

    size_t count = 0, structures_allocated = 0;
    NFAPI_CRC_INDICATION_PDU_T *array = init_array(max_structures, &structures_allocated);
    if (!array) return NULL; // Handle memory allocation failures gracefully

    read_config(file, &array, &count);
    fclose(file);

    pthread_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        if (pthread_mutex_lock(&lock)) return NULL; // Handle mutex lock failures gracefully

        size_t found = 0;
        for (size_t j = 0; j < structures_allocated; ++j) {
            if (array[j].tag == array[i].tag && array[j].rnti == array[i].rnti) {
                found = 1;
                break;
            }
        }

        pthread_mutex_unlock(&lock);

        if (found) continue; // Skip duplicates

        array[structures_allocated].tag = array[i].tag;
        array[structures_allocated].rnti = array[i].rnti;
        array[structures_allocated].crc_indication.CRCFLAG = probabilistic_function();

        structures_allocated++;
    }

    if (pthread_mutex_destroy(&lock)) return NULL; // Handle mutex lock destruction failures gracefully

    pthread_detach(pthread_self()); // Ensure the thread does not interfere with other threads or the main process

    custom_log(&logger, "Loaded %zu structures from configuration file", count);

    free(array); // Free any unused memory (in case we loaded more structures than necessary)

    if ((float)structures_allocated / max_structures > load_threshold) {
        custom_log(&logger, "Adjusted threshold to %zu due to high system load", (size_t)((float)max_structures * load_threshold));
        max_structures = (size_t)((float)max_structures * load_threshold);
    }

    if (structures_allocated > max_structures) {
        custom_log(&logger, "Exceeded maximum allowed structures limit of %zu", max_structures);
        return NULL; // Ensure the function does not exceed the defined system-defined maximum threshold
    }

    array = realloc(array, structures_allocated * sizeof(**array));
    if (!array) return NULL; // Handle memory allocation failures gracefully

    custom_log(&logger, "Final number of allocated structures: %zu", structures_allocated);

    fclose(logger.logfile); // Close the log file before returning

    return array;
}
